\section*{Appendix}

\subsection*{Appendix A: Pseudocode for estimating the LSTM-BEKK}
The following pseudocode outlines the parameter estimation process for the LSTM-BEKK model:

\begin{algorithm}[H]
\caption{LSTM-BEKK Parameter Estimation Process}
\begin{algorithmic}[1]
\Require Initialized parameters: $\mathbf{C}$ (static lower triangular matrix), $a$, $b$, LSTM weights, and Swish activation parameter $\beta$
\Require Hyperparameters: learning rate $\eta$, RMSprop settings, and maximum number of epochs (max\_epochs)
\State Split data into training, validation, and testing sets
\State Initialize optimizer (RMSprop) with $\eta$ and regularization parameters
\For{epoch = 1 to max\_epochs}
    \State Reset cumulative training loss to zero
    \For{each training batch of returns $\mathbf{r}_{1:T}$}
        \For{each time step $t = 1$ to $T$}
            \State Generate dynamic component $\mathbf{C}_t$ using LSTM: $\tilde{\mathbf{C}}_t = \text{LSTM}(\tilde{\mathbf{C}}_{t-1}, \mathbf{r}_{t-1})$
            \State Compute conditional covariance $\mathbf{H}_t$:
            \[
            \mathbf{H}_t = \mathbf{C}\mathbf{C}' + \mathbf{C}_t\mathbf{C}_t' + a \mathbf{r}_{t-1}\mathbf{r}_{t-1}' + b \mathbf{H}_{t-1}
            \]
            \State Accumulate negative log-likelihood (NLL) for batch:
            \[
            \text{NLL} = \text{NLL} + \left( \log|\mathbf{H}_t| + \mathbf{r}_t' \mathbf{H}_t^{-1} \mathbf{r}_t \right)
            \]
        \EndFor
        \State Compute gradients of NLL with respect to all parameters
        \State Update parameters using RMSprop
    \EndFor
    \State Evaluate validation loss
    \If{validation loss does not improve for patience epochs}
        \State Apply learning rate scheduler and/or early stopping
        \State Break
    \EndIf
\EndFor
\State Return optimized parameters: $\mathbf{C}$, $a$, $b$, LSTM weights, and $\beta$
\end{algorithmic}
\end{algorithm}

