	%\noindent Procedure~\ref{alg:send} describes the process of \verb*|Send| operation, that includes the initial signal along with memory bits (by {\em root} node), forward/backward the receiving bits (by intermediate nodes) and {\em match} signal through the state flag. Procedure~\ref{alg:rcv} describes the process of \verb*|Receive| operation of a node that includes, receiving bits from its neighbors and update its flags accordingly. At each iteration, both the operations, \verb*|Send| and \verb*|Receive|, are performed simultaneously to each node.
	\begin{algorithm}[tbh]	
		\begin{algorithmic}
			\fontsize{7.5}{6.5}\selectfont
			%	\begin{tiny}
				\Require A word $\mathscr{B}_j$.
				\State(Local Variable)
				\State $clock_j\gets 0;~ state_j\gets 0;~ start_j\gets 0;~ match_j\gets 1;$
				%\State $state_j\gets 0;$
				%\State $start_j\gets 0;$
				%\State $match_j\gets 1;$
				\State \textbf{Receive: $j$ receives one bit $(state_i)$ from $i$:}
				\State $\mathcal{L}\gets length(\mathscr{B}_{j})$
				\If{$j=root$}
				\If{$clock_j>\mathcal{L}$}
				\If{$state_j=1$}
				\State $state_j\gets state_j$;
				\Else
				\ForAll{$d\in state_i.j$}
				\State $state_j\gets state_j\vee state_d$;
				\EndFor
				\EndIf 	
				\Else
				\State \textbf{wait untill} a bit is received.
				\EndIf
				\Else
				\If{$clock_j\leq\mathcal{L}$}
				\State $state_j\gets state_i$;
				\If{$start_j=0$}
				\If{$state_j=1$}
				\State $start_j\gets 1$;
				\Else
				\State $start_j\gets 0$;
				\EndIf

				\Else
				\If{$match_j=1$}
				\If{$state_j=\mathscr{B}_j[clock_j-1]$}
				\State $match_j\gets 1$;
				\Else
				\State $match_j\gets 0$;
				\EndIf
				\Else
				\State $match_j\gets match_j$;
				\EndIf

				\EndIf
				\Else
				\State $NS_j\gets 0$;
				\ForAll{$d\in state_i.j$}
				\State $NS_j\gets NS_j\vee state_d$;
				\EndFor
				\State $state_j\gets NS\vee match_j$;
				\If{$match_j=1$}
				\State $match_j\gets 0$;
				\EndIf

				\EndIf

				\EndIf

				%	\end{tiny}

		\end{algorithmic}

		\caption{\begin{scriptsize}receive-search in searching of a node $j,~1\leq j\leq n$\end{scriptsize}}\label{alg:rcv}
	\end{algorithm}

	\begin{algorithm}[ht]
		\begin{scriptsize}
			\begin{algorithmic}		
				\Require A word $\mathscr{B}_j$.% as \textbf{Input}.
				\State(Local Variable)
				\State $clock_j\gets 0;~ state_j\gets 0;~ start_j\gets 0;~ match_j\gets 1;$
				%\State $state_j\gets 0;$
				%\State $start_j\gets 0;$
				%\State $match_j\gets 1;$
				\State \textbf{Send: $j$ sends one bit $(state_j)$ to $k$:}
				\State $\mathcal{L}\gets length(\mathscr{B}_{j})$
				\If{$j=root$}
				\If{$clock_j=0$}				
				\State$state_j\gets 1$;
				\ForAll{$d\in state_j.k$}
				\SEND $(state_j)$ to $d$;
				\EndFor
				\ElsIf{$clock_j\leq\mathcal{L}$}
				%\State 	$clock_i \gets clock_i+1$;
				\State $state_j\gets \mathscr{B}_j[clock_j-1]$;
				\ForAll{$d\in state_j.k$}
				\SEND $(state_j)$ to $d$;
				\EndFor
				\Else
				%\State 	$clock_i \gets clock_i+1$;
				\State \textbf{wait for} receive bit from $k$;
				\EndIf
				\Else
				%\State 	$clock_i \gets clock_i+1$;
				\If{$clock_j>\mathcal{L}$}
				\SEND $(state_j)$ to $k$;
				\Else
				\ForAll{$d\in state_j.k$}
				\SEND $(state_j)$ to $d$;
				\EndFor
				\EndIf	
				\EndIf	
				\State$clock_j \gets clock_j+1$;	

			\end{algorithmic}
		\end{scriptsize}
		\caption{\begin{scriptsize}
				send-search in searching of a node $j,~1\leq j\leq n$
		\end{scriptsize}}\label{alg:send}
	\end{algorithm}

