%During the computation, each node of the Cayley tree receives one bit from  its children. Based on the received bit, it updates its flags and sends the updated {\em state} flag to its children. 
The earlier discussion points to the fact that the computation of max is done through execution of two tasks (procedures) within a node. These are the \verb*|send-max| (Procedure~\ref{alg:send_max}) and \verb*|receive-max| (Procedure~\ref{alg:rcv_max}). %Procedure~\ref{alg:send_max} and Procedure~\ref{alg:rcv_max} are designed to realize the \verb*|Send-max| and \verb*|Receive-max| operations respectively. 
Here, in the procedures,
\begin{itemize}
	\item $\mathscr{B}_j$ is the memory of node $j$.
	\item $state_j$ and $start_j$ are the {\em state} and {\em start} flags of a node $j$. Additionally, one memory flag say, $l_m$ and $\eta+1$ link flags for its $\eta+1$ neighbors are there. A link flag $l_x$ of a node corresponds to the neighbor $x$ of the node. A node does not consider the received bit from $x$ if $l_x$ is $1$.
	%$l_x$ of node $j$ indicates the corresponding link flag of a neighbor $x$ of $j$. There exists, one memory link flag $l_m$ that indicates the connection of the node with its attached memory word. A link $l=0$ (resp. $l=1$) indicates connected (resp. disconnected), e.g., a link $l_{\mathscr{B}_j}=1$ indicates the memory word $\mathscr{B}_j$ of node $j$ is disconnected and the logical \verb*|OR| operation does not consider that memory word.
\end{itemize}
\begin{algorithm}[ht]
	\begin{scriptsize}
		\begin{algorithmic}		
			\Require A word $\mathscr{B}_j$.% as \textbf{Input}.
			\State(Local Variable)
			\State $clock_j\gets 0;~ state_j\gets 0;$
			\State \textbf{Send: $j$ sends one bit $(state_j)$ to $k$:}

			\If{$j\in leaves$}
			\If{$clock_j$ = $0$}
			\State $state_j \gets 1$
			\Else
			\State $state_j \gets \mathcal{MSB}.\mathscr{B}_j$

			\EndIf
			\ForAll{$d\in state_j.k$}
			\If{$d\in state_j.parent$}
			\SEND $(state_j)$ to $d$;
			\EndIf
			\EndFor
			\State \verb*|Circular-Left-Shift| on $\mathscr{B}_j$	
			\ElsIf {$j\in intermediate-nodes$}
			\ForAll{$d\in state_j.k$}
			\If{$d\in state_j.parent$}
			\SEND $(state_j)$ to $d$;
			\EndIf
			\EndFor
			\EndIf	

			\State$clock_j \gets clock_j+1$;	

		\end{algorithmic}
	\end{scriptsize}
	\caption{\begin{scriptsize}
			send-max operation in {\em computing max} of a node $j,~1\leq j\leq n$
	\end{scriptsize}}\label{alg:send_max}

\end{algorithm}

