			\State(Local Variable)
			\State $clock_j\gets 0;~ state_j\gets 0;~ start_j\gets 0;~ l_{\mathscr{B}_j}\gets0;$
			\ForAll{$\mathcal{Y}\in neighbours.j$}
				\State $l_\mathcal{Y}\gets0$;
			\EndFor

			\State \textbf{Receive: $j$ receives one bit $(state_i)$ from $i$:}
			%\State $\mathcal{L}\gets length(\mathscr{B})$
			\If{$j=root$}
			\If{$start_j=0$}

			\State \textbf{wait until} a bit is received.
			\Else
			\ForAll{$d\in state_i.j$ and $d\neq state_{i(parent)}.j$ and $l_d=0$} 
			\State $s\gets s\vee state_d$;
			\If{$state_d\neq s$}
			\State $l_d\gets 1$;
			\EndIf
			\EndFor	

			\State $state_j\gets s$

			\State $\mathcal{MSB}.\mathscr{B}_j\gets state_j$
			\State \verb*|Circular-Left-Shift| on $\mathscr{B}_j$						
			\EndIf

			%\State from the next clock, all such $i$ where $state_i\neq s$ are not considered to update $state_j$	
			\ElsIf {$j\in intermediate-nodes$}
			\If{$start_j=0$}
			\State $state_j\gets state_i$.
			\Else
			\ForAll{$d\in state_i.j$ and $d\neq state_{i(parent)}.j$ and $l_d=0$}
			\State $s\gets s\vee state_d$;
			\If{$state_d\neq s$}
			\State $l_d\gets 1$;
			\EndIf
			\EndFor
			\If{$l_{\mathscr{B}_j}=0$}
			\State $s\gets s\vee \mathcal{MSB}.\mathscr{B}_j$;
			\If{$\mathcal{MSB}.\mathscr{B}_j=s$}
			\State $l_{\mathscr{B}_j}\gets 0$
			\Else
			\State  $l_{\mathscr{B}_j}\gets 1$
			\EndIf
			\EndIf	

			\State $state_j\gets s$
			\State \verb*|Circular-Left-Shift| on $\mathscr{B}_j$
			\EndIf

			%					\If{$\mathscr{B}_j[0]=s$}
			%						\State from the next clock, all such $i$ where $state_i\neq s$ are not considered to update $state_j$
			%					\Else
			%						\State from the next clock, all such $i$ where $state_i\neq s$ and $\mathscr{B}_j$ are not considered to update $state_j$
			%					\EndIf								

			\EndIf
			\State $clock_j \gets clock_j+1$;

		\end{algorithmic}
	%\end{scriptsize}	
	\caption{\begin{scriptsize}receive-max operation in {\em computing max} of a node $j,~1\leq j\leq n$\end{scriptsize}}\label{alg:rcv_max}
\end{algorithm}
