	\begin{scriptsize}
		\begin{algorithmic}			
%			\Require A word $\mathscr{B}_j$.% as \textbf{Input}.
			\State \textbf{Step 1:} Find the max (min) value using {\em computing max (min)} (Procedure~\ref{alg:send_max} and Procedure~\ref{alg:rcv_max}).
			\Comment{At the end of step one, the {\em root} contains the max (min) value.}\\
			\State \textbf{Step 2:} \textbf{Report} the element of the {\em root} and \textbf{reset} the flags for the searching ({\em in-memory searching}). During \textbf{reset}, a disabled link is switched to enable if it was disabled during Step 1.\\
			\State \textbf{Step 3:} The Phase~1 of {\em in-memory searching} is performed using Procedure~\ref{alg:send} and Procedure~\ref{alg:rcv}. After that, the $l_{m}$ flag of a node is disabled if its {\em match} flag is $1$ (the node contains the {\em search key}).
