\section{Condensed functional analysis} \label{Sec:Condensed} In this section we will develop the theory of solid condensed functional analysis over uniform Banach $\qp$-algebras, inspired by and mostly following \cite{CondensedNotes}, \cite{RJRC}, \cite[Appendix A]{Bosco}. In \S \ref{Sub:CondensedPrelim}, we discuss the basic theory of solid modules over $p$-adically complete rings and the relation to topological modules, and in \S \ref{Sub:CondensedStandard}, we introduce certain standard Banach and Smith modules, and compute their duals. In \S \ref{Sub:TraceClassCompact}, we discuss the theory of trace-class and compact type morphisms. In \S \ref{Sub:Frechet}, we introduce (strongly countable) Fr\'echet modules, prove that these are always flat (Proposition \ref{Prop:FrechetFlat}), and use this property to describe their interactions with tensor products and duals (Proposition \ref{Prop:TensorInverseLimit} and Corollary \ref{Cor:DualTensorCommute}).

\subsection{Preliminaries} \label{Sub:CondensedPrelim} Fix an uncountable strong limit cardinal $\kappa$ and let $\prof_{\kappa}$ denote the category of profinite sets of cardinality at most $\kappa$, see \cite[Remark 1.3]{CondensedNotes}. Recall that the category of $\kappa$-small condensed sets (abelian groups, rings,...) is defined to be the category of sheaves of sets (abelian groups, rings,...) on $\prof_{\kappa}$ with respect to the topology of finite jointly surjective families of maps, see \cite[Definition 2.1]{CondensedNotes}. The category of condensed sets (abelian groups, rings,...) is defined to be the filtered colimit over all $\kappa$ as above of the category of $\kappa$-small condensed sets (abelian groups, rings,...), see \cite[Definition 2.11]{CondensedNotes}. 

The category of condensed abelian groups is a Grothendieck abelian category satisfying Grothendieck’s axioms (AB4), (AB5), (AB3*) and (AB4*), see \cite[Theorem 1.10]{CondensedNotes}, which moreover admits  all (small) limits and colimits.

\subsubsection{} If $R$ is a $\kappa$-small condensed ring, then a $\kappa$-small $R$-module is a sheaf of $R$-modules on $\prof_{\kappa}$. Taking the colimit over $\kappa$, we obtain the abelian tensor category $\Mod_{R}^{\mathrm{cond}}$, which is simply the category of $R$-modules in condensed abelian groups. This category is an abelian category admitting all (small) limits and colimits, which moreover satisfies Grothendieck’s axioms (AB4), (AB5), (AB3*) and (AB4*). Indeed, this follows from the case of condensed abelian groups discussed above (since limits and colimits can be computed on the underlying condensed abelian group, and since exactness can be tested on the underlying condensed abelian group). If $R=\ul{\mathbb{Z}}$, then $\Mod_{\ul{\mathbb{Z}}}^{\mathrm{cond}}$ is simply the category of condensed abelian groups, and we will denote it by $\Mod_{\mathbb{Z}}^{\mathrm{cond}}$.

\subsubsection{} Recall from \cite[Definition 5.1]{CondensedNotes} the notion of a solid abelian group. The full subcategory $\Mod_{\mathbb{Z}}^{\operatorname{solid}} \subset \Mod_{\mathbb{Z}}^{\mathrm{cond}}$ consisting of solid abelian groups is closed under (small) colimits and limits, and extensions, see \cite[Theorem 5.8]{CondensedNotes}. Therefore, it also satisfies Grothendieck’s axioms (AB4), (AB5), (AB3*) and (AB4*). The category $\Mod_{\mathbb{Z}}^{\operatorname{solid}}$ has a symmetric monoidal structure given by the solid tensor product $\otimes^{\blacksquare}_{\ul{\mathbb{Z}}}$. \smallskip 

If $R$ is a condensed commutative ring whose underlying abelian group is solid, then we can consider the category $\Mod_{R}^{\operatorname{solid}} \subset \Mod_{R}^{\cond} $ of condensed $R$-modules whose underlying abelian group is solid. This subcategory is closed under (small) colimits and limits, and extensions, see \cite[Theorem 5.8]{CondensedNotes}. Therefore, it also satisfies Grothendieck’s axioms (AB4), (AB5), (AB3*) and (AB4*). The category $\Mod_{R}^{\operatorname{solid}}$ has a symmetric monoidal structure given by the solid tensor product $\otimes^{\blacksquare}_{R}$.

\subsubsection{} \label{SubSub:FullyFaithfulOnCGspaces}

There is a functor from topological spaces (abelian groups, rings,...) to condensed sets (abelian groups, rings,...) sending $V$ to the condensed set $\ul{V}$ whose value on a $\kappa$-small profinite set $S$ is the set $C^0(S,V)$ of continuous functions from $S$ to $V$, see \cite[Example 1.5]{CondensedNotes}. The functor $V \mapsto \ul{V}$ is fully faithful when restricted to $V$ whose underlying topological space is compactly generated (e.g., metrizable), see \cite[Proposition 1.7]{CondensedNotes}.

The functor $V \mapsto \ul{V}$ has a left adjoint given by $M \mapsto M(\ast)_{\mathrm{top}}$, which is a certain way to topologize the evaluation of the condensed set $M$ on the one-point profinite set $\ast$. By construction, the topological space $M(\ast)_{\mathrm{top}}$ is compactly generated.

\begin{Lem} \label{Lem:DiscreteDirectLimit}
    For $X=\varinjlim_i X_i$ a countably indexed filtered direct limit of discrete topological spaces, the natural map
    \begin{align}
        \varinjlim_i \ul{X_i} \to \ul{X}
    \end{align}
    is an isomorphism. 
\end{Lem}
\begin{proof}
It suffices to show that continuous maps $S \to X$, with $S$ a profinite set, factor through $X_i$ for some $i$. Since $S$ is profinite and $X$ is discrete, the image of a continuous map is compact hence finite; the lemma follows. 
\end{proof}

\subsubsection{} If $R$ is a topological ring, then we will write $\operatorname{Mod}_{R}^{\mathrm{cond}}=\operatorname{Mod}_{\ul{R}}^{\mathrm{cond}}$ for the category of condensed $\ul{R}$-modules. If $R$ is a topological ring and $M$ is a topological $R$-module, then $\ul{M}$ is naturally an $\ul{R}$-module. 
\begin{Lem} \label{Lem:Fullyfaithful}
Let $R$ be a topological ring. If $M,N$ are compactly generated\footnote{By this we always mean compactly generated as a topological space.}topological $R$-modules, then the natural map
    \begin{align}
        \hom_{C^0,R}(M,N) \to \hom_{\ul{R}}(\ul{M}, \ul{N})
    \end{align}
    is a bijection.
\end{Lem}
\begin{proof}
As mentioned in \S \ref{SubSub:FullyFaithfulOnCGspaces}, the fully faithfulness for compactly generated topological spaces is \cite[Proposition 1.7]{CondensedNotes}. The condition for a morphism $f:M \to N$ of topological spaces to be a homomorphism of $R$-modules comes down to the commutativity of the diagrams
\begin{equation}
    \begin{tikzcd}
        M \times M \arrow{r}{f \times f} \arrow{d} & N \times N \arrow{d} \\
        M \arrow{r}{f} & N
    \end{tikzcd}
    \begin{tikzcd}
        M \times A \arrow{r}{f \times \operatorname{Id}_{A}} \arrow{d} & N \times A \arrow{d} \\
        M \arrow{r}{f} & N.
    \end{tikzcd}
\end{equation}
Since the functor from topological spaces to condensed sets commutes with products and is faithful, the commutativity of these diagrams can be checked after passing to condensed sets. Thus a continuous map $M \to N$ is a homomorphism of $R$-modules if and only if the induced map $\ul{M} \to \ul{N}$ is a homomorphism of $\ul{R}$-modules.
\end{proof} 
\subsubsection{} For a condensed ring $R$ and condensed $R$-modules $M,N$, we will write $\Hom_{R}(M,N)$ for the internal hom in the category of condensed $R$-modules. If $R$ is a topological ring and $M$ a topological $R$-module, then for a profinite set $S$ we will write $M_{S}=C^0(S,M)$ for the set of continuous functions $f:S \to M$ equipped with the compact open topology. If $R$ and $M$ are compactly generated Hausdorff, then this is a topological $R$-module, because $C^0(S,M)$ is the internal hom in the category of Hausdorff compactly generated topological spaces, see \cite[Theorem 5.14]{Topology}. 
\begin{Lem} \label{Lem:PreEvaluationCondensed}
    Let $R$ be a topological ring and $M,N$ be topological $R$-modules. If $R,N,M$ are compactly generated and Hausdorff, then for a profinite set $S$ there is a natural bijection
    \begin{align}
        \Hom_{\ul{R}}(\ul{M},\ul{N})(S) \to \hom_{\Cont, R}(M, N_{S}). 
    \end{align}
\end{Lem}
\begin{proof}
Write $\pi^{-1}$ for the functor which takes sheaves on profinite sets and restricts them to the category of profinite sets over $S$. It has a right adjoint $\pi_{\ast}$ which takes a sheaf $F$ on profinite sets over $S$ and sends it to the sheaf $T \mapsto F(S \times T)$. Using the definition and the adjunction we find that
\begin{align}
    \Hom_{\ul{R}}(\ul{M}, \ul{N})(S)&:= \hom_{\pi^{-1} \ul{R}}(\pi^{-1} \ul{M}, \pi^{-1} \ul{N}) \\
    &=\hom_{\ul{R}}(\ul{M}, \pi_{\ast}\pi^{-1} \ul{N}).
\end{align}
The sheaf $\pi_{\ast}\pi^{-1} \ul{N}$ is given by 
\begin{align}
    T \mapsto C^0(T \times S, N)
\end{align}
which we claim is naturally isomorphic to $T \mapsto C^0(T, C^0(S,N))$. This claim follows from the fact that $C^0(S,N)$ is the internal hom in the category of weakly Hausdorff compactly generated topological spaces, see \cite[Theorem 5.14]{Topology} (here we are using the fact that $N$ is compactly generated Hausdorff); in particular $C^0(S,N)$ is itself compactly generated. Thus we have identified $\pi_{\ast}\pi^{-1} \ul{N} = \ul{C^0(S,N)}$ and by Lemma \ref{Lem:Fullyfaithful} we see that
\begin{align}
    \hom_{\ul{R}}(\ul{M}, \ul{C^0(S,N)})&= \hom_{C^0,R}(M, C^0(S,N)).
\end{align}
\end{proof}
\begin{Lem} \label{Lem:CompactOpen}
Let $N$ be a $p$-adically complete and separated topological abelian group with the $p$-adic topology and let $S$ be a profinite set. Then the $p$-adic topology on $C^0(S,N)$ agrees with the compact-open topology.
\end{Lem}
\begin{proof}
Since $S$ is compact Hausdorff, the compact-open topology on $C^0(S,N)$ is compactly generated. We now use the fact that $C^0(S,N)$, with the compact-open topology, is the internal hom in the category of compactly generated and weakly Hausdorff topological spaces, see \cite[Theorem 5.14]{Topology}. It follows from this that
\begin{align}
    C^0(S,N) &= C^0(S,\varprojlim_n N/p^n) \\
    &=\varprojlim_n C^0(S,N/p^n),
\end{align}
and thus it suffices to prove that the compact open topology on $C^0(S,N/p^n)$ is the discrete topology. Let $f:S \to N/p^n$ be a continuous map; we will show that $\{f\} \subset C^0(S,N/p^n)$ is open. Note that $f$ takes finitely many values $r_{1}, \cdots, r_{k}$ whose preimages give an open cover $K_{1}, \cdots, K_{k}$ of $S$. Per definition of the compact-open topology, the subsets $U_{i} \subset C^0(S,N/p^n)$ of continuous functions $g$ taking $K_i$ to $r_i$ are open. Now $\{f\}=\cap_{i=1}^{k} U_i$, so that $\{f\}$ is open.
\end{proof}

\subsubsection{} Let $R^+$ be a $p$-adically complete and separated ring, and let $M,N$ be $p$-adically complete and separated $R^+$-modules whose topology is the $p$-adic topology. 
\begin{Prop} \label{Prop:TensorProductsSolidVSComplete} 
If $\ul{M}$ is flat for the solid tensor product over $\ul{R^+}$, and $N$ and $R^+$ are $p$-torsion free, then the condensed $\ul{R^{+}}$-module $\ul{M \widehat{\otimes}_{R^+} N}$ is isomorphic to the solid tensor product $\ul{M} \otimes^{\blacksquare}_{\ul{R^+}} \ul{N}$.
\end{Prop}
\begin{proof}
For a profinite set $S=\varprojlim_i S_i$ we compute 
    \begin{align}
        C^0(S,M \widehat{\otimes}_{R^{+}} N) &= C^0(S, \varprojlim_n (M/p^n \otimes_{R^{+}/p^n} N/p^n)) \\
        &=\varprojlim_n \left( C^0(S, M/p^n \otimes_{R^{+}/p^n} N/p^n) \right) \\
        &=\varprojlim_n \left( \varinjlim_i C^0(S_i, M/p^n \otimes_{R^{+}/p^n} N/p^n) \right).
\end{align}
where the last equality follows from $M/p^n \otimes_{R^{+}/p^n} N/p^n$ having the discrete topology. Now we use the fact that tensor products commute with finite products and with colimits to see
\begin{align}
        \varprojlim_n \left( \varinjlim_i C^0(S_i, M/p^n \otimes_{R^{+}/p^n} N/p^n) \right) &=\varprojlim_n \left( \varinjlim_i C^0(S_i, M/p^n) \otimes_{C^0(S_i, R^{+}/p^n)} C^0(S_i, N/p^n) \right) \\
        &=\varprojlim_n \left( C^0(S, M/p^n) \otimes_{C^0(S, R^{+}/p^n)} C^0(S, N/p^n) \right) \\
        &=\varprojlim_n (\ul{M/p^n} \otimes_{\ul{R^{+}/p^n}} \ul{N/p^n})(S).
    \end{align}
So we see that the condensed $\ul{R^{+}}$-module $\ul{M \widehat{\otimes}_{R^{+}} N}$ is given by the $p$-adic completion of the (non-solid) condensed tensor product, i.e.,\[ \ul{M \widehat{\otimes}_{R^{+}} N} =\varprojlim_n (\ul{M/p^n} \otimes_{\ul{R^{+}/p^n}} \ul{N/p^n}) = \varprojlim_n \left((\ul{M} \otimes_{\ul{R^{+}}} \ul{N})/p^n\right) .\]
Now for the solid tensor product we use the flatness to write
\begin{align}
    \ul{M} \otimes^{\blacksquare}_{\ul{R^+}} \ul{N} = \ul{M} \otimes^{\blacksquare, \mathbb{L}}_{\ul{R^+}} \ul{N}.
\end{align}
It then follows from \cite[Lemma A.3]{BoscoII}, that the right hand side is derived $p$-adically complete. 
We can thus compute
\begin{align}
    \ul{M} \otimes^{\blacksquare, \mathbb{L}}_{\ul{R^+}} \ul{N} &= R \varprojlim_n \left( (\ul{M} \otimes^{\blacksquare, \mathbb{L}}_{\ul{R^+}} \ul{N}) \otimes_{\ul{R^+}}^{\blacksquare, \mathbb{L}} \ul{R^+/p^n} \right) \\
    &=R \varprojlim_n \left( \ul{M} \otimes^{\blacksquare, \mathbb{L}}_{\ul{R^+}}  \ul{R^+/p^n} \otimes_{\ul{R^+}}^{\mathbb{L},\blacksquare} \ul{N} \right) \\
    &=R \varprojlim_n \left( \ul{M} \otimes^{\blacksquare}_{\ul{R^+}}  \ul{R^+/p^n} \otimes_{\ul{R^+}}^{\mathbb{L},\blacksquare} \ul{N} \right) \\
    &=R \varprojlim_n \left( \ul{M/p^n} \otimes_{\ul{R^+}}^{\mathbb{L},\blacksquare} \ul{N} \right) \\
    &=R \varprojlim_n \left( \ul{M/p^n} \otimes_{\ul{R^+/p^n}}^{\mathbb{L},\blacksquare} \ul{R^+/p^n} \otimes_{\ul{R^+}}^{\mathbb{L},\blacksquare} \ul{N} \right).
\end{align}
where the third equality uses the flatness of $\ul{M}$. We now claim that $\ul{R^+/p^n} \otimes_{\ul{R^+}}^{\mathbb{L},\blacksquare} \ul{N}$ is isomorphic to $\ul{N/p^n}$ since $N$ is $p$-torsion free: For this we first note that $\ul{R^+/p^n} \otimes_{\ul{R^+}}^{\mathbb{L},\blacksquare} \ul{N} \simeq \ul{\mathbb{Z}/p^n \mathbb{Z}}\otimes_{\ul{\mathbb{Z}}}^{\mathbb{L},\blacksquare} \ul{N}$ (this uses the assumption that $R^+$ is $p$-torsion free). Now $\ul{N}(S)$ is torsion free for all $S$ because $N$ is torsion free, hence $N$ is flat for the (non-solid) condensed tensor product, see \cite[Lemma A.5]{BoscoII}. We see that
\begin{align}
\ul{\mathbb{Z}/p^n \mathbb{Z}}\otimes_{\ul{\mathbb{Z}}}^{\mathbb{L}} \ul{N} &\simeq \ul{\mathbb{Z}/p^n \mathbb{Z}}\otimes_{\ul{\mathbb{Z}}} \ul{N} \\
&=\ul{N/p^n}.
\end{align}
This is already solid, and so its derived solidification equals itself (see \cite[Theorem 6.2 and the paragraph following it]{CondensedNotes}), and so we get $\ul{R^+/p^n} \otimes_{\ul{R^+}}^{\mathbb{L},\blacksquare} \ul{N} \simeq \ul{N/p^n}$. We now continue with our computation: 
\begin{align}
    &=R \varprojlim_n \left( \ul{M/p^n} \otimes_{\ul{R^+/p^n}}^{\mathbb{L},\blacksquare} \ul{N/p^n} \right) \\
    &=R \varprojlim_n \left( \ul{M/p^n} \otimes_{\ul{R^+/p^n}}^{\blacksquare} \ul{N/p^n} \right) \\
    &=R\varprojlim_n \left( \ul{M/p^n \otimes_{R^+/p^n} N/p^n}\right) \\
    &=\varprojlim_n \left( \ul{M/p^n \otimes_{R^+/p^n} N/p^n}\right),
\end{align}
where, in the second equality we have used that $\ul{M/p^n}$ is a flat $\ul{R^+/p^n}$-module, and $p$-adic completeness of $M,N$ has been used in the last step. This finishes the proof of the lemma.
\end{proof}

\begin{Rem} \label{Rem:UncompletedTensor}
    The assumption that $M$ and $N$ have the $p$-adic topology is necessary. Indeed, let $R=\zp, N=\zp[[T]]$ with the $(p,T)$-adic topology and $M=\zp\langle X \rangle$ (the $p$-adic completion of $\zp[X]$). In this case $M \widehat{\otimes}_{\zp} N$ is the $(T,p)$-adic completion of $\zp[T,X]$ while $\ul{M} \otimes_{\ul{\zp}}^{\blacksquare} \ul{N}$ is the (condensed module associated with the) $p$-adic completion of $\zp[[T]][X]$ (which is not $T$-adically complete). 
\end{Rem}


\subsection{Standard modules} \label{Sub:CondensedStandard} Let $(R,R^+)$ be a uniform Huber pair over $(\qp,\zp)$, so that $R^+$ is a $p$-adically complete and separated ring. We define for an index set $I$ the solid $\ul{R^{+}}$ (resp. $\ul{R}$)-modules
\begin{align} \label{eq:CondensedStandard}
    \hat{\oplus}_I \ul{R^+}:=\varprojlim_n \oplus_I \ul{R^{+}/p^n} \\
    \hat{\oplus}_I \ul{R}:=(\hat{\oplus}_I \ul{R^{+}})[\tfrac{1}{p}].
\end{align}
As suggested by the notation, the module $\hat{\oplus}_I \ul{R}$ does not depend on the choice of $R^+$. 

The module $\hat{\oplus}_I \ul{R^+}$ is solid because it is an inverse limit of discrete $\ul{R^+}$-modules, which are automatically solid. Inverting $p$ is a filtered colimit, and therefore $\hat{\oplus}_I \ul{R}$ is also solid. We will refer to solid $\ul{R}$-modules isomorphic to $\hat{\oplus}_I \ul{R}$ as \emph{orthonormalizable Banach} $\ul{R}$-modules. For an index set $I$ we also consider the solid $\ul{R^{+}}$ (resp. $\ul{R}$)-modules
\begin{align}
    \textstyle\prod_I \ul{R^+}, \; \left(\textstyle\prod_I \ul{R^+}\right)[\tfrac{1}{p}],
\end{align}
where we note as before that the second module does not depend on the choice of $R^+$. We will refer to solid $\ul{R}$-modules isomorphic to $(\textstyle\prod_I \ul{R^+})[\tfrac{1}{p}]$ as \emph{free Smith} $\ul{R}$-modules. When $I$ is countable, then we will call these modules \emph{countably orthonormalizable Banach} and \emph{countably free Smith}. 

\subsubsection{} \label{Subsub:classicalStdModules} For an index set $I$, we can also form the topological $R^+$-modules 
\begin{align} \label{Eq:TopologicalStandard}
    \hat{\oplus}_I R^+&:=\varprojlim_n \oplus_I R^+/p^n, \qquad \textstyle\prod_I R^{+},
\end{align}
with the $p$-adic and product topologies respectively. Since $M \mapsto \ul{M}$ commutes with limits and takes direct sums of discrete modules to direct sums, see Lemma \ref{Lem:DiscreteDirectLimit}, it follows that the natural maps 
\begin{align}
    \hat{\oplus}_I \ul{R^{+}} &\to \ul{\hat{\oplus}_I R^+}  \\
    \ul{\textstyle\prod_I R^{+}} &\to \textstyle\prod_I \ul{R^+}
\end{align}
are isomorphisms. We also have the following lemma (which we do not generally expect to hold for the product when $I$ is not countable).
\begin{Lem} \label{Lem:CompactlyGenerated}
The topological spaces $\hat{\oplus}_I R^+$ and $\hat{\oplus}_I R$ are compactly generated and Hausdorff. If $I$ is countable, then the topological spaces $\textstyle\prod_I R^{+}$ and $(\textstyle\prod_I R^{+})[\tfrac{1}{p}]$ are compactly generated and Hausdorff.
\end{Lem}
\begin{proof}
The topological ring $R^+$ has the $p$-adic topology, which is metrisable (since $R^+$ is complete and separated for the $p$-adic topology) hence compactly generated and Hausdorff. The topological abelian group $\hat{\oplus}_I R^+$ has the $p$-adic topology, which is metrisable and therefore compactly generated; it is Hausdorff because $\hat{\oplus}_I R^+$ is $p$-adically separated. It follows that $\hat{\oplus}_I R$ is compactly generated and Hausdorff as it is a countably direct limit of compactly generated Hausdorff topological spaces under open and closed transition maps. The module $\textstyle\prod_I R^+$ is a countable product of metrisable (Hausdorff) spaces which is (Hausdorff) metrisable, see \cite[Satz 4.4.12 on p. 117]{HerrlichTopology}, and thus compactly generated Hausdorff. It follows similarly to before that $(\textstyle\prod_I R^{+})[\tfrac{1}{p}]$ is compactly generated and Hausdorff.
\end{proof}

\subsubsection{} Recall the completed tensor $\widehat{\otimes}$ product of linearly topologized modules over linearly topologized rings (in the sense of \cite[Tag 07E7]{stacks-project}), see \cite[Tag 0AMU]{stacks-project}. 

\begin{Lem} \label{Lem:StandardTensorTopological}
If $R^+ \to B^+$ is a morphism of $p$-complete rings, then the natural maps
    \begin{align}
        (\hat{\oplus}_I R^+) \widehat{\otimes}_{R^+} B^+ &\to  \hat{\oplus}_{I} B^+ \\
        (\hat{\oplus}_I R^+) \widehat{\otimes}_{R^+} (\hat{\oplus}_{J} R^+ )&\to  \hat{\oplus}_{I \times J} R^+
    \end{align}
    are isomorphisms.
\end{Lem}
\begin{proof}
This follows directly from the definition of the completed tensor product, and the fact that (usual) tensor products commute with direct sums. 
\end{proof}

\subsubsection{} We now study properties of these standard modules.

\begin{Lem} \label{Lem:BanachFlat}
If $(R,R^+)$ is a uniform Huber pair, then $\hat{\oplus}_I \ul{R^+}$ is flat for the solid tensor product.
\end{Lem}
\begin{proof}
First of all, $\textstyle\prod_I \ul{\mathbb{Z}}$ is flat for the solid tensor product over $\ul{\mathbb{Z}}$ because it is torsion free, see \cite[Lemma A.5]{BoscoII}. By \cite[Lemma A.19]{Bosco} we have $\textstyle\prod_I \ul{\mathbb{Z}} \otimes_{\ul{\mathbb{Z}}} \ul{\zp} = \textstyle\prod_I \ul{\mbb{Z}_p}$ which is therefore flat for the solid tensor product over $\ul{\zp}$. By \cite[Lemma A.4]{BoscoII}, we can write $\hat{\oplus}_I \ul{\zp}$ as a filtered colimit of objects isomorphic to $\textstyle\prod_I \ul{\zp}$ and it is thus flat for the solid tensor product over $\ul{\zp}$. It follows from Proposition \ref{Prop:TensorProductsSolidVSComplete} and Lemma \ref{Lem:StandardTensorTopological} that $\hat{\oplus}_I \ul{\zp} \otimes_{\ul{\zp}}^\blacksquare \ul{R^+} = \hat{\oplus}_I \ul{R^+}$, which is hence flat for the solid tensor product over $\ul{R^+}$.
\end{proof}

\begin{Prop} \label{Prop:StandardBCproperty}
Let $(R, R^+) \to (B, B^+)$ be a morphism of uniform Huber pairs over $(\mbb{Q}_p, \mbb{Z}_p)$. For any index set $I$, the natural maps
    \[
    \hat{\oplus}_I \ul{R}^+ \otimes^{\blacksquare}_{\ul{R}^+} \ul{B}^+ \xrightarrow{\sim} \hat{\oplus}_I \ul{B}^+ \quad \textrm{and} \quad \hat{\oplus}_I \ul{R} \otimes^{\blacksquare}_{\ul{R}} \ul{B} \xrightarrow{\sim} \hat{\oplus}_I \ul{B} 
    \]
    are isomorphisms. Moreover, for any two index sets $I$ and $J$, the natural maps
    \[ 
         \hat{\oplus}_I \ul{R^{+}} \otimes^{\blacksquare}_{\ul{R^+}}  \hat{\oplus}_J \ul{R^{+}} \to  \hat{\oplus}_{I \times J} \ul{R^+}\quad \textrm{and} \quad
         (\hat{\oplus}_I \ul{R}) \otimes^{\blacksquare}_{\ul{R}}  (\hat{\oplus}_J \ul{R}) \to  \hat{\oplus}_{I \times J} \ul{R} \]
are isomorphisms.
\end{Prop}
\begin{proof}
Because the solid tensor product commutes with inverting $p$, it suffices to prove the first and the third isomorphisms. By Proposition \ref{Prop:TensorProductsSolidVSComplete} and Lemma \ref{Lem:BanachFlat}, these reduce to a computation for the completed tensor product, where it is Lemma \ref{Lem:StandardTensorTopological}.
\end{proof}

\subsubsection{} Recall that we write $\Hom_{\ul{R^{+}}}$ and $\Hom_{\ul{R}}$ for the internal hom in condensed $\ul{R^{+}}$-modules or condensed $\ul{R}$-modules.

\begin{Prop} \label{Prop:DualityCondensed}
The natural maps
\begin{align}
\Hom_{\ul{R^{+}}}\left(\hat{\oplus}_{I}\ul{R^{+}}, \ul{R^{+}}\right) &\to  \textstyle\prod_{i \in I} \ul{R}^{+} \\
\Hom_{\ul{R}}\left(\hat{\oplus}_{I}\ul{R}, \ul{R}\right) &\to  \left(\textstyle\prod_{I} \ul{R}^{+}\right)[\tfrac{1}{p}]
\end{align}
are isomorphisms. If $I$ is countable, then the natural maps
\begin{align}
    \hat{\oplus}_{I}\ul{R^{+}} &\to \Hom_{\ul{R^{+}}}\left(\textstyle\prod_I \ul{R^{+}}, \ul{R^{+}}\right) \\
    \hat{\oplus}_{I}\ul{R} &\to \Hom_{\ul{R}}\left(\left(\textstyle\prod_I \ul{R^{+}}\right)[\tfrac{1}{p}], \ul{R}\right)
\end{align}
are isomorphisms.
\end{Prop}
\begin{proof}
For the first claim, we follow the proof of \cite[Lemma 3.10]{RJRC}: We note that
\begin{align}
     \Hom_{\ul{R^{+}}}\left(\hat{\oplus}_{I}\ul{R^{+}}, \ul{R^{+}}\right) &= \varprojlim_{n}  \Hom_{\ul{R^{+}}/p^n}\left(\oplus_{I}\ul{R^{+}}/p^n, \ul{R^{+}}/p^n\right) \\
     &=\varprojlim_{n}  \textstyle\prod_{I} \ul{R^{+}}/p^n \\
     &= \textstyle\prod_{I} \ul{R^{+}}.
\end{align}
The second claim follows from the first claim once we establish that the natural map
\begin{align}
    \Hom_{\ul{R^{+}}}\left(\hat{\oplus}_{I}\ul{R^{+}}, \ul{R^{+}}\right)[\tfrac{1}{p}] \to \Hom_{\ul{R}}\left(\hat{\oplus}_{I}\ul{R}, \ul{R}\right).
\end{align}
is an isomorphism. Using Lemma \ref{Lem:PreEvaluationCondensed} (whose assumptions are satisfied by Lemma \ref{Lem:CompactlyGenerated}), we can identify this map (on $S$ points for a profinite set $S$) with the natural map
\begin{align}
    \hom_{\Cont, R^+}(\hat{\oplus}_{I}R^+, R^+_S)[\tfrac{1}{p}] \to \hom_{\Cont, R}(\hat{\oplus}_{I}R, R_S). 
\end{align}
This map is a bijection since any continuous map of $\qp$-Banach spaces is bounded. For the third claim, we consider 
\begin{align}
    \Hom_{\ul{R^{+}}}\left(\textstyle\prod_I \ul{R^{+}}, \ul{R^{+}}\right) &= \varprojlim_n \Hom_{\ul{R^{+}}/p^n}\left(\textstyle\prod_I \ul{R^{+}}/p^n, \ul{R^{+}}/p^n\right).
\end{align}
This receives a natural map from $\hat{\oplus}_I \ul{R^+}$,
\begin{multline}  \label{eq:DirectSumToProduct}
    \hat{\oplus}_I \ul{R^+}=\varprojlim_n \oplus_I \Hom_{\ul{R^{+}}/p^n}\left(\ul{R^{+}}/p^n, \ul{R^{+}}/p^n\right) \to \varprojlim_n \Hom_{\ul{R^{+}}/p^n}\left(\textstyle\prod_I \ul{R^{+}}/p^n, \ul{R^{+}}/p^n\right),
\end{multline}
by taking the natural map termwise in the limit. We claim that this map is an isomorphism. We can check this on $S$-points for profinite sets $S$, and by Lemma \ref{Lem:PreEvaluationCondensed} applied to $R^+/p^n$ (whose assumptions hold because $\textstyle\prod_I R^+/p^n$ is compactly generated), we can identify the natural map on $S$-points with
\begin{align}
     \varprojlim_n \oplus_I \Hom_{\Cont, R^+/p^n}\left(R^+/p^n, R_S^+/p^n\right) \to \varprojlim_n \Hom_{\Cont,R^+/p^n}\left(\textstyle\prod_I R^+/p^n, R_S^+/p^n\right). 
\end{align}
Now $R_S^+/p^n$ has the discrete topology (see Lemma \ref{Lem:CompactOpen}), and so every continuous $R^+/p^n$-linear map $\textstyle\prod_I \ul{R^+}/p^n \to R_S^+/p^n$  has kernel containing $\textstyle\prod_{J} \{0\} \times \textstyle\prod_{I\backslash J} R^+/p^n$ for some finite $J \subseteq I$. This implies that \eqref{eq:DirectSumToProduct} is a bijection and the third claim follows. \smallskip 

For the final claim of the proposition, it suffices to show that the natural map
\begin{align}
    \Hom_{\ul{R^{+}}}\left(\textstyle\prod_I \ul{R^{+}}, \ul{R^{+}}\right)[\tfrac{1}{p}] \to \Hom_{\ul{R}}\left(\left(\textstyle\prod_I \ul{R^{+}}\right)[\tfrac{1}{p}], \ul{R}\right)
\end{align}
is an isomorphism. We can check this on $S$-points for profinite sets $S$, and then using Lemma \ref{Lem:PreEvaluationCondensed} (using Lemma \ref{Lem:CompactlyGenerated} to check its assumptions), we can identify this with
\begin{align}
    \hom_{C^0,R^+}\left(\textstyle\prod_I R,R^{+}_{S}\right)[\tfrac{1}{p}] \to  \hom_{C^0,R}\left(\left(\textstyle\prod_I R^{+}\right)[\tfrac{1}{p}],R_{S}\right).
\end{align}
This map is a bijection because the image of $\textstyle\prod_I R^+$ under any continuous morphism $(\textstyle\prod_I R^+)[\tfrac{1}{p}] \to R_{S}$ is bounded: Indeed, the preimage of $R^+_S$ intersected with $\textstyle\prod_I R^{+}$ is open and contains $0$, thus, by the definition of the product topology, contains a set of the form $(\textstyle\prod_{j\in J} p^{n_j} R^+) \times \textstyle\prod_{I \backslash J} R^+$ for some $J \subseteq I$ finite, but then, taking $n=\mathrm{max}_{j \in J}( n_j)$, we see $\textstyle\prod_I R^{+}$ maps into $p^{-n} R^+_S$. 
\end{proof}


\subsubsection{} We have the following complement to Propositions \ref{Prop:DualityCondensed} and \ref{Prop:StandardBCproperty}.
\begin{Prop} \label{Prop:TensorDualSmith}
Let $(R,R^+) \to (B,B^+)$ be a morphism of uniform Huber pairs over $(\qp,\zp)$. If $I,J$ are countable sets, then the natural maps
\begin{align}
    \hat{\oplus}_I B^+ &\to \Hom_{\ul{B^+}}\left(\textstyle\prod_I \ul{R^+} \otimes_{\ul{R^+}}^{\blacksquare} \ul{B^+}, \ul{B^+}\right) \\
    \hat{\oplus}_I B &\to \Hom_{\ul{B}}\left(\left(\textstyle\prod_I \ul{R^+}\right)[\tfrac{1}{p}] \otimes_{\ul{R}}^{\blacksquare} \ul{B}, \ul{B}\right) 
\end{align}
are isomorphisms. Moreover, the natural maps
\begin{align}
    \hat{\oplus}_{I \times J} R^+ &\to \Hom_{\ul{R^+}}\left(\textstyle\prod_I \ul{R^+} \otimes_{\ul{R^+}}^{\blacksquare} \textstyle\prod_J \ul{R^+}, \ul{R^+}\right) \\
    \hat{\oplus}_{I \times J} R &\to \Hom_{\ul{R^+}}\left(\left(\textstyle\prod_I \ul{R^+}\right)[\tfrac{1}{p}] \otimes_{\ul{R}}^{\blacksquare} \left(\textstyle\prod_J \ul{R^+}\right)[\tfrac{1}{p}], \ul{R}\right)
\end{align}
are isomorphisms.
\end{Prop}
\begin{proof}
For the first isomorphism, we notice that by the tensor-hom adjunction we have
\begin{align}
    \Hom_{\ul{B^+}}\left(\textstyle\prod_I \ul{R^+} \otimes_{\ul{R^+}}^{\blacksquare} \ul{B^+}, \ul{B^+}\right)=\Hom_{\ul{R^+}}\left(\textstyle\prod_I \ul{R^+}, \ul{B^+}\right).
\end{align}
Let $S$ be a profinite set. Then it follows from Lemma \ref{Lem:PreEvaluationCondensed} (whose assumptions hold by Lemma \ref{Lem:CompactlyGenerated}), that we may identify 
\begin{align}
    \Hom_{\ul{R^+}}\left(\textstyle\prod_I \ul{R^+}, \ul{B^+}\right)(S) &= \hom_{\Cont, R^+}\left(\textstyle\prod_I R^+, B^+_{S}\right) \\
    &=\varprojlim_{n} \hom_{\Cont, R^+}\left(\textstyle\prod_I R^+/p^n, B^+_{S}/p^n\right).
\end{align}
Arguing with the product topology as in the proof of Proposition \ref{Prop:DualityCondensed}, we further identify
\begin{align}
   \varprojlim_{n} \hom_{\Cont, R^+}\left(\textstyle\prod_I R^+/p^n, B^+_{S}/p^n\right) &=\varprojlim_{n} \oplus_I \hom_{R^+}\left( R^+/p^n, B^+_{S}/p^n\right) \\
    &=\varprojlim_{n} \oplus_I B^+_{S}/p^n \\
    &=(\hat{\oplus}_I B^+)(S).
\end{align}
For the second isomorphism, we consider the commutative diagram (for a profinite set $S$)
\begin{equation}
    \begin{tikzcd}
        \Hom_{\ul{R^+}}\left(\textstyle\prod_I \ul{R^+}, \ul{B^+}\right)(S)[\tfrac{1}{p}] \arrow{r} \arrow{d} & \hom_{\Cont, R^+}\left(\textstyle\prod_I R^+, B^+_{S}\right)[\tfrac{1}{p}] \arrow{d} \\
        \Hom_{\ul{R}}\left(\left(\textstyle\prod_I \ul{R^+}\right)[\tfrac{1}{p}], \ul{B}\right)(S) \arrow{r} & \hom_{\Cont, R}\left(\left(\textstyle\prod_I R^+\right)[\tfrac{1}{p}], B_S\right).
    \end{tikzcd}
\end{equation}
By the tensor-hom adjunction and the first claim of the Proposition, it suffices to show that the left vertical arrow is an isomorphism. The top horizontal arrow is an isomorphism by the case handled above, and it follows as in the proof of Proposition \ref{Prop:DualityCondensed} that the right vertical arrow is an isomorphism. The bottom horizontal arrow is an isomorphism by Lemma \ref{Lem:PreEvaluationCondensed} (using Lemma \ref{Lem:CompactlyGenerated} to verify the assumptions), and so we are done. 

For the third isomorphism we use Proposition \ref{Prop:DualityCondensed} and the tensor-hom adjunction to write
\begin{align}
    \Hom_{\ul{R^+}}\left(\textstyle\prod_I \ul{R^+} \otimes_{\ul{R^+}}^{\blacksquare}\textstyle\prod_J \ul{R^+}, \ul{R^+}\right)
    &=\Hom_{\ul{R^+}}\left(\textstyle\prod_I \ul{R^+}, \Hom_{\ul{R^+}}\left(\textstyle\prod_J \ul{R^+}, \ul{R^+}\right)\right) \\
    &=\Hom_{\ul{R^+}}\left(\textstyle\prod_I \ul{R^+}, \hat{\oplus}_J \ul{R^+}\right).
\end{align}
Let $S$ be a profinite set. Then it follows from Lemma \ref{Lem:PreEvaluationCondensed} (whose assumptions hold by Lemma \ref{Lem:CompactlyGenerated}), that 
\begin{align}
    \Hom_{\ul{R^+}}\left(\textstyle\prod_I \ul{R^+},  \hat{\oplus}_J \ul{R^+}\right)(S) &= \hom_{\Cont, R^+}\left(\textstyle\prod_I R^+, \left(\hat{\oplus}_J R^+\right)_{S}\right) \\
    &= \hom_{\Cont, R^+}\left(\textstyle\prod_I R^+, \hat{\oplus}_J R^+_{S}\right),
\end{align}
where we used Lemma \ref{Lem:CompactOpen} and Lemma \ref{Lem:DiscreteDirectLimit} in the last step. We further compute
\begin{align}
    \hom_{\Cont, R^+}\left(\textstyle\prod_I R^+, \hat{\oplus}_J R^+_{S}\right) &=\varprojlim_{n} \hom_{\Cont, R^+/p^n}\left(\textstyle\prod_I R^+/p^n, \oplus_{J} R^+_{S}/p^n\right) \\
    &=\varprojlim_{n} \oplus_I \hom_{R^+/p^n}\left( R^+/p^n, \oplus_{J} R^+_{S}/p^n\right),
\end{align}
where the last step follows by arguing with the product topology as in the proof of Proposition \ref{Prop:DualityCondensed}. Continuing, we get (using Lemma \ref{Lem:DiscreteDirectLimit} in the second step)
\begin{align}
    \varprojlim_{n} \oplus_I \hom_{R^+/p^n}\left( R^+/p^n, \oplus_{J} R^+_{S}/p^n\right)&=\varprojlim_{n} \oplus_I \oplus_{J} R^+_{S}/p^n \\
    &=\varprojlim_{n} \oplus_{I \times J} R^+_{S}/p^n \\
    &=\left(\hat{\oplus}_{I \times J} \underline{R^+}\right)(S).
\end{align}

 For the final isomorphism, we consider the commutative diagram (for a fixed profinite set $S$)
\begin{equation}
    \begin{tikzcd}
        \Hom_{\ul{R^+}}\left(\textstyle\prod_I \ul{R^+}, \hat{\oplus}_J \ul{R^+} \right)(S)[\tfrac{1}{p}] \arrow{r} \arrow{d} & \hom_{\Cont, R^+}(\textstyle\prod_I R^+, \hat{\oplus}_J R^+_{S})[\tfrac{1}{p}] \arrow{d} \\
        \Hom_{\ul{R}}((\textstyle\prod_I \ul{R^+})[\tfrac{1}{p}],  \hat{\oplus}_J \ul{R})(S) \arrow{r} & \hom_{\Cont, R}\left((\textstyle\prod_I R^+)[\tfrac{1}{p}], \hat{\oplus}_J R_{S}\right).
    \end{tikzcd}
\end{equation}
By the tensor-hom adjunction and the third claim of the proposition, it suffices to show that the left vertical arrow is an isomorphism. The top horizontal arrow is an isomorphism by the case handled above, and it follows as in the proof of Proposition \ref{Prop:DualityCondensed} that the right vertical arrow is an isomorphism. The bottom horizontal arrow is an isomorphism by Lemma \ref{Lem:PreEvaluationCondensed} (using Lemma \ref{Lem:CompactlyGenerated} to verify the assumptions), so we are done. \end{proof}
\begin{Rem}
    It is not true in general that the natural map $\left(\textstyle\prod_I \ul{R^+}\right) \otimes^{\blacksquare}_{\ul{R^+}} \ul{B^+} \to \textstyle\prod_I \ul{B^+}$ is an isomorphism, see Remark \ref{Rem:UncompletedTensor} and \cite[Theorem 3.27]{andreychev2021pseudocoherentperfectcomplexesvector}.
\end{Rem}

\subsection{Compact type and trace-class maps} \label{Sub:TraceClassCompact}  Let $(R,R^+)$ be a uniform Huber pair over $(\qp,\zp)$. Recall from \cite[Definition A.44]{Bosco} that a morphism $f: M \to N$ of solid $\ul{R}$-modules is said to be \emph{trace-class} if $f$ is in the image of the natural map
\begin{align}
  \left(\Hom_{\ul{R}}(M, \ul{R}) \otimes_{\ul{R}}^{\blacksquare} N\right)(\ast) \to \hom_{\ul{R}}(M,N).
\end{align}
More concretely, writing $M^{\ast}=\Hom_{\ul{R}}(M, \ul{R})$, there is a morphism $g:\ul{R} \to M^{\ast} \otimes_{\ul{R}}^{\blacksquare} N$ such that $f$ is equal to the composition
\begin{align}
    M = M \otimes_{\ul{R}}^{\blacksquare} \ul{R} \xrightarrow{1 \otimes g} M \otimes_{\ul{R}}^{\blacksquare} M^{\ast} \otimes_{\ul{R}}^{\blacksquare} N \xrightarrow{\operatorname{ev} \otimes 1} N
\end{align}
where $\mathrm{ev} \colon M \otimes_{\ul{R}}^{\blacksquare} M^{\ast} \to \ul{R}$ denotes the natural map (given by evaluation).
 The following lemma captures some of the basic properties of trace-class morphisms.
\begin{Lem} \label{Lem:TensorTraceClass}
    Let $(R,R^+) \to (B,B^+)$ be a morphism of uniform Huber pairs over $(\qp,\zp)$ and let $f:M \to N, f':M' \to N'$ be morphisms of solid $\ul{R}$-modules. 
\begin{enumerate}
    \item  If $f$ is trace-class, then so is $f \otimes 1_{\ul{B}}:M \otimes_{\ul{R}}^{\blacksquare} \ul{B} \to N \otimes_{\ul{R}}^{\blacksquare} \ul{B}$. 

    \item If $f$ and $f'$ are trace class, then so is $f \otimes f' : M \otimes_{\ul{R}}^{\blacksquare} M' \to N \otimes_{\ul{R}}^{\blacksquare} N'$. 

    \item If $f$ is trace class, then there exists a (not necessarily unique) dotted arrow in the commutative diagram 
    \begin{equation}
        \begin{tikzcd}
            M \arrow{r}{f}  \arrow{d} & N \arrow{d}\\
            M^{\ast \ast} \arrow{r}{f^{\ast \ast}} \arrow[ur, dashed, printersafe] & N^{\ast \ast},
        \end{tikzcd}
    \end{equation}
    making both triangles commute. Moreover, the map $f^{\ast \ast}$ is also trace-class.
\end{enumerate}    
\end{Lem}
\begin{proof}
The first statement follows directly from examining the commutative diagram
\begin{equation}
    \begin{tikzcd}
        \left(\Hom_{\ul{R}}(M, \ul{R}) \otimes_{\ul{R}}^{\blacksquare} N\right)(\ast) \arrow{r} \arrow{d} &\hom_{\ul{R}}(M,N) \arrow{d} \\
         \left(\Hom_{\ul{B}}(M \otimes_{\ul{R}}^{\blacksquare} \ul{B}, \ul{B}) \otimes_{\ul{B}}^{\blacksquare} N \otimes_{\ul{R}}^{\blacksquare} \ul{B} \right)(\ast) \arrow{r} & \hom_{\ul{B}}(M \otimes_{\ul{R}}^{\blacksquare} \ul{B}, N \otimes_{\ul{R}}^{\blacksquare} \ul{B}).
    \end{tikzcd}
\end{equation}
The second statement follows directly from the commutative diagram 
\begin{equation}
    \begin{tikzcd}
    & M \otimes_{\ul{R}}^{\blacksquare} M' \otimes_{\ul{R}}^{\blacksquare} \left(M \otimes_{\ul{R}}^{\blacksquare} M'\right)^{\ast}\otimes_{\ul{R}}^{\blacksquare} N \otimes_{\ul{R}} ^{\blacksquare} N' \arrow{dr} \\
   M \otimes_{\ul{R}}^{\blacksquare} M' \arrow{r} \arrow[ur, dashed, printersafe] & M \otimes_{\ul{R}}^{\blacksquare} M' \otimes_{\ul{R}}^{\blacksquare} M^{\ast} \otimes_{\ul{R}}^{\blacksquare} M^{'\ast} \otimes_{\ul{R}}^{\blacksquare} N \otimes_{\ul{R}} ^{\blacksquare} N' \arrow{r} \arrow{u} & N \otimes_{\ul{R}}^{\blacksquare} N'.
    \end{tikzcd}
\end{equation}
The third statement follows directly from the commutative diagram 
\begin{equation}
    \begin{tikzcd}
        & M^{\ast \ast} \otimes_{\ul{R}}^{\blacksquare} M^{\ast \ast \ast} \otimes_{\ul{R}}^{\blacksquare} N^{\ast \ast} \arrow{r} & N^{\ast \ast } \\
        M^{\ast \ast} \arrow{r} \arrow[dashed, printersafe, drr] \arrow[dashed, printersafe, ur] & M^{\ast \ast} \otimes_{\ul{R}}^{\blacksquare} M^{\ast} \otimes_{\ul{R}}^{\blacksquare} N \arrow{dr} \arrow{u} \\
        M \arrow{r} \arrow{u} & M \otimes_{\ul{R}}^{\blacksquare} M^{\ast} \otimes_{\ul{R}}^{\blacksquare} N \arrow{r} \arrow{u} & N \arrow{uu}.
    \end{tikzcd}
\end{equation}
\end{proof}

\subsubsection{} \label{subsub:compact} Let $(R,R^+)$ be a uniform Huber pair over $(\qp,\zp)$. Following \cite[Definition 3.33]{RJRC}, we define a morphism $f:M \to N$ of solid $\ul{R}$-modules to be \emph{compact} if the induced map
\begin{align}
    N^{\ast} \to M^{\ast}
\end{align}
is trace-class. Compact morphisms are not preserved under base change or tensor products in general: Consider $R=\mathbb{Q}_p\langle T \rangle$, $M=N=\hat{\oplus}_{\mathbb{Z}} \mathbb{Q}_p$, viewed as a module supported at $T=0$, and $f$ the identity map --- since $M^*=N^*=0$, the map $f$ is trivially compact, but its base change to $\mathbb{Q}_p$ is not compact. However, we do have the following result.
\begin{Lem} \label{Lem:CompactTensor}
    Let $(R,R^+) \to (B,B^+)$ be a morphism of uniform Huber pairs over $(\qp,\zp)$ and let $f:M \to N, f':M' \to N'$ be morphisms of solid $\ul{R}$-modules. Suppose that $M,N,M',N'$ are direct summands of countably orthonormalizable $\ul{R}$-modules.
    \begin{enumerate}
    \item  If $f$ is compact, then $f \otimes 1_{\ul{B}}:M \otimes_{\ul{R}}^{\blacksquare} \ul{B} \to N \otimes_{\ul{R}}^{\blacksquare} \ul{B}$ is compact (as a morphism of solid $\ul{B}$-modules). 

    \item If $f$ and $f'$ are both compact, then $f \otimes f' \colon M \otimes_{\ul{R}}^{\blacksquare} M' \to N \otimes_{\ul{R}}^{\blacksquare} N'$ is compact. 
    \end{enumerate}
\end{Lem}
\begin{proof}
For the first statement, we note that it follows from Propositions \ref{Prop:DualityCondensed} and \ref{Prop:TensorDualSmith} and the exactness of idempotent projection, that the natural map
\begin{align}
    M^{\ast} \otimes_{\ul{R}}^{\blacksquare} \ul{B} \to (M \otimes_{\ul{R}}^{\blacksquare} \ul{B})^{\ast}
\end{align}
identifies the target with the double dual of the source. It follows from Lemma \ref{Lem:TensorTraceClass}-(1) that $N^{\ast} \otimes_{\ul{R}}^{\blacksquare} \ul{B} \to M^{\ast} \otimes_{\ul{R}}^{\blacksquare} \ul{B}$ is trace class, and then from Lemma \ref{Lem:TensorTraceClass}-(3) that $(N \otimes_{\ul{R}}^{\blacksquare} \ul{B})^{\ast} \to (M \otimes_{\ul{R}}^{\blacksquare} \ul{B})^{\ast}$ is trace-class. For the second statement, a similar argument works once we note that
\begin{align}
    M^{\ast} \otimes_{\ul{R}}^{\blacksquare} N^{\ast} \to (M \otimes_{\ul{R}}^{\blacksquare} N)^{\ast}
\end{align}
identifies the target with the double dual of the source; this follows from Propositions \ref{Prop:DualityCondensed} and \ref{Prop:TensorDualSmith} and the exactness of idempotent projection. 
\end{proof}

\subsection{Fr\'echet modules and flatness} \label{Sub:Frechet}  Let $R$ be a $\qp$-Banach algebra. Recall that $\operatorname{Mod}_R^{\mathrm{cond}}$ denotes the category of condensed $\ul{R}$-modules, and that $\operatorname{Mod}_R^{\operatorname{solid}}$ denotes the subcategory of solid modules (i.e., modules over the analytic ring $(\ul{R}, \mbb{Z})_{\blacksquare}$ from \cite[Proposition A.29]{Bosco}, noting that $\ul{R}$ is solid). Let $\operatorname{Mod}_{R}^{\operatorname{nuc}}$ denote the full subcategory of $\operatorname{Mod}^{\operatorname{solid}}_R$ consisting of nuclear $\ul{R}$-modules (as in Definition A.40 of \emph{op.cit.}). Note that $\ul{R}$ is a nuclear solid $\mbb{Q}_p$-algebra (Corollary A.50 in \emph{op.cit.}).

Here are some properties of nuclear $\ul{R}$-modules. 

\begin{enumerate}
    \item $\operatorname{Mod}^{\operatorname{nuc}}_R$ is an abelian category stable under the solid tensor product $\otimes^{\blacksquare}_{\ul{R}}$, finite limits, countable products, and all colimits (see \cite[Theorem A.43]{Bosco}). 
    \item Orthonormalizable Banach $\ul{R}$-modules are nuclear and flat for the solid tensor product (\cite[Proposition A.55.(iii)]{Bosco}). Also, $\operatorname{Mod}^{\operatorname{nuc}}_R$ is generated under colimits by orthonormalizable Banach $\ul{R}$-modules (\cite[Proposition A.55.(ii)]{Bosco}).\footnote{We note that the objects denoted by $\Hom_{A}(A[S],A)$ in the statement of \cite[Proposition A.55.(ii)]{Bosco} are orthonormalizable Banach, and conversely any orthonormalizable Banach module is of this form. Indeed, this follows from \cite[Lemma A.52]{Bosco} and \cite[Proposition A.55.(i)]{Bosco}.}
    \item The subcategory of $\operatorname{Mod}_R^{\operatorname{nuc}}$ generated under filtered colimits by orthonormalizable Banach $R$-modules is stable under countable products (\cite[Proposition A.57]{Bosco}).
\end{enumerate}

\subsubsection{} Consider the following definition.
\begin{definition} \label{Def:Frechet}
We say a condensed $\ul{R}$-module $M$ is \emph{strongly Fr\'echet} if it is isomorphic to the limit of a countable inverse system $\{ M_n \}$ where each $M_n$ is a direct summand of an orthonormalizable Banach $\ul{R}$-module, and where the transition maps $M_{n+1}(\ast)_{\mathrm{top}} \to M_{n}(\ast)_{\mathrm{top}}$ have dense image. We say $M$ is \emph{strongly countably Fr\'echet} if each $M_n$ is a direct summand of a countably orthonormalizable Banach $\ul{R}$-module. We say that $M$ is of \emph{compact type} if the transition maps $M_{n+1} \to M_{n}$ are compact.
\end{definition}

We have the following crucial technical result about strongly Fr\'echet $\ul{R}$-modules.
\begin{Prop} \label{Prop:FrechetFlat}
If $M$ is a strongly Fr\'echet $\ul{R}$-module, then $M$ is flat for the solid tensor product $\otimes_{\ul{R}}^{\blacksquare}$.
\end{Prop}
\begin{proof}
    Let $M \simeq \varprojlim M_n$ as above. Since the forgetful functor $\operatorname{Mod}_R^{\mathrm{cond}} \to \operatorname{Mod}_{\mbb{Q}_p}^{\mathrm{cond}}$ has a left-adjoint, and exactness of sequences can be checked after composing with this forgetful functor, one has a short exact sequence 
    \[
    0 \to M \to \textstyle\prod_n M_n \xrightarrow{s} \textstyle\prod_n M_n \to 0
    \]
    where the map $s$ is the identity minus the transition morphisms. Here we are using \cite[Lemma A.37]{Bosco} with $F = \mbb{Q}_p$ to deduce that the sequence is exact on the right. Now each $M_n$ is a direct summand of an orthonormalizable Banach $\ul{R}$-module $N_n$, and it follows that
    \begin{align}
        \textstyle\prod_{n } M_n \subset \textstyle\prod_n N_n
    \end{align}
    is also the inclusion of a direct summand (take the product of the idempotents). By properties (1) and (2) above (second paragraph of \S\ref{Sub:Frechet}), the module $\textstyle\prod_n N_n$ is nuclear, and by property (3), it can be written as a filtered colimit of orthonormalizable Banach $\ul{R}$-modules. Since the solid tensor product commutes with filtered colimits, the category $\operatorname{Mod}^{\operatorname{solid}}_R$ satisfies (AB5), and orthonormalizable Banach $\ul{R}$-modules are flat (Lemma \ref{Lem:BanachFlat}), we see that $\textstyle\prod_n N_n$ is flat for the solid tensor product. This implies that $\textstyle\prod_{n } M_n$ is flat for the solid tensor product since direct summands of (solidly) $\ul{R}$-flat modules are again (solidly) $\ul{R}$-flat.

    Let $N$ be a solid $\ul{R}$-module, and let $\operatorname{Tor}_i^{R, \blacksquare}(-, N)$ denote the $i$-th left derived functor of $- \otimes_{\ul{R}}^{\blacksquare} N$. Passing to the long exact sequence for the above exact sequence, we see that $\operatorname{Tor}_i^{R, \blacksquare}(M, N)$ ($i \geq 1$) sits in the exact sequence
    \[
    \operatorname{Tor}_{i+1}^{R, \blacksquare}(\textstyle\prod_n M_n, N) \to \operatorname{Tor}_i^{R, \blacksquare}(M, N) \to \operatorname{Tor}_i^{R, \blacksquare}(\textstyle\prod_n M_n, N) .
    \]
    Now, since $\textstyle\prod_n M_n$ is flat for the solid tensor product, both of the outer terms vanish (since $i \geq 1$). This implies that $\operatorname{Tor}_i^{R, \blacksquare}(M, N) = 0$ for all $i \geq 1$ and all solid $N$, and hence $M$ is flat for the solid tensor product.
\end{proof}

\subsubsection{} We collect the following lemmas. We call an $\ul{R}$-module $M$ a \emph{Banach} module if $M=\ul{M^+}[\tfrac{1}{p}]$ where $M^+$ is a $p$-torsion free $p$-adically complete and separated topological $R^+$-module with the $p$-adic topology. Note that Banach $R^+$-modules are automatically metrizable, hence compactly generated. 

\begin{Lem} \label{Lem:DenseImageTensor}
    Let $(R,R^+)$ be a uniform Huber pair over $(\qp,\zp)$, let $M_{1}$ and $M_2$ be direct summands of orthonormalizable Banach $\ul{R}$-modules and let $N$ be a Banach $\ul{R}$-module. If $f:M_{1} \to M_{2}$ is a morphism of $\ul{R}$-modules whose induced morphism on topological $R$-modules has dense image, then the same is true for
    \begin{align}
        f \otimes_{\ul{R}}^{\blacksquare} \operatorname{Id}_{N}: M_1 \otimes_{\ul{R}}^\blacksquare N \to M_2 \otimes_{\ul{R}}^\blacksquare N.
    \end{align}
\end{Lem}
\begin{proof}
Using Lemma \ref{Lem:DenseImageTensorTopological}, it suffices to prove that for $i=1,2$ we have 
\begin{align}
    \left(M_i \otimes_{\ul{R}}^\blacksquare N\right)(\ast)_{\mathrm{top}} \simeq M_i(\ast)_{\mathrm{top}} \widehat{\otimes}_{R} N(\ast)_{\mathrm{top}}.
\end{align}
This is true when $M_i$ is orthonormalizable by Proposition \ref{Prop:TensorProductsSolidVSComplete} (because then $M_i=M_i^+[\tfrac{1}{p}]$ with $M_i^+$ flat over $\ul{R^+}$ for the solid tensor product, see Lemma \ref{Lem:BanachFlat}). The case of direct summands follows from the additivity of the completed projective tensor product. 
\end{proof}

\begin{Lem} \label{Lem:DualOfFrechet}
    Let $M=\varprojlim_n M_n$ be a strongly Fr\'echet $R$-module with presentation as in Definition \ref{Def:Frechet}. Then the natural map
    \begin{align}
        \varinjlim_n \Hom_{\ul{R}}(M_n, \ul{R}) \to \Hom_{\ul{R}}(\varprojlim_n M_n, \ul{R})
    \end{align}
    is an isomorphism. 
\end{Lem}
\begin{proof}
It suffices to check this on $S$-points for profinite sets $S$. By the adjunction argument of Lemma \ref{Lem:PreEvaluationCondensed}, this comes down to showing that 
\begin{align}
     \varinjlim_n \hom_{\ul{R}}(M_n, \ul{R_{S}}) \to \hom_{\ul{R}}(M, \ul{R_{S}})
\end{align}
is a bijection. Now $M_n(\ast)_{\mathrm{top}}$ is compactly generated and thus $\varprojlim_n M_n(\ast)_{\mathrm{top}}$ is compactly generated.\footnote{Indeed, each $M_n$ has the $p$-adic topology and is thus metrizable, which shows that $\textstyle\prod_n M_n$ is also metrizable. Now use that $\varprojlim_n M_n \subset \textstyle\prod_n M_n$ is closed and thus metrizable and hence compactly generated. } Since $\ul{\varprojlim_n M_n(\ast)_{\mathrm{top}}}=M$, we can use Lemma \ref{Lem:Fullyfaithful} to reduce to showing that the natural map
\begin{align}
     \varinjlim_n \hom_{C^0, R}(M_n(\ast)_{\mathrm{top}}, R_{S}) \to \hom_{C^0, R}(M(\ast)_{\mathrm{top}}, R_{S})
\end{align}
is a bijection. Note that $M$ is a $\qp$-Fr\'echet space and that $R_S$ is a $\qp$-Banach space, so that the result follows from the proof of \cite[Lemma 3.31]{RJRC} (here we are using the property that $M(\ast)_{\mathrm{top}} \to M_n(\ast)_{\mathrm{top}}$ has dense image to conclude that any $f \in \hom_{C^0, R}(M(\ast)_{\mathrm{top}}, R_{S})$ factors through a continuous \emph{$R$-linear} morphism $M_n(\ast)_{\mathrm{top}} \to R_S$, for some $n$).
\end{proof}
\subsubsection{} Let $V = \varprojlim_m V_m$ be a strongly countably Fr\'echet $\ul{R}$-module written as an inverse limit as in Definition \ref{Def:Frechet}. Let $\{W_n\}$ be a countable family of direct summands of orthonormalizable Banach $\ul{R}$-modules. We have the following proposition.
\begin{Prop} \label{Prop:TensorCommuteProducts}
The natural map
 \begin{align}
      V \otimes_{\ul{R}}^{\blacksquare} \textstyle\prod_n W_n  \to \textstyle\prod_{n}\left( V  \otimes_{\ul{R}}^{\blacksquare} W_n\right)
    \end{align}
    is an isomorphism.
\end{Prop}
\begin{proof}
We follow the proof of \cite[Proposition A.66]{Bosco}: As in the proof of Proposition \ref{Prop:FrechetFlat}, we can fit $V$ in a short exact sequence
\begin{align}
    0 \to V \to \textstyle\prod_m V_m \to \textstyle\prod_m V_m \to 0.
\end{align}
We now consider the commutative diagram
\begin{equation}
    \begin{tikzcd}
        0 \arrow{r} & V \otimes_{\ul{R}}^{\blacksquare} \textstyle\prod_n W_n \arrow{d} \arrow{r} &  \left(\textstyle\prod_m V_m\right) \otimes_{\ul{R}}^{\blacksquare} \left(\textstyle\prod_n W_n \right)\arrow{d} \arrow{r} &  \left(\textstyle\prod_m V_m\right) \otimes_{\ul{R}}^{\blacksquare} \left(\textstyle\prod_n W_n \right)\arrow{d} \arrow{r} & 0 \\
        0 \arrow{r} & \textstyle\prod_{n}\left( V  \otimes_{\ul{R}}^{\blacksquare} W_n\right) \arrow{r} & \arrow{r} \textstyle\prod_{n}\left( \textstyle\prod_{m} V_m  \otimes_{\ul{R}}^{\blacksquare} W_n\right) & \textstyle\prod_{n}\left( \textstyle\prod_{m} V_m  \otimes_{\ul{R}}^{\blacksquare} W_n\right) \arrow{r} & 0.
    \end{tikzcd}
\end{equation}
Note that the top row is exact because $\textstyle\prod_n W_n$ is flat by Proposition \ref{Prop:FrechetFlat}, and the bottom row is exact by the exactness of countable products (AB4*). By the five-lemma, the proposition reduces to the case that $V=\textstyle\prod_{m} V_m$. By an argument with idempotents as in the proof of Proposition \ref{Prop:FrechetFlat}, this reduces to showing that for countable index sets $I$ and $J$, the natural map
\begin{align} \label{Eq:ProductBanachMap}
    \left(\textstyle\prod_m \hat{\oplus}_{I} \ul{R} \right) \otimes^{\blacksquare}_{\ul{R}} \left(\textstyle\prod_n \hat{\oplus}_{J} \ul{R}\right) \xrightarrow{} \textstyle\prod_{n} \left(\textstyle\prod_{m} \hat{\oplus}_{I} \ul{R} \otimes^{\blacksquare}_{\ul{R}} \hat{\oplus}_{J} \ul{R} \right)
\end{align}
is an isomorphism.\footnote{More precisely, we can assume $V_m \simeq \hat{\oplus}_{I_m} \ul{R}$ and $W_n \simeq \hat{\oplus}_{J_n} \ul{R}$ for countable index sets $I_m$ and $J_n$, and without loss of generality, we may assume that $I_m = J_m = \mbb{Z}$ (since finite-free $\ul{R}$-modules are direct summands of $\hat{\oplus}_{\mbb{Z}} \ul{R}$).} By the discussion in the last paragraph of the proof of \cite[Proposition A.57]{Bosco} (they write $A$ for what we call $\ul{R}$ and $M_A$ for our $\hat{\oplus}_{I} \ul{R}$ and we are taking $F=\ul{\qp}$) we can identify
\begin{align}
    \textstyle\prod_m \hat{\oplus}_{I} \ul{R} = \left(\hat{\oplus}_{I} \ul{\qp}\right) \otimes^{\blacksquare}_{\ul{\qp}} \left(\textstyle\prod_{m} \ul{\qp}\right) \otimes^{\blacksquare}_{\ul{\qp}} \ul{R},
\end{align}
since $\hat{\oplus}_{I} \ul{R} = \hat{\oplus}_{I} \ul{\qp} \otimes^{\blacksquare}_{\ul{\qp}} \ul{R}$, see Proposition \ref{Prop:StandardBCproperty}. Thus we can rewrite the left hand side of \eqref{Eq:ProductBanachMap} as
\begin{align}
    \left(\hat{\oplus}_{I} \ul{\qp}\right) \otimes^{\blacksquare}_{\ul{\qp}}  \left(\hat{\oplus}_{J} \ul{\qp}\right) \otimes^{\blacksquare}_{\ul{\qp}} \left(\textstyle\prod_{m} \ul{\qp}\right) \otimes^{\blacksquare}_{\ul{\qp}} \left(\textstyle\prod_{n} \ul{\qp}\right)\otimes^{\blacksquare}_{\ul{\qp}} \ul{R}.
\end{align}
By \cite[Corollary A.59]{Bosco}, the proposition reduces to proving that the natural map
\begin{align}
    \left(\textstyle\prod_{m} \ul{\qp}\right) \otimes^{\blacksquare}_{\ul{\qp}} \left(\textstyle\prod_{n} \ul{\qp}\right) \to \textstyle\prod_{n,m} \ul{\qp}
\end{align}
is an isomorphism; this is explained at the end of \cite[Proposition A.66]{Bosco}, see \cite[Equation A.22]{Bosco}. 
\end{proof}
\subsubsection{} Let $V = \varprojlim_m V_m$ and $W=\varprojlim_n W_n$ be strongly countably Fr\'echet $R$-modules written as inverse limits as in Definition \ref{Def:Frechet}. We have the following proposition.
\begin{Prop} \label{Prop:TensorInverseLimit}
The natural map
 \begin{align}
      V \otimes_{\ul{R}}^{\blacksquare} W \to \varprojlim_{m,n} \left(V_{m} \otimes_{\ul{R}}^{\blacksquare} W_n\right)
    \end{align}
    is an isomorphism.
\end{Prop}
\begin{proof}
We follow the proof of \cite[Corollary A.67]{Bosco}. As in the proof of Proposition \ref{Prop:FrechetFlat}, there is an exact sequence
\begin{align}
    0 \to W \to \textstyle\prod_n W_n\to \textstyle\prod_n  W_n \to 0.
\end{align}
By the flatness proved in Proposition \ref{Prop:FrechetFlat}, it remains exact after taking the tensor product with $V$, giving 
\begin{align}
    0 \to V \otimes^{\blacksquare}_{\ul{R}} W \to V \otimes^{\blacksquare}_{\ul{R}} \textstyle\prod_n W_n\to V \otimes^{\blacksquare}_{\ul{R}} \textstyle\prod_n W_n \to 0.
\end{align}
Applying Proposition \ref{Prop:TensorCommuteProducts} gives us the exact sequence
\begin{align}
    0 \to V \otimes^{\blacksquare}_{\ul{R}} W \to \textstyle\prod_n \left(V \otimes^{\blacksquare}_{\ul{R}}  W_n\right) \to \textstyle\prod_n \left(V \otimes^{\blacksquare}_{\ul{R}}  W_n\right) \to 0,
\end{align}
which exhibits $V \otimes^{\blacksquare}_{\ul{R}} W$ as the projective limit $\varprojlim_n \left(V \otimes^{\blacksquare}_{\ul{R}} W_n\right)$. 
The same argument after tensoring $W_n$ with the exact sequence
\begin{align}
    0 \to V \to \textstyle\prod_m V_m\to \textstyle\prod_m  V_m \to 0.
\end{align}
shows that the natural map
\begin{align}
    V \otimes^{\blacksquare}_{\ul{R}} W_n\to \varprojlim_m (V_m \otimes^{\blacksquare}_{\ul{R}}  W_n)
\end{align}
is an isomorphism, completing the proof.
\end{proof}

\begin{Cor} \label{Cor:DualTensorCommute}
    For strongly countably Fr\'echet $\ul{R}$-modules $V$ and $W$ of compact type, the natural map
\begin{align}
    \Hom_{\ul{R}}(V, \ul{R}) \otimes_{\ul{R}}^{\blacksquare} \Hom_{\ul{R}}(W, \ul{R}) \to \Hom_{\ul{R}}(V \otimes_{\ul{R}}^{\blacksquare} W, \ul{R})
\end{align}
is an isomorphism.
\end{Cor}
\begin{proof}
Write $V=\varprojlim V_n, W=\varprojlim_m V_m$ as before and define $H_{n,m}=V_n \otimes^{\blacksquare}_{\ul{R}} W_m$. It follows from Lemma \ref{Lem:DenseImageTensor}, Lemma \ref{Lem:BanachFlat} that the transition maps $H_{n+1, m}(\ast)_{\mathrm{top}} \to H_{n,m}(\ast)_{\mathrm{top}}$ and $H_{n,m+1}(\ast)_{\mathrm{top}} \to H_{n,m}(\ast)_{\mathrm{top}}$ have dense image. Moreover, it is clear that each $H_{n,m}$ is a direct summand of $\hat{\oplus}_{I} \ul{R}$ for some countable set $I$. If we combine this analysis with Lemma \ref{Lem:CompactTensor}, we see that $H=\varprojlim_{n,m} H_{n,m}$ is strongly countably Fr\'echet of compact type. \smallskip

It now follows from Lemma \ref{Lem:DualOfFrechet} and Proposition \ref{Prop:TensorInverseLimit} that we may identify the map of the corollary with
\begin{align}
    \varinjlim_{n,m} V_n^{\ast} \otimes_{\ul{R}}^{\blacksquare} W_m^{\ast} \to \varinjlim_{n,m} H_{n,m}^{\ast}. 
\end{align}
We first note that it follows from Lemma \ref{Lem:TensorTraceClass}-(2) and Proposition \ref{Prop:DualityCondensed} that the transition maps in the direct system $\{ V_n^{\ast} \otimes_{\ul{R}}^{\blacksquare} W_m^{\ast}\}$ are trace class. It follows as in the proof of Lemma \ref{Lem:CompactTensor} that the natural maps
\begin{align}
   V_n^{\ast} \otimes_{\ul{R}}^{\blacksquare} W_m^{\ast} \to H_{n,m}^{\ast} 
\end{align}
identify the target with the double dual of the source. Consider the commutative diagram
\begin{equation}
    \begin{tikzcd}
        V_n^{\ast} \otimes_{\ul{R}}^{\blacksquare} W_m^{\ast} \arrow{d} \arrow{r} & V_{n+1}^{\ast} \otimes_{\ul{R}}^{\blacksquare} W_{m+1}^{\ast} \arrow{d} \\
        H_{n,m}^{\ast} \arrow{r} \arrow[ur, dashed, printersafe] & H_{n+1,m+1}^{\ast},
    \end{tikzcd}
\end{equation}
where we note that the bottom arrow is the double dual of the top arrow. It follows from Lemma \ref{Lem:TensorTraceClass}-(3) that the dashed arrow exists in a way that makes both triangles commute. This shows that the natural map
\begin{align}
      \varinjlim_{n,m} V_n^{\ast} \otimes_{\ul{R}}^{\blacksquare} W_m^{\ast} \to \varinjlim_{n,m} H_{n,m}^{\ast}
\end{align}
is an isomorphism. 
\end{proof}
\begin{Cor} \label{Cor:DualTensorFrechetBaseChange}
Let $V = \varprojlim_m V_m$ be a strongly countably Fr\'echet $\ul{R}$-module of compact type written as an inverse limit as in Definition \ref{Def:Frechet}. If $(R,R^+) \to (B,B^+)$ is a morphism of uniform Huber pairs over $(\qp,\zp)$, then the natural map
    \begin{align}
        V^{\ast} \otimes_{\ul{R}}^{\blacksquare} \ul{B} \to (V \otimes_{\ul{R}}^{\blacksquare} \ul{B})^{\ast}
    \end{align}
    is an isomorphism. 
\end{Cor}
\begin{proof}
Using Proposition \ref{Prop:TensorCommuteProducts} and Lemma \ref{Lem:DenseImageTensor} we find that $V \otimes_{\ul{R}}^{\blacksquare} \ul{B} \xrightarrow{\sim} \varprojlim_n (V_n \otimes_{\ul{R}}^{\blacksquare} \ul{B})$ is a strongly countably Fr\'echet $\ul{B}$-module. By Lemma \ref{Lem:DualOfFrechet} we may moreover identify the map of the corollary with
    \begin{align}
        \varinjlim_{n} V_n^{\ast} \otimes_{\ul{R}}^{\blacksquare} \ul{B} \to \varinjlim_{n} (V_n  \otimes_{\ul{R}}^{\blacksquare} \ul{B})^{\ast}.
    \end{align}
It follows as in the proof of Lemma \ref{Lem:CompactTensor} that the natural maps
\begin{align}
  V_n^{\ast} \otimes_{\ul{R}}^{\blacksquare} \ul{B} \to (V_n  \otimes_{\ul{R}}^{\blacksquare} \ul{B})^{\ast}.
\end{align}
identify the target with the double dual of the source. By Proposition \ref{Prop:DualityCondensed} (and the fact that $V$ is of compact type) the transition maps in the direct system $\{V_n^{\ast}\}$ are trace class. The corollary now follows as in the proof of Corollary \ref{Cor:DualTensorCommute} from Lemma \ref{Lem:TensorTraceClass}-(3).
\end{proof}


\section{Sheaves on v-stacks} \label{Sec:VSheaves} In this section we introduce a way to think about sheaves of $\mathcal{O}$-modules on nice analytic adic spaces over $\spa(\qp,\zp)$. In fact, we develop a theory that works for arbitrary small v-stacks on the site of affinoid perfectoid spaces over $\spa(\qp,\zp)$. In \S \ref{Sub:Prelim} we collect preliminaries about small v-stacks and sheaves of $\mathcal{O}$-modules on them, and introduce the notion of (fiercely) v-complete affinoid analytic adic spaces. In \S \ref{Sub:Standard}, we introduce certain standard sheaves of $\mathcal{O}$-modules and check that they (and their duals) take the expected values on v-complete affinoid analytic adic spaces. We also introduce a notion of (locally strongly countably) Fr\'echet sheaves of $\mathcal{O}$-modules in this setting, and similarly prove that they take the expected values on v-complete affinoid analytic adic spaces. In \S \ref{Sub:GeometricOrigin} we prove a criterion for checking that a sheaf ``of geometric origin" is Fr\'echet, and also prove the K\"unneth formula for sheaves ``of geometric origin". 

\newcommand{\perfd}{{\mathrm{Perfd}}}
\subsection{Preliminaries} \label{Sub:Prelim} We write $\perfd$ for the opposite of the category of perfectoid Huber pairs $(A,A^{+})$ over $(\qp,\zp)$, equipped with the v-topology, see \cite[Definition 8.1]{EtCohDiam}. We will consider stacks and sheaves in the v-topology, with an important example being the representable sheaf $\spd(A,A^+)$ for $(A,A^+) \in \perfd$. A sheaf (or stack) $X$ on $\perfd$ in the v-topology is called \emph{small} (see \cite[Section 4]{EtCohDiam}) if there is an uncountable strong limit cardinal $\kappa$, an index set $I$ of cardinality bounded by $\kappa$, a collection of $\kappa$-small perfectoid Huber pairs $(A_i,A_{i}^+)$ over $\spa(\qp,\zp)$ for $i \in I$, and a surjection 
\begin{align}
    \coprod_{i \in I} \spd(A_i, A_i^+) \to X. 
\end{align}
An important example of a small v-sheaf is $X^{\lozenge}$, where $X$ is an analytic adic space over $\spa(\qp,\zp)$, see \cite[Definition 15.5]{EtCohDiam}. In the affinoid case, we will write $\spd(R,R^+)$ for $\spa(R,R^+)^{\lozenge}$.

For a small v-stack we will write $X_{\mv}$ for the full subcategory of (small) v-sheaves $Y \to X$ where $Y=\spd(A,A^+)$ for $(A,A^+)$ a perfectoid Huber pair over $(\qp,\zp)$. This definition is different from \cite[Definition 14.1]{EtCohDiam}, which takes the category of all (small) v-sheaves $Y \to X$. However, this does not affect the category of v-sheaves on $X_v$ since every small v-sheaf $Y \to X$ can be covered by a disjoint union of $\spd(A,A^+)$'s.

\subsubsection{} Let us write $\prof$ for the category of profinite sets as before. There is a natural functor from $\prof$ to small sheaves on $\perfd$ sending $T \to \ul{T}=\spd(C^0(T,\qp), C^0(T,\zp))$, where for a topological ring $Y$ the ring $C^0(T,Y)$ is the ring of continuous functions from $T$ to $Y$, equipped with the compact-open topology. We note that by Lemma \ref{Lem:CompactOpen}, if $(R,R^+)$ is a Huber pair over $(\qp,\zp)$, then so is $(C^0(T,R), C^0(T,R^+))$. If $(R,R^+)$ is moreover affinoid perfectoid, then so is $(C^0(T,R), C^0(T,R^+))$, see \cite[Example 11.12]{EtCohDiam}. We note that $\ul{T}$ represents the functor sending $\spa(R,R^+)$ to the set of continuous functions from $|\spa(R,R^+)|$ to $T$; we will often use this in the case of $T=\zp$. \smallskip

A sheaf $\mathcal{F}$ on $X_{\mv}$ determines a sheaf of condensed sets $\mathcal{F}_{\cond}$ on $X_{\mv}$ which takes $(A,A^{+}) \in X_{\mv}$ to the condensed set\footnote{That this is a condensed set follows from the fact that if $S \to T$ is a surjective map of profinite sets, then $\spd(C^{0}(S,A), C^{0}(S,A^{+})) \to \spd(C^{0}(T,A), C^{0}(T,A^{+}))$ is a v-cover.} sending $T \in \prof$ to the set $\mathcal{F}((C^{0}(T,A), C^{0}(T,A^{+}))$. We will sometimes write $\mathcal{F}_{\cond}(-)=H^0_{\cond}(-,\mathcal{F})$, and we note that the functor sending $(A,A^+) \in X_{\mv}$ to $\mathcal{F}_{\cond}(A,A^+)$ commutes with limits and filtered colimits. 

\subsubsection{} There is a presheaf of rings $\mathcal{O}$ on $\perfd$ sending $(A,A^{+}) \mapsto A$ and similarly a presheaf $\mathcal{O}^{+}$ of rings sending $(A,A^{+}) \mapsto A^{+}$; these are sheaves by \cite[Theorem 8.7]{EtCohDiam}. Note that $\mathcal{O}^+[\frac{1}{p}]=\mathcal{O}$. If $X$ is a small v-stack, then we will write $\mathcal{O}_X$ and $\mathcal{O}_{X}^+$ for the inverse image of $\mathcal{O}$ and $\mathcal{O}^+$ along the structure map $X \to \spd \qp$. The following observation will be useful.
\begin{Lem} \label{Lem:PullBackO}
    Let $f:X \to Y$ be a morphism of small v-sheaves, then $f^{-1} \mathcal{O}_X = \mathcal{O}_Y$ and $f^{-1} \mathcal{O}_X^{+}=\mathcal{O}_Y^{+}$.
\end{Lem}
\begin{proof}
This follows directly from the definitions, since we are pulling back to slice categories. More precisely, for $\spd(A,A^+) \to X$ we have that $\left(f^{-1}\mathcal{O}_{Y}\right)(\spd(A,A^+) \to X)$ will be given by $\mathcal{O}_Y(\spd(A,A^+) \to X \to Y)=A$ which equals $\mathcal{O}_X(\spd(A,A^+) \to X)$.
\end{proof}
From now on we will write $f^{\ast}$ for $f^{-1}$. Because of Lemma \ref{Lem:PullBackO}, this will cause no ambiguity.

\begin{Cor} \label{Cor:CohomologyAndBaseChange}
Given a Cartesian diagram of small v-sheaves
\begin{equation}
\begin{tikzcd}
X' \arrow{r}{g'} \arrow{d}{f'} & X \arrow{d}{f} \\
Y' \arrow{r}{g} & Y, 
\end{tikzcd}
\end{equation}
there is a natural base change isomorphism
\begin{align}
g^{\ast} f_{\ast} \mathcal{O}_X \to f'_{\ast} \mathcal{O}_{X'}.
\end{align}
\end{Cor}
\begin{proof}
There is a natural base change map $g^{\ast} f_{\ast} \mathcal{O}_X \to f'_{\ast} (g')^{\ast} \mathcal{O}_X$ for abstract reasons, and we can identify $\mathcal{O}_{X'}= (g')^{\ast} \mathcal{O}_X$ using Lemma \ref{Lem:PullBackO}. The natural base change map is moreover an isomorphism because base change always holds when restricting to slice categories, cf. \cite[Proposition 17.6]{EtCohDiam}.
\end{proof}

\subsubsection{} Let $(R,R^+)$ be a uniform Huber pair over $\spa(\qp,\zp)$ and consider $U=\spa(R,R^+)$. Then we can consider $U^{\lozenge}=\spd(R,R^+)$ as a small v-sheaf on $\perfd$ as above. We can thus consider the condensed ring $H^0_{\cond}(U^{\lozenge}, \mathcal{O})$. Recall that $(R,R^+)$ as above is called v-complete, see \cite[Definition 9.6]{HansenKedlaya}, if the natural map $(R,R^+) \to (H^0(U^{\lozenge}, \mathcal{O}),H^0(U^{\lozenge}, \mathcal{O}^+)) $ is a bijection. The following lemma is implicit in \cite[Section 9]{HansenKedlaya}. 
\begin{Lem} \label{Lem:CondensedRingStructure}
If $(R,R^+)$ is v-complete, then the condensed ring $H^0_{\cond}(U^{\lozenge}, \mathcal{O})$ is isomorphic to the condensed ring $\underline{R}$ associated to the topological ring $R$.
\end{Lem}

\subsubsection{} \label{subsub:HuberFiberProduct} Let $(R,R^+) \to (P,P^+)$ and $(R,R^+) \to (Q,Q^+)$ be morphisms of uniform Huber pairs over $\spa(\qp,\zp)$. Recall that the fiber product $\spd(P,P^+) \times_{\spd(R,R^+)} \spd(Q,Q^+)$ is given by $\spd(E,E^+)$, where
\begin{align}
    E = \left(P^+ \widehat{\otimes}_{R^+} Q^+ \right)[\tfrac{1}{p}]
\end{align}
and where $E^+$ is the integral closure of the image of $P^+ \hat{\otimes}_{R^+} Q^+$ in $E$. In this generality, we caution that $(E,E^+)$ may not have nice properties such as uniformity or $v$-completeness, even if all three terms in the fiber product have these properties. However, it follows from the construction and  Proposition \ref{Prop:TensorProductsSolidVSComplete} and its proof that, for a profinite set $S$ and a uniform Huber pair $(R,R^+)$ over $(\qp,\zp)$, we have
\begin{align} \label{Eq:ProductProfiniteSet}
    \spd(R,R^+) \times_{\spd \qp} \ul{S} = \spd(C^{0}(S,R), C^{0}(S, R^{+})).
\end{align}


\begin{proof}[Proof of Lemma \ref{Lem:CondensedRingStructure}]
It follows from \cite[Lemma 3.6.26]{KedlayaLiu} that we can find a faithfully profinite \'etale Galois morphism $(R,R^+) \to (A,A^{+})$ with $(A,A^{+})$ affinoid perfectoid (note that v-complete implies uniform). Let $\Gamma$ be the Galois group of $\spa(A,A^{+}) \to \spa(R,R^+)$. \smallskip

The condensed ring $H^0_{\cond}(U^{\lozenge}, \mathcal{O})$ is naturally identified with $H^0_{\cond}(\spd(A,A^{+}), \mathcal{O})^{\underline{\Gamma}}$ using v-descent. On the other hand since $R$ is v-complete we deduce from \cite[Lemma 9.7]{HansenKedlaya} that the natural map $R \to A^{\Gamma}=H^0_{\cond}(\spd(A,A^{+}), \mathcal{O})^{\underline{\Gamma}}(\ast)$ is a bijection. Since $R$ has the subspace topology inside $A$, this means that $R=A^{\Gamma}$ as topological rings. Since the functor $R \mapsto \underline{R}$ is a right adjoint, it commutes with limits such as taking fixed points. It thus suffices to show that $H^0_{\cond}(\spd(A,A^{+}), \mathcal{O})=\underline{A}$ for all $(A,A^{+}) \in \perfd$. \smallskip

By definition, this means that we need to show that for $T \in \prof$ we have a natural identification $H^0_{\cond}(\spd(A,A^{+}), \mathcal{O})(T) = C^{0}(T,A)$. But this is a tautology since
\begin{align}
    H^0_{\cond}(\spd(A,A^{+}), \mathcal{O})(T) &= H^0((\spd(A,A^{+}) \times \underline{T}), \mathcal{O}) \\ &= H^0(\spd(C^{0}(T,A), C^{0}(T, A^{+})), \mathcal{O}) \\
    &=C^{0}(T,A)
\end{align}
by equation \eqref{Eq:ProductProfiniteSet} (and using that $C^0(T,A)$ is perfectoid). 
\end{proof}

\subsubsection{} \label{subsub:Fierce} The class of v-complete Huber pairs over $\spa(\qp,\zp)$ is not known to have good permanence properties, for example under rational localisations, finite \'etale maps, or the formation of Tate-algebras. For our purposes, we need a class of v-complete Huber pairs that does have these permanence properties. 
\begin{Def} \label{Def:Fierce}
Consider the largest full subcategory $\mathcal{C}_{\mathrm{frc}}$ of the category of all v-complete Huber pairs $(R,R^+)$ over $(\qp,\zp)$ such that:
\begin{itemize}
    \item If $(R,R^+) \in \mathcal{C}_{\mathrm{frc}}$, then for all rational localisations $(R,R^+) \to (B,B^+)$, we have that $(B,B^+) \in \mathcal{C}_{\mathrm{frc}}$. 

    \item If $(R,R^+) \in \mathcal{C}_{\mathrm{frc}}$, then for all finite \'etale morphisms $(R,R^+) \to (B,B^+)$, we have that $(B,B^+) \in \mathcal{C}_{\mathrm{frc}}$.

    \item If $(R,R^+) \in \mathcal{C}_{\mathrm{frc}}$, then $(R\langle T \rangle, \overline{R^+\langle T \rangle}) \in \mathcal{C}_{\mathrm{frc}}$.
\end{itemize}
Objects of $ \mathcal{C}_{\mathrm{frc}}$ are called \emph{fiercely v-complete Huber pairs}.
\end{Def}
\begin{Lem} \label{Lem:Fierce}
The following classes of Huber pairs over $(\qp,\zp)$ are fiercely v-complete: 
\begin{itemize}
        \item Affinoid perfectoid Huber pairs.

        \item Diamantine Huber pairs in the sense of \cite[Definition 11.1]{HansenKedlaya}.

        \item Huber pairs $(R,R^+)$ over $(K, \mathcal{O}_K)$ with $K$ a nonarchimedean field, such that $R$ is a seminormal affinoid algebra over $K$.\footnote{Recall that an affinoid algebra over $K$ is a quotient of $K\langle X_1, \cdots, X_n \rangle$ for some $n$.} 
    \end{itemize}
\end{Lem}
\begin{proof}
    Affinoid perfectoid Huber pairs are diamantine by \cite[Proposition 11.3]{HansenKedlaya}, so the second bullet point implies the first. The second bullet point follows from the fact that diamantine Huber pairs are themselves stable under rational localisations (\cite[Theorem 11.10]{HansenKedlaya}), finite \'etale morphisms (\cite[Lemma 11.13]{HansenKedlaya}), and forming 
    Tate algebras (\cite[Corollary 11.5]{HansenKedlaya}), and that diamantine Huber pairs are v-complete by definition. \smallskip

    To establish the third bullet point, we note that the affinoid algebras $(R,R^+)$ over $K$ with $R$ seminormal are v-complete (e.g. by \cite[Theorem 10.3]{HansenKedlaya}). Moreover, being seminormal is preserved under rational localization and finite \'etale morphisms (\cite[Lemma 6.4]{HansenKedlaya}), and under the formation of Tate algebras by \cite[Theorem 10.3, Lemma 11.4]{HansenKedlaya}. 
\end{proof}
\begin{Def} \label{Def:LocallyFiercelyVComplete}
    An analytic adic space $Y$ over $\spa(\qp,\zp)$ is said to be \emph{locally fiercely v-complete} if $Y$ is locally of the form $\spa(R,R^+)$ with $(R,R^+)$ fiercely v-complete.
\end{Def}
\begin{Lem} \label{Lem:FiercelyFullyFaithful}
    Let $X,Y$ be locally fiercely v-complete analytic adic spaces over $\spa(\qp,\zp)$. Then the natural map
    \begin{align}
        \hom(X,Y) \to \hom_{\spd \qp}(X^{\lozenge}, Y^{\lozenge})
    \end{align}
   is a bijection.
\end{Lem}
\begin{proof}
    It follows from Definition \ref{Def:Fierce} that $X$ and $Y$ are stably v-complete in the sense of \cite[Definition 9.5]{Kim}. The lemma is now a consequence of \cite[Lemma 9.8]{Kim}.
\end{proof}

\begin{Def} \label{Def:StronglySmooth}
    Let $(R,R^+)$ be a uniform Huber pair over $(\qp,\zp)$. We say that $(R,R^+) \to (P,P^+)$ is \emph{strongly smooth} if $(R,R^+) \to (P,P^+)$ factors as
    \begin{align}
        (R,R^+) \to (R\langle X_1, \cdots, X_k \rangle, \overline{R^+\langle X_1, \cdots, X_k \rangle}) \xrightarrow{f} (P,P^+),
    \end{align}
    with $f$ finite \'etale. 
\end{Def}
\begin{Lem} \label{Lem:SmoothOverFierce}
Let $(R,R^+) \to (B,B^+)$ be a morphism of Huber pairs over $(\qp, \zp)$ which 
is strongly smooth. If $(R,R^+)$ is fiercely v-complete, then so is $(B,B^+)$. 
\end{Lem}
\begin{proof}
This is a direct consequence of Definition \ref{Def:Fierce} and Definition \ref{Def:StronglySmooth}. 
\end{proof}

\subsubsection{} For any small v-stack $X$ on $\perfd$ recall that we write $X_{\mv}$ for the category of $(A,A^{+}) \in \perfd$ together with a map $\spd(A,A^{+}) \to X$, equipped with the v-topology. We will work in the category $\operatorname{Ab}(X_{\mv})$ of (small) sheaves of abelian groups on $X_{\mv}$; this is a Grothendieck abelian category closed under small limits and colimits, see \cite[03CO]{stacks-project}. We note that by definition, every cover in $X_{\mv}$ has a finite subcover; in other words, the objects $\spd(A,A^+)$ are qcqs in the topos-theoretic sense. This has the consequence that filtered colimits of sheaves can be computed pointwise, see \cite[Tag 0738]{stacks-project}.

\subsubsection{} For a small v-stack $X$ we can now consider the abelian category of (sheaves of) $\mathcal{O}_X$-modules in $X_{\mv}$, see \cite[Tag 03DA]{stacks-project}. By \cite[Tag 03DB]{stacks-project}, the forgetful functor from $\mathcal{O}_X$-modules to sheaves of abelian groups commutes with limits and colimits. As before every sheaf $F$ of $\mathcal{O}_X$-modules can be considered as a sheaf of condensed $\mathcal{O}_X$-modules over the sheaf of condensed rings $\mathcal{O}_{X,\cond}$. In other words, for $(A,A^+) \in X_{\mv}$ the condensed abelian group $H^0_{\cond}(\spd(A,A^+), F)$ is a condensed $\ul{A}$-module. 

\subsection{Standard sheaves and Fr\'echet sheaves} \label{Sub:Standard} 
For $I$ an index set we consider the following sheaves of $\mathcal{O}^+$ or $\mathcal{O}$-modules on $\perfd$
\begin{align} \label{Eq:Standard}
    \hat{\oplus}_{I} \mathcal{O}^{+}&:= \varprojlim_{n}\oplus_{I} \mathcal{O}^+/p^n \\
    \hat{\oplus}_{I} \mathcal{O}&:= \left(\hat{\oplus}_{I} \mathcal{O}^{+}\right)[\tfrac{1}{p}] \\
    \textstyle\prod_{I} \mathcal{O}^{+}&, \qquad
    (\textstyle\prod_{I} \mathcal{O}^{+})[\tfrac{1}{p}].
\end{align}
We have the following lemma.
\begin{Lem} \label{Lem:Sheaves}
For $(R,R^+)$ a v-complete Huber pair and $Y=\spd(R,R^+)$, there are natural isomorphisms
\begin{align}
H^0_{\cond}(Y, \hat{\oplus}_{I} \mathcal{O}^{+}) &\simeq \hat{\oplus}_{I} \ul{R^+} \\
H^0_{\cond}(Y, \hat{\oplus}_{I} \mathcal{O}) &\simeq \hat{\oplus}_{I} \ul{R} \\
H^0_{\cond}(Y, \textstyle\prod_I \mathcal{O}^+) &\simeq \textstyle\prod_I \ul{R^+} \\
H^0_{\cond}(Y, (\textstyle\prod_I \mathcal{O}^+)[\tfrac{1}{p}]) &\simeq (\textstyle\prod_{I} \ul{R^+})[\tfrac{1}{p}]. 
\end{align}
\end{Lem}
\begin{proof}
The natural isomorphism $\ul{R^+} \to H^0_{\cond}(Y, \mathcal{O}^{+})$ of Lemma \ref{Lem:CondensedRingStructure} induces the third natural isomorphism upon taking the product, since products commute with global sections. The fourth isomorphism is induced from the third by taking a filtered colimit (which also commutes with global sections). The second isomorphism is similarly induced from the first, which we now explain how to construct. \smallskip 

For $n > 0$, by taking the long exact sequence in condensed cohomology for $0 \rightarrow \mathcal{O}^+ \xrightarrow{p^n} \mathcal{O}^+ \rightarrow \mathcal{O}^+/p^n \rightarrow 0$, we obtain an exact sequence 
\[ 0 \rightarrow \ul{R^+/p^n} \rightarrow H^0_{\cond}(Y,\mathcal{O}^+/p^n) \rightarrow H^1_{\cond}(Y,\mathcal{O}^+)[p^n] \rightarrow 0. \]
By varying $n$ and using that the first system is Mittag--Leffler, taking the inverse limit gives an exact sequence
\[ 0 \rightarrow \ul{R^+} \rightarrow H^0_{\cond}(Y,\mathcal{O}^+) \rightarrow \varprojlim_n H^1_{\cond}(Y,\mathcal{O}^+)[p^n] \rightarrow 0. \]
The first arrow is an isomorphism by assumption, so $\varprojlim_n H^1_{\cond}(Y,\mathcal{O}^+)[p^n] =0$. Next we consider the long exact sequence in cohomology for 
\begin{align}
   0 \to \oplus_I \mathcal{O}^+ \xrightarrow{p^n} \oplus_I \mathcal{O}^+ \to \oplus_I \mathcal{O}^+/p^n \to 0,
\end{align}
giving
\[ 0 \rightarrow \oplus_I \ul{R^+/p^n} \rightarrow H^0_{\cond}(Y, \oplus_I \mathcal{O}^+/p^n) \rightarrow H^1_{\cond}(Y, \oplus_I \mathcal{O}^+) [p^n] \rightarrow 0. \] Taking the inverse limit and using the fact that the first system is Mittag--Leffler, we get an exact sequence
\begin{align}
    0 \to \hat{\oplus}_{I} \ul{R^+} \to H^0_{\cond}(Y, \hat{\oplus}_I \mathcal{O}^+) \to \varprojlim_n (H^1_{\cond}(Y, \oplus_I \mathcal{O}^+) [p^n]) \to 0.
\end{align}
But now we observe that (using the fact that cohomology commutes with filtered colimits and thus with direct sums in a coherent site)
\begin{align}
    \varprojlim_n (H^1_{\cond}(Y, \oplus_I \mathcal{O}^+) [p^n]) &= \varprojlim_n \oplus_I (H^1_{\cond}(Y, \mathcal{O}^+) [p^n]) \\
    & \subset \varprojlim_n \textstyle\prod_I (H^1_{\cond}(Y, \mathcal{O}^+) [p^n]) \\
    & \subset \textstyle\prod_I \varprojlim_n (H^1_{\cond}(Y, \mathcal{O}^+) [p^n])=0
\end{align}
to conclude. 
\end{proof}
We let $\Hom_{\mathcal{O}^+}$ denote the internal hom in sheaves of $\mathcal{O}^+$-modules, and we let $\Hom_{\mathcal{O}}$ denote the internal hom in sheaves of $\mathcal{O}$-modules. The following result should be compared to Proposition \ref{Prop:DualityCondensed}.
\begin{Prop} \label{Prop:DualityvSheaves}
The natural maps
\begin{align}
\Hom_{\mathcal{O}^+}\left(\hat{\oplus}_{I}\mathcal{O}^+, \mathcal{O}^+\right) &\to \textstyle\prod_{I} \mathcal{O}^{+} \\
\Hom_{\mathcal{O}}\left(\hat{\oplus}_{I}\mathcal{O}, \mathcal{O}\right) &\to (\textstyle\prod_{I} \mathcal{O}^{+})[\tfrac{1}{p}]
\end{align}
are isomorphisms. If $I$ is countable, then the natural maps
\begin{align}
     \hat{\oplus}_{I}\mathcal{O}^+ &\to \Hom_{\mathcal{O}^+}\left(\textstyle\prod_I \mathcal{O}^+, \mathcal{O}^+\right) \\
    \hat{\oplus}_{I}\mathcal{O} &\to \Hom_{\mathcal{O}}\left((\textstyle\prod_I \mathcal{O}^+)[\tfrac{1}{p}], \mathcal{O}\right)
\end{align}
are isomorphisms.
\end{Prop}
Our proof of the proposition is very similar to our proof of Proposition \ref{Prop:DualityCondensed}. Let $(R,R^+)$ denote a Huber pair over $(\qp,\zp)$ and let $\mathcal{O}^{?}$ denote either $\mathcal{O}^+$ or $\mathcal{O}$ (we will use similar notation for Huber pairs later) and let $F$ be a sheaf of $\mathcal{O}^{?}$-modules on $\spd(R,R^+)$. There is an evaluation map
\begin{align} \label{eq:evaluationsheaf}
    H^0_{\mathrm{cond}}(\spd(R,R^+), \Hom_{\mathcal{O}^{?}}(F, \mathcal{O}^{?})) \to \Hom_{\ul{R^{?}}}(H^0_{\mathrm{cond}}(\spd(R,R^+),F), \ul{R^{?}}).
\end{align}
\begin{Lem} \label{Lem:EvaluationAbstract}
    Let $(R,R^+)$ be a v-complete Huber pair over $(\qp,\zp)$ and let $F$ be a sheaf of $\mathcal{O}^{?}$-modules on $Y=\spd(R,R^+)$. If for all $(R,R^+) \to (A,A^+) \in \spd(R,R^+)_{\mathrm{v}}$ the natural map
    \begin{align}
        H^0_{\mathrm{cond}}(\spd(R,R^+),F) \otimes^{\blacksquare}_{\ul{R^{?}}} \ul{A^{?}} \to H^0_{\mathrm{cond}}(\spd(A,A^+),F)
    \end{align}
    is an isomorphism, then the evaluation map \eqref{eq:evaluationsheaf} is an isomorphism.
\end{Lem}
\begin{proof}
    We follow the proof of Lemma \ref{Lem:PreEvaluationCondensed}: Fix a profinite set $S$, write $\ul{S}_{(R,R^+)}$ for $\ul{S} \times_{\spd \qp} \spd(R,R^+)$ and consider the evaluation of \eqref{eq:evaluationsheaf} on $S$
    \begin{multline} \label{eq:evaluationsheafevaluation}
        H^0_{\mathrm{cond}}(\spd(R,R^+), \Hom_{\mathcal{O}^{?}}(F, \mathcal{O}^{?}))(S) \\\to \Hom_{\ul{R^{?}}}(H^0_{\mathrm{cond}}(\spd(R,R^+),F), \ul{R^{?}})(S).
    \end{multline}
    We can identify the left hand side with the set
    \begin{align}
        H^0(\spd(C^{0}(S,R),C^{0}(S,R^+)), \Hom_{\mathcal{O}^{?}}(F, \mathcal{O}^{?})),
    \end{align}
    so a section gives a map $f \in \hom_{\mathcal{O}^{?}}(F, \mathcal{O}^{?})$ of sheaves on $(\ul{S}_{(R,R^+)})_{\mathrm{v}}$. The map $f$ is uniquely determined by the induced map of condensed sets (notation as in Lemma \ref{Lem:PreEvaluationCondensed})
    \begin{align}
        H^0_{\mathrm{cond}}(\ul{S}_{(R,R^+)},F) \to \ul{R^{?}_{S}}
    \end{align}
    since for any $\spd(A,A^+) \to \ul{S}_{(R,R^+)}$, there is a unique induced map
    \begin{align}
       H^0_{\mathrm{cond}}(\spd(A,A^+),F) \to \ul{A^{?}}
    \end{align}
    given by $f \otimes^{\blacksquare}_{\mathcal{O}^{?}(\ul{S}_{(R,R^+)})} \ul{A^{?}}$; this uses the assumption of the lemma. \smallskip

    The right hand side of \eqref{eq:evaluationsheafevaluation} is the set of $ \pi^{-1}\ul{R^{?}}$-linear homomorphisms (notation as in the proof of Lemma \ref{Lem:PreEvaluationCondensed})
    \begin{align}
        \pi^{-1}H^0_{\mathrm{cond}}(\spd(R,R^+),F) \to \pi^{-1}\ul{R^{?}}
    \end{align}
    on the site of profinite sets over $S$. Using the adjunction argument as in Lemma \ref{Lem:PreEvaluationCondensed}, we identify this with the set of $\ul{R^{?}}$-linear homomorphisms
    \begin{align}
        H^0_{\mathrm{cond}}(\spd(R,R^+),F) \to \ul{R^{?}_{S}},
    \end{align}
    which is identified with the left hand side of \eqref{eq:evaluationsheafevaluation} as above. 
\end{proof}

\begin{Cor} \label{Cor:CondensedEvaluationMaps}
For a v-complete Huber pair $(R,R^+)$ over $\spa(\qp,\zp)$, the natural condensed evaluation maps
\begin{align}
    H^0_{\cond}(\spd(R,R^{+}), \Hom_{\mathcal{\mathcal{O}^{+}}}(\hat{\oplus}_{I} \mathcal{O}^+, \mathcal{O}^+)) &\to\Hom_{\underline{R}^+}(\hat{\oplus}_{I} \underline{R^+} , \underline{R^+}) \\
    H^0_{\cond}(\spd(R,R^{+}),\Hom_{\mathcal{\mathcal{O}}}(\hat{\oplus}_{I} \mathcal{O}, \mathcal{O})) &\to\Hom_{\underline{R}}(\hat{\oplus}_{I} \underline{R} , \underline{R}) 
\end{align}
are isomorphisms. If $I$ is moreover countable, then the natural condensed evaluation maps
\begin{align}
    H^0_{\cond}(\spd(R,R^{+}),\Hom_{\mathcal{\mathcal{O}^+}}(\textstyle\prod_I \mathcal{O}^+, \mathcal{O}^+)) &\to\Hom_{\underline{R}^+}(\textstyle\prod_I \underline{R^+} , \underline{R^+}) \\
    H^0_{\cond}(\spd(R,R^{+}),\Hom_{\mathcal{\mathcal{O}}}((\textstyle\prod_I  \mathcal{O}^+)[\tfrac{1}{p}], \mathcal{O})) &\to\Hom_{\underline{R}}((\textstyle\prod_I \underline{R})[\tfrac{1}{p}], \underline{R})
\end{align}
are isomorphisms.
\end{Cor}
\begin{proof}
The first two statements are a direct consequence of Lemma \ref{Lem:EvaluationAbstract} and the fact that the formation of $\hat{\oplus}_I R^+$ and $\hat{\oplus}_I R$ commute with the solid tensor product, see Proposition \ref{Prop:StandardBCproperty}. For the third and fourth claim, we slightly modify the argument of Lemma \ref{Lem:EvaluationAbstract}. Write
\begin{align}
    F^? &= \twopartdef{\textstyle\prod_I \mathcal{O}^+}{?=+}{(\textstyle\prod_I \mathcal{O}^+)[\tfrac{1}{p}]}{?=\emptyset.} \\
    F^?_R &= \twopartdef{\textstyle\prod_I \ul{R^+}}{?=+}{(\textstyle\prod_I \ul{R^+})[\tfrac{1}{p}]}{?=\emptyset.}
\end{align}
It follows from Proposition \ref{Prop:DualityCondensed}, Proposition \ref{Prop:TensorDualSmith} and Lemma \ref{Lem:Sheaves} that for all morphisms $(A,A^+) \to (B,B^+)$ of v-complete Huber pairs over $(\qp,\zp)$, the natural map
\begin{align}
    H^0_{\cond}(\spd(A,A^+), F^?) \otimes_{\ul{A^?}} \ul{B^?} \to H^0_{\cond}(\spd(B,B^+), F^?)
\end{align}
identifies the target with the double dual of the source. Using this, we can write down an explicit inverse of the natural map of the corollary: For a fixed profinite set $S$ we can identify the natural map as in the proof of Lemma \ref{Lem:EvaluationAbstract} with
\begin{align} \label{Eq:BigEquationReferenceFiveHundred}
     &H^0_{\cond}(\spd(R,R^{+}),\Hom_{\mathcal{\mathcal{O}^?}}(F^?, \mathcal{O}^?))(S) = H^0(\spd(R_S,R^+_S), \Hom_{\mathcal{\mathcal{O}^?}}(F^?, \mathcal{O}^+)) \to \\
     &\Hom_{\underline{R}^?}(F^?_{R}, \underline{R^?})(S) = \hom_{\underline{R}^?}(F^?_{R}, \underline{R^?_{S}}).
\end{align}
An inverse is now given by taking $f: F^?_{R} \to \underline{R^?_{S}}$ to the morphism of sheaves over $\spd(R_S,R_S^+)$ whose evaluation on $(R_S, R_S^+) \to (A,A^+)$ is: We first extend $f$ to a morphism $F^?_{R_S} \to \underline{R^?_{S}}$ by taking (solid) extension of scalars along $\ul{R^?} \to \ul{R_S^?}$ and then taking double dual, we then take solid extension of scalars of $f$ along $\ul{R^?_S} \to \ul{A^?}$ and take double dual again.
\end{proof}
\begin{proof}[Proof of Proposition \ref{Prop:DualityvSheaves}]
All statements are a direct consequence of Proposition \ref{Prop:DualityCondensed} and Corollary \ref{Cor:CondensedEvaluationMaps}.
\end{proof}

\subsubsection{} Let $Y$ be a small v-sheaf and let $F$ be a sheaf of $\mathcal{O}$-modules on $Y_{\mv}$. We say that $F$ is \emph{countably orthonormalizable Banach} if $F \simeq \hat{\oplus}_{I} \mathcal{O}_{Y}$ for some countable set $I$. We say that $F$ is \emph{locally countably orthonormalizable Banach} if there is a v-cover $Y' \to Y$ such that the pullback of $F$ to $Y'$ is isomorphic to $\hat{\oplus}_{I} \mathcal{O}_{Y'}$ for some countable set $I$. We say that $F$ is \emph{reflexive} if the natural map $F \rightarrow \Hom_{\mathcal{O}}(\Hom_\mathcal{O}(F, \mathcal{O}))$ is an isomorphism. 
\begin{Cor} \label{Cor:BanachReflexive}
    If $F$ is a locally countably orthonormalizable Banach sheaf of $\mathcal{O}$-modules on $Y_{\mv}$, then the sheaf $F$ is reflexive.
\end{Cor}
\begin{proof}
    This can be checked locally in the topology, where it follows from Proposition \ref{Prop:DualityvSheaves}.
\end{proof}
We need the following refinement.
\begin{Cor} \label{Cor:SummandReflexive}
    Suppose that $F$ is v-locally a direct summand of a locally countably orthonormalizable Banach sheaf of $\mathcal{O}_Y$-modules. Then $F$ is reflexive. 
\end{Cor}
\begin{proof}
The statement is local, so we may suppose that $F=F_1 \xrightarrow{\oplus} F_2$ where $F_2$ is a locally free Banach sheaf of $\mathcal{O}_Y$-modules; let $\Theta$ be an idempotent of $F_2$ with kernel $F_1$. The point is now that splitting an idempotent is both a limit and a colimit, hence using Corollary \ref{Cor:BanachReflexive} we get
\begin{align}
    \Hom_{\mathcal{O}_Y}(\Hom_{\mathcal{O}_Y}(F_1, \mathcal{O}_Y), \mathcal{O}_Y) &= \Hom_{\mathcal{O}_Y}(\Hom_{\mathcal{O}_Y}(F_2, \mathcal{O}_Y)^{\Theta=0}, \mathcal{O}_Y)  \\
    &= \Hom_{\mathcal{O}_Y}(\Hom_{\mathcal{O}_Y}(F_2, \mathcal{O}_Y), \mathcal{O}_Y)^{\Theta=0} \\
    &=F_1.
\end{align}
\end{proof}

\begin{Def} \label{Def:LocallyFrechet}
A sheaf $F$ of $\mathcal{O}_Y$-modules is called \emph{locally strongly countably Fr\'echet} if there is a v-cover $Y'=\coprod_{j \in J} \spd(A_{j},A_{j}^{+}) \to Y$ with $(A_j, A_j^+) \in \perfd$ such that the pullback of $f_j^{\ast}F$ to $\spd(A_{j},A_{j}^{+})$ can be written as an inverse limit $f_j^{\ast}F=\varprojlim_n F_n$ with the property that: T he sheaf $F_n$ is isomorphic to a direct summand of $\hat{\oplus}_{I} \mathcal{O}_{Y'}$ for some countable set $I$ and the transition maps $H^0_{\cond}(\spd(A_{j},A_{j}^{+}), F_{n+1})(\ast)_{\mathrm{top}} \to H^0_{\cond}(\spd(A_{j},A_{j}^{+}), F_{n})(\ast)_{\mathrm{top}}$ have dense image. If the transition maps $H^0_{\cond}(\spd(A_{j},A_{j}^{+}), F_{n+1}) \to H^0_{\cond}(\spd(A_{j},A_{j}^{+}), F_{n})$ are moreover compact, then $F$ is called \emph{locally strongly countably Fr\'echet of compact type}.  
\end{Def} 
\begin{Lem} \label{Lem:EvaluationFrechet}
Let $Y=\spd(R,R^+)$ with $(R,R^+)$ a v-complete Huber pair over $(\qp,\zp)$ and let $F=\varprojlim_n F_n$ be a sheaf of $\mathcal{O}_Y$-modules such that for all $n$ the sheaf $F_n$ is isomorphic to a direct summand of $\hat{\oplus}_{I} \mathcal{O}_{Y}$ for some countable set $I$, and such that the transition maps $H^0_{\cond}(\spd(R,R^+), F_{n+1})(\ast)_{\mathrm{top}} \to H^0_{\cond}(\spd(R,R^+), F_{n})(\ast)_{\mathrm{top}}$ have dense image. Then for $(R,R^+) \to (B,B^+)$ a morphism of v-complete Huber pairs over $(\qp,\zp)$, the natural map
\begin{align}
    H^0_{\mathrm{cond}}(\spd(R,R^+),F) \otimes^{\blacksquare}_{\ul{R}} \ul{B} \to H^0_{\mathrm{cond}}(\spd(B,B^+),F)
\end{align}
is an isomorphism. 
\end{Lem}
\begin{proof}
The formation of $\hat{\oplus}_{I} \ul{R}$ commutes with the solid tensor product (Proposition \ref{Prop:StandardBCproperty}), so the lemma holds for $F_n$ for all $n$ since tensor products and global sections commute with idempotent projections. It follows from the definitions that $H^0_{\mathrm{cond}}(\spd(R,R^+),F)$ is a strongly countably Fr\'echet $\ul{R}$-module, and thus it follows from Proposition \ref{Prop:TensorInverseLimit} that
\begin{align}
    H^0_{\mathrm{cond}}(\spd(R,R^+),F) \otimes^{\blacksquare}_{\ul{R}} \ul{B} &= \left(\varprojlim_n H^0_{\mathrm{cond}}(\spd(R,R^+),F_n) \right)\otimes^{\blacksquare}_{\ul{R}} \ul{B} \\
    &\simeq \varprojlim_n\left(H^0_{\mathrm{cond}}(\spd(R,R^+),F_n)\otimes^{\blacksquare}_{\ul{R}} \ul{B} \right).
\end{align}
Since the lemma holds for each $F_n$, we can identify this with
\begin{align}
    \varprojlim_n\left(H^0_{\mathrm{cond}}(\spd(A,A^+),F_n)\otimes^{\blacksquare}_{\ul{R}} \ul{B} \right) &= \varprojlim_n\left(H^0_{\mathrm{cond}}(\spd(B,B^+),F_n)\right) \\
    &=H^0_{\mathrm{cond}}(\spd(B,B^+),F).
\end{align}
\end{proof}
\begin{Lem} \label{Lem:FrechetDualSheaf}
Let $Y=\spd(R,R^+)$ with $(R,R^+)$ a v-complete Huber pair over $(\qp,\zp)$ and let $F=\varprojlim_n F_n$ be a sheaf of $\mathcal{O}_Y$-modules such that for all $n$ the sheaf $F_n$ is isomorphic to a direct summand of $\hat{\oplus}_{I} \mathcal{O}_{Y}$ for some countable set $I$, and such that the transition maps $H^0_{\cond}(\spd(R,R^+), F_{n+1})(\ast)_{\mathrm{top}} \to H^0_{\cond}(\spd(R,R^+), F_{n})(\ast)_{\mathrm{top}}$ have dense image. Then the natural map
\begin{align}
    \varinjlim_n \Hom_{\mathcal{O}_Y}(F_n, \mathcal{O}_Y) \to \Hom_{\mathcal{O}_Y}(\varprojlim_n F_n, \mathcal{O}_Y) 
\end{align}
is an isomorphism.
\end{Lem}
\begin{proof}
By Lemma \ref{Lem:EvaluationFrechet}, the assumptions of Lemma \ref{Lem:EvaluationAbstract} hold. The result then follows from Lemma \ref{Lem:EvaluationAbstract} and Lemma \ref{Lem:DualOfFrechet}. 
\end{proof}
The statement of Lemma \ref{Lem:FrechetDualSheaf} can be thought of as saying that $\Hom_{\mathcal{O}_Y}(F, \mathcal{O}_Y)$ is the dual ``equipped with the weak topology". Indeed, the filtered colimit of the weak topologies does indeed give the weak topology on the dual of the inverse limit (given that every functional factors through some stage of the inverse limit).
\begin{Cor} \label{Cor:FrechetReflexive}
    A locally strongly countably Fr\'echet $\mathcal{O}_Y$-module $F$ is reflexive. 
\end{Cor}
\begin{proof}
This can be proved locally in the v-topology, so we may assume that we are in the setting of Lemma \ref{Lem:FrechetDualSheaf}. Then it follows from Lemma \ref{Lem:FrechetDualSheaf} that
    \begin{align}
        \Hom_{\mathcal{O}_{Y}}(\Hom_{\mathcal{O}_{Y}}(\varprojlim_n F_n, \mathcal{O}_Y), \mathcal{O}_Y) &= \Hom_{\mathcal{O}_{Y}}(\varinjlim_n \Hom_{\mathcal{O}_{Y}}(F_n, \mathcal{O}_Y), \mathcal{O}_Y) \\
        &=\varprojlim_n \Hom_{\mathcal{O}_{Y}}(\Hom_{\mathcal{O}_{Y}}(F_n, \mathcal{O}_Y), \mathcal{O}_Y) \\
        &=\varprojlim_n F_n,
    \end{align}
    where we used Corollary \ref{Cor:SummandReflexive} in the last step.
\end{proof}

\subsubsection{Solid tensor products} \label{Subsubb:SolidTensor} Let $Y$ be a small v-stack and let $F,G$ be $\mathcal{O}_Y$-modules. Then we write
\begin{align}
    F \otimes^{\blacksquare}_{\mathcal{O}_Y} G
\end{align}
for the sheafification of the presheaf sending $(A, A^+)$ to
\begin{align}
    \left(H^0_{\cond}(\spd(A,A^+), F) \otimes^{\blacksquare}_{\ul{A}} H^0_{\cond}(\spd(A,A^+), G)\right)(\ast),
\end{align}
where $\otimes^{\blacksquare}_{\ul{A}}$ is the solid tensor product.

\begin{Rem}
As a warning, we note that $F \otimes_{\mathcal{O}_Y}^{\blacksquare} \mathcal{O}_Y$ might not be equal to $F$, because $H^0_{\cond}(\spd(A,A^+), F)$ might not be solid. Even when starting with sheaves satisfying this solidity condition, it is not clear that the tensor product is associative or has any other good formal properties (we thank Peter Scholze for pointing this out to us). 
\end{Rem}

\subsection{Sheaves of geometric origin} \label{Sub:GeometricOrigin} Let $f:X \to Y$ be a morphism of small v-sheaves and consider the sheaf of $\mathcal{O}_Y$-algebras $\mathcal{O}_{X/Y}:=f_{\ast} \mathcal{O}_{X}$. We are going to study this sheaf under some assumptions.
\begin{Lem} \label{Lem:SheafBanach}
Let $(R,R^+)$ be a fiercely v-complete Huber pair and let $(R,R^+) \to (P,P^+)$ be strongly smooth. For $X=\spd(P,P^+) \to \spd(R,R^+)=Y$, the sheaf $\mathcal{O}_{X/Y}$ is a direct summand of a countably orthonormalizable Banach sheaf of $\mathcal{O}_Y$-modules. 
\end{Lem}
\begin{proof}
Factor $(R,R^+) \to (P,P^+)$ as $(R,R^+) \to (R\langle X_1, \cdots, X_k \rangle, \overline{R^+\langle X_1, \cdots, X_k \rangle}) \to (P,P^+)$ with the second map finite \'etale as in the definition. This exhibits $(P,P^+) $ as a finite locally free module over $R\langle X_1, \cdots, X_k \rangle$, and thus an $R\langle X_1, \cdots, X_k \rangle$-linear direct summand of $R\langle X_1, \cdots, X_k \rangle^{\oplus N}$ for some $N$, see \cite[Tag 00NX]{stacks-project}. \smallskip 

Write $Z=\spd(R\langle X_1, \cdots, X_k \rangle, \overline{R^+\langle X_1, \cdots, X_k \rangle})$. Then we claim that
\begin{align}
    \mathcal{O}_{Z/Y} \simeq \hat{\oplus}_I \mathcal{O}_Y
\end{align}
with $I=\mathbb{Z}_{\ge 0}^{k}$. The claim follows from Corollary \ref{Cor:CohomologyAndBaseChange} together with the fact that the formation of Tate algebras commutes with fiber products of adic spaces (see Section \ref{subsub:HuberFiberProduct}) and Lemma \ref{Lem:SmoothOverFierce}, which gives the v-completeness of Tate algebras over affinoid perfectoid $(A,A^+)$. Since $X \to Z$ is finite \'etale and $(R,R^+)$ is fiercely v-complete, it follows in a similar way that (here we are taking the algebraic tensor product)
\begin{align}
    \mathcal{O}_{X/Y} \simeq \mathcal{O}_{Z/Y} \otimes_{H^0(Y, \mathcal{O}_{Z/Y})} P.
\end{align}
Now since $P$ is an $H^0(Y, \mathcal{O}_{Z/Y})=R\langle X_1, \cdots, X_k \rangle$-linear direct summand of $H^0(Y, \mathcal{O}_{Z/Y})^{\oplus N}$ for some $N$, it follows that $\mathcal{O}_{X/Y}$ is a $\mathcal{O}_{Z/Y}$-linear direct summand of $\mathcal{O}_{Z/Y}^{\oplus N}$ for some $N$, proving the lemma. 
\end{proof}

\begin{Lem} \label{Lem:SheafFrechet}
Let $Y=\spd(R,R^+)$ for $(R,R^+)$ a fiercely v-complete Huber pair over $(\qp,\zp)$. Let $f:X \to Y$ be a morphism of small v-sheaves such that $X=\varinjlim_n U_n$, where $U_n \to \spd(R,R^+)$ is given by $\spd(P_n,P_n^+) \to \spd(R,R^+)$ with $(R,R^+) \to (P_n,P_n^+)$ strongly smooth. If the transition maps $P_{n+1} \to P_{n}$ have dense image,  then $\mathcal{O}_{X/Y}$ is locally strongly countably Fr\'echet. If the transition maps $\ul{P_{n+1}} \to \ul{P_{n}}$ are moreover compact, then $\mathcal{O}_{X/Y}$ is locally strongly countably Fr\'echet of compact type. 
\end{Lem}
\begin{proof}
First of all $\mathcal{O}_{U_n/Y}$ is a direct summand of a countably orthonormalizable Banach sheaf of $\mathcal{O}_Y$-modules by Lemma \ref{Lem:SheafBanach}. It follows from Lemma \ref{Lem:SmoothOverFierce} and Lemma \ref{Lem:CondensedRingStructure} that $H^0_{\cond}(Y, \mathcal{O}_{U_n/Y}) \simeq P_n$, thus the transition maps $H^0_{\cond}(Y, \mathcal{O}_{U_n/Y})(\ast)_{\mathrm{top}} \to H^0_{\cond}(Y, \mathcal{O}_{U_n/Y})(\ast)_{\mathrm{top}}$ have dense image. Moreover, the transition maps $H^0_{\cond}(Y,\mathcal{O}_{U_n/Y})\to H^0_{\cond}(Y, \mathcal{O}_{U_n/Y})$ are compact if the maps $\ul{P_{n+1}} \to \ul{P_{n}}$ are compact. The lemma is thus proved if we show that the natural map 
\begin{align}
    \mathcal{O}_{X/Y} \to \varprojlim_n \mathcal{O}_{U_n/Y}
\end{align}
is an isomorphism. We can check this on $(A,A^+) \in \spd(R,R^+)_{\mv}$, and then
\begin{align}
    H^0(X_{\spd(A,A^+)}, \mathcal{O}) &= \hom\left(X_{\spd(A,A^+)}, \mathbb{A}^{1,\lozenge}_{\spd(A,A^+)}\right) \\
    &=\hom\left(\varinjlim_n U_{n,\spd(A,A^+)} , \mathbb{A}^{1,\lozenge}_{\spd(A,A^+)}\right) 
\end{align}
which identifies with $H^0\left(\spd(A,A^+), \varinjlim_n \mathcal{O}_{U_n/Y}\right) = \varprojlim_n H^0\left(\spd(A,A^+), \mathcal{O}_{U_n/Y}\right)$, proving the lemma. 
\end{proof}

\subsubsection{} Let $X \to Y, Z \to Y$ be morphisms of small v-stacks. Then there is a natural cup product morphism
\begin{align} \label{eq:TensorProductMap}
\mathcal{O}_{X/Y} \otimes^{\blacksquare}_{\mathcal{O}_Y}\mathcal{O}_{Z/Y} \to \mathcal{O}_{\left(X \times_{Y} Z\right)/ Y}.
\end{align}
given by the solidification (and then sheafification) of the usual cup product map (see e.g. \cite[Tag 0B6C]{stacks-project}). 
\begin{Lem} \label{Lem:Kunneth}
    Let $Y=\spd(R,R^+)$ for a fiercely v-complete Huber pair $(R,R^+)$ over $(\qp,\zp)$. Let $(R,R^+) \to (P,P^+)$ and $(R,R^+) \to (Q,Q^+)$ be strongly smooth morphisms of Huber pairs over $(\qp,\zp)$. If we write $X=\spd(P,P^+)$ and $Z=\spd(Q,Q^+)$, then the natural map
    \begin{align}
        H^0_{\cond}(Y,\mathcal{O}_{X/Y}) \otimes_{\ul{R}}^{\blacksquare} H^0_{\cond}(Y,\mathcal{O}_{Z/Y}) \to H^0_{\cond}(Y,\mathcal{O}_{(X \times_{Y} Z)/Y})
    \end{align}
    is an isomorphism. 
\end{Lem}
\begin{proof}
Factor $(R,R^+) \to (P,P^+)$ as  $$(R\langle X_1, \cdots, X_k \rangle, \overline{R^+\langle X_1, \cdots, X_k \rangle}) \xrightarrow{f} (P,P^+)$$ with $f$ finite \'etale and similarly factor $(R,R^+) \to (Q,Q^+)$ as $$(R\langle X_{k+1}, \cdots, X_{k+j} \rangle, \overline{R^+\langle X_{k+1}, \cdots, X_{k+j} \rangle}) \xrightarrow{g} (Q,Q^+)$$ with $g$ finite \'etale. It follows from the discussion in \S\ref{subsub:HuberFiberProduct} and the preservation of Tate rings under fiber products of Huber pairs over $(\qp,\zp)$ that we can describe the fiber product $\spa(Q,Q^+) \times_{\spa (R,R^+)} \spa(P,P^+)$ as $\spa(E,E^+)$ where 
\begin{align}
   E=Q \langle X_1, \cdots, X_k \rangle \otimes_{R\langle X_1, \cdots, X_{j+k} \rangle} P \langle X_{k+1}, \cdots, X_{k+j} \rangle,
\end{align}
In particular, the natural map $(R,R^+) \to (E,E^+)$ is strongly smooth, and so $(E,E^+)$ is v-complete by Lemma \ref{Lem:SmoothOverFierce}. Moreover, since
\begin{align}
    \ul{R\langle X_1, \cdots, X_k \rangle} \otimes^{\blacksquare}_{\ul{R}}\ul{R\langle X_{k+1}, \cdots, X_{k+j} \rangle} \simeq \ul{R\langle X_1, \cdots, X_{k+j} \rangle}
\end{align}
by Proposition \ref{Prop:StandardBCproperty}, it follows that $\ul{E}=\ul{P} \otimes^{\blacksquare}_{\ul{R}} \ul{Q}$. Thus by Lemma \ref{Lem:CondensedRingStructure} the natural maps
\begin{align}
     \ul{P} &\to H^0_{\mathrm{cond}}(X, \mathcal{O}) \\
     \ul{Q} &\to H^0_{\mathrm{cond}}(Z, \mathcal{O}) \\
     \ul{P} \otimes^{\blacksquare}_{\ul{R}} \ul{Q} &\to H^0_{\cond}(X \times_{Y} Z, \mathcal{O})
\end{align}
are isomorphisms, proving the lemma.   
\end{proof}
\begin{Lem} \label{Lem:Kunneth1}
Let $X \to Y, Z \to Y$ be morphisms of small v-stacks. If there is a v-cover $Y'=\coprod_{j \in J} \spd(A_j,A^+_{j}) \to Y$ with $(A_j,A_j^+) \in \perfd$ such that: For each $j \in J$ we have $Z_{\spd(A_j,A^+_{j})} \simeq \spd(R,R^+)$ and $X_{\spd(A_j,A^+_{j})} \simeq \spd(P,P^+)$ for $(A_j,A_j^{+}) \to (R,R^+)$ and $(A_j,A_j^{+}) \to (P,P^+)$ strongly smooth, then the natural map of \eqref{eq:TensorProductMap} is an isomorphism. 
\end{Lem}
\begin{proof}
It suffices to prove this after basechanging to $Y'$, so we will assume $Y=Y'=\spd(A,A^+)$. We can then check the statement of the proposition on $\spd(B,B^+)$ points for $(B,B^+) \in \spd(A,A^+)_{\mathrm{v}}$ and we may assume without loss of generality that $(B,B^+)=(A,A^+)$, noting that the assumptions of the lemma are stable under basechange. The lemma now follows from Lemma \ref{Lem:Kunneth}.
\end{proof}

\begin{Prop} \label{Prop:Kunneth3}
Let $Y=\spd(R,R^+)$ for a fiercely v-complete Huber pair $(R,R^+)$ over $(\qp,\zp)$. Let $X=\varinjlim_n U_n$, where $U_n \to \spd(R,R^+)$ is given by $\spd(P_n,P_n^{+}) \to \spd(R,R^+)$ for some strongly smooth $(R,R^+) \to (P_n,P_n^+)$. If the transition maps $P_{n+1} \to P_{n}$ have dense image, then the natural map
 \begin{align}
        H^0_{\cond}(Y,\mathcal{O}_{X/Y}) \otimes_{\ul{R}}^{\blacksquare} H^0_{\cond}(Y,\mathcal{O}_{X/Y}) \to H^0_{\cond}(Y,\mathcal{O}_{(X \times_{Y} X)/Y})
    \end{align}
    is an isomorphism.
\end{Prop}
\begin{proof}
It follows from Lemma \ref{Lem:Kunneth} that the natural map
\begin{align}
    H^0_{\cond}(Y,\mathcal{O}_{U_{n}/Y}) \otimes_{\ul{R}}^{\blacksquare} H^0_{\cond}(Y,\mathcal{O}_{U_{n}/Y}) \to H^0_{\cond}(Y,\mathcal{O}_{(U_{n} \times_{Y} U_{n})/Y})
\end{align}
is an isomorphism. The lemma now follows by observing that
\begin{align}
    H^0_{\cond}(Y,\mathcal{O}_{X/Y}) \simeq \varprojlim_n H^0_{\cond}(Y,\mathcal{O}_{U_{n}/Y}),
\end{align}
see the proof of Lemma \ref{Lem:SheafFrechet}, and applying Proposition \ref{Prop:TensorInverseLimit} to commute the solid tensor product with the inverse limit in both factors. 
\end{proof}
\begin{Prop} \label{Prop:Kunneth2}
    Let $f:X \to Y$ be a morphism of small v-sheaves. Assume that there is a v-cover $Y'=\coprod_{j \in J} \spd(A_j,A^+_{j}) \to Y$ with $(A_j,A_j^+) \in \perfd$ such that: For each $j \in J$ we have $X_{\spd(A_j,A^+_{j})}=\varinjlim_n U_n$ where $U_n \to \spd(A_j,A_j^+)$ is given by $\spd(A_j,A_j^+) \to \spd(P_{n,j},P_{n,j}^+)$ for some strongly smooth $(A_j,A_j^+) \to (P_{n,j},P_{n,j}^+)$. If the transition maps $P_{n,j} \to P_{n+1,j}$ have dense image, then the natural map of \eqref{eq:TensorProductMap} (with $Z=X$) is an isomorphism. 
\end{Prop}
\begin{proof}
It suffices to prove this after basechanging to $Y'$, so we will assume $Y=Y'=\spd(A,A^+)$. We can then check the statement of the proposition on $\spd(B,B^+)$ points for $(B,B^+) \in \spd(A,A^+)_{\mathrm{v}}$, and we can as in the proof of Lemma \ref{Lem:Kunneth1} assume that $(B,B^+)=(A,A^+)$ (using Lemma \ref{Lem:DenseImageTensor}). The statement now follows from Proposition \ref{Prop:Kunneth3}. 
\end{proof}

\subsubsection{} Let $Y$ be a small v-stack and let $f:X \to Y$ be a morphism of small v-stacks. We will write $\mathcal{O}^{+}_{X/Y}=(f_\ast \mathcal{O}_X^+)$ and $\mathcal{O}^{\mathrm{bdd}}_{X/Y}=\mathcal{O}^+_{X/Y}[\tfrac{1}{p}]$.
\begin{Lem} \label{Lem:BoundedFunctions}
    Let $Y=\spd(R,R^+)$ for a fiercely v-complete Huber pair $(R,R^+)$ over $(\qp,\zp)$. Let $X=\varinjlim_n U_n$, where $U_n \to \spd(R,R^+)$ is given by $\spd(P_n,P_n^{+}) \to \spd(R,R^+)$ for some strongly smooth $(R,R^+) \to (P_n,P_n^+)$. For $X^\mathrm{rig}:=\varinjlim_n \spa(P_n, P_n^+)$, there are isomorphisms 
    \begin{align}
        H^0_{\cond}(Y,\mathcal{O}^{+}_{X/Y}) \xrightarrow{\sim} \ul{H^0(X^{\mathrm{rig}}, \mathcal{O}_X^+)} \\
        H^0_{\cond}(Y,\mathcal{O}^{\mathrm{bdd}}_{X/Y}) \xrightarrow{\sim} \ul{H^0(X^{\mathrm{rig}}, \mathcal{O}_X^+)[\tfrac{1}{p}]}.
    \end{align}
\end{Lem}
\begin{proof}
    This is an immediate consequence of the v-completeness of $(P_n, P_n^+)$, see Lemma \ref{Lem:SmoothOverFierce}, and the fact  (which follows as in the proof of Lemma \ref{Lem:SheafFrechet}) that
    \begin{align}
         H^0_{\cond}(Y,\mathcal{O}^{+}_{X/Y}) = \varprojlim_n  H^0_{\cond}(Y,\mathcal{O}^{+}_{U_n/Y}) \\
         H^0(X^{\mathrm{rig}}, \mathcal{O}_X^+) = \varprojlim_n H^0(\spa(P_n, P_n^+), \mathcal{O}_X^+).
    \end{align}
\end{proof}




\section{Families of \texorpdfstring{$p$}{p}-divisible rigid analytic groups} \label{Sec:FamiliesPDiv} In this section we discuss the theory of families of $p$-divisible rigid analytic groups. In \S \ref{Sub:RigidPDiv}, we discuss families of $p$-divisible rigid analytic groups over sousperfectoid adic spaces and rigid spaces over non-archimedean extensions of $\qp$. When the base is the adic spectrum of a non-archimedean extension of $\qp$, we discuss the classification of $p$-divisible rigid analytic groups in terms of Hodge--Tate triples, following Fargues \cite{FarguesI}. In \S \ref{Sub:RigidPDivII}, we define $p$-divisible v-groups over general small v-stacks and construct a functor from Hodge--Tate triples to $p$-divisible v-groups in this generality. In \S \ref{Sub:FiniteHeight}, we introduce the category of finite height $p$-divisible v-groups and relate them to locally analytic character data. 

\subsection{Families of $p$-divisible rigid analytic groups} \label{Sub:RigidPDiv}
In this section, we discuss families of $p$-divisible rigid analytic groups, following Fargues \cites{FarguesI,FarguesII}.

\subsubsection{} Let $Y$ be a sousperfectoid adic space over $\spa \qp$ or a rigid space over a non-archimedean extension of $\qp$. We will consider relative commutative groups $H \to Y$ in the category of smooth adic spaces over $Y$, see \cite[Section IV.4.1]{FarguesScholze}. These have a Lie algebra $\operatorname{Lie} H$, see \cite[p. 10]{HeuerXu}, which is functorial in $H$. To define a logarithm map, we need to restrict to groups which are $p$-divisible in a precise sense, see \cite[Definition 4.1]{FarguesII}. We will present this definition following \cite[Section 3.2]{HeuerXu}.

\subsubsection{} \label{subsub:HeuerXu}  Recall from \cite[Definition 3.2.3]{HeuerXu} that a subspace $T \subset H$ is called \emph{topologically $p$-torsion} if for any open subspace $U \subset H$ containing the image of the unit section, and any quasicompact open subspace $T_0 \subset T$ there is an $n \in \mathbb{Z}_{\ge 1}$ such that $[p^n](T_0) \subset U$, where $[p^n]:H \to H$ is the multiplication by $p^n$ map. 

In the rest of \S \ref{subsub:HeuerXu}, we explain the statement of  \cite[Proposition 3.2.4]{HeuerXu}: There is an open $Y$-subgroup $H \langle p^{\infty} \rangle \subset H$ which is topologically $p$-torsion and is maximal among topologically $p$-torsion open $Y$-subgroups of $H$.\footnote{Note that \cite[Proposition 3.2.4]{HeuerXu} writes $\widehat{H}$ for what we call $H \langle p^{\infty} \rangle$; we instead follow \cite[Definition 2.6]{Heuer}.} Moreover, there is a functorial map of $Y$-groups
\begin{align}
    \log_{H \langle p^{\infty} \rangle}:H \langle p^{\infty} \rangle \to \operatorname{Lie} H,
\end{align}
which induces the identity map on Lie algebras. This fits in an exact sequence
\begin{align}
    0 \to H[p^{\infty}] \to H \langle p^{\infty} \rangle \to \operatorname{Lie} H,
\end{align}
where $H[p^{\infty}]=\bigcup_{n} H[p^n]$. If $[p]:H \to H$ is \'etale, then so is $\log_{H \langle p^{\infty} \rangle}$, and if $[p]:H \to H$ is surjective, then so is $\log_{H \langle p^{\infty} \rangle}$. Finally, the morphism of v-sheaves in groups $H \langle p^{\infty} \rangle^{\lozenge} \to H^{\lozenge}$ over $Y^{\lozenge}$ can be identified with the evaluation at $1$ map $\Hom_{Y^{\lozenge}}(\ul{\zp}_{Y}, H^{\lozenge}) \to H^{\lozenge}$. In particular, this gives $H \langle p^{\infty} \rangle^{\lozenge}$ the structure of a $\ul{\zp}$-module. 

\subsubsection{} Let $Y$ be a sousperfectoid adic space over $\spa \qp$ or a rigid space over a non-archimedean extension of $\qp$ and let $H \to Y$ be a commutative smooth relative group in adic spaces. Recall that $H \to Y$ is a \emph{$p$-divisible rigid analytic group} if $H \langle p^{\infty} \rangle=H$ and if $[p]$ is finite \'etale surjective, see \cite[Definition 4.1]{FarguesII}. Note that \cite{Gerth} uses the terminology analytic $p$-divisible group. 

\begin{Eg} \label{Eg:RigidGM}
Let $Y=\spa \qp$ and consider the rigid analytic fiber $\gmhateta$ over $Y$ of the formal multiplicative group $\gmhat$. This is a $p$-divisible rigid analytic group (e.g. by Lemma \ref{Lem:RigidFiberFormalGroup}). The logarith map $\operatorname{log} \colon \gmhateta \to \mathbb{G}_{a}$ is defined by the usual power series expansion 
\[ \log(1+t)=\sum_{n \geq 1}(-1)^{n+1}\frac{t^n}{n}.\] 
For $\varpi=2p$, the map $\operatorname{log}^{\lozenge}$ is an isomorphism from $\mathbb{B}(1, |\varpi|)$, the ball of radius $|\varpi|$ around $1$ in $\widehat{\mathbb{G}}_{m, \eta}^\lozenge$, to $\mathbb{B}(0, |\varpi|)$, the ball of radius $|\varpi|$ around $0$ in $\mathbb{G}_{a}^\lozenge$, with inverse defined by the usual exponential series 
\[ 
\exp(t)=\sum_{n \geq 0} \frac{1}{n!} t^n.
\]
\end{Eg}
\subsubsection{} Recall that a $p$-divisible group over a $p$-adic formal scheme $X$ (in the sense of \cite[Section 2.2]{ScholzeWeinstein}) is a relative commutative group functor $\mathcal{H} \to X$  such that $[p]:\mathcal{H} \to \mathcal{H}$ is an epimorphism in the fpqc topology, such that $\varinjlim_n \mathcal{H}[p^n] \to \mathcal{H}$ is an isomorphism, and such that $\mathcal{H}[p^n] \to X$ is representable in finite locally free group schemes for all $n$. Note that $\mathcal{H}$ might not be representable by a formal scheme (although it often is, see \cite[Lemma 3.1.1]{ScholzeWeinstein}). We will write $T_p \mathcal{H}$ for the $p$-adic Tate module $\varprojlim_n \mathcal{H}[p^n]$, where the transition maps are induced by multiplication by $p$. The functor $T_p \mathcal{H} \to X$ is representable in flat affine morphisms over $R$, see \cite[Proposition 3.3.1]{ScholzeWeinstein}.
\begin{Lem} \label{Lem:RigidFiberFormalGroup}
Let $Y=\spa(R,R^+)$ be a sousperfectoid adic space over $\spa \qp$ or a rigid space over a non-archimedean extension of $\qp$, and let $\mathcal{H} \to \spf R^+$ be a $p$-divisible group. If $(R,R^+)$ is uniform, then the rigid generic fiber\footnote{Which is defined because $R^+$ is a ring of definition, since $R$ is uniform.} in the sense of \cite[Section 2.2]{ScholzeWeinstein}, $\mathcal{H}^{\mathrm{ad}}_{\eta}$, is a $p$-divisible rigid analytic group over $Y$. 
\end{Lem}
\begin{proof}

This follows from \cite[Proposition 3.4.2.(ii)]{ScholzeWeinstein} and its proof, as we will now explain. Let $H:=\mathcal{H}^{\mathrm{ad}}_{\eta}$. First of all, it follows from that proof that $H \to Y$ is representable by a relative group in adic spaces. It is moreover established that $H$ comes equipped with an exact sequence (where $\operatorname{Lie} H = \operatorname{Lie} \mathcal{H} \otimes_{R^+} \mathbb{G}_a$)
\begin{align}
    0 \to H[p^\infty] \to H \xrightarrow{\log_H} \operatorname{Lie} H.
\end{align}
Furthermore, there is an open subset $U \subset H$ containing the identity section such that the restriction of $\log_{H}$ to $U$ induces an isomorphism between $U$ and $\log_{H}(U)$. On top of that, $\log_{H}(U)$ is an open subset of $\operatorname{Lie} H$ containing the identity section, and it follows that $U$ is smooth over $Y$. Finally it is shown in the proof of \cite[Proposition 3.4.2.(ii)]{ScholzeWeinstein} that $H$ is covered by the inverse images under $[p^n]$ of $U$, and that $[p]:H \to H$ is relatively representable and finite locally free. \smallskip 

It remains to show that $[p]:H \to H$ is finite \'etale and surjective. By the discussion above, for an affinoid open $W=\spa(R,R^+) \subset H$, the inverse image $V=[p]^{-1}W = \spa(B,B^+)$ for some finite locally free $R$-algebra $B$. Since $[p]$ is clearly a quasi-torsor for $H[p]$, we see that $V \times_{W} V \simeq V \times H[p]$ over $W$. But $V \times_{W} V$ is given by $\spa(D,D^+)$ where $D=B \otimes_{R} B$, and $H[p]$ is finite \'etale over $\spa(R,R^+)$ since $p$ is invertible in $R$. Thus it follows from faithfully flat descent that $B$ is a finite \'etale $R$-algebra, showing that $[p]$ is finite \'etale and surjective.
\end{proof}



\subsubsection{} Let $\pi:H \to Y$ be a $p$-divisible rigid analytic group as above. Then the $p^n$-torsion $H[p^n]$ of $H$ is a locally free of finite rank sheaf of $\mathbb{Z}/p^n \mathbb{Z}$-modules on $Y_{\et}$. The multiplication by $p$ map is surjective and thus defines a surjection $H[p^{n+1}] \to H[p^{n}]$ with kernel $H[p]$. Using this observation, we define a $\zp$-local system on $Y$ by $T_p H:=\varprojlim_n H[p^{n+1}]$, the inverse limit being taken in $Y_{\mv}^{\lozenge}$. 

\subsubsection{Classification I} \label{subsub:ClassificationConstruction} Let $Y=\spa(R,R^+)$ be a sousperfectoid adic space over $\spa \qp$ or a rigid space over a non-archimedean extension of $\qp$. 
\begin{Def} \label{Def:EtaleHodgeTateTriple}
We define the category $\LAE(Y)$ of \emph{\'etale Hodge--Tate triples} to be the category of triples $(T,W,\alpha)$, where $T$ is a $\zp$-local system on $Y^{\lozenge}_{\mv}$, where $W$ is an \'etale vector bundle on $Y$, and where $\alpha:W^\lozenge \to T(-1) \otimes_{\ul{\zp}} \mathcal{O}_{Y^\lozenge}$ is a morphism of locally free $\mathcal{O}_{Y^\lozenge}$-modules on $Y^{\lozenge}_{\mv}$. Associated to a triple $\mathcal{L}=(T, W, \alpha) \in \LAE(Y)$ we consider the v-sheaf $\mathcal{H}_{\mathcal{L}}$ of commutative groups over $Y^\lozenge$ given by the fiber product
\begin{equation} \label{Eq:FiberProduct}
    \begin{tikzcd}
        H_{\mathcal{L}} \arrow{d} \arrow{r} \arrow[dr, phantom, "\scalebox{1.5}{$\lrcorner$}" , very near start, color=black] &  T(-1) \otimes_{\ul{\zp}} \widehat{\mathbb{G}}_{m, \eta,Y}^{\lozenge} \arrow{d}{1 \otimes \log^{\lozenge}}\\
        W^{\lozenge} \arrow{r}{\alpha} & T(-1) \otimes_{\ul{\zp}} \mathbb{G}_{a,Y}^{\lozenge}.
    \end{tikzcd}
\end{equation}
\end{Def}
\begin{Prop} \label{Prop:Representable}
Let $\mathcal{L}=(T,W,\alpha)$ and $H_{\mathcal{L}}$ be as above. If $(R,R^+)$ is fiercely v-complete, then there is a unique $p$-divisible rigid analytic group $H_{\mathcal{L}}^{\mathrm{rig}} \to Y$ such that $H_{\mathcal{L}}^{\mathrm{rig},\lozenge}$ is isomorphic to $H_{\mathcal{L}}$. 
\end{Prop}
In the proof of Proposition \ref{Prop:Representable}, we will reduce to the case that the vector bundle $W$ is trivial.
\begin{Lem} \label{Lem:GeometryOfHI}
Let $\mathcal{L}=(T,W,\alpha)$ and $H=H_{\mathcal{L}}$ be as above. If $(R,R^+)$ is fiercely v-complete and $W$ is free, then there are open subgroups $H_n \subset H$ indexed by $n \in \mathbb{Z}_{\ge 1}$ such that $H=\bigcup_n H_n$ and such that $H_n=\spd(A_n,A_n^+)$ with $(R,R^+) \to (A_n,A_n^+)$ strongly smooth.
\end{Lem}
\begin{proof}
Let $\varpi=2p$ and for $n \ge 0$ let 
\begin{align}
    \mathbb{B}(1, |\varpi|^{1/p^n}) \subset \widehat{\mathbb{G}}_{m, \eta}
\end{align}
denote the open subset defined by the inequality $|T|^{p^i} \leq |\varpi|$, and let
\begin{align}
   \mathbb{B}(0, |\frac{\varpi}{p^n}|) \subset \mathbb{G}_{a}
\end{align}
be the closed unit disk of radius $|\frac{\varpi}{p^n}|$. Consider the commutative diagram 
\begin{equation}\label{eq.first-fiber-diagram-functions-structure-proof}\begin{tikzcd}
	{\mathbb{B}(1,|\varpi|^{1/p^n})^{\lozenge} \otimes_{\ul{\zp}} T(-1)} & {\mathbb{B}(1,|\varpi|)^{\lozenge} \otimes_{\ul{\zp}} T(-1)} \\
	{\mathbb{B}(0, |\frac{\varpi}{p^n}|)^{\lozenge} \otimes_{\ul{\zp}} T(-1) } & {\mathbb{B}(0,|\varpi|)^{\lozenge} \otimes_{\ul{\zp}} T(-1)}. \\
	{}
	\arrow["{z \mapsto z^{p^n}}", from=1-1, to=1-2]
	\arrow["{\log \otimes 1}"{description}, from=1-1, to=2-1]
	\arrow["{\mathrm{log}\otimes 1}"{description}, from=1-2, to=2-2]
	\arrow["{t \mapsto p^nt}"', from=2-1, to=2-2]
\end{tikzcd}\end{equation}
The right vertical arrow and bottom horizontal arrow are isomorphisms (see Example \ref{Eg:RigidGM}). Since the top horizontal arrow is finite \'{e}tale, the left vertical arrow is also finite \'etale. We now consider an affinoid open neighborhood of $U \subseteq W$ of $U$ such that $U^{\lozenge}$ is contained in $\mathbb{B}(0,|\varpi|)^{\lozenge} \otimes_{\ul{\zp}} T(-1)$. We define $H_0^\lozenge$ to be the preimage of $U$ in $\mathbb{B}(1,|\varpi|)^{\lozenge}$ (so that $H_0^\lozenge$ is isomorphic by $\log \otimes 1$ to $U$). We then define $H_n^\lozenge$ to be the preimage of $H_0^\lozenge$ in ${\mathbb{B}(1,|\varpi|^{1/p^n})^{\lozenge} \otimes_{\ul{\zp}} T(-1)}$. It is a finite \'{e}tale cover of $H_0^\lozenge$ sitting in the subdiagram of \eqref{eq.first-fiber-diagram-functions-structure-proof}
\begin{equation}
        \begin{tikzcd}
        H_n^{\lozenge} \arrow{r} \arrow{d}{\log} & H_0^{\lozenge} \arrow{d}{\log} \\
        (\frac{1}{p^n} U)^{\lozenge} \arrow{r}{t \mapsto p^n t} & U^{\lozenge}.
\end{tikzcd}
\end{equation}
We thus have $H^{\lozenge}=\bigcup_n H_n^{\lozenge}$, and each $H_n^{\lozenge}$ is finite \'{e}tale over $U^{\lozenge}$ via the map $(t \mapsto p^n t) \circ \log$. By the equivalence of the finite \'{e}tale sites of $U$ and $U^{\lozenge}$, see \cite[Lemma 15.6]{EtCohDiam}, each $H_n^{\lozenge}$ is of the form $\spd(A_n, A_n^+)$ where $A_n$ is a finite \'{e}tale $A=\mathcal{O}(U)$-algebra. Now, since $W$ is trivializable, we may choose $U$ to be an affinoid ball so that $(R,R^+) \to (\mathcal{O}(U), \mathcal{O}^+(U)) \to (A_n,A_n^+)$ exhibits $(R,R^+) \to (A_n,A_n^+)$ as strongly smooth. 
\end{proof}

\begin{proof}[Proof of Proposition \ref{Prop:Representable}]
It follows from Lemma \ref{Lem:GeometryOfHI} and Lemma \ref{Lem:SmoothOverFierce} that, analytically locally on $Y$, we can write $H_{\mathcal{L}} \to Y^{\lozenge}$ as $H^{\mathrm{rig}}_{\mathcal{L}} \to Y$ with $H^{\mathrm{rig}}_{\mathcal{L}} \to Y$ locally fiercely v-complete. By the fully faithfulness proved in Lemma \ref{Lem:FiercelyFullyFaithful}, this also holds globally on $Y$ since the gluing datum for the v-sheaf $H_{\mathcal{L}}$ induces a gluing datum of adic spaces. By the same fully faithfulness and the compatibility of $X \mapsto X^{\lozenge}$ with products, we see that $H^{\mathrm{rig}}_{\mathcal{L}} \to Y$ has the structure of a relative smooth commutative group in adic spaces, and it suffices to show that it is a $p$-divisible rigid analytic group. \smallskip 

For this, we note that $H_{\mathcal{L}}=\Hom_{Y^{\lozenge}}(\ul{\zp}_{Y^{\lozenge}}, H_{\mathcal{L}})$ since this is true for the other three terms in the fiber product diagram. Moreover, the natural map $[p]:H_{\mathcal{L}} \to H_{\mathcal{L}}$ is (representable in) surjective finite \'etale morphisms since this is true for the other three terms in the diagram. By Lemma \ref{Lem:FiercelyFullyFaithful} and \cite[Lemma 15.6]{EtCohDiam}, this implies that $[p]:H^{\mathrm{rig}}_{\mathcal{L}} \to H^{\mathrm{rig}}_{\mathcal{L}}$ is finite \'etale surjective. Thus $H^{\mathrm{rig}}_{\mathcal{L}} \to Y$ is a $p$-divisible rigid analytic group.
\end{proof}
The construction $\mathcal{L} \to H_{\mathcal{L}}^{\mathrm{rig}}$ defines a functor from $\LAE(Y)$ to the category of $p$-divisible rigid analytic groups over $Y$.

\subsubsection{Classification II} \label{subsub:Classification} A result of Fargues, see \cite[Théorème 0.1]{FarguesI}, tells us that the functor $\mathcal{L} \mapsto H_{\mathcal{L}}^{\mathrm{rig}}$ is an equivalence of categories when $Y=\spa(K, \mathcal{O}_K)$ with $K$ a field. In the forthcoming PhD thesis of Gerth \cite{GerthThesis}, this will be generalized to work over an arbitrary perfectoid $Y$. 

\subsection{Families over small v-stacks}\label{Sub:RigidPDivII}  Let $Y$ be a small v-stack (see \S \ref{Sub:Prelim}).
\begin{Def} \label{Def:PdivisibleGroup}
  We say that a v-sheaf of commutative groups $H \to Y$ is a \emph{$p$-divisible v-group} if for all affinoid perfectoid spaces $Y'=\spd(A,A^+) \to Y$, the base change $H_{Y'} \to Y'$ is (the diamond associated to) a $p$-divisible rigid analytic group over $\spa(A,A^+)$.
\end{Def}
\subsubsection{} Let $Y$ be a small v-stack and let $H \to Y$ be a $p$-divisible v-group. 
\begin{Lem} \label{Lem:LieLog}
There is a locally free sheaf of $\mathcal{O}_Y$-modules $\operatorname{Lie} H$ and a short exact sequence
\begin{align}
    0 \to H[p^{\infty}] \to H \xrightarrow{\operatorname{Log}_{H}} \operatorname{Lie} H \to 0
\end{align}
of v-sheaves in abelian groups on $Y_{\mv}$. The formation of $(\operatorname{Lie} H, \operatorname{Log}_{H})$ is functorial in morphisms of $p$-divisible v-groups over $Y$ and commutes with pullback along $Y' \to Y$.
\end{Lem}
\begin{proof}
By v-descent, it suffices to prove this when $Y=\spd(A,A^+)$ with $(A,A^+)$ affinoid perfectoid. But then it is established in \S \ref{subsub:HeuerXu}.
\end{proof}
\subsubsection{} Let $Y=\spd(R,R^+)$, where $(R,R^+)$ is a fiercely v-complete Huber pair over $(\qp,\zp)$. 
\begin{Lem} \label{Lem:RepresentableFierce}
  If $H \to \spd(R,R^+)$ is a $p$-divisible v-group such that $\operatorname{Lie} H$ comes from an analytic vector bundle over $\spa(R,R^+)$, then there is a unique commutative group $H^{\mathrm{rig}} \to \spa(R,R^+)$ in smooth analytic adic spaces over $\spa(R,R^+)$ whose associated diamond is $H$. 
\end{Lem}
\begin{proof}
This follows from Proposition \ref{Prop:Representable} and its proof, using Lemma \ref{Lem:LieLog}. 
\end{proof}
This gives us a theory of $p$-divisible rigid analytic groups over arbitrary fiercely v-complete Huber pairs over $(\qp,\zp)$.
\begin{Lem} \label{Lem:vDescentDiamantine}
Let $H \to Y$ be a v-sheaf of commutative groups. If there is a v-cover $Y' \to Y$ such that $H_{Y'} \to Y'$ is (the diamond associated to) a $p$-divisible rigid analytic group, then $H \to Y$ is a $p$-divisible v-group.
\end{Lem}
\begin{proof}
The property that $\Hom_{Y}(\ul{\zp}_{Y}, H) \to H$ is an isomorphism can be checked v-locally, because it is a map of v-sheaves. By \cite[Proposition 10.11.(iii)]{EtCohDiam}, the same is true for the property that $[p]$ is finite \'etale surjective. The existence of the logarithm as in Lemma \ref{Lem:LieLog} can also be proved v-locally, and the representability over perfectoid spaces follows from the existence of the logarithm as in the proof of Lemma \ref{Lem:RepresentableFierce}.
\end{proof}
If $Y$ is a sousperfectoid adic space over $\spa \qp$ or a rigid space over a non-archimedean extension of $\qp$, and $H \to Y$ is a $p$-divisible rigid analytic group, then $H^{\lozenge} \to Y^{\lozenge}$ is a $p$-divisible v-group; this follows as in Lemma \ref{Lem:vDescentDiamantine}. We note however that $H \mapsto H^{\lozenge}$ is generally not essentially surjective. 


\subsubsection{Classification} \label{subsub:ClassificationII} Let $Y$ be a small v-stack.
\begin{Def} \label{Def:HodgeTateTripleVstacks}
    Let $\LA(Y)$ be the category of Hodge--Tate triples consisting of triples $(T,W,\alpha)$, where $T$ is a $\zp$-local system on $Y_{v}$, where $W$ is a locally free sheaf of $\mathcal{O}_Y$-modules on $Y_{\mathrm{v}}$, and where $\alpha:W \to T(-1) \otimes_{\ul{\zp}} \mathcal{O}_Y$ is a morphism. For $\mathcal{L}=(T,W,\alpha) \in \LA(Y)$, we write $H_{\mathcal{L}}$ for the fiber product
\begin{equation} \label{Eq:FiberProductII}
    \begin{tikzcd}
        H_{\mathcal{L}} \arrow{d} \arrow{r} \arrow[dr, phantom, "\scalebox{1.5}{$\lrcorner$}" , very near start, color=black] &  T(-1) \otimes_{\ul{\zp}} \widehat{\mathbb{G}}_{m, \eta,Y}^{\lozenge} \arrow{d}{1 \otimes \log^{\lozenge}}\\
        W \arrow{r}{\alpha} & T(-1) \otimes_{\ul{\zp}} \mathbb{G}_{a,Y}^{\lozenge}.
    \end{tikzcd}
\end{equation}
\end{Def}
\begin{Lem} \label{Lem:CompatibleBaseChange}
    The functor $\mathcal{L} \mapsto H_{\mathcal{L}}$ commutes with basechange along $Y' \to Y$.
\end{Lem}
\begin{proof}
    This follows from the fact that tensor products of sheaves of modules and fiber products of sheaves both commute with base change. 
\end{proof}
\begin{Lem} \label{Lem:LocSpat}
Let $Y$ be a small v-stack. If $\mathcal{L} \in \LA(Y)$, then the v-sheaf in commutative groups $H_{\mathcal{L}} \to Y$ is a $p$-divisible v-group. 
\end{Lem}
\begin{proof}
By Lemma \ref{Lem:CompatibleBaseChange}, it suffices to prove representability when $Y=\spd(A,A^+)$ with $(A,A^+) \in \perfd$. In this case, the sheaf $W$ of $\mathcal{O}_Y$-modules is free \'etale locally on $Y$ by \cite[Theorem 3.5.8]{KedlayaLiuII}, and the result is Proposition \ref{Prop:Representable}.
\end{proof}

\subsubsection{} If $Y$ is a locally spatial diamond in the sense of \cite[Definition 11.17]{EtCohDiam}, then we define the full subcategory $\LAE(Y) \subset \LA(Y)$ of \'etale Hodge--Tate triples to be those triples $(T,W,\alpha)$ with $W$ an \'etale vector bundle (using the \'etale site of \cite[Definition 14.1]{EtCohDiam}). If $X$ is a sousperfectoid adic space over $\spa \qp$ or a rigid space over a non-archimedean extension of $\mathbb{Q}_p$, then, by \cite[Lemma 15.6]{EtCohDiam}, $\LAE(X^{\lozenge})=\LAE(X)$, where the latter was defined in Definition \ref{Def:EtaleHodgeTateTriple}. 
\begin{Conj} \label{Conj:Gerth}
    Let $Y$ be a small v-stack. The functor $\mathcal{L}=(T,W,\alpha) \to H_{\mathcal{L}}$ is an equivalence of categories between $\LA(Y)$ and the category of $p$-divisible $v$-groups over $Y$.
\end{Conj}

Note that both categories are the evaluation of a v-stack on $Y$: For $\LA(Y)$ this is clear from the definition and for $p$-divisible v-groups this is Lemma \ref{Lem:vDescentDiamantine}. Thus it suffices to prove Conjecture \ref{Conj:Gerth} for $Y$ a (strictly totally disconnected) perfectoid space; this will be done in the forthcoming PhD thesis of Gerth \cite{GerthThesis}.

\subsection{\texorpdfstring{$p$}{p}-divisible v-groups of finite height} \label{Sub:FiniteHeight} Let $Y$ be a small v-stack. 
\begin{Def} \label{Def:FiniteHeight}
    We say that a triple $\mathcal{L}=(T,W,\alpha) \in \LA(Y)$ has \emph{finite height} if $\alpha$ is injective. Note that this condition is stable under pullback along $Y' \to Y$. We define $\LAD(Y) \subset \LA(Y)$ to be the full subcategory of triples $\mathcal{L}=(T,W,\alpha)$ of finite height. We say that a $p$-divisible v-group $H \to Y$ has \emph{finite height} if $H=H_{\mathcal{L}}$ with $\mathcal{L}$ of finite height. 
\end{Def}
If $H$ arises as the generic fiber of a $p$-divisible group, then it is of finite height, see Proposition \ref{Prop.TateModule}. As a special case, this includes the generic fibers of $p$-divisible (equivalently, finite height) formal groups; this explains our choice of terminology. 
\begin{Lem} \label{Lem:LocalDirectSummand}
Let $Y$ be a small v-stack and $\mathcal{L}=(T,W,\alpha) \in \LA(Y)$. The triple $\mathcal{L}$ has finite height if and only if $\alpha$ realizes $W$ as a local direct summand of $T(-1) \otimes_{\ul{\zp}} \mathcal{O}_Y$. In this case, $\mathrm{coker}(\alpha)$ is a locally free $\mathcal{O}_Y$-module. 
\end{Lem}
\begin{proof}
The if direction is trivial. Thus, let us assume $\alpha$ is injective. We may assume that $Y=\Spd(A,A^+)$ is perfectoid and that $W$ has constant rank over $Y$. Via taking global sections, the category of locally free of finite rank $\mathcal{O}_Y$-modules is equivalent to the category of finite projective $A$ modules, see \cite[Theorem 3.5.8]{KedlayaLiuII}. Let $P=H^0(Y,W)$ and $Q=H^0(Y, T(-1) \otimes_{\ul{\zp}} \mathcal{O}_Y)$ be the associated finite projective $A$ modules, and let $f: P \hookrightarrow Q$ be the associated map. By testing on geometric points, we find that for any $x \in \Spa(A,A^+)$, the map $f \otimes_A \kappa(x): P\otimes_A \kappa(x) \rightarrow Q \otimes_A \kappa(x)$ is also injective. Thus $\coker(f) \otimes_A \kappa(x)$ has constant rank and, by \cite[Proposition 2.8]{KedlayaLiu}, $\coker(f)$ is finite projective. Thus the short exact sequence
\[ 0 \rightarrow P \rightarrow Q \rightarrow \coker f \rightarrow 0\]
is split, and any associated direct sum decomposition $Q=P \oplus \coker f$ induces the desired direct sum decomposition of sheaves
    \[ T(-1) \otimes_{\ul{\zp}} \mathcal{O}_Y = Q \otimes_A \mathcal{O}_Y = (P \otimes_A \mathcal{O}_Y) \oplus (\mathrm{coker}(f) \otimes_A \mathcal{O}_Y) = W \oplus W'. \] 
\end{proof}

\subsubsection{} The following proposition shows that the adic generic fiber of a (classical) $p$-divisible group is of finite height. Recall that given a $p$-divisible group $\mathcal{H}$ over a $p$-adic formal scheme $X$, there is a Serre-dual $p$-divisible group $\mathcal{H}^{\vee}$ and a Hodge--Tate map $T_p \mathcal{H}^{\vee} \to \omega_{\mathcal{H}}$, see for example Section \ref{subsub:HodgeTate} below.
\begin{Prop}\label{Prop.TateModule}
    Let $(R,R^+)/(\mathbb{Q}_p, \zp)$ be a fiercely v-complete Huber pair. If $\mathcal{H}$ is a $p$-divisible group over $\spf R^+$, then there is a canonical isomorphism 
    \[ \mathcal{H}_\eta^{\lozenge} \xrightarrow{\sim} H_{\mathcal{L}} \textrm{ for } \mathcal{L}={(T_p \mathcal{H}_\eta, \Lie \mathcal{H} \otimes_{R^+} \mathcal{O}_{Y},  \Lie \mathcal{H} \otimes_{R^+} \mathcal{O}_{Y} \hookrightarrow T_p \mathcal{H}_\eta(-1) \otimes_{\ul{\zp}} \mathcal{O}_{Y})}.\]
    Here $\alpha:\Lie \mathcal{H} \otimes_{R^+} \mathcal{O}_{Y} \hookrightarrow T_p \mathcal{H}_\eta(-1) \otimes_{\ul{\zp}} \mathcal{O}_{Y}$ is the dual Hodge--Tate map. 
\end{Prop}
\begin{proof}
    We follow the proof of \cite[Theorem 5.2.1]{ScholzeWeinstein}. Let $T_p(H)$ be the $p$-adic Tate module of $H=H_{\eta}$, which is a $\zp$-local system on $\spa(R,R^+)$ that we can identify with $\left(T_p \mathcal{H}^{\vee} \right)_{\eta}^{\mathrm{ad}}$. Let $H'= T_p(H) \otimes_{\ul{\zp}_{R}} \widehat{\mathbb{G}}_{m, \eta, R}$ and note that there is a natural map $H \to H'$ of $p$-divisible rigid analytic groups over $\spa(R,R^+)$ which induces an isomorphism $T_p(H) \xrightarrow{\sim} T_p(H')$ on $p$-adic Tate modules. The induced map $\Lie \mathcal{H}[\tfrac{1}{p}]=\operatorname{Lie} H \to \operatorname{Lie} H' = T_p(H)(-1) \otimes_{\ul{\zp}} \mathbb{A}^1_{\spa(R,R^+)}$ is moreover identified with the Hodge--Tate map. Thus we get a commutative diagram
    \begin{equation}
    \begin{tikzcd}
        H \arrow{r} \arrow{d} & H' \arrow{d} \\
        \operatorname{Lie} \mathcal{H} \otimes_{R^+} \mathbb{A}^1_{\spa(R,R^+)} \arrow{r} & T_p \mathcal{H}_{\eta}(-1) \otimes_{\ul{\zp}} \mathbb{A}^1_{\spa(R,R^+)}
       \end{tikzcd} 
    \end{equation}
    and the proposition comes down to showing that it is in fact Cartesian. This can be proved as in the proof of \cite[Theorem 5.2.1]{ScholzeWeinstein}. 
\end{proof}

\subsubsection{} \label{subsub:CharacterDatum} Let $Y$ be a small v-stack. 
\begin{Def} \label{Def:CharacterDatum}
    A locally analytic character datum over $Y$ is a triple $\mathcal{X}=(\Lambda,V,\gamma)$,  where $\Lambda$ is a $\zp$-local system over $Y$, where $V$ is a locally free of finite rank sheaf of $\mathcal{O}_Y$-modules and $\gamma$ is a surjection $\gamma:\Lambda \otimes_{\ul{\zp}} \mathcal{O}_Y \to V$. We will write $\CD(Y)$ for the category of locally analytic character data over $Y$. For $\mathcal{X}=(\Lambda,V,\gamma)$ we define the character v-group to be the fiber product
    \begin{equation}
        \begin{tikzcd}
           H_{\mathcal{X}} \arrow{r} \arrow{d} & \Hom_{Y}(\Lambda_{Y}, \widehat{\mathbb{G}}_{m,\eta,Y}^{\lozenge}) \arrow{d}{\operatorname{Log}} \\
            \Hom_{\mathcal{O}_{Y}}(V, \mathbb{G}_{a,Y}^{\lozenge}) \arrow{r}{\gamma^{\ast}} & \Hom_{Y}(\Lambda_{Y}, \mathbb{G}_{a,Y}^{\lozenge}).
        \end{tikzcd}
    \end{equation}
\end{Def}
There is a contravariant functor $\CD(Y) \to \LAD(Y)$ given by
\begin{align}
    \mathcal{X}=(\Lambda, V, \gamma) \mapsto \mathcal{X}^{\vee}=(\Lambda^{\ast}(1), V^{\ast}, \gamma^{\ast}), 
\end{align}
which is an equivalence of categories with inverse
\begin{align}
    \mathcal{L}=(T, W, \alpha) \mapsto \mathcal{L}^{\vee}=(T^{\ast}(1), W^{\ast}, \alpha^{\ast}).
\end{align}
\begin{Lem}
Let $Y$ be a small v-stack and let $\mathcal{X}$ be a locally analytic character datum over $Y$. There is a functorial isomorphism
    \begin{align}
        H_{\mathcal{X}} \to H_{\mathcal{X}^{\vee}}.
    \end{align}
    In particular, $H_{\mathcal{X}}$ is a $p$-divisible v-group, and every finite height $p$-divisible $v$-group is of the form $H_{\mathcal{X}}$ for some character datum $\mathcal{X}$. 
\end{Lem}
\begin{proof}
Observe that
\begin{align}
    \Hom_{Y}(\Lambda_{Y}, \widehat{\mathbb{G}}_{m,\eta,Y}^{\lozenge}) &= \Lambda^{\ast} \otimes_{\ul{\zp}} \widehat{\mathbb{G}}_{m,\eta,Y}^{\lozenge} \\
        \Hom_{Y}(\Lambda_{Y}, \mathbb{G}_{a,Y}^{\lozenge}) &= \Lambda^{\ast} \otimes_{\ul{\zp}} \mathbb{G}_{a,Y}^{\lozenge} \\
        \Hom_{Y}(V, \mathbb{G}_{a,Y}^{\lozenge})&= V^{\ast}. 
\end{align}
The first part of the lemma is now a direct consequence of the definition of $\mathcal{X}^{\vee}$, together with Definition \ref{Def:CharacterDatum} and Definition \ref{Def:PdivisibleGroup}. The second part of the lemma follows from Lemma \ref{Lem:LocSpat}.
\end{proof}



\subsubsection{Moduli} Fix an integer $h \ge 0$ and an integer $0 \le d \le h$ and let $Y$ be a small v-stack. Then there is a full subcategory $\mathcal{LA}_{h,d}(Y) \subset \LAD(Y)$ consisting of those triples $(T, W, \alpha)$ where $T$ is locally free of rank $h$ and $W$ is locally free of rank $d$. Note that the assignment $Y \mapsto \mathcal{LA}_{h,d}(Y) \subset \LAD(Y)$ is a substack for the v-topology. Consider the natural action of $\ul{\operatorname{GL}_h(\zp)}$ on $\operatorname{Gr}_{h,d}^{\lozenge}$, where $\operatorname{Gr}_{h,d}$ is the (schematic) Grassmannian of $d$-planes in $\qp^{\oplus h}$.
\begin{Lem} \label{Lem:Moduli}
    There is an equivalence of v-stacks on $\perf$
    \begin{align}
        \left[\operatorname{Gr}_{h,d}^{\lozenge}/ \ul{\operatorname{GL}_h(\zp)} \right] \to \mathcal{LA}_{h,d}.
    \end{align}
\end{Lem}
\begin{proof}
It suffices to define the equivalence on affinoid perfectoid test objects $(A,A^+)$, where it is essentially a tautology once we use the fact that v-vector bundles on affinoid perfectoid spaces descend to analytic vector bundles, see \cite[Theorem 3.5.8]{KedlayaLiuII}. 
\end{proof}



\section{Sheaves of functions and distributions} \label{Sec:SheavesOfLaFunctions}

In \S \ref{Sub:Functions}, we show that sheaves of functions on $p$-divisible v-groups over small v-stacks have good functional analytic properties, see Proposition \ref{Prop:GeometricFrechet}. In \S \ref{Sub:FunctionsII}, we introduce spaces of locally analytic functions associated with locally analytic character data, and show that these have good functional analytic properties, see Proposition \ref{Prop:GeometricLB}. 

\subsection{Functions on \texorpdfstring{$p$}{p}-divisible v-groups.} \label{Sub:Functions} Let $Y$ be a small v-stack and let $\mathcal{L}=(T, W, \alpha) \in \LA(Y)$ be a Hodge--Tate triple. Consider the $p$-divisible v-group $H_{\mathcal{L}} \xrightarrow{f} Y$ constructed from $\mathcal{L}$ as in Definition \ref{Def:HodgeTateTripleVstacks} and Lemma \ref{Lem:LocSpat}. Write $\mathcal{O}_{H_{\mathcal{L}}/Y}=f_{\ast} \mathcal{O}_{H_{\mathcal{L}}}$ for the pushforward on v-sites, and let $\mathcal{D}_{H_{\mathcal{L}}/Y}=\Hom_{\mathcal{O}_Y}(\mathcal{O}_{H_{\mathcal{L}}/Y}, \mathcal{O}_Y)$ be its dual. 
\begin{Prop} \label{Prop:GeometricFrechet}
If $Y=\spd(R,R^+)$ for a fiercely v-complete Huber pair $(R,R^+)$ over $(\qp,\zp)$ and $W$ is free, then the following hold: 
\begin{enumerate}
    \item For all morphisms of fiercely v-complete Huber pairs $(R,R^+) \to (B,B^+)$, the natural map (where $Y'=\spd(B,B^+)$)
        \begin{align}
            H^0_{\cond}(Y,  \mathcal{O}_{H_{\mathcal{L}}/Y}) \otimes_{\ul{R}}^{\blacksquare} \ul{B} \to H^0_{\cond}(Y', \mathcal{O}_{H_{\mathcal{L}}/Y})
        \end{align}
        is an isomorphism.

      \item The natural map
    \begin{align}
        H^0_{\cond}(Y,\mathcal{O}_{H_{\mathcal{L}}/Y}) \otimes_{\ul{R}}^{\blacksquare} H^0_{\cond}(Y,\mathcal{O}_{H_{\mathcal{L}}/Y}) \to  H^0_{\cond}(Y,\mathcal{O}_{H_{\mathcal{L} \times \mathcal{L}}/Y})
    \end{align}
    is an isomorphism. 

    \item The natural map
    \begin{align}
        H^0_{\cond}(Y,\mathcal{D}_{H_{\mathcal{L}}/Y}) &\to \Hom_{\ul{R}}(H^0_{\cond}(Y,\mathcal{O}_{H_{\mathcal{L}}/Y}), \ul{R})
    \end{align}
    is an isomorphism.

    \item The natural map
    \begin{align}
        H^0_{\cond}(Y,\mathcal{D}_{H_{\mathcal{L}}/Y}) \otimes^{\blacksquare}_{\ul{R}} H^0_{\cond}(Y,\mathcal{D}_{H_{\mathcal{L}}/Y}) \to  H^0_{\cond}(Y,\mathcal{D}_{H_{\mathcal{L} \times \mathcal{L}}/Y})
    \end{align}
    is an isomorphism.
\end{enumerate}
For $Y$ an arbitrary small v-stack, the following hold: 
\begin{enumerate}
\setcounter{enumi}{4}

    \item The sheaf $\mathcal{O}_{H_{\mathcal{L}}/Y}$ is reflexive.

    \item The sheaf $\mathcal{O}_{H_{\mathcal{L}}/Y}$ is locally strongly countably Fr\'echet of compact type in the sense of Definition \ref{Def:LocallyFrechet}.

    \item The natural map
    \begin{align}
        \mathcal{O}_{H_{\mathcal{L}}/Y} \otimes^{\blacksquare}_{\mathcal{O}_Y}\mathcal{O}_{H_{\mathcal{L}}/Y} \to \mathcal{O}_{H_{\mathcal{L} \times \mathcal{L}} /Y}.
    \end{align}
    is an isomorphism.

    \item The natural map
    \begin{align}
        \mathcal{D}_{H_{\mathcal{L}}/Y} \otimes^{\blacksquare}_{\mathcal{O}_Y} \mathcal{D}_{H_{\mathcal{L}}/Y} \to \left(\mathcal{O}_{H_{\mathcal{L}}/Y} \otimes^{\blacksquare}_{\mathcal{O}_Y} \mathcal{O}_{H_{\mathcal{L}}/Y} \right)^{\ast}
    \end{align}
    is an isomorphism.

\end{enumerate}

\end{Prop}

We start by proving a geometric lemma.
\begin{Lem} \label{Lem:GeometryofH}
Let $Y=\spa(R,R^+)$ for a fiercely v-complete Huber pair $(R,R^+)$ over $(\qp,\zp)$. Let $\mathcal{L}=(T, W, \alpha) \in \LAE(Y^{\lozenge})$ and let $H_{\mathcal{L}}^{\mathrm{rig}}=H \to Y$ be the corresponding commutative smooth group in adic spaces (see Lemma \ref{Lem:RepresentableFierce}). If $W$ is free, then there is an increasing union of open affinoid $Y$-subgroups $H_n \subset H$ indexed by $n \in \mathbb{Z}_{\ge 1}$ such that $H=\bigcup_n H_n$ and such that:
    \begin{itemize}
        \item For each $n$, there is a finite \'{e}tale map $H_n \rightarrow U$, where $U$ is a closed ball in $W$. In particular, $\mathcal{O}(H_n)$ is a (topological) direct summand of the countably orthonormalizable Banach $R$-module $\mathcal{O}(U)^{\oplus m_n}$ for some $m_{n}$.

        \item For $n < n'$ the restriction map $\mathcal{O}(H_{n'}) \rightarrow \mathcal{O}(H_n)$ has dense image and the map $\ul{\mathcal{O}(H_{n'})} \rightarrow \ul{\mathcal{O}(H_n)}$ is compact in the sense of Section \ref{subsub:compact}.
   \end{itemize}
\end{Lem}
\begin{proof}
Following the proof and notation of Lemma \ref{Lem:GeometryOfHI}, we will write $H_n=\bigcup_n H_n$ where each $H_n$ is finite \'{e}tale over a ball $U \subset W$. Then $H_n=\spa(A_n,A_n^+)$, where $A_n$ is a finite \'{e}tale $A=\mathcal{O}(U)$-algebra. In particular, $A_n$ is a finite projective $A$-module, so a direct summand of $A^{\oplus m_n}$ for some $m_n$ (see the proof of Lemma \ref{Lem:SheafFrechet}). Now, since $W$ is trivializable, we may choose $U$ to be an affinoid ball, so that $A$ is orthonormalizable and we obtain the claim (2) on the structure of $A_n$. 

For the claims about dense image and compactness, note that the diagram
\[\begin{tikzcd}
	{H_n} & {H_{n+1}} \\
	U & U
	\arrow[hook, from=1-1, to=1-2]
	\arrow["{p^n \cdot \log}"', from=1-1, to=2-1]
	\arrow["{p^{n+1}\cdot \log}", from=1-2, to=2-2]
	\arrow["p"', from=2-1, to=2-2]
\end{tikzcd}\]
realizes $H_n$ as a clopen subset of $H_{n+1} \times_U {pU}$. Thus $\mathcal{O}(H_n)$ is a direct summand of $\mathcal{O}(H_{n+1} \times_U {pU})$ as a topological $R$-module. We find that $\mathcal{O}(H_{n+1}) \rightarrow \mathcal{O}(H_n)$ can be factored as 
\[\begin{tikzcd}
	{\mathcal{O}(H_{n+1})} & {\mathcal{O}(H_{n+1} \times_U pU)} & {\mathcal{O}(H_n)} \\
	{\mathcal{O}(U)^{m}} & {\mathcal{O}(pU)^{m}}
	\arrow[from=1-1, to=1-2]
	\arrow["\oplus", hook, from=1-1, to=2-1]
	\arrow[two heads, from=1-2, to=1-3]
	\arrow["\oplus", hook, from=1-2, to=2-2]
	\arrow[from=2-1, to=2-2]
	\arrow[dashed, printersafe, two heads, from=2-2, to=1-3]
\end{tikzcd}\]
where the middle vertical arrow is obtained by tensoring the left vertical arrow over $\mathcal{O}(U)$ along the restriction map $\mathcal{O}(U) \rightarrow \mathcal{O}(pU)$. 

In particular, to see that $\mathcal{O}(H_{n+1}) \rightarrow \mathcal{O}(H_n)$ has dense image, we claim it suffices to see that $\mathcal{O}(U) \rightarrow \mathcal{O}(pU)$ has dense image. Indeed, choosing an idempotent $e$ projecting from $\mathcal{O}(U)^m$ onto $\mathcal{O}(H_{n+1})$, we see that image of $\mathcal{O}(H_{n+1}) \rightarrow \mathcal{O}(H_n)$ is dense because $\mathcal{O}(H_{n+1} \times_U pU) \rightarrow \mathcal{O}(H_n)$ is a surjection and $\mathcal{O}(U)^m \rightarrow \mathcal{O}(pU)^m$ has dense image thus $\mathcal{O}(H_{n+1}) \rightarrow \mathcal{O}(H_{n+1} \times_U pU)$ also has dense image as it can be identified with $e \mathcal{O}(U)^m \rightarrow  e\mathcal{O}(pU)^m$. Now, we obtain the desired density because $\mathcal{O}(U) \rightarrow \mathcal{O}(pU)$ evidently has dense image: Choosing coordinates, it is the natural inclusion $R\langle T_1, \ldots T_d\rangle \rightarrow R \langle \frac{T_1}{p} \ldots, \frac{T_d}{p} \rangle$, whose image contain the polynomials $R[T_1, \ldots, T_d]$, which are a dense subset. 

Similarly, to see $\mathcal{O}(H_{n+1}) \rightarrow \mathcal{O}(H_n)$ is compact, since it is obtained from $\mathcal{O}(U)^m \rightarrow \mathcal{O}(pU)^m$ by pre-composition with the inclusion of a direct summand and post-composition with projection onto a direct summand, it suffices to show that $\mathcal{O}(U)^m \rightarrow \mathcal{O}(pU)^m$ is compact. Since a finite direct sum of compact maps is compact, it thus suffices to show $\mathcal{O}(U) \rightarrow \mathcal{O}(pU)$ is compact. To prove this, we can moreover reduce to the case that $Y=\spd(\qp,\zp)$ by Lemma \ref{Lem:CompactTensor}, and then the result is well known in classical functional analysis; with the present condensed definitions see, e.g., \cite[Remark 4.9]{RJRC}.
\end{proof}
\begin{Cor} \label{Cor:IsFrechet}
Let $Y=\spa(R,R^+)$ for a fiercely v-complete Huber pair $(R,R^+)$ over $(\qp,\zp)$. Let $\mathcal{L}=(T, W, \alpha) \in \LAE(Y^{\lozenge})$ and let $H=H_{\mathcal{L}}^{\mathrm{rig}} \to Y$ be the corresponding commutative smooth group in adic spaces (see Lemma \ref{Lem:RepresentableFierce}). If $W$ is free, then $\ul{\mathcal{O}(H)}$ is a strongly countably Fr\'echet $\ul{R}$-module of compact type.
\end{Cor}
\begin{proof}[Proof of Proposition \ref{Prop:GeometricFrechet}]
Part (1) is a direct consequence of Lemma \ref{Lem:EvaluationFrechet} and Lemma \ref{Lem:GeometryofH}. Part (2) follows from Proposition \ref{Prop:Kunneth3} and Lemma \ref{Lem:GeometryofH}. Part (3) follows from Lemma \ref{Lem:EvaluationAbstract} and part (1). Part (4) follows from parts (2) and (3), in combination with Corollary \ref{Cor:IsFrechet} and Corollary \ref{Cor:DualTensorCommute}.

For the rest of the proposition, we can reduce to the case that $T$ and $W$ are trivial and that $Y=\spd(A,A^+)$ is affinoid perfectoid. Part (6) is then a direct consequence of Lemma \ref{Lem:SheafFrechet} and Lemma \ref{Lem:GeometryofH}. Part (5) follows from Corollary \ref{Cor:FrechetReflexive} and part (7) from Proposition \ref{Prop:Kunneth2}. Finally, part (8) follows by applying (3) and (4) to affinoid perfectoid $(A,A^+) \to (B,B^+)$.
\end{proof}

