\subsubsection{} \label{subsub:Hopf} Let $Y$ be a small v-stack, let $\mathcal{L}=(T, W, \alpha) \in \LA(Y)$ and let $H=H_{\mathcal{L}}$ be the corresponding $p$-divisible v-group. Using part (7) of Proposition \ref{Prop:GeometricFrechet}, we see that the K\"unneth map
\begin{align}
    \mathcal{O}_{H/Y} \otimes^{\blacksquare}_{\mathcal{O}_Y}\mathcal{O}_{H/Y} \to \mathcal{O}_{\left(H \times_{Y} H\right)/ Y}
\end{align}
is an isomorphism. This means that we can use the group structure (given by the multiplication map and the identity section) to equip $\mathcal{O}_{H/Y}$ with the structure of a commutative solid Hopf $\mathcal{O}_Y$-algebra.\footnote{We define a commutative solid Hopf $\mathcal{O}_Y$-algebra to be a co-commutative co-group object in the category of commutative solid $\mathcal{O}_Y$-algebras with the solid tensor product. It follows in the usual way that for a commutative group $H \to Y$ satisfying the K\"unneth formula for the solid tensor product, the sheaf $\mathcal{O}_{H/Y}$ is a solid Hopf $\mathcal{O}_Y$-algebra.} \smallskip

Let $\mathcal{D}_{H/Y}$ be $\Hom_{\mathcal{O}_Y}(\mathcal{O}_{H/Y}, \mathcal{O}_Y)$. Then by part (8) of Proposition \ref{Prop:GeometricFrechet}, we see that the natural map
\begin{align}
    \mathcal{D}_{H/Y} \otimes^{\blacksquare}_{\mathcal{O}_Y} \mathcal{D}_{H/Y} \to \Hom_{\mathcal{O}_Y}(\mathcal{O}_{H/Y} \otimes^{\blacksquare}_{\mathcal{O}_Y} \mathcal{O}_{H/Y}, \mathcal{O}_Y)
\end{align}
is an isomorphism. This means that the commutative solid Hopf $\mathcal{O}_Y$-algebra structure on $\mathcal{O}_{H/Y}$ induces a commutative solid Hopf $\mathcal{O}_Y$-algebra structure on $\mathcal{D}_{H/Y}$.

\subsection{Locally analytic functions} \label{Sub:FunctionsII}


Let $Y$ be a small v-stack and let $\mathcal{X}=(\Lambda, V, \gamma)$ be a locally analytic character datum. We are going to define a sheaf $\mathcal{O}^{\gamma-\locan}_{\Lambda/Y} \subseteq \mathcal{O}_{\Lambda/Y}$ of functions that extend locally along $\gamma$ to an open neighborhood in $V$, and show that it is a subsheaf of $\mathcal{O}_{\Lambda/Y}$. 

\begin{Def}\label{def.loc-an-vectors}
Let $Y$ be a small v-stack.
    \begin{enumerate}
    \item Let $\mathcal{X}=(\Lambda, V, \gamma)$ be a locally analytic character datum over $Y$. We define
    \[ \mathcal{O}_{\Lambda/Y}^{\gamma-\locan}: = \varinjlim_{(n, U)} \mathcal{O}_{U/Y}, \]
    where the colimit is over pairs $(n,U)$ where $n \in \mathbb{Z}_{\ge 0}$ and $U$ is an open neighborhood of the image of $\Lambda$ in $\Lambda/p^n \Lambda \times V$ (under the product of $\Lambda \rightarrow \Lambda/p^n$ and $\gamma|_{\Lambda}$). We let
    \[ \mathcal{D}_{\Lambda/Y}^{\gamma-\locan}:= \Hom_{\mathcal{O}_Y}(\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}, \mathcal{O}_Y). \]
    \item Let $\Lambda$ be a $\zp$-local system over $Y$. We write $\mathcal{O}_{\Lambda/Y}^{\locan} := \mathcal{O}_{\Lambda/Y}^{\mathrm{Id}_{\Lambda \otimes_{\ul{\mbb{Z}_p}} \mathcal{O}_Y}-\locan}$, i.e., the sheaf of locally analytic functions attached to the character datum $(\Lambda, \Lambda \otimes_{\ul{\zp}} \mathcal{O}_Y, \mathrm{Id}_{\Lambda \otimes_{\ul{\mbb{Z}_p}} \mathcal{O}_Y}).$ 
    \end{enumerate}
\end{Def}

\subsubsection{} The assignment $(\Lambda, V, \gamma) \mapsto \mathcal{O}_{\Lambda/Y}^{\gamma-\locan}$ is contravariantly functorial in $(\Lambda, V, \gamma)$. 
\begin{Lem}\label{lem.cofinal-system}
    In the notation of Definition \ref{def.loc-an-vectors}-(1), suppose $U_0$ is an open subsheaf of $V$ containing $\gamma(\Lambda \otimes_{\ul{\mbb{Z}_p}} \mathcal{O}_Y^+)$ and contained in $p^{-N} \gamma(\Lambda \otimes_{\ul{\mbb{Z}_p}} \mathcal{O}_Y^+)$ for some $N>0$. Then, the subsheaf $U_{0,n}$ of $\Lambda/p^n \times_Y V$ consisting of pairs $(\overline{\lambda}, v)$ where $\gamma(\lambda) - v \in p^n U_0$ for one, equivalently any, local lift $\lambda$ of $\overline{\lambda}$, is open. Moreover, there is a natural isomorphism
    \[ \mathcal{O}_{\Lambda/Y}^{\gamma-\locan} \to \varinjlim_{n} \mathcal{O}_{U_{0,n}/Y}. \]
\end{Lem}
\begin{proof}
To verify that $U_{0,n}$ is an open subsheaf, it suffices to show that $U_{0,n}$ is open after restriction to any affinoid perfectoid test object $Y'=\Spa(A,A^+)$ where $\Lambda\simeq \ul{\mbb{Z}}_p^{h}$ is trivial and $V\simeq\mathcal{O}_{Y'}^d$. We thus assume $Y=Y'$ and fix such trivializations. For any $n \geq 0$, we may fix elements $\lambda_1, \ldots, \lambda_{p^{nh}}$ of $\mbb{Z}_p^{h}$ that map bijectively onto $\mbb{Z}_p^{h}/p^n \mbb{Z}_p^{h}$. Then $U_{0,n}$ is the disjoint union of the open subsheaves
   \[ \{\overline{\lambda_i}\} \times (\gamma(\lambda_i) + p^n U_0) \subseteq \Lambda/p^n \Lambda \times_{Y} V. \]
To show the second statement, we observe that $U_{0,n}$ is an open neighborhood of the image of $\Lambda$ in $\Lambda/p^{n}\Lambda \times V$. Thus there is a restriction map
\begin{align}
    \varinjlim_n \mathcal{O}_{U_{0,n}/Y} \to \varinjlim_{(n,U)} \mathcal{O}_{U/Y}.
\end{align}
We can show it is an isomorphism after restricting to any affinoid perfectoid $Y'=\spa(A,A^+)$ where $\Lambda$ and $V$ are trivial. We thus assume $Y=Y'$ and fix such trivializations. Then, it suffices to show that for each $(U,n)$ as in Definition \ref{def.loc-an-vectors}-(1), there exists $m \geq n$ such that $U_{0,m}$ is contained in the pre-image of $U$ under $\Lambda/p^{m}\Lambda \times V \to \Lambda/p^{n}\Lambda \times V$. Equivalently, that the image of $U_{0,m}$ in $\Lambda/p^{n}\Lambda \times V$ is contained in $U$ for some $m$. \smallskip 

For this, we note that $U_{0,m}$ is the image in $\Lambda/p^{m}\Lambda \times V$ of $\Lambda \times p^{m} U_0$ (under the map given by the product of $\Lambda \rightarrow \Lambda/p^n$ and $\gamma|_{\Lambda}$ in the first factor).Thus the image of $U_{0,m}$ in $\Lambda/p^{n}\Lambda \times V$ is also the image of $\Lambda \times p^{m} U_0$. But these clearly form a basis of neighborhoods of the image of $\Lambda$ as $m$ goes to infinity. 
\end{proof}

\begin{Rem} \label{Rem:CanonicalUNaught}
In Lemma \ref{lem.cofinal-system}, one can always take $U_0 = \gamma (\Lambda \otimes_{\ul{\mbb{Z}_p}} \mathcal{O}_Y^+)$, and this choice is moreover functorial so that we could have simply defined $\mathcal{O}_{\Lambda/Y}^{\locan}$ as the colimit in Lemma \ref{lem.cofinal-system} for this fixed choice of $U_0$. However, to establish good functional analytic properties of $\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}$, it is convenient to use the more general definition; in particular, it will be convenient to take $U_0$ to be an affinoid ball containing $\gamma (\Lambda \otimes_{\ul{\mbb{Z}_p}} \mathcal{O}_Y^+)$ so that one obtains a colimit of Banach modules under injective transition maps.
\end{Rem}

\begin{Lem}\label{lem.pullback-of-locan}
For any map of small v-stacks $f: Y' \rightarrow Y$, the natural map 
\[ f^*\mathcal{O}_{\Lambda/Y}^{\gamma-\locan} \rightarrow \mathcal{O}_{f^*\Lambda/Y'}^{f^*\gamma-\locan} \]
is an isomorphism. 
\end{Lem}
\begin{proof}
    The presentation of Lemma \ref{lem.cofinal-system} is compatible with pullback, and then we can use Corollary \ref{Cor:CohomologyAndBaseChange}.
\end{proof}

\subsubsection{} \label{subsub:derivationaction} Let $Y$ be a small v-stack and $\mathcal{X}=(\Lambda,V, \gamma)$ be a locally analytic character datum. Note that for an affinoid perfectoid $Y'=\spa(A,A^+) \to Y$, the basechange $U_{0,m,Y'}$ is the diamond associated with a smooth commutative group in adic spaces, with Lie algebra $V_{Y'}$. Then $V_{Y'}$ acts by invariant derivations on each term of the direct system, and thus on the colimit $\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}$. This action is moreover compatible with pullback, and thus gives an action of $V$ on $\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}$. In other words, we have constructed  a functorial $\mathcal{O}_Y$-linear map $$V \rightarrow \End_{\mathcal{O}_Y}(\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}).$$
\begin{Lem} \label{Lem:LaAndCauchyRiemann}
 Let $(\Lambda, V, \gamma)$ be as before and let $W=\ker \gamma$. Then the natural map
 \begin{align}
    \mathcal{O}_{\Lambda/Y}^{\gamma-\locan} \to \mathcal{O}_{\Lambda/Y}^{\locan}
 \end{align}
induced by $(\Lambda, \Lambda \otimes_{\ul{\zp}} \mathcal{O}_Y, \operatorname{id}_{\Lambda \otimes_{\ul{\zp}} \mathcal{O}_Y}) \to(\Lambda, V, \gamma)$ is a monomorphism and identifies $\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}$ with the $W$-fixed points of $\mathcal{O}_{\Lambda/Y}^{\locan}$ under the action of \S \ref{subsub:derivationaction}.
\end{Lem}
\begin{proof}
By the compatibility with pullback of Lemma \ref{lem.pullback-of-locan} we may assume $Y$ is an affinoid perfectoid $\Spa(A,A^+)$ and $\Lambda$, $V$, and $W$ are all trivial. Let $U'_0=\Lambda \otimes_{\ul{\zp}} \mathcal{O}_{Y}^+$ and $U_0=\gamma(\Lambda \otimes_{\ul{\zp}} \mathcal{O}_{Y}^+)$. Using the presentation of Lemma \ref{lem.cofinal-system} twice, we can identify the natural map of the lemma with
\begin{align}
    \varinjlim_{m} \mathcal{O}_{U_{0,m}/Y} \to \varinjlim_{m} \mathcal{O}_{U_{0,m}'/Y}.
\end{align}
By the discussion in \S \ref{subsub:derivationaction}, this natural map is $\Lambda \otimes_{\zp} \mathcal{O}_Y$-equivariant for the action on the left hand side given by $\gamma:\Lambda \otimes_{\zp} \mathcal{O}_Y \to V$. In particular, it induces a natural map
\begin{align}
    \varinjlim_{m} \mathcal{O}_{U_{0,m}/Y} \to \left(\varinjlim_{m} \mathcal{O}_{U_{0,m}'/Y}\right)^{W},
\end{align}
which we want to show is an isomorphism. Taking fixed points for the action of $W$ is a finite limit (since $W$ is a finitely generated free $\mathcal{O}_Y$-module) and thus passes through the filtered colimit. Thus it suffices to show that the natural map
\begin{align}
    \mathcal{O}_{U_{0,m}/Y}\to (\mathcal{O}_{U_{0,m}'/Y})^{W} 
\end{align}
is an isomorphism. In other words, we are trying to show that functions on a ball inside $\Lambda \otimes_{\ul{\zp}} \mathcal{O}_Y$ that are killed by the derivations coming from $W=\ker \gamma$,
must factor through $\gamma:\Lambda \otimes_{\ul{\zp}} \mathcal{O}_Y \to V$. Writing $\Lambda \otimes_{\ul{\zp}} \mathcal{O}_Y$ as $W \oplus V$, see Lemma \ref{Lem:LocalDirectSummand}, this can be checked in coordinates where it is straightforward.
\end{proof}

It is immediate from Definition \ref{def.loc-an-vectors} that there is a natural restriction map
\begin{equation}\label{eq.restriction-map-locally-analytic}\mathcal{O}_{\Lambda/Y}^{\gamma-\locan} \rightarrow \mathcal{O}_{\Lambda/Y}.\end{equation}

\begin{Lem}\label{lemma.restriction-map-injective}
The restriction map \eqref{eq.restriction-map-locally-analytic} is injective. 
\end{Lem}
\begin{proof}
    By Lemma \ref{Lem:LaAndCauchyRiemann}, it suffices to prove that the restriction map $\mathcal{O}_{\Lambda/Y}^\locan \rightarrow \mathcal{O}_{\Lambda/Y}$ is injective. Evaluating on an affinoid perfectoid $\Spa(A,A^+)/Y$ where $\Lambda\simeq \ul{\zp^h}$ is trivial, the restriction map is the natural injection $C^{\locan}(\zp^h, A) \hookrightarrow \Cont(\zp^h, A).$ 
    We conclude as such affinoid perfectoids form a basis for $Y_{\mathrm{v}}$. 
\end{proof}
Let $Y$ be a small v-stack and let $\mathcal{X}=(\Lambda,V,\gamma)$ be a locally analytic character datum over $Y$. 
\begin{Prop} \label{Prop:GeometricLB}
Assume that $Y=\spd(R,R^+)$ for a fiercely v-complete Huber pair $(R,R^+)$ over $(\qp,\zp)$ and that $V$ is free. The following hold: 
    \begin{enumerate}
        \item For all morphisms of fiercely v-complete Huber pairs $(R,R^+) \to (B,B^+)$, the natural map ($Y'=\spd(B,B^+)$)
        \begin{align}
            H^0_{\cond}(Y,  \mathcal{O}_{\Lambda/Y}^{\gamma-\locan}) \otimes_{\ul{A}}^{\blacksquare} \ul{B} \to H^0_{\cond}(Y', \mathcal{O}_{\Lambda/Y}^{\gamma-\locan})
        \end{align}
        is an isomorphism.

        \item The natural map
        \begin{align}
        H^0_{\cond}(Y,\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}) \otimes_{\ul{R}}^{\blacksquare} H^0_{\cond}(Y,\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}) \to  H^0_{\cond}(Y,\mathcal{O}_{(\Lambda \oplus \Lambda)/Y}^{(\gamma \oplus \gamma)-\locan})
    \end{align}
    is an isomorphism. 

    \item The natural map
    \begin{align}
        H^0_{\cond}(Y,\mathcal{D}_{\Lambda/Y}^{\gamma-\locan}) &\to \Hom_{\ul{A}}(H^0_{\cond}(Y,\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}), \ul{R})
    \end{align}
    is an isomorphism. 

    \item The natural map
    \begin{align}
        H^0_{\cond}(Y,\mathcal{D}_{\Lambda/Y}^{\gamma-\locan}) \otimes_{\ul{R}}^{\blacksquare} H^0_{\cond}(Y,\mathcal{D}_{\Lambda/Y}^{\gamma-\locan}) \to  H^0_{\cond}(Y,\mathcal{D}_{(\Lambda \oplus \Lambda)/Y}^{(\gamma \oplus \gamma)-\locan})
    \end{align}
    is an isomorphism.

    \item The module $H^0_{\cond}(Y,\mathcal{D}_{\Lambda/Y}^{\gamma-\locan})$ is strongly countably Fr\'echet of compact type. 
     \end{enumerate}
For an arbitrary small v-stack $Y$, the following hold:
\begin{enumerate}
\setcounter{enumi}{5}
         \item The sheaf $\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}$ is reflexive.

        \item The sheaf $\mathcal{D}_{\Lambda/Y}^{\gamma-\locan}$ is locally strongly countably Fr\'echet of compact type. 

        \item The natural map
        \begin{align}
            \mathcal{O}_{\Lambda/Y}^{\gamma-\locan} \otimes_{\mathcal{O}_Y}^{\blacksquare} \mathcal{O}_{\Lambda/Y}^{\gamma-\locan} \to \mathcal{O}_{(\Lambda \oplus \Lambda)/Y}^{(\gamma \oplus \gamma)-\locan}
        \end{align}
        is an isomorphism.

        \item The natural map
        \begin{align}
            \mathcal{D}_{\Lambda/Y}^{\gamma-\locan} \otimes_{\mathcal{O}_Y}^{\blacksquare} \mathcal{D}_{\Lambda/Y}^{\gamma-\locan} \to \left( \mathcal{O}_{\Lambda/Y}^{\gamma-\locan} \otimes_{\mathcal{O}_Y}^{\blacksquare} \mathcal{O}_{\Lambda/Y}^{\gamma-\locan} \right)^{\ast}
        \end{align}
        is an isomorphism.
\end{enumerate}
\end{Prop}
We start by proving a lemma.

\begin{Lem} \label{Lem:OgammalaIsLB}
Let $Y=\Spd (R,R^+)$ for a fiercely v-complete Huber pair $(R,R^+)$ over $(\qp,\zp)$, and let $\mathcal{X}=(\Lambda, \mathcal{O}_{Y}^{\oplus d}, \gamma)$ be a locally analytic character datum such that $\restr{\gamma}{\Lambda}$ factors through the unit ball $(\mathcal{O}^{+}_{Y})^{d}$. For any $n \geq 0$, let $U_n \subseteq \Lambda/p^n \Lambda \times \mathcal{O}_Y^{\oplus d}$ be the open subset of pairs $(\lambda, w)$ where $\gamma(\lambda)-w \in p^n (\mathcal{O}_Y^{+})^d$. Then   
    \[ \mathcal{O}_{\Lambda/Y}^{\gamma-\locan}(Y) = \varinjlim_n \mathcal{O}(U_n)=\varinjlim_n H^0(Y, \mathcal{O}_{U_n/Y}), \]
and $H^0_\cond(Y, \mathcal{O}_{U_n/Y})$ is a direct summand of an orthonormalizable Banach $R$-module. 

Moreover, suppose $(R,R^+) \to (B,B^+)$ is a map of fiercely v-complete Huber pairs, and let $Y'=\Spd(B,B^+)$. Then the natural map
    \begin{equation} \label{Eqn:BCforSummandsOfBalls}
    H^0_{\cond}(Y, \mathcal{O}_{U_{n}/Y}) \otimes_{\ul{R}}^{\blacksquare} \ul{B} \to H^0_{\cond}(Y', \mathcal{O}_{U_{n}/Y})
    \end{equation}
    is an isomorphism.
\end{Lem}
\begin{proof}
The first equality follows from Lemma \ref{lem.cofinal-system}. 

For the rest, we first choose a perfectoid cover $Y_\infty=\Spa(R_\infty, R^+_\infty)$ with $R_\infty = (\varinjlim_i R_i)^\wedge$ where each $R \rightarrow R_i$ is faithfully flat finite \'{e}tale and such that $\Lambda$ is trivial after pullback to $Y_\infty$ --- this is possible by first taking a cover as in \cite[Lemma 3.6.26]{KedlayaLiu} and then taking fiber products with the trivializing covers for $\Lambda/p^{i} \Lambda$. We write $R_i^+$ for the integral closure of $R^+$ in $R_i$, and $Y_i=\Spa(R_i, R_i^+)$. 

We are going to first show that, for some index $i$, $U_n \times_Y {Y_i}$ is a finite disjoint union of balls over $Y_i$. First we fix a section $\lambda: Y_\infty \rightarrow \Lambda_{Y_\infty}$. We write $\overline{\lambda}: Y_\infty \rightarrow (\Lambda/p^n \Lambda)_{Y_\infty}$ for the induced map. Then the map $p^n \mathcal{O}^+_{Y_\infty} \rightarrow \overline{\lambda}^* U_{n,Y_\infty}$, $v \mapsto \gamma(\lambda)+v$ is an isomorphism, i.e., $\overline{\lambda}^* U_{n,Y_\infty}$ is a closed ball of radius $|p^n|$ in $\mathbb{A}^d_{Y_\infty}$ centered at $\gamma(\lambda)$. Writing $\gamma(\lambda)=(a_1, \ldots, a_d) \in R_\infty^d$, we find that, by the density of $\varinjlim_i R_i$ in $R_\infty$, for $i$ sufficiently large there is a center $(b_1, \ldots, b_d) \in R_i^d$ for the same ball. 

In particular, if we first pass to $i$ large enough to fix an isomorphism $\Lambda/p^n \Lambda = (\mathbb{Z}_p/p^n\mathbb{Z}_p)^h$, then we may pass to a further $i$ so that for each $\alpha \in (\mathbb{Z}_p/p^n \mathbb{Z}_p)^h$, we have $U_n|_{\alpha \times Y_i}$ is a ball of radius $p^n$. Thus $U_n \times_Y {Y_i}$ is a disjoint union of $p^{nh}$ $d$-dimensional balls of radius $|p^n|$ over $Y_i$. It follows, in particular, that $\mathcal{O}(U_n \times_Y Y_i)$ is an orthonormalizable Banach $R_i$-module. 

Now, since $R \rightarrow R_i$ is faithfully flat finite \'{e}tale, descent is effective along $R \rightarrow R_i$, and thus we find
%
    \[ \mathcal{O}(U_n) \otimes_R R_i = \mathcal{O}(U_n \times_Y Y_i). \]
%
(in making the descent argument, note that $R_i/R$ is finite so the completed tensor product with $R_i$ agrees with the regular tensor product). Note that $R_i$ is projective over $R$, so $R$ is a direct summand of $R_i$ as an $R$-module and $R_i$ is a direct summand of $R^m$ as an $R$-module (see the proof of Lemma \ref{Lem:SheafFrechet}). It follows from Lemma \ref{Lem:CondensedRingStructure} that $H^0_\cond(Y, \mathcal{O}_{U_n/Y})$ is a direct summand of an orthonormalizable Banach $R$-module. 

Now suppose given a map $(R,R^+) \rightarrow (B,B^+)$ of fiercely $v$-complete Huber pairs, let $Y'=\Spa(B,B^+)$, and, for $i$ as above, let $Y_i' = Y_i \times_Y Y'=\spa(B_i, B_i^+)$. Then, since $U_n \times_Y {Y_i}$ is a union of $p^{nh}$ $d$-dimensional balls of radius $|p^n|$, we see that the natural map 
    \begin{equation} \label{Eqn:BCinproofforballs}
    H^0_{\cond}(U_n \times_Y Y_i, \mathcal{O}) \otimes^{\blacksquare}_{\ul{R_i}} \ul{B_i} \to H^0_{\cond}(U_n \times_Y Y_i', \mathcal{O})
    \end{equation}
    is an isomorphism. Indeed, this amounts to checking $\ul{R_i\langle T_1, \ldots, T_d} \rangle \otimes^{\blacksquare}_{\ul{R_i}} \ul{B_i} \simeq \ul{B_i\langle T_1, \ldots T_d \rangle}$, which
    is Proposition \ref{Prop:StandardBCproperty}. But now applying the projectors for the direct summands as above, we conclude 
    \[ H^0_{\cond}(U_n \times_Y Y', \mathcal{O})=H^0_{\cond}(U_n, \mathcal{O}) \otimes_{\ul{R}}^{\blacksquare} \ul{B}, \]
    giving the claimed result. 
\end{proof}

In the proof of Proposition \ref{Prop:GeometricLB}, we will need the following lemma.
\begin{Lem} \label{Lem:OgammaisLSspace}
With the notation as in Lemma \ref{Lem:OgammalaIsLB}, let $U_n^{\circ} \subset \Lambda/p^{n+1} \Lambda \times \mathcal{O}_Y^{\oplus d}$ denote the open subset of pairs $(\lambda, w)$ where $\gamma(\lambda) - w \in p^{n + \varepsilon}(\mathcal{O}_Y^+)^d$ for some $\varepsilon > 0$. Then we have 
    \begin{align} \label{Eqn:OgammalaPresentation}
    \mathcal{O}_{\Lambda/Y}^{\gamma-\locan}(Y) = \varinjlim_n H^0(Y, \mathcal{O}^{\mathrm{bdd}}_{U^{\circ}_n/Y}),
    \end{align}
    where $\mathcal{O}^{\mathrm{bdd}}_{U^{\circ}_n/Y} := \mathcal{O}^{+}_{U^{\circ}_n/Y}[\tfrac{1}{p}]$, and each term in the colimit is a direct summand of a countably free Smith $R$-algebra.
\end{Lem}
\begin{proof}
This follows as in the proof of Lemma \ref{Lem:OgammalaIsLB}, noting that $U_{n, Y_i}^{\circ}$ is union of $p^{(n+1)h}$ ``open balls'' of radius $|p^n|$, and that the restriction maps $\mathcal{O}_{U_n/Y} \to \mathcal{O}_{U_{n+1}/Y}$ factor through $\mathcal{O}_{U^{\circ}_{n}}^{\mathrm{bdd}}$. We now observe that each term in the colimit is a direct summand of a countably free Smith $R$-algebra because $\mathcal{O}^{\mathrm{bdd}}_{U^{\circ}_{n,Y_i}}$ is countably free Smith; indeed, one has $\mathcal{O}^{\mathrm{bdd}}_{U^{\circ}_{n,Y_i}}(R, R^+) \simeq \bigoplus_{\left(\mbb{Z}/p^{n+1}\mbb{Z}\right)^h} R^+[\![T_1, \dots, T_d]\!][\tfrac{1}{p}]$ for any affinoid open $\operatorname{Spd}(R, R^+) \to Y_i$, see Lemma \ref{Lem:BoundedFunctions}.
\end{proof}
\begin{proof}[Proof of Proposition \ref{Prop:GeometricLB}]
Part (1) follows from Lemma \ref{Lem:OgammalaIsLB} by commuting the colimit with the solid tensor product. Part (3) follows directly from the first property and Lemma \ref{Lem:EvaluationAbstract}. Part (2) follows directly from Lemma \ref{Lem:OgammalaIsLB} and Lemma \ref{Lem:Kunneth}, together with the fact that the solid tensor product commutes with direct limits. \smallskip

We now continue with the notation of Lemma \ref{Lem:OgammaisLSspace}. 

\begin{Claim}
The dual transition maps
\begin{align}
	\mathcal{O}^{\mathrm{bdd}}(U_n^{\circ})^{\ast} \to \mathcal{O}^{\mathrm{bdd}}(U_{n+1}^{\circ})^{\ast}
\end{align} 
are compact in the sense of Section \ref{subsub:compact} and have dense image.    
\end{Claim}
\begin{proof}[Proof of Claim]
We can choose an $i$ sufficiently large as in the proof of Lemma \ref{Lem:OgammaisLSspace} so that $U_{n+1}^\circ\times Y_{Y_i}$ is a union of $p^{(n+2)h}$ open balls of radius $|p^{(n+1)}|$, $U_{n}^\circ \times_Y {Y_i}$ is a union of $p^{(n+1)h}$ open balls of radius $|p^{n}|$, and the map $U_n^\circ \times_Y {Y_i} \rightarrow U_{n+1}^\circ \times_Y {Y_i}$ is described on each open ball of radius $|p^{n}|$ as the sum of the restriction maps to $p^h$ (not necessarily distinct) open sub-balls of radius $|p^{n+1}|$. We will reduce to analyzing these simple restriction maps.

To that end, we first note that for $e$ an $R=\mathcal{O}(Y)$-linear projector on $\mathcal{O}(Y_i)$ such that $e \mathcal{O}(Y_i)=\mathcal{O}(Y)$, we have 
\[ e \mathcal{O}^\bdd(U_\bullet^\circ \times_Y Y_i) = \mathcal{O}^\bdd(U_\bullet^\circ) \textrm{ for } \bullet=n,n+1.\]
This implies 
\[ e \mathcal{O}^\bdd(U_\bullet^\circ \times_Y Y_i)^* = \mathcal{O}^\bdd(U_\bullet^\circ)^* \textrm{ for } \bullet=n,n+1.\]
so it suffices to prove that 
\begin{equation}\label{eq.balls-dual-restriction-map}\mathcal{O}^\bdd(U_{n+1}^\circ \times_Y Y_i)^* \rightarrow \mathcal{O}^\bdd(U_n^\circ \times_Y  Y_i)^*\end{equation} has dense image and is compact, since these properties are preserved after applying $e$. 

To that end, we first note that for any of the single restriction maps from a ball of radius $|p^n|$ to $|p^{n+1}|$, we are free to choose coordinates such that both balls are centered at zero and rescale to obtain, at the level of functions, the map
\[ R^+_i[[T_1, \ldots, T_d]][\tfrac{1}{p}] \xrightarrow{ T_i \mapsto p T_i} R^+_i[[T_1, \ldots, T_d]][\tfrac{1}{p}].\]
The dual of this map is 
\begin{equation}\label{eq.dual-of-simple-map} R_i^* \langle S_1, \ldots, S_d\rangle \xrightarrow{ S_i \mapsto p S_i} R_i^*\langle S_1, \ldots, S_d\rangle \end{equation}
where $R_i^*$ denotes the $R$-linear dual. Since $R_i$ is projective, so is $R_i^*$, thus for some $N$ this is a direct summand of the map
\[ (R\langle S_1, \ldots, S_d \rangle \xrightarrow{ S_i \mapsto p S_i} R\langle S_1, \ldots, S_d\rangle)^{\oplus N}. \]
Thus, to see \eqref{eq.dual-of-simple-map} has dense image and is compact, it suffices to observe that 
\begin{equation}\label{eq.tate-mult-by-p-map} R\langle S_1, \ldots, S_d \rangle \xrightarrow{ S_i \mapsto p S_i} R\langle S_1, \ldots, S_d\rangle.\end{equation}
has dense image and is compact (since these properties are preserved under finite direct sums and, by applying a projector as earlier in the proof, direct summands). The image of \eqref{eq.tate-mult-by-p-map} is dense because it contains the polynomials $R[S_1, \ldots, S_d]$, and we have already argued at the end of the proof of Lemma \ref{Lem:GeometryofH} that \eqref{eq.tate-mult-by-p-map} is compact. 

Since \eqref{eq.dual-of-simple-map} has dense image, so does \eqref{eq.balls-dual-restriction-map}: this follows already by considering a single ball in $U_{n+1}^\circ \times_Y Y_i$ contained in each ball in $U_n^\circ \times_Y  Y_i$. Similarly, by grouping the restriction maps according to their source ball in $U_n^\circ \times_Y  Y_i$, we find that \eqref{eq.dual-of-simple-map} is a direct sum of $p^{nh}$ maps, each of which is a sum of $p^h$ compact maps, and thus it is compact. 
\end{proof}

The claim proves part (5). Now part (4) follows from (2) together with part (3) and Corollary \ref{Cor:DualTensorCommute}. \smallskip 

Parts (6)-(9) are v-local on the base and so we may assume that $Y=\spd(A,A^+)$ with $(A,A^+)$ perfectoid and with $\Lambda$ and $V$ free. We prove (6) directly, by computing
    \begin{align}
        &\Hom_{\mathcal{O}_Y}(\Hom_{\mathcal{O}_Y}(\varinjlim_n \mathcal{O}^{\mathrm{bdd}}_{U^{\circ}_n}, \mathcal{O}_Y), \mathcal{O}_Y) \\
        &=\Hom_{\mathcal{O}_Y}(\varprojlim_n \Hom_{\mathcal{O}_Y}( \mathcal{O}^{\mathrm{bdd}}_{U^{\circ}_n}, \mathcal{O}_Y), \mathcal{O}_Y) \\
        &=\varinjlim_n \Hom_{\mathcal{O}_Y}(\Hom_{\mathcal{O}_Y}( \mathcal{O}^{\mathrm{bdd}}_{U^{\circ}_n}, \mathcal{O}_Y), \mathcal{O}_Y) 
    \end{align}
    as in the proof of Corollary \ref{Cor:FrechetReflexive}, using (5). We conclude by the reflexivity of (direct summands of) countably free smith $\mathcal{O}_Y$-modules, see Proposition \ref{Prop:DualityvSheaves}. Part (7) follows by applying part (5) to affinoid perfectoid $(A,A^+)$ over $Y$ and similarly part (8) follows from part (2) and part (9) follows from parts (2)-(4). 
\end{proof}

\subsubsection{} Let $Y$ be a small v-stack and let $\mathcal{X}=(\Lambda, V, \gamma)$ be a locally analytic character datum over $Y$.

\begin{Lem} \label{Lem:GammaLaSheavesHopf}
    Both $\mathcal{O}_{\Lambda/Y}^{\gamma\mathrm{-la}}$ and $\mathcal{D}_{\Lambda/Y}^{\gamma\mathrm{-la}}$ are naturally solid Hopf $\mathcal{O}_Y$-algebras.
\end{Lem}
\begin{proof}
    For $\mathcal{O}_{\Lambda/Y}^{\gamma\mathrm{-la}}$, the algebra structure is the natural one (and the multiplication structure factors through the solid tensor product), induced from the individual algebra structures on the terms in the colimit defining $\mathcal{O}_{\Lambda/Y}^{\gamma\mathrm{-la}}$. For the co-algebra structure, consider the morphism 
    \[
    \Lambda \oplus \Lambda \xrightarrow{\gamma \oplus \gamma} V \oplus V .
    \]
The co-algebra structure is now induced from pulling back along the addition map $\Lambda \oplus \Lambda \to \Lambda$ and using Proposition \ref{Prop:GeometricLB}-(8). The co-unit is induced from the natural map $0 \to \Lambda$. \smallskip 

This solid Hopf $\mathcal{O}_Y$-algebra structure on $\mathcal{O}_{\Lambda/Y}^{\gamma\mathrm{-la}}$ induces a solid Hopf $\mathcal{O}_Y$-algebra structure on $\mathcal{D}_{\Lambda/Y}^{\gamma\mathrm{-la}}$ once we show that the natural map 
    \begin{equation} \label{Eqn:DualOfSolidEqualsSolidII}
    \left( \mathcal{O}_{\Lambda/Y}^{\gamma\mathrm{-la}} \otimes^{\blacksquare}_{\mathcal{O}_Y} \mathcal{O}_{\Lambda/Y}^{\gamma\mathrm{-la}} \right)^* \leftarrow \mathcal{D}_{\Lambda/Y}^{\gamma\mathrm{-la}} \otimes^{\blacksquare}_{\mathcal{O}_Y} \mathcal{D}_{\Lambda/Y}^{\gamma\mathrm{-la}}
    \end{equation}
    is an isomorphism. But this is part (9) of Proposition \ref{Prop:GeometricLB}.
\end{proof}


\section{The Fourier transform} \label{Sec:Fourier}

In this section we construct the Fourier transform for $p$-divisible v-groups over a small v-stack and establish the main results of this article. In \S \ref{Sub:ExponentialPairing}, we construct the universal character $\kappa$ and establish that it is analytic (Lemma \ref{Lem:UniversalKappaAsSection}). In \S \ref{Sub:FourierDef}, we use this to define the Fourier transform. In \S \ref{Sub:MainTheorem}, we prove Theorem \ref{Thm:IntroFourierVsheaves} (see Theorem \ref{Thm:Main}), and in \S \ref{Sub:Equivariance}, we prove Proposition \ref{Prop:Equivariance}. Finally, we prove Theorem \ref{thm.rational-fourier-theory} in \S \ref{Sub:Field}, and in \S \ref{Sub:STComparison}, we compare our results with those of Schneider--Teitelbaum \cite{SchneiderTeitelbaumFourier}. 

\subsection{The universal character} \label{Sub:ExponentialPairing}
Let $Y$ be a small v-stack and let $\Lambda$ be a locally free sheaf of $\ul{\mathbb{Z}_p}$-modules on $Y_{\mathrm{v}}$. Let $\Lambda^{\ast} := \Hom_{\ul{\mathbb{Z}_p}}(\Lambda, \ul{\mathbb{Z}_p})$ denote its linear dual. Recall that:
\begin{itemize}
    \item $\mathbb{G}_{a, Y}^{\lozenge}$ denotes the group over $Y$ satisfying $\mathbb{G}_{a, Y}^{\lozenge}(R, R^+) = R$ for any $(R, R^+) \in Y_{\mathrm{v}}$;
    \item $\widehat{\mathbb{G}}_{m, \eta, Y}^{\lozenge}$ denotes the group over $Y$ satisfying $\widehat{\mathbb{G}}_{m, \eta, Y}^{\lozenge}(R, R^+) = 1 + R^{00}$ for any $(R, R^+) \in Y_{\mathrm{v}}$, where $R^{00}$ denotes the ideal of topologically nilpotent elements.
\end{itemize}
Note that all of these sheaves of abelian groups come equipped with a natural action of $\ul{\zp}$, see \S \ref{subsub:HeuerXu}. 

\subsubsection{} Recall from Example \ref{Eg:RigidGM} that there is a logarithm map $\operatorname{log}^{\lozenge} \colon \widehat{\mathbb{G}}_{m, \eta, Y}^{\lozenge} \to \mathbb{G}_{a, Y}^{\lozenge}$. Recall moreover that, for $\varpi=2p$, the map $\operatorname{log}^{\lozenge}$ is an isomorphism from $\mathbb{B}(1, |\varpi|)$ to $\mathbb{B}(0, |\varpi|)$, with inverse defined by the usual exponential series.

\subsubsection{} We let $H_{\Lambda}=\Lambda^* \otimes_{\ul{\mathbb{Z}_p}} \widehat{\mathbb{G}}_{m,\eta,Y}^\lozenge$ be the full character group of $\Lambda$ (in terms of Definition \ref{Def:CharacterDatum}, this is the group $H_{\mathcal{X}}$ corresponding to the locally analytic character datum $\mathcal{X}=(\Lambda, \Lambda \otimes_{\ul{\zp}} \mathcal{O}_Y, \mathrm{id}_{\Lambda \otimes_{\ul{\zp}} \mathcal{O}_Y})$).  

\begin{Def}\label{def.H-lambda-charts}
    Let $i \geq 0$ and set $\varpi = 2p$. We define $H^{(i)}_{\Lambda} \subset H_{\Lambda}$ to be the open\footnote{To see that this is open, we can check this v-locally -- in particular, we may assume that $\Lambda$ is free, and then the result is clear.} subgroup defined by
    \[
    H^{(i)}_{\Lambda} = \Lambda^{\ast} \otimes_{\ul{\mathbb{Z}_p}} \mathbb{B}(1, |\varpi|^{1/p^i})_Y^{\lozenge}
    \]
    where $\mathbb{B}(1, |\varpi|^{1/p^i}) \subset \widehat{\mathbb{G}}_{m, \eta}$ denotes the subset defined by the inequality $|T|^{p^i} \leq |\varpi|$. 
\end{Def}



Note that $H_{\Lambda} = \bigcup_{i \geq 0} H^{(i)}_{\Lambda}$, and $\mathcal{O}_{H_{\Lambda}/Y}$ is locally strongly countably Fr\'{e}chet, with a presentation given by $\mathcal{O}_{H_{\Lambda}/Y} = \varprojlim_i \mathcal{O}_{H^{(i)}_{\Lambda}/Y}$, see Proposition \ref{Prop:GeometricFrechet}-(3).


\subsubsection{}

Let $Z_{\Lambda} = \Lambda \otimes_{\ul{\mathbb{Z}_p}} \mathbb{G}_{a, Y}^{\lozenge}$. We will also consider certain open subgroups of this space thickening $\Lambda$ as in Lemma \ref{Lem:OgammalaIsLB}. Explicitly:

\begin{Def}
For $i \geq 0$, consider the open affinoid subgroup $\mathbb{G}^{(n)}_a \subset \mathbb{G}_a$ given by $\mathbb{G}^{(n)}_a(R, R^+) = \ul{\mathbb{Z}_p}(R) + p^i R^+$. We let
\[
Z_{\Lambda,i} := \Lambda \otimes_{\ul{\mathbb{Z}_p}} \mathbb{G}_{a,Y}^{(i), \lozenge} \subset Z_{\Lambda} 
\]
denote the corresponding open subgroup. 
\end{Def}


\begin{Lem}
$\mathcal{O}_{Z_{\Lambda,i}/Y}$ is locally countably orthonormalizable Banach. 
\end{Lem}
\begin{proof}
For $(R, R^+) \in Y_{\mathrm{v}}$ such that $\Lambda|_{\operatorname{Spa}(R, R^+)}$ is free of rank $h$, if we fix an isomorphism $\Lambda|_{\Spa(R,R^+)}\cong \ul{\mathbb{Z}_p^h}$, then $Z_{\Lambda,n, \spd(R,R^+)}$ is a disjoint union of balls indexed by $(\mathbb{Z}_p/p^n\mathbb{Z}_p)^h$. The lemma now follows from Lemma \ref{Lem:SheafBanach}.
\end{proof}

For $i \geq 0$, also consider the subgroup $Z_{\Lambda,i}^{\circ} \subset Z_{\Lambda,i}$ given by the sheafification of 
    \[
    (R, R^+) \mapsto p^i\left( \Lambda(R) \otimes_{\ul{\mathbb{Z}_p}(R)} R^+ \right).
    \]

\begin{Lem}\label{lemma.lambda-thickening-pushout}
The natural map $\Lambda \oplus Z_{\Lambda,i}^\circ \rightarrow Z_{\Lambda,i},\; (\lambda, z) \mapsto \lambda + z$ is a surjection with kernel $p^i \Lambda$ embedded antidiagonally by $\lambda \mapsto (\lambda,-\lambda)$. 
\end{Lem}
\begin{proof}
    Immediate. 
\end{proof}

Consider the natural pairing
\begin{align*} \kappa_{\Lambda}: \Lambda \times H_{\Lambda} &\rightarrow \mathbb{G}_{m, \eta, Y}^{\lozenge} \\
 (\lambda, \lambda' \otimes z) & \mapsto z^{\lambda'(\lambda)}.
\end{align*} 
It is bilinear: 
\begin{equation}\label{eq.univ-char-bilinearity} \kappa(x_1+x_2, y)=\kappa(x_1, y)\kappa(x_2, y) \textrm{ and } \kappa(x, y_1y_2) = \kappa(x, y_1)\kappa(x, y_2).\end{equation}

Since $\mathbb{G}_{m, \eta, Y}^{\lozenge} \subseteq \mathbb{A}^{1,\lozenge}_Y$, we may view $\kappa_{\Lambda}$ as an element of $\mathcal{O}(\Lambda \times_Y H_{\Lambda})=\mathcal{O}_{\Lambda/Y}(H_{\Lambda}).$ 

\begin{Lem}
    For each $i\geq 0$, the restriction $\kappa|_{\Lambda \times H^{(i)}_{\Lambda}}$ extends naturally to a pairing
\[ \kappa_{\Lambda,i}: Z_{\Lambda,i} \times H_{\Lambda}^{(i)} \rightarrow \mathbb{G}_{m, \eta, Y}^{\lozenge}. \]
In particular, 
    $\kappa_{\Lambda} \in \mathcal{O}_{\Lambda/Y}^{\locan}(H_{\Lambda}) \subseteq \mathcal{O}_{\Lambda/Y}(H_{\Lambda})$. 
\end{Lem}
\begin{proof}
We can define a pairing on $Z_{\Lambda,i}^\circ \times H_{\Lambda}^{(i)}$
by 
\[ 
(\lambda \otimes r, \lambda' \otimes z) \mapsto \mathrm{exp}(\lambda'(\lambda) r \log(z)),
\]
where the exponential converges because $\lambda'(\lambda) \in \underline{\mathbb{Z}_p} \subseteq \mathcal{O}^+$, $r \in p^i \mathcal{O}^+$, and $\log(z) \in p^{-i}\varpi \mathcal{O}^+$, so that the product lies in $\varpi \mathcal{O}^+$. This pairing agrees with $\kappa_\Lambda$ on $p^i \Lambda \times H^{(i)}_{\Lambda}$, thus we obtain the desired pairing $\kappa_{\Lambda, i}$ by invoking Lemma \ref{lemma.lambda-thickening-pushout}. Since 
\[ 
\mathcal{O}_{\Lambda/Y}^\locan(H_{\Lambda})=\varprojlim_i \mathcal{O}_{\Lambda/Y}^\locan(H_{\Lambda}^{(i)})=\varprojlim_i \varinjlim_j \mathcal{O}(Z_{\Lambda,j} \times H_{\Lambda}^{(i)})
\]
we conclude $\kappa_{\Lambda} \in \mathcal{O}_{\Lambda/Y}^\locan(H_{\Lambda})$ (note that for $j \geq i$, we have $\kappa_{\Lambda,j}|_{Z_{\Lambda, j} \times_Y H_{\Lambda}^{(i)}} = \kappa_{\Lambda,i}|_{Z_{\lambda,j} \times_Y H_{\Lambda}^{(i)}}$).
\end{proof}







\begin{Eg} \label{Eg:kappaForTrivialLambda}
    Suppose that $Y = \operatorname{Spa}(R, R^+)$ for $(R,R^+)$ a fiercely v-complete Huber pair over $(\qp,\zp)$, and let $\Lambda = \underline{\mathbb{Z}_p}$ be the trivial local system. Then $H_{\Lambda}(Y) = \mathbb{G}_{m, \eta, Y}^{\lozenge}(Y) = 1 + R^{00}$ and $Z_{\Lambda, i}(Y) = \underline{\mathbb{Z}_p}(R) + p^i R^+$. The pairing $\kappa$ is given by
    \[
    \kappa(z, 1+t) = (1+t)^z = \sum_{k=0}^{\infty} { z \choose k} t^k \; \in \; 1 + R^{00}.
    \]
    For $z \in 1+p^i R^+$, we find this series converges for $t \in \varpi^{1/p^i} R^+$. This can also be deduced from Amice's description of an orthonormal basis for $\mathcal{O}(Z_{\ul{\mathbb{Z}_p},n})$ (see \S \ref{sub:TheAmiceTransform}).
\end{Eg}

\begin{Lem}\label{Lem.DerivationActionLocAn}\hfill
\begin{enumerate} 
\item For the derivation action $\cdot$ of $\Lambda_{H_{\Lambda}} \otimes_{\ul{\zp}} \mathcal{O}_{H_\Lambda}$ on $\mathcal{O}_{\Lambda_{H_\Lambda}/H_{\Lambda}}^\locan$,
\[
\lambda \cdot \kappa_{\Lambda} = \langle \lambda, \log_{H_{\Lambda}}\rangle \kappa_{\Lambda},
\]
where we view $\log_{H_{\Lambda}}$ as a section of $\Lambda_{H_\Lambda}^* \otimes_{\ul{\zp}} \mathcal{O}_{H_\Lambda}$ over $H_\Lambda$. 
\item For the derivation action $\cdot$ of $\Lambda_{H_\Lambda}^* \otimes_{\ul{\zp}} \mathcal{O}_{H_\Lambda}$ on $\mathcal{O}^{\locan}_{\Lambda_{H_\Lambda}/H_{\Lambda}}$, 
\[
\lambda' \cdot \kappa_{\lambda} = \lambda' \kappa_\Lambda,
\]
where on the right-hand side $\lambda'$ is viewed as a function on $\Lambda_{H_\Lambda}$. Here we are identifying $\Lambda_{H_\Lambda}^* \otimes_{\ul{\zp}} \mathcal{O}_{H_\Lambda} = \operatorname{Lie}H_{\Lambda} \otimes_{\mathcal{O}_Y} \mathcal{O}_{H_{\Lambda}}$.
\end{enumerate}
\end{Lem}
\begin{proof}
For both statements, it suffices to work over an affinoid perfectoid $Y'=\Spa (A,A^+) \rightarrow H_\Lambda$ such that $\Lambda|_{Y'} \cong \mathbb{Z}_p^h$ is trivial. Then, fixing such a trivialization, we may view $\kappa_\Lambda$ as an element of $C^\locan(\mathbb{Z}_p^h, A)$ and view $\log_{H_{\Lambda}}$ as an element of $(\mathbb{Z}_p^h)^* \otimes_{\mathbb{Z}_p} A$. By construction, for $x$ in a small enough neighborhood of $0 \in \mathbb{Z}_p^h$, $\kappa(x)=\exp( \langle x, \log_{H_{\Lambda}}\rangle).$

Let $A[\varepsilon]$ denote the ring of dual numbers over $A$ (so $\varepsilon^2 = 0$). For $\lambda \in (\Lambda_{H_{\Lambda}} \otimes_{\ul{\zp}} \mathcal{O}_{H_\Lambda})(Y') = A^h$, we can then compute
\begin{align*} (\lambda \cdot \kappa_\Lambda)(x) & =  \varepsilon^{-1} \cdot (\kappa_\Lambda(x+\varepsilon \lambda) - \kappa_\Lambda(x)) \\
&= \kappa_\Lambda(x) \varepsilon^{-1}(\kappa_\Lambda(\varepsilon \lambda)- 1) \\
&= \kappa_\Lambda(x) \varepsilon^{-1}\exp( \langle \varepsilon \lambda, \log_{H_{\Lambda}} \rangle - 1)\\
&= \kappa_\Lambda(x) \langle \lambda, \log_{H_{\Lambda}} \rangle. \end{align*}
This establishes (1). Similarly, we obtain (2) by computing 
\begin{align*} (\lambda' \cdot \kappa_{\Lambda})(x) & =  \varepsilon^{-1}(\exp(\lambda' \varepsilon) \kappa_\Lambda(x)) - \kappa_\Lambda(x)) \\
&= \varepsilon^{-1}((1+ \lambda'\varepsilon)\kappa_{\Lambda}(x)-\kappa_{\Lambda}(x))\\
&=\lambda' \kappa_\Lambda(x). 
\end{align*}

\end{proof}

\subsubsection{General locally analytic character groups} \label{SubSub:GeneralPDivGps}

Let $Y$ be a small v-stack, and let $\mathcal{X}=(\Lambda, V, \gamma)$ be a locally analytic character datum as in Definition \ref{Def:CharacterDatum} with associated character group $H_\mathcal{X} \subseteq H_{\Lambda}$. We let $\kappa_{\mathcal{X}}$ be the restriction of $\kappa_{\Lambda}$ to $\Lambda \times_Y H_{\mathcal{X}}$. 


\begin{Lem} \label{Lem:UniversalKappaAsSection}
One has $\kappa_{\mathcal{X}} \in \mathcal{O}_{\Lambda/Y}^{\gamma-\locan}(H_{\mathcal{X}})$. Furthermore, this section is contravariantly functorial in the character datum $\mathcal{X}$ in the following sense: If $\mathcal{X}'=(\Lambda', V', \gamma')$ is another locally analytic character datum and we have a morphism $\mathcal{X} \to \mathcal{X}'$, then the images of $\kappa_{\mathcal{X}}$ and $\kappa_{\mathcal{X}'}$ agree under the natural maps $\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}(H_{\mathcal{X}}) \to \mathcal{O}_{\Lambda/Y}^{\gamma-\locan}(H_{\mathcal{X}'})$ and $\mathcal{O}_{\Lambda/Y}^{\gamma'-\locan}(H_{\mathcal{X}'}) \to \mathcal{O}_{\Lambda'/Y}^{\gamma-\locan}(H_{\mathcal{X}'})$ respectively.
\end{Lem}
\begin{proof}
The functoriality is immediate from the definitions, so we will just verify that $\kappa_{\mathcal{X}} \in \mathcal{O}_{\Lambda/Y}^{\gamma-\locan}(H_{\mathcal{X}})$. 
It is equivalent to verify that $\kappa_{\mathcal{X}}$, viewed as a global section of $\mathcal{O}_{\Lambda_{H_{\mathcal{X}}}/H_{\mathcal{X}}}^\locan$ over $H_{\mathcal{X}}$, lies in $\mathcal{O}_{\Lambda_{H_{\mathcal{X}}}/H_{\mathcal{X}}}^{\gamma-\locan}$. By Lemma \ref{Lem:LaAndCauchyRiemann}, for $W:=\ker \gamma$, it is then equivalent to verify that $\kappa_{\mathcal{X}}$ is annihilated by the invariant derivation action of $W \subseteq \Lambda_{H_{\Lambda}} \otimes_{\ul{\zp}} \mathcal{O}_{H_{\Lambda}}.$ But by Lemma \ref{Lem.DerivationActionLocAn}, a section $w$ of $W$ acts as multiplication by the function $\langle w, \log_{H_\Lambda}|_{H_{\mathcal{X}}} \rangle$. Since, by the definition of $H_{\mathcal{X}}$, we have that $\log_{H_{\Lambda}}|_{H_{\mathcal{X}}}=\log_{H_{\mathcal{X}}}$ lies in the annihilator of $W$, we conclude. 
\end{proof}



\subsection{Constructing the Fourier transforms} \label{Sub:FourierDef}

Let $Y$ be a small v-stack and let $\mathcal{X}=(\Lambda, V, \gamma)$ be a locally analytic character datum over $Y$ as in Definition \ref{Def:CharacterDatum}. Recall that 
\[ \mathcal{D}_{\Lambda/Y}^{\gamma-\locan} := \Hom_{\mathcal{O}_Y}(\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}, \mathcal{O}_Y) \textrm{ and } \mathcal{D}_{H_{\mathcal{X}}}= \Hom_{\mathcal{O}_Y}(\mathcal{O}_{H_{\mathcal{X}}/Y}, \mathcal{O}_Y). \]

We now use the universal character $\kappa_{\mathcal{X}}$ to define our Fourier transforms. 
\subsubsection{} For $\pi: \mathcal{H}_{\mathcal{X}} \rightarrow Y$, we define $\mathbb{F}_{\mathcal{X}}: \mathcal{D}_{\Lambda/Y}^{\gamma-\locan}  \rightarrow \mathcal{O}_{H_{\mathcal{X}}/Y}$ to be the composition of the natural maps
\[ \mathcal{D}_{\Lambda/Y}^{\gamma-\locan} \rightarrow \pi_*\pi^*\mathcal{D}_{\Lambda/Y}^{\gamma-\locan}=\pi_* \mathcal{D}_{\Lambda_{H_{\mathcal{X}}}/H_\mathcal{X}}^{\gamma-\locan} \xrightarrow{\mu \mapsto \mu(\kappa_{\mathcal{X}})} \pi_*\mathcal{O}_{H_{\mathcal{X}}}=\mathcal{O}_{H_{\mathcal{X}}/Y}. \]
From the functoriality properties of Lemma \ref{Lem:UniversalKappaAsSection}, it follows that $\mathbb{F}_{\mathcal{X}}$ is a natural transformation between covariant functors of the character datum $\mathcal{X}$. 

\subsubsection{} For $\rho: \Lambda \rightarrow Y$, we define $\mathbb{F}^{\mathcal{X}}_0$ to be the composition of the natural maps (where now we consider $\kappa$ as an element of $\mathcal{O}_{H \times_{Y} \Lambda / \Lambda}(\Lambda)$)
\[ \mathcal{D}_{H_{\mathcal{X}}/Y} \rightarrow \rho_*\rho^* \mathcal{D}_{H_{\mathcal{X}}/Y} = \rho_* \mathcal{D}_{H_{\mathcal{X}} \times_Y \Lambda/\Lambda} \xrightarrow{ \mu \mapsto  \mu(\kappa_{\mathcal{X}})} \rho_*\mathcal{O}_{\Lambda}=\mathcal{O}_{\Lambda/Y}.\]

\begin{Lem}\label{lem.fourier-factorization} 
With notation as above, $\mathbb{F}^\mathcal{X}_0$ factors through a unique map
\[
\mathbb{F}^{\mathcal{X}}: \mathcal{D}_{H_{\mathcal{X}}/Y} \to \mathcal{O}_{\Lambda/Y}^{\gamma-\locan}
\]
via the inclusion $\mathcal{O}_{\Lambda/Y}^{\gamma-\locan} \subseteq \mathcal{O}_{\Lambda/Y}$. 
\end{Lem}
\begin{proof}
Uniqueness follows from the injectivity of $\mathcal{O}_{\Lambda/Y}^{\gamma-\locan} \rightarrow \mathcal{O}_{\Lambda/Y}$ (Lemma \ref{lemma.restriction-map-injective}). Thus, to see that the factorization exists, it suffices to verify it assuming $Y$ is affinoid perfectoid and $V$ is free. We then take subgroups $H_n$ as in Lemma \ref{Lem:GeometryofH}. Applying Lemma \ref{Lem:FrechetDualSheaf}, we find 
\[
 \mathcal{D}_{H_{\mathcal{X}}/Y} = \varinjlim_n \mathcal{D}_{H_{n}/Y}, \]
so it suffices to treat the analogous maps 
\[ \mathcal{D}_{H_n/Y} \rightarrow \rho_*\rho^{*} \mathcal{D}_{H_n/Y} = \rho_* \mathcal{D}_{H_n \times_Y \Lambda/ \Lambda }\xrightarrow{\mu \mapsto \mu(\kappa_{\mathcal{X}}|_{H_n \times_Y \Lambda})} \rho_*\mathcal{O}_{\Lambda}=\mathcal{O}_{\Lambda/Y}.\]
Restricting to any affinoid perfectoid $Y'/Y$ where $\Lambda$ is free of finite rank and $W=\ker \gamma$ is free, Lemma \ref{Lem:UniversalKappaAsSection} implies
\[ \restr{\kappa_{\mathcal{X}}}{Y'} \in C^\locan(\mathbb{Z}_p^h, \mathcal{O}_{H_n/Y}(Y'))^{W=0} \subseteq \Cont(\mathbb{Z}_p^h, \mathcal{O}_{H_n/Y}(Y'))=\mathcal{O}_{H_{n} \times_Y \Lambda/\Lambda}(Y'_\Lambda).\]
Applying a section $\mu$ of $\mathcal{D}_{H_n/Y}(Y')$ is accomplished on the coefficients, so we find that the image of such a $\mu$ lies in 
$C^\locan(\mathbb{Z}_p^h, \mathcal{O}(Y'))^{W=0}$
and thus is $\gamma$-locally analytic by Lemma \ref{Lem:LaAndCauchyRiemann}.
\end{proof}

From the functoriality properties of Lemma \ref{Lem:UniversalKappaAsSection}, it follows that $\mathbb{F}^{\mathcal{X}}$ is a natural transformation of contravariant functors on character data $\mathcal{X}$. 



\subsubsection{}
Recall from \S \ref{subsub:Hopf} and Lemma \ref{Lem:GammaLaSheavesHopf} that all of the solid sheaves of $\mathcal{O}_Y$-modules $\mathcal{O}_{\Lambda/Y}^{\gamma\mathrm{-la}}$, $\mathcal{D}_{\Lambda/Y}^{\gamma\mathrm{-la}}$, $\mathcal{O}_{H_{\mathcal{X}}/Y}$, $\mathcal{D}_{H_{\mathcal{X}}/Y}$, are naturally solid Hopf $\mathcal{O}_Y$-algebras.

\begin{Lem} \label{Lem:MorphismOfHopfAlgebras}
    Let $\mathcal{X} = (\Lambda, V, \gamma)$ be a locally analytic character datum. 
    \begin{enumerate}
        \item The Fourier transforms $\mbb{F}_{\mathcal{X}}$ and $\mbb{F}^{\mathcal{X}}$ are morphisms of solid Hopf $\mathcal{O}_Y$-algebras.
        \item The Fourier transforms $\mbb{F}_{\mathcal{X}}$ and $\mbb{F}^{\mathcal{X}}$ are mutually dual under the reflexivity of $\mathcal{O}_{H_\mathcal{X}}$ and $\mathcal{O}_{\Lambda/Y}^{\gamma\mathrm{-la}}$ proved in Proposition \ref{Prop:GeometricFrechet}-(2) and Proposition \ref{Prop:GeometricLB}-(2).
    \end{enumerate}
\end{Lem}
\begin{proof}
    The first part follows from functoriality in the character datum. For example, consider the diagonal morphism
    \[
    \Delta \colon \Lambda \to \Lambda \oplus \Lambda 
    \]
    which induces a morphism of character data  $\mathcal{X} \to \mathcal{X} \oplus \mathcal{X} = (\Lambda \oplus \Lambda, V \oplus V, \gamma \oplus \gamma)$. The linear dual of this map $\Delta^{\ast} \colon \Lambda^{\ast} \oplus \Lambda^{\ast} \to \Lambda^{\ast}$ is the addition map, and induces the multiplication map $H_{\mathcal{X}} \times H_{\mathcal{X}} \to H_{\mathcal{X}}$ via the identification $H_{\mathcal{X}} \times_Y H_{\mathcal{X}} = H_{\mathcal{X} \oplus \mathcal{X}}$. On the other hand, the diagonal map induces the diagonal $Z_{\Lambda,n} \to Z_{\Lambda \oplus \Lambda,n} = Z_{\Lambda,n} \times Z_{\Lambda,n}$, which in turn induces the algebra structure on $\mathcal{O}_{Z_{\Lambda, n}/Y}$ (and hence $\mathcal{O}_{\Lambda/Y}^{\gamma\operatorname{-la}}$). The functoriality of $\mathbb{F}^{\bullet}$ with respect to the diagonal map $\Delta$ now implies that $\mbb{F}^{\mathcal{X}}$ is a morphism of $\mathcal{O}_Y$-algebras. The other assertions about $\mbb{F}_{\mathcal{X}}$ and the comultiplication structures can be proved similarly, and we leave the details to the reader. 

We now establish the second part. Let $\rho: \Lambda \rightarrow Y$ and $\pi: H_{\mathcal{X}} \rightarrow Y$ denote the structure maps. We claim that for $Y'/Y$, $\mu\in \mathcal{D}_{\Lambda}^{\gamma-\locan}(Y')$, and $\delta \in \mathcal{D}_{H_{\mathcal{X}}}(Y')$,  
\begin{equation}\label{eq.order-doesnt-matter-concat} \delta((\pi^*\mu)(\kappa_{\mathcal{X}})) = \mu( (\rho^*\delta)(\kappa_{\mathcal{X}})).  \end{equation}
Indeed, as in the proof of Lemma \ref{lem.fourier-factorization}, it suffices to assume $Y=Y'=\Spd(R,R^+)$ is affinoid perfectoid with $V$ trivial, and to replace $H_{\mathcal{X}}$ with one of the $H_n$'s as in Lemma~\ref{Lem:GeometryofH}. Then, for $U_i$ as in Lemma \ref{Lem:OgammalaIsLB},
\begin{align*} \pi_*\mathcal{O}^{\gamma-\locan}_{\Lambda \times_Y H_n / H_n} &=  \pi_* \varinjlim_i \mathcal{O}_{U_i \times_Y H_n / H_n}	 \\
&=  \varinjlim_i  \left(\pi_* \mathcal{O}_{U_i \times_Y H_n/H_n}\right) \\
&=  \varinjlim_i \left(\mathcal{O}_{U_i \times_Y H_n / Y} \right)\\
&=  \varinjlim_i \left(\mathcal{O}_{U_i / Y} \otimes_{\mathcal{O}_Y}^{\blacksquare} \mathcal{O}_{H_n / Y} \right)\\
&= \left( \varinjlim_i \mathcal{O}_{U_i / Y} \right)\otimes_{\mathcal{O}_Y}^{\blacksquare} \mathcal{O}_{H_n / Y}\\
&=  \mathcal{O}_{\Lambda/Y}^{\gamma\mathrm{-la}} \otimes_{\mathcal{O}_Y}^{\blacksquare} \mathcal{O}_{H_n / Y} 
\end{align*}
where the second equality is because $\pi:H_n \rightarrow Y$ is quasi-compact, the fourth equality is by Lemma \ref{Lem:Kunneth1}, and the fifth equality is because colimits and solid tensor products commute. 
In this presentation, \eqref{eq.order-doesnt-matter-concat} can be unwound to the statement that we can concatenate $\kappa_{\mathcal{X}}|_{\Lambda \times_Y H_n}$, viewed as a section of this sheaf, with $\mu$ and $\delta$ in either order. 

Given \eqref{eq.order-doesnt-matter-concat}, the verification that $\mathbb{F}^{\mathcal{X}}$ and $\mathbb{F}_{\mathcal{X}}$ are mutually dual is essentially formal: for example, we have 
\[ 
(\mathbb{F}_{\mathcal{X}}^*\delta)(\mu) = \delta(\mathbb{F}_{\mathcal{X}}(\mu))=\delta(\pi^*\mu(\kappa_{\mathcal{X}}))=\mu(\rho^*\delta(\kappa_{\mathcal{X}}))=\mu(\mathbb{F}^{\mathcal{X}}(\delta)).
\]
\end{proof}

\begin{Lem} \label{Lem:TheAmiceCase}
If $Y=\spa \qp$ and $\mathcal{X}=(\ul{\zp}, \mathcal{O}_Y, \ul{\zp} \xrightarrow{} \mathcal{O}_Y)$, then $\mathbb{F}_{\mathcal{X}}$ is an isomorphism.
\end{Lem}
\begin{proof}
For $(A,A^+)$ affinoid perfectoid over $(\qp,\zp)$, the natural map
\begin{align}
    H^0_{\cond}(Y, \mathcal{O}_{\gmhateta/Y}) \otimes_{\ul{\qp}}^{\blacksquare} \ul{A} \to H^0_{\cond}(\spd(A,A^+), \mathcal{O}_{\gmhateta/Y}) 
\end{align}
is an isomorphism by Proposition \ref{Prop:GeometricFrechet}-(1). Furthermore, the natural map
\begin{align}
    H^0_{\cond}(Y, \mathcal{D}_{\ul{\zp}/Y}^{\mathrm{la}}) \otimes_{\ul{\qp}}^{\blacksquare}\ul{A} \to H^0_{\cond}(\spd(A,A^+), \mathcal{D}_{\ul{\zp}/Y}^{\mathrm{la}}) 
\end{align}
is an isomorphism by Proposition \ref{Prop:GeometricLB}-(1),(3) and Corollary \ref{Cor:DualTensorFrechetBaseChange}. Thus it suffices to show that $\mathbb{F}_{\mathcal{X}}$ induces an isomorphism on condensed global sections. \smallskip

It follows from Proposition \ref{Prop:GeometricLB}-(3) that 
\begin{align}
    H^0_{\cond}(Y, \mathcal{D}_{\ul{\zp}/Y}^{\mathrm{la}}) = \Hom_{\ul{\qp}}(H^0_{\cond}(Y, \mathcal{O}^{\la}_{\ul{\zp}/Y}), \ul{\qp}),
\end{align}
and from Example \ref{Eg:kappaForTrivialLambda} that we may identify $(\mathbb{F}_{\mathcal{X}})(\ast)$ with the bijection $\mathbb{F}_{\gmhateta}$ of Corollary \ref{cor.amice-bijections}. We conclude\footnote{They are Fr\'echet spaces by Proposition \ref{Prop:FrechetVSClassicalFrechet} together with Corollary \ref{Cor:IsFrechet} and Proposition \ref{Prop:GeometricLB}-(5).} that $F_{\mathcal{X}}(\ast)_{\mathrm{top}}$ is a continuous bijection between two Fr\'echet spaces over $\qp$ and thus an isomorphism by the open mapping theorem for $\mathbb{Q}_p$-Frechet spaces (see \cite[Proposition 8.6]{SchneiderFA}). It follows from Proposition \ref{Prop:FrechetVSClassicalFrechet} that ${\mathbb{F}}_{\mathcal{X}}$ itself is an isomorphism. 
\end{proof}

\subsection{The Fourier transforms are isomorphisms} \label{Sub:MainTheorem}

The main theorem of this article is the following (it is Theorem \ref{Thm:IntroFourierVsheaves} from the introduction). Let $Y$ be a small v-stack and let $\mathcal{X}=(\Lambda,V,\gamma)$ be a locally analytic character datum over $Y$. 
\begin{Thm} \label{Thm:Main}
    The Fourier transforms $\mbb{F}^{\mathcal{X}}$ and 
    $\mbb{F}_{\mathcal{X}}$ are isomorphisms of solid Hopf $\mathcal{O}_Y$-algebras. 
\end{Thm}

By Lemma \ref{Lem:MorphismOfHopfAlgebras}-(1), it suffices to prove that $\mathbb{F}^{\mathcal{X}}$ is an isomorphism, and this is the main goal of the rest of \S\ref{Sub:MainTheorem}. 

\begin{Prop} \label{Prop:InvariantsCoinvariants}
Let $Y$ be a small v-stack and let $\mathcal{X}=(\Lambda,V,\gamma)$ be a locally analytic character datum over $Y$. Let $W=\ker \gamma$. 
\begin{enumerate}
    \item The natural map $\mathcal{O}_{H_{\Lambda}/Y} \to \mathcal{O}_{H_{\mathcal{X}}/Y}$ identifies the target with the quotient of the source by the action of $W$ given by precomposing with multiplication by $\langle w, \operatorname{log}_{H_{\Lambda}} \rangle$.
    \item The natural map $\mathcal{D}_{H_{\mathcal{X}}/Y} \to \mathcal{D}_{H_{\Lambda}/Y}$
identifies the source with the kernel of the dual $W$-action on the target. 
\end{enumerate}
\end{Prop}
\begin{proof}[Proof of Proposition \ref{Prop:InvariantsCoinvariants}]
The second claim follows from the first since $\Hom_{\mathcal{O}_Y}(-,\mathcal{O}_Y)$ turns colimits into limits. For the first claim, we may assume that $Y=\spa (A,A^+)$ such that $V$, $\Lambda$, and $W$ are all trivial of constant rank.  Consider the Cartesian diagram
\begin{equation}
    \begin{tikzcd}
        H_{\mathcal{X}} \arrow{r} \arrow{d}{\log} & H_{\Lambda} \arrow{d}{\log} \\
        V^{\ast} \arrow{r}{\iota} & \Lambda^{\ast} \otimes_{\ul{\zp}} \mathbb{G}_{a,Y}^{\lozenge}.
    \end{tikzcd}
\end{equation}
The ideal sheaf $\mathcal{J} \subset \mathcal{O}_{H_{\Lambda}^{\mathrm{rig}}}$ cutting out $H_{\mathcal{X}}^{\mathrm{rig}}$ is a pseudo-coherent sheaf in the sense of \cite[Section 2.5]{KedlayaLiuII} by\footnote{Note that $H_{\Lambda}^{\mathrm{rig}}$ and $H_{\Lambda}^{\mathrm{rig}}$ are smooth sousperfectoid adic spaces over $Y$, this follows from Lemma \ref{Lem:GeometryofH} together with \cite[Definition 7.1, Lemma 7.5, and Lemma 7.3]{HansenKedlaya}.} \cite[Proposition IV.4.19]{FarguesScholze} and is generated by functionals of the form $\langle w , - \rangle$ for $w \in W(\Spa(A,A^+))$ by \cite[Proposition IV.4.19]{FarguesScholze}. This shows that the natural map $\mathcal{O}(H_{\Lambda}^{\mathrm{rig}}) \to \mathcal{O}(H_{\mathcal{X}}^{\mathrm{rig}})$ factors through the natural map $\mathcal{O}(H_{\Lambda}^{\mathrm{rig}}) \to  \mathcal{O}(H_{\Lambda}^{\mathrm{rig}})_{W}$ and an injection $\mathcal{O}(H_{\Lambda}^{\mathrm{rig}})_{W} \hookrightarrow \mathcal{O}(H_{\mathcal{X}}^{\mathrm{rig}})$; it now suffices to show that $\mathcal{O}(H_{\Lambda}^{\mathrm{rig}}) \to \mathcal{O}(H_{\mathcal{X}}^{\mathrm{rig}})$ is surjective. \smallskip 

The natural map $\mathcal{O}_{H_{\Lambda}^{\mathrm{rig}}} \to \mathcal{O}_{H_{\mathcal{X}}^{\mathrm{rig}}}$ is surjective by \cite[Proposition IV.4.19]{FarguesI}. The surjectivity on global sections follows directly from 
\cite[Theorem 2.6.5.(iii)]{KedlayaLiuII} since $H_{\Lambda}$ is a quasi-stein space in the sense of \cite[Definition 2.6.2]{KedlayaLiuII} by Lemma \ref{Lem:GeometryofH}. We give an alternative argument below for the surjectivity on global sections. \smallskip

Let $k$ be the rank of $W$, and choose a filtration $W=W_0 \supsetneq W_1 \supsetneq \cdots \supsetneq W_k=0$ with free graded pieces, using the freeness of $W$. Set $V_i=\Lambda \otimes_{\zp} \mathcal{O}_Y / W_i$, let $\gamma_i$ be the natural map $\Lambda \otimes_{\zp} \mathcal{O}_Y \to V_i$ and let $\mathcal{X}_i=(\Lambda, V_i, \gamma_i)$. There is a filtration
\begin{align}
    H_{\mathcal{X}}^{\mathrm{rig}}&=H_0 \subset H_1 \subset \cdots \subset H_{k}=H_{\Lambda}^{\mathrm{rig}},
\end{align}
where $H_i=H_{\mathcal{X}_i}^{\mathrm{rig}}$. It remains to show that for all $i$ the map
\begin{align}
    \mathcal{O}(H_i) \to \mathcal{O}(H_{i-1})
\end{align}
is surjective. Write $\mathcal{J}_i \subset \mathcal{O}_{H_i}$ for the ideal sheaf cutting out $H_{i-1}$, which is a line bundle because $H_{i-1}$ has codimension one, see \cite[Proposition IV.4.19]{FarguesScholze} and its proof. Write $H_i = \cup_{n \in \mathbb{Z}_{\ge 0}} H_i^{(n)}$ as in the proof of Lemma \ref{Lem:GeometryofH}. Evaluating the short exact sequence
\begin{align}
    0 \to \mathcal{J}_i \to  \mathcal{O}_{H_i} \to \mathcal{O}_{H_{i-1}} \to 0
\end{align}
on $H_{i}^{(n)}$ gives the short exact sequence (again by \cite[Proposition IV.4.19]{FarguesScholze})
\begin{align}
    0 \to \mathcal{J}_i^{(n)} \to \mathcal{O}(H_i^{(n)}) \to  \mathcal{O}(H_{i-1}^{(n)}) \to 0. 
\end{align}
We now consider the commutative diagram
\begin{equation}
    \begin{tikzcd}
        & 0 \arrow{d} & 0 \arrow{d} & 0 \arrow{d} \\
        0 \arrow{r} & \varprojlim_{n} \mathcal{J}_i^{(n)} \arrow{r} \arrow{d} & \prod_n \mathcal{J}_i^{(n)} \arrow{r} \arrow{d} & \prod_n \mathcal{J}_i^{(n)} \arrow{r} \arrow{d} & 0 \\
        0 \arrow{r} & \varprojlim_n \mathcal{O}(H_i^{(n)}) \arrow{d} \arrow{r} & \prod_{n} \mathcal{O}(H_i^{(n)}) \arrow{r} \arrow{d} & \prod_{n}\mathcal{O}(H_i^{(n)}) \arrow{d} \arrow{r} & 0 \\
        0 \arrow{r} & \varprojlim_n \mathcal{O}(H_{i-1}^{(n)}) \arrow{r} \arrow{d} & \prod_{n} \mathcal{O}(H_{i-1}^{(n)}) \arrow{r} \arrow{d} & \prod_{n} \mathcal{O}(H_{i-1}^{(n)})  \arrow{r} \arrow{d} & 0 \\
         & 0  & 0 & 0. 
    \end{tikzcd}
\end{equation}
Since the transition maps in all three inverse system have dense image by Lemma \ref{Lem:GeometryofH} and the fact that $\mathcal{J}_i$ is a line bundle, the rows are exact by the proof of Proposition \ref{Prop:FrechetFlat}. The middle and right columns are exact by the exactness of countable products, and the exactness of the left column now follows from the snake lemma. Since taking global sections of a sheaf on $H_i$ is the same as taking the inverse limit of the sections on $H_i^{(n)}$, we see that 
\begin{align}
   \mathcal{O}(H_i) \to \mathcal{O}(H_{i-1})
\end{align}
is surjective, concluding the proof. 
\end{proof}

\begin{proof}[Proof of Theorem \ref{Thm:Main}]
By Lemma \ref{Lem:MorphismOfHopfAlgebras}, the Fourier transforms are dual morphisms of solid Hopf $\mathcal{O}_Y$-algebras, so it suffices to show that $\mbb{F}^{\mathcal{X}}$ is an isomorphism of abelian sheaves. The main idea is to reduce to a statement about the classical Amice transform. More precisely, the claim is local on $Y$, so we may assume that $Y = \operatorname{Spa}(R, R^+)$ is affinoid perfectoid, $\Lambda \cong \underline{\mbb{Z}}_p^{\oplus h}$ is trivial, and $W$ is free. In this setting, consider the locally analytic character datum $\mathcal{X}'=(\Lambda, \Lambda \otimes_{\ul{\zp}} \mathcal{O}_Y, \mathrm{id}_{\Lambda \otimes_{\ul{\zp}} \mathcal{O}_Y})$. We of course have a morphism $\mathcal{X} \to \mathcal{X}'$, which induces a morphism $H_{\mathcal{X}} \to H_{\mathcal{X}'} = H_{\Lambda} = \widehat{\mathbb{G}}_{m,\eta, Y}^{\lozenge, \oplus h}$. By Proposition \ref{Prop:InvariantsCoinvariants} and Lemma \ref{Lem:LaAndCauchyRiemann}, we see that one can obtain $\mbb{F}^{\mathcal{X}}$ by passing to the $W$-invariants of 
    \[
    \mbb{F}^{\mathcal{X}'} \colon \mathcal{D}_{H_{\Lambda}/Y} \to \mathcal{O}_{\Lambda/Y}^{\mathrm{la}} .
    \]
    It therefore suffices to show that $\mbb{F}^{\mathcal{X}'}$ is an isomorphism. Using the K\"unneth formulas for $\mathcal{O}^{\operatorname{la}}_{\Lambda/Y}$, see Proposition \ref{Prop:GeometricLB}-(4), and for $\mathcal{D}_{H_{\Lambda}/Y}$, see Proposition \ref{Prop:GeometricFrechet}-(8), we deduce that it is enough to prove the theorem for $\Lambda=\ul{\zp}$. Since $\Lambda=\ul{\zp}$ is base-changed from $\spd(\qp,\zp)$, we may assume that $Y=\spd(\qp,\zp)$. Using Lemma \ref{Lem:MorphismOfHopfAlgebras}, we can equivalently show that the dual map
\begin{align}
    \mbb{F}_{\mathcal{X}'} \colon \mathcal{D}_{\ul{\zp}/Y}^{\mathrm{la}} \to \mathcal{O}_{\gmhateta/Y}
\end{align}
is an isomorphism. and then the result is Lemma \ref{Lem:TheAmiceCase}. This concludes the proof.
\end{proof}

\subsubsection{}\label{sss.solid-hopf-and-duality-discussion-fiercely} We now deduce a version of Theorem \ref{thm.rational-fourier-theory} over a fiercely v-complete affinoid. 

Let $(R,R^+)$ be a fiercely v-complete Huber pair over $(\qp,\zp)$, and let $Y=\spd(R,R^+)$. Let $\mathcal{X}=(\Lambda, V, \gamma)$ be a locally analytic character datum over $Y$ such that $V$ is free. In this case, the solid Hopf $\mathcal{O}_Y$-algebra structures on $\mathcal{O}_{H_{\mathcal{X}}/Y}$, $\mathcal{D}_{H_{\mathcal{X}}/Y},$ $\mathcal{O}_{\Lambda/Y}^{\gamma\mathrm{-la}}$, and $\mathcal{D}_{\Lambda/Y}^{\gamma\mathrm{-la}}$ induce solid Hopf $\ul{R}$-algebra structures upon taking global sections:
\begin{itemize}
    \item For $H^0_{\cond}(Y,\mathcal{O}_{H_{\mathcal{X}}/Y})$, this follows from Proposition \ref{Prop:GeometricFrechet}-(2),(7).

    \item For $H^0_{\cond}(Y,\mathcal{D}_{H_{\mathcal{X}}/Y})$, this follows from Proposition \ref{Prop:GeometricFrechet}-(4),(7),(8). 

    \item For $H^0_{\cond}(Y,\mathcal{O}_{\Lambda/Y}^{\gamma\mathrm{-la}})$, this follows from Proposition \ref{Prop:GeometricLB}-(2),(8).

    \item For $H^0_{\cond}(Y,\mathcal{D}_{\Lambda/Y}^{\gamma\mathrm{-la}})$, this follows from Proposition \ref{Prop:GeometricLB}-(4),(8),(9). 
\end{itemize}    
Moreover, we find the solid Hopf $\ul{R}$-algebras $H^0_{\cond}(Y,\mathcal{O}_{H_{\mathcal{X}}/Y})$ and $H^0_{\cond}(Y,\mathcal{D}_{H_{\mathcal{X}}/Y})$ are mutually dual Hopf $\ul{R}$-algebras by further invoking Proposition \ref{Prop:GeometricFrechet}-(3), and similarly $H^0_{\cond}(Y,\mathcal{O}_{\Lambda/Y}^{\gamma\mathrm{-la}})$ and $H^0_{\cond}(Y,\mathcal{D}_{\Lambda/Y}^{\gamma\mathrm{-la}})$ are mutually dual Hopf $\ul{R}$-algebras by Proposition \ref{Prop:GeometricLB}-(3).


\begin{Cor} \label{Cor:Main} 
Let $(R,R^+)$ be a fiercely v-complete Huber pair over $(\qp,\zp)$, let $Y=\spd(R,R^+)$ and let $\mathcal{X}=(\Lambda, V, \gamma)$ be a locally analytic character datum over $Y$. If $V$ is free, then the Fourier transforms
 \begin{align*}
        \mbb{F}^{\mathcal{X}} &\colon H^0_{\cond}(Y,\mathcal{D}_{H_{\mathcal{X}}/Y}) \to H^0_{\cond}(Y,\mathcal{O}_{\Lambda/Y}^{\gamma\mathrm{-la}})  \\
        \mbb{F}_{\mathcal{X}} &\colon H^0_{\cond}(Y,\mathcal{D}_{\Lambda/Y}^{\gamma\mathrm{-la}}) \to H^0_{\cond}(Y,\mathcal{O}_{H_{\mathcal{X}}/Y})
    \end{align*}
    are dual isomorphisms of solid $\ul{R}$-Hopf algebras. 
\end{Cor}
\begin{proof}
In light of the above discussion, this is immediate from Theorem \ref{Thm:Main} by taking global sections. 
\end{proof}

Specializing Corollary \ref{Cor:Main} to $(K, \mathcal{O}_K)$ for $K/\mathbb{Q}_p$ a $p$-adic non-archimedean extension gives Theorem~\ref{thm.rational-fourier-theory}. 

\begin{Rem}\label{remark.etale-expectations}
    We expect the computations of \S\ref{sss.solid-hopf-and-duality-discussion-fiercely} and thus also Corollary \ref{Cor:Main} to hold whenever $V$ is an \'{e}tale (equivalently, analytic) vector bundle. 
\end{Rem}

\subsection{Equivariance under invariant derivations} \label{Sub:Equivariance} We now establish the equivariance properties for the Fourier transforms $\mbb{F}^{\mathcal{X}}$ and $\mbb{F}_{\mathcal{X}}$ for invariant derivations generalizing those appearing in Proposition \ref{Prop:Equivariance}. 

\subsubsection{}
Recall from \S\ref{subsub:derivationaction} that there is a natural action of $V$ on $\mathcal{O}^{\gamma-\locan}_{\Lambda/Y}$ by invariant derivations. It extends to an action of $\Sym^\bullet V$ (by invariant differential operators; note the Lie bracket is trivial). We equip $\mathcal{D}_{\Lambda/Y}^{\gamma\mathrm{-la}}$ with the dual action of $\operatorname{Sym}^{\bullet}V$. These actions are evidently functorial in $\mathcal{X}$. 

There is a natural map $\log_{H_\mathcal{X}}: H_{\mathcal{X}} \rightarrow V^*$, so $\mathcal{O}_{H_{\mathcal{X}}/Y}$ is naturally a $\Sym^\bullet V$-algebra by pullback along $\log_{H_\mathcal{X}}$ of the polynomial functions $\Sym^\bullet V \subseteq \mathcal{O}_{V^*/Y}$. We equip $\mathcal{D}_{H_{\mathcal{X}}/Y}$ with the dual action of $\Sym^\bullet V$. These actions are evidently functorial in $\mathcal{X}$. 


\begin{Prop} \label{Prop:FTequivSymV}
    The Fourier transforms $\mbb{F}^{\mathcal{X}}$ and $\mbb{F}_{\mathcal{X}}$ are equivariant for the above actions of $\operatorname{Sym}^{\bullet}V$.
\end{Prop}
\begin{proof}
By the duality of Lemma \ref{Lem:MorphismOfHopfAlgebras}, it suffices to treat $\mbb{F}_{\mathcal{X}}$. For $v$ a section of $V$ and $\mu$ a section of $\mathcal{D}^{\gamma-\locan}_{\Lambda/Y}$, 
\[ \mbb{F}_{\mathcal{X}}(v \cdot \mu)= (v\cdot \mu)(\kappa_{\mathcal{X}})=\mu(v \cdot \kappa_{\mathcal{X}}) = \mu(\langle v, \log_{H_{\mathcal{X}}}\rangle \kappa_\mathcal{X}) \]
where the final equality is deduced from Lemma \ref{Lem.DerivationActionLocAn}-(1) and functoriality in $\mathcal{X}$. This is equal to 
$\langle v, \log_{H_{\mathcal{X}}}\rangle\mu(\kappa_\mathcal{X})$
because, by the construction of $\mathbb{F}_{\mathcal{X}}$, we are applying $\mu$ after pulling it back to an element of $D^{\gamma-\locan}_{\Lambda_{H_{\mathcal{X}}}/H_{\mathcal{X}}}$, so that it is $\mathcal{O}_{H_{\mathcal{X}}}$-linear.  
\end{proof}


\subsubsection{}
Since $\operatorname{Lie}H_{\mathcal{X}}$ is identified with $V^{\ast}$, we obtain an action of $V^{\ast}$ on $\mathcal{O}_{H_{\mathcal{X}}/Y}$ through invariant derivations. It extends to an  action of $\operatorname{Sym}^{\bullet}V^{\ast}$ (by invariant differential operators; note the Lie bracket is trivial). We equip $\mathcal{D}_{H_{\mathcal{X}}/Y}$ with the dual action of $\operatorname{Sym}^{\bullet}V^{\ast}$. These actions are evidently functorial in $\mathcal{X}$. 

There is a natural map $\gamma|_{\Lambda}: \Lambda \rightarrow V$, which induces by pullback an algebra map $\mathcal{O}_{V/Y} \rightarrow \mathcal{O}_{\Lambda/Y}$. By definition, it factors through $\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}$. In particular, restricting to the polynomial functions $\Sym^{\bullet} V^{\ast} \subseteq  \mathcal{O}_{V/Y}$, we obtain a $\Sym^\bullet V^{\ast}$-module structure on $\mathcal{O}^{\gamma-\locan}_{\Lambda/Y}$. We equip $\mathcal{D}^{\gamma-\locan}_{\Lambda/Y}$ with the dual action of $\Sym^\bullet V^{\ast}$. These actions are evidently functorial in $\mathcal{X}$. 



\begin{Prop} \label{Prop:FTSymVstarEquiv}
    The Fourier transforms $\mbb{F}^{\mathcal{X}}$ and $\mbb{F}_{\mathcal{X}}$ are equivariant for the actions of $\operatorname{Sym}^{\bullet}V^{\ast}$ described above.
\end{Prop}
\begin{proof}
By the duality of Lemma \ref{Lem:MorphismOfHopfAlgebras}, it suffices to treat $\mathbb{F}_\mathcal{X}$. For $v'$ a section of $V^*$ and $\mu$ a section of $\mathcal{D}^{\gamma-\locan}_{\Lambda/Y}$, 
\[ \mbb{F}_{\mathcal{X}}( v' \cdot \mu)= (v' \cdot \mu)(\kappa_{\mathcal{X}})=\mu( (\gamma^*v') \kappa_{\mathcal{X}}). \]
On the other hand, 
\[ v' \cdot \mathbb{F}_\mathcal{X}(\mu)  = v' \cdot \mu(\kappa_{\mathcal{X}})=\mu(v' \cdot \kappa_{\mathcal{X}}) \]
where the final equality holds because the differentiation is happening in the coefficients direction. By functoriality, the result then follows from Lemma \ref{Lem.DerivationActionLocAn}-(2). 
\end{proof}

Specialising Propositions \ref{Prop:FTequivSymV} and \ref{Prop:FTSymVstarEquiv} to $Y = \operatorname{Spd}(K, \mathcal{O}_K)$ completes the proof of Proposition \ref{Prop:Equivariance} in the introduction.



\subsection{Classical interpretation over a field} \label{Sub:Field} Let $K$ be a non-archimedean field with completed algebraic closure $C$. We will now explain how to interpret Corollary \ref{Cor:Main} for $Y=\spa(K,\mathcal{O}_K)$ in terms of locally convex topological vector spaces over $K$. 

\subsubsection{} Let $\mathcal{X}=(\Lambda,V,\gamma)$ be a locally analytic character datum and suppose that $V$ is trivial (equivalently, an \'etale vector bundle). Then concretely, we can think of $\Lambda$ as a continuous representation of $\mathrm{Gal}(\overline{K}/K)$ on a finite free $\mathbb{Z}_p$-module $\Lambda$, of $V$ as a finite dimensional $K$-vector space, and of $\gamma: \Lambda_C \twoheadrightarrow V_{C}$ as a $\mathrm{Gal}(\overline{K}/K)$-equivariant surjection. Let $\mathcal{O}^{\gamma-\locan}(\Lambda)$ be the locally convex vector space of locally analytic functions from $\Lambda$ to $C$ that are $\Gal(\overline{K}/K)$-equivariant and $\gamma$-locally analytic, i.e., locally on $\Lambda$, factor as the composition of $\gamma$ with an analytic function on an open ball in $V_C$. We let $\mathcal{D}^{\gamma-\locan}(\Lambda)$ be its dual equipped with the strong topology, see Section \ref{subsub:weakdual}.

Let $H_{\mathcal{X}}$ be the $p$-divisible v-group over $\spd(K, \mathcal{O}_K)$ associated with $\mathcal{X}$. Since $V$ is an \'etale vector bundle, this is the diamond associated to a $p$-divisible rigid analytic group over $\spa(K, \mathcal{O}_K)$ by Proposition \ref{Prop:Representable}, which we will denote by $H_{\mathcal{X}}^{\mathrm{rig}}$. Let us write $\mathcal{O}(H_{\mathcal{X}}^{\mathrm{rig}})$ for the locally convex $K$-Fr\'echet space of global sections. 
\begin{Lem} \label{Lem:LocallyConvexVSCondensed}
    There are natural isomorphisms
    \begin{align}
        H^0_{\cond}(Y,\mathcal{O}_{H_{\mathcal{X}}/Y}) &\xrightarrow{\sim} \ul{\mathcal{O}(H_{\mathcal{X}}^{\mathrm{rig}})} \\
         H^0_{\cond}(Y,\mathcal{D}_{\Lambda/Y}^{\gamma-\locan}) &\xrightarrow{\sim}\ul{\mathcal{D}^{\gamma\mathrm{-la}}(\Lambda)}.
    \end{align}
\end{Lem}
\begin{proof}
For the second isomorphism, we first recall from \S\ref{sss.solid-hopf-and-duality-discussion-fiercely}
 that
\begin{align}
     H^0_{\cond}(Y,\mathcal{D}_{\Lambda/Y}^{\gamma-\locan}) &= \Hom_{\ul{K}}(H^0_{\cond}(Y,\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}), \ul{K}).
\end{align}
We now continue in the notation of Lemma \ref{Lem:OgammaisLSspace}
\begin{align}
     \Hom_{\ul{K}}(H^0_{\cond}(Y,\mathcal{O}_{\Lambda/Y}^{\gamma-\locan}), \ul{K})&=\Hom_{\ul{K}}(H^0_{\cond}(Y, \varinjlim_{n} \mathcal{O}^{\mathrm{bdd}}_{U_{n}^{\circ}/Y}), \ul{K}) \\
     &=\Hom_{\ul{K}}(\varinjlim_{n}  H^0_{\cond}(Y, \mathcal{O}^{\mathrm{bdd}}_{U_{n}^{\circ}/Y}), \ul{K}) \\
     &=\varprojlim_{n} \Hom_{\ul{K}}(H^0_{\cond}(Y, \mathcal{O}^{\mathrm{bdd}}_{U_{n}^{\circ}/Y}), \ul{K}) \\
     &=\varprojlim_{n} \Hom_{\ul{K}}(\ul{\mathcal{O}^{\mathrm{bdd}}(U_n^{\circ})}, \ul{K}),
\end{align}
where the last equality is Lemma \ref{Lem:BoundedFunctions}. We can similarly write ($\mathrm{lcv}$ stands for locally convex) 
\begin{align}
    \mathcal{D}^{\gamma\mathrm{-la}}(\Lambda) &= \left(\mathcal{O}^{\gamma\mathrm{-la}}(\Lambda)\right)'_{b} \\
    &=\left(\varinjlim_n^{\mathrm{lcv}} \mathcal{O}^{\mathrm{bdd}}(U_n^{\circ})\right)'_{b} \\
    &=\varprojlim_n \left(\mathcal{O}^{\mathrm{bdd}}(U_n^{\circ})\right)'_{b}. 
\end{align}
It is a consequence of Lemma \ref{Lem:TopologicalDuals} that 
\begin{align}
   \ul{\left(\mathcal{O}^{\mathrm{bdd}}(U_n^{\circ})\right)'_b} \simeq \Hom_{\ul{K}}(\ul{\mathcal{O}^{\mathrm{bdd}}(U_n^{\circ})}, \ul{K}).
\end{align}
This, together with the commutation of $W \mapsto \ul{W}$ with limits, concludes the proof of the second isomorphism. 

For the first isomorphism, we write (in the notation of Lemma \ref{Lem:GeometryofH})
\begin{align}
    H^0_{\cond}(Y,\mathcal{O}_{H_{\mathcal{X}}/Y}) = \varprojlim_n H^0_{\cond}(Y,\mathcal{O}_{H_{n}/Y}) = \varprojlim_n \ul{\mathcal{O}(H_n)},
 \end{align}
using Lemma \ref{Lem:CondensedRingStructure}. We similarly have
\begin{align}
    \mathcal{O}(H_{\mathcal{X}}^{\mathrm{rig}})= \varprojlim_n \mathcal{O}(H_n),
\end{align}
and we conclude as before. 
\end{proof}

\subsubsection{} We have the following corollary of Theorem \ref{thm.rational-fourier-theory}.
\begin{Cor} \label{Cor:LocallyConvexMain}
    There is an isomorphism of locally convex $K$-vector spaces
    \begin{align}
        \mathcal{D}^{\gamma\mathrm{-la}}(\Lambda) &\xrightarrow{\sim} \mathcal{O}(H_{\mathcal{X}}^{\mathrm{rig}}) \\
    \end{align}
    functorial in $(\Lambda, V, \gamma)$.
\end{Cor}
\begin{proof}
Lemma \ref{Lem:LocallyConvexVSCondensed} and Theorem \ref{thm.rational-fourier-theory} give an isomorphism
\[ \underline{\mathcal{D}^{\gamma\mathrm{-la}}(\Lambda)} \xrightarrow{\sim} \underline{\mathcal{O}(H_{\mathcal{X}}^{\mathrm{rig}})} \]
and then we conclude by Proposition \ref{Prop:FrechetVSClassicalFrechet}. 
\end{proof}

\begin{Rem} \label{Rem:WhyCondense}
It is possible to upgrade Corollary \ref{Cor:LocallyConvexMain} to include Hopf algebra structures (with respect to the completed projective tensor product of locally convex $K$-vector spaces). Indeed, since $V \mapsto \ul{V}$ commutes with products, we see that there are natural commutative algebra structures on the two locally convex $K$-vector spaces in the statement of Corollary \ref{Cor:LocallyConvexMain}. Moreover, the solid Hopf $K$-algebra structures on the corresponding condensed $K$-vector spaces, see Lemma \ref{Lem:LocallyConvexVSCondensed}, induce locally convex Hopf $K$-algebra structures on the two locally convex $K$-vector spaces in the statement of Corollary \ref{Cor:LocallyConvexMain}. Indeed, this follows from \cite[Proposition A.68]{Bosco}. 
\end{Rem}

\subsection{Comparison with Schneider--Teitelbaum} \label{Sub:STComparison} 
Let us explain how Corollary \ref{Cor:LocallyConvexMain} compares with the work of Schneider--Teitelbaum \cite{SchneiderTeitelbaumFourier}. Suppose that we have embeddings $\mbb{Q}_p \subset L \subset K \subset \mathbb{C}_p$, where $K$ is complete and $L/\mbb{Q}_p$ is finite, and take $Y =\operatorname{Spa}(K, \mathcal{O}_K)$. Let $\iota_0 \colon L \hookrightarrow \mathbb{C}_p$ denote this fixed embedding. We will consider the locally analytic character datum $\mathcal{X}=(\Lambda, V, \gamma)$ where $\Lambda=\mathcal{O}_L$ has the trivial Galois action, $V=K$, and, for $\iota_0: L \hookrightarrow \mathbb{C}_p$ the given embedding, $\gamma$ is the map
\begin{align}
    \gamma=\iota_0|_{\mathcal{O}_L} \otimes \mathrm{id}_{\mathbb{C}_p}:\mathcal{O}_L \otimes_{\zp} \mathbb{C}_p \rightarrow  \mathbb{C}_p= K \otimes_K \mathbb{C}_p.
\end{align}
In particular, $H_{\mathcal{X}}^{\mathrm{rig}}$ is a 1-dimensional $p$-divisible rigid analytic group.

\subsubsection{} We recall the notation of \cite[Section 1]{SchneiderTeitelbaumFourier}. Let $G=\mathcal{O}_L$ considered as an $L$-analytic manifold, and $G_0=\mathcal{O}_L$ considered as a $\qp$-analytic manifold. Schneider and Teitelbaum consider a quotient map
\begin{align}
    D(G_0,K) \to D(G,K)
\end{align}
of $K$-Fr\'echet spaces, where $D(-,K)$ denotes the strong dual to the locally convex $K$-vector space of locally analytic $K$-valued functions on $-$. 
\begin{Lem} \label{Lem:DistributionST}
    There is a commutative diagram of topological $K$-modules
\begin{equation} 
    \begin{tikzcd}
             D(G_0, K) \arrow[r] \arrow{d} & D(G, K) \arrow{d} \\
             \mathcal{D}^{\locan}(\Lambda) \arrow[r] & \mathcal{D}^{\gamma-\locan}(\Lambda)
    \end{tikzcd}
\end{equation}
where the vertical maps are isomorphisms.
\end{Lem}
\begin{proof}
The left vertical arrow is an isomorphism by definition. To show that this induces an isomorphism on the right vertical arrows, we need to check that our $\gamma$-locally analytic condition agrees with the ``$L$-linearity'' condition of Schneider--Teitelbaum. Using Proposition \ref{Prop:InvariantsCoinvariants}, this follows from the observation that $W=\ker \gamma$ is generated by elements of the form $\lambda \otimes x - 1 \otimes \iota_0(\lambda) x$ for $\lambda \in \Lambda=\mathcal{O}_K$ and $x \in \mathbb{C}_p$; this matches the ``$L$-linearity'' condition in \cite[Lemma 1.1]{SchneiderTeitelbaumFourier}. 
\end{proof}

\subsubsection{} Let $\widehat{G}_0$ be the smooth rigid analytic group over $K$
whose $\mathbb{C}_p$-points are the continuous characters $\chi:\mathcal{O}_L \to \mathcal{O}_{\mathbb{C}_p}^{\times}$, and write $\widehat{G} \subset \widehat{G}_0$ for the closed subgroup whose $\mathbb{C}_p$ points are the $L$-analytic characters $\chi$, see \cite[Corollary 1.5]{SchneiderTeitelbaumFourier}. 
\begin{Lem} \label{Lem:CharacterVarieties}
    There is a commutative diagram 
    \begin{equation}
    \begin{tikzcd}
         \widehat{G} \arrow[r, hook] \arrow{d}& \widehat{G}_0 \arrow{d} \\
        H_{\mathcal{X}}^{\mathrm{rig}} \arrow[r, hook] & \Hom(\Lambda, \gmhateta),
    \end{tikzcd}
    \end{equation}
    where the vertical arrows are isomorphisms.
\end{Lem}
\begin{proof}
The existence of the right vertical isomorphism is straightforward. That it identifies $\widehat{G}$ and $H_{\mathcal{X}}^{\mathrm{rig}}$ can be checked on Lie algebras, where it follows from \cite[Corollary 1.5]{SchneiderTeitelbaumFourier}. 
\end{proof}

\subsubsection{} Schneider and Teitelbaum prove, see \cite[Theorem 2.2, Theorem 2.3]{SchneiderTeitelbaumFourier}, that there is a commutative diagram of locally convex $K$-vector spaces (they write $\mathcal{F}$ for what we call $\mathcal{F}_0$)
\begin{equation} \label{Eq:STFourier}
    \begin{tikzcd}
        D(G_0, K) \arrow{r} \arrow{d}{\mathcal{F}_0} & D(G,K) \arrow{d}{\mathcal{F}} \\
        \mathcal{O}(\widehat{G_0}) \arrow{r} & \mathcal{O}(\widehat{G}), 
    \end{tikzcd}
\end{equation}
where the vertical maps are isomorphisms and where the left vertical map is the (multidimensional) Amice transform.

\begin{Prop} \label{Prop:Comparison}
    Under the isomorphisms of Lemma \ref{Lem:CharacterVarieties} and Lemma \ref{Lem:DistributionST}, the isomorphism $\mathcal{F}$ agrees with the map $\mathbb{F}_{\mathcal{X}}$ of Corollary \ref{Cor:LocallyConvexMain}.
\end{Prop}
\begin{proof}
By Example \ref{Eg:kappaForTrivialLambda}, this is true for $\mathcal{F}_0$ because our Fourier transform agrees with the Amice transform for $H=\gmhateta$ and thus with the multidimensional Amice transform for $(\gmhateta)^h$. The result follows for $\mathcal{F}$, because of the functoriality of our Fourier transform, the commutativity of \eqref{Eq:STFourier} and the surjectivity of $D(G_0, K) \to D(G, K)$.
\end{proof}


\section{Integral Fourier theory}\label{s.integral-fourier}

\newcommand{\oh}{\mathcal{O}(\mathcal{H})}
Let $R$ be a $p$-adically complete and separated ring. In this section, we are going to prove an integral analog of Theorem \ref{thm.rational-fourier-theory} for $p$-divisible groups over $R$. In nice situations, we will also compare our integral theory with the rational theory on the generic fiber. 

\subsubsection{} We give the statement of our main result in this context. Recall that given a $p$-divisible group $\mathcal{H}$ over $\spf R$, there is a Serre-dual $p$-divisible group $\mathcal{H}^{\vee}$ and a Hodge--Tate map $T_p \mathcal{H}^{\vee} \to \omega_{\mathcal{H}}$, see for example Section \ref{subsub:HodgeTate} below. For $\mathcal{H}$ a $p$-divisible group over $\spf R$, we show that $\mathcal{O}(\mathcal{H})$ and $\mathcal{O}(T_p \mathcal{H}^\vee)$, along with their continuous $R$-linear duals (equipped with the weak topology), are commutative topological Hopf $R$-algebras\footnote{By which we mean a co-commutative co-group object in the category of complete linearly topologized $R$-algebras with the completed tensor product of linearly topologized $R$-modules as in \cite[Tag 0AMU]{stacks-project}.}, and there is a universal character\footnote{See Section \ref{subsub:StructureSheaf} for our conventions about evaluating $\mathcal{O}$ on ind-schemes.} 
\[ \kappa \in \mathcal{O}(T_p \mathcal{H}^\vee) \; \widehat{\otimes}_R \; \mathcal{O}(\mathcal{H}). \]
Building up from Cartier duality for the finite flat group schemes $\mathcal{H}[p^n]_{R/p^k}$, we prove

\begin{Thm}\label{thm.integral-fourier-theory}
    Integration against the universal character $\kappa$ defines functorial and naturally dual isomorphisms of complete linearly topologized Hopf $R$-algebras
    \[ \mathbb{F}^{\mathcal{H}}: \mathcal{O}(\mathcal{H})^{\ast} \xrightarrow{\sim} \mathcal{O}(T_p \mathcal{H}^\vee) \textrm{ and } \mathbb{F}_{\mathcal{H}}: \mathcal{O}(T_p \mathcal{H}^\vee)^{\ast} \xrightarrow{\sim} \mathcal{O}(\mathcal{H}). \]
\end{Thm}
We equip $\mathcal{O}(\mathcal{H})$ with the action of $\Sym^\bullet \Lie \mathcal{H}$ induced by the action of $\Lie \mathcal{H}$ by differentiation along invariant vector fields, and on $\mathcal{O}(\mathcal{H})^{\ast}$ we take the dual action. We equip $\mathcal{O}(T_p \mathcal{H}^\vee)$, with the action of $\mathrm{Sym}^\bullet \Lie \mathcal{H}=\mathcal{O}(\omega_{\mathcal{H}})$ through multiplication by functions pulled back along the Hodge--Tate map, and on $\mathcal{O}(T_p \mathcal{H}^\vee)^{\ast}$ we take the dual action. With these actions, we obtain an analogue of Proposition \ref{Prop:Equivariance}.

\begin{Prop}\label{Prop:IntegralEquivariance}
The Fourier transforms of Theorem \ref{thm.integral-fourier-theory} are equivariant for the actions of $\Sym^\bullet \operatorname{Lie} \mathcal{H}$  described above. 
\end{Prop}

\begin{Rem} \label{remark.integral-artier-duality}
If $\mathcal{H}$ is represented by a formal group, then the natural map
\begin{align}
    \mathrm{Sym}^\bullet \Lie \mathcal{H} \to \mathcal{O}(T_p \mathcal{H}^\vee)
\end{align}
induced by pulling back along the Hodge--Tate map extends to an isomorphism $\operatorname{Dif}(\mathcal{H}) \xrightarrow{\sim} \mathcal{O}(T_p \mathcal{H}^\vee)$, where $\operatorname{Dif}(\mathcal{H})$ is the $p$-adic completion of the ring of invariant differential operators on $\mathcal{H}$. This is due to Cartier, see \cite[Theorem 1.56]{ZinkCartier}.
\end{Rem}

\begin{Eg}\label{example.mahler}
    For $\mathcal{H}=\widehat{\mbb{G}}_m = \varinjlim_n \mu_{p^n}$, we have $\mathcal{H}^\vee=\mbb{Q}_p/\mbb{Z}_p= \varinjlim \frac{1}{p^n}\mbb{Z}/\mbb{Z}$ and $T_p \mathcal{H}^\vee=\ul{\mathbb{Z}_p}=\spf \Cont(\mbb{Z}_p, R)$. The functions on $\mathcal{H} \times T_p \mathcal{H}^\vee$ are naturally identified with
    \[ \Cont(\mbb{Z}_p, R) \widehat{\otimes}_{R} R[[t]] = \Cont(\mbb{Z}_p, R)[[t]] \]
    and the universal character $\kappa$ is the element
    \[ z \mapsto (1+t)^z = \sum_{k \geq 0} \binom{z}{k} t^k \textrm{ where } \binom{z}{k}:=\frac{z(z-1)\ldots(z-k+1)}{k!}.\]
    For $\mu \in \Cont(\mathbb{Z}_p, R)^{\ast} \cong \hom_{\mathbb{Z}_p}(\Cont(\mathbb{Z}_p, \mathbb{Z}_p), R)$, i.e., an $R$-valued measure on $\mathbb{Z}_p$, the Fourier transform $\mathbb{F}_{\mathcal{H}}$ sends $\mu$ to 
    \begin{equation}\label{eq.mahler-character-expansion} \mu(z \mapsto (1+t)^z) = \sum_{k \geq 0} \mu\left(\binom{z}{k}\right) t^k \in R[[t]]. \end{equation}
    That this is an isomorphism is equivalent to the claim that the binomial coefficients $\left(\binom{z}{k}\right)_{k \geq 0}$ are a Hilbert basis for $\Cont(\mathbb{Z}_p, \mathbb{Z}_p)$, as first established in \cite{Mahler}. Under this isomorphism, multiplication by the coordinate function $z$ on $\mathbb{Z}_p$ (i.e., the algebra map $\mathbb{Z}_p \hookrightarrow R$) is matched with precomposition with the invariant derivation $(1+t) \partial_t$, as one readily verifies in the formula by applying the chain rule to compute 
    \[ (1+t)\partial_t \left((1+t)^z\right) = (1+t) (z (1+t)^{z-1})=z(1+t)^z. \]
\end{Eg}


\begin{Eg}
In Example \ref{example.mahler}, $\Cont(\mathbb{Z}_p, R)$ has the $p$-adic topology so the linear dual is equal to the continuous dual. When one writes down the dual Fourier transform $\mathbb{F}_{\mathcal{H}}$ in the same setting, it is important to keep track of the correct topology already mod $p$ when computing the dual. Indeed, $R[[t]]$ is equipped with the $(p,t)$-adic topology, so that the elements of $R[[t]]^{\ast}$ are the $R$-linear functionals $\mu$ satisfying $\mu(t^k) \rightarrow 0$ as $k \rightarrow \infty$; this is necessary to have that $\sum_{k \geq 0} \binom{z}{k} \mu(t^k)$ converges in $\Cont(\mathbb{Z}_p, R)$ so the Fourier transform is well-defined.
\end{Eg}


\begin{Rem}
As in Remark \ref{remark.locally-compact-analog}, it is natural to look for a more general category of commutative group functors on nilpotent $R$-algebras that is preserved under Cartier duality and contains both $p$-divisible groups and their duals, and to extend Theorem \ref{thm.integral-fourier-theory} to this setting. Any reasonable such category should also be closed under extensions; for example, just as the category of locally compact abelian groups contains the extension $\mathbb{R}$ of the compact group $\mathbb{R}/\mathbb{Z}=S^1$ by the discrete group $\mbb{Z}$, this category should also contain the universal cover $\widetilde{\mathcal{H}}=\varprojlim_{[p]} \mathcal{H}$ of any $p$-divisible group $\mathcal{H}$, which is an extension of $\mathcal{H}$ by $T_p \mathcal{H}$. In the integral case, one can deduce Fourier isomorphisms for universal covers from the Fourier isomorphisms for $p$-divisible groups; this will be explained in \cite{GHHBC}. From this more general perspective, the compatibility for the action of $\mathrm{Sym}^\bullet \Lie \mathcal{H}$ is closely related to the functoriality of Cartier duality for the inclusion into $\mathcal{H}$ of the divided powers neighborhood of the identity (which is naturally identified with the divided powers neighborhood of the identity in $\Lie \mathcal{H}$). 
\end{Rem}

Theorem \ref{thm.integral-fourier-theory} and Proposition \ref{Prop:IntegralEquivariance} are proved in \S \ref{ss.integral-fourier-proof}. In \S \ref{ss.integral-rational-comparison} we establish, for $(R,R^+)$ a fiercely v-complete Huber pair, a compatibility between the integral Fourier theory over $R^+$ and the rigid analytic Fourier theory on the generic fiber (Theorem \ref{thm.integral-rational-compatibility}). 

\begin{Eg}
Suppose $R=\mathcal{O}_K$, for $K/\mathbb{Q}_p$ a non-archimedean extension. By a result of Amice \cite{AmiceInterpolation}, after inverting $p$, the formula \eqref{eq.mahler-character-expansion} for the integral Fourier transform $\mathbb{F}^{\mathcal{H}}$ of Example \ref{example.mahler} restricts to a bijection between the continuous dual of the space of locally analytic $K$-valued functions on $\mathbb{Z}_p$ and the subring of $K[[t]]$ consisting of power series converging for $|t|<1$, i.e., the space of global functions on the rigid analytic generic fiber $\widehat{\mathbb{G}}_{m,\eta}$. This compatibility between the integral and rigid analytic Fourier transforms is a special case of the general compatibility in Theorem \ref{thm.integral-rational-compatibility}. The general case is more subtle because, for a general $p$-divisible group, we do not know whether the integral functions on the Tate module and the Hodge--Tate locally analytic functions on its generic fiber live naturally inside a common space (see Remark \ref{remark.non-injectivity}). 
\end{Eg}




\subsection{Proofs for integral Fourier theory}\label{ss.integral-fourier-proof}


\subsubsection{} 
We first explain how Cartier duality can be interpreted as Fourier theory for finite flat group schemes. Theorem \ref{thm.integral-fourier-theory} will be proved by bootstrapping from this case. 

Let $R$ be any commutative ring and let $\mathcal{H}$ be a finite locally free commutative group scheme over $\spec R$. For $\Hom$ the sheaf hom of groups on the fpqc site of $R$, let
\begin{align}
    \mathcal{H}^D=\Hom(\mathcal{H}, \gm)
\end{align}
be the Cartier dual of $\mathcal{H}$, which is itself representable by a finite locally free commutative group scheme, see, e.g, \cite[\S1.2]{Tate}. There is a canonical pairing
\begin{align}
    \kappa:\mathcal{H}\times \mathcal{H}^{D} \to \gm
\end{align}
and its composition with $\gm \to \mathbb{A}^1$ gives us an element
\begin{align}
    \kappa \in \mathcal{O}(\mathcal{H}\times \mathcal{H}^D) \simeq \oh \otimes_{R} \mathcal{O}(\mathcal{H}^{D}).
\end{align}
Contracting with this element defines $R$-linear maps (where the superscript $\ast$-denotes $R$-linear dual)
\begin{align}
    \mathbb{F}^{\mathcal{H}}:\oh^{\ast} &\to \mathcal{O}(\mathcal{H}^{D}) \\
    \mathbb{F}_{\mathcal{H}}:\mathcal{O}(\mathcal{H}^{D})^{\ast} &\to \oh.
\end{align}

We equip $\mathcal{O}(\mathcal{H})^{\ast}$ and $\mathcal{O}(\mathcal{H}^D)^{\ast}$ with the dual Hopf $R$-algebra structures. 

\begin{Lem} \label{Lem:CartierDualityFiniteFlat}
    The maps $ \mathbb{F}_{\mathcal{H}}$ and $\mathbb{F}^{\mathcal{H}}$ are dual isomorphisms of Hopf $R$-algebras.
\end{Lem}
\begin{proof}
    See \cite[II.1.2.10]{DemazureGabriel}.
\end{proof}

\subsubsection{} \label{subsub:StructureSheaf} Let $X=\varinjlim_n X_n$ be an ind-scheme written as a (countable) direct limit of qcqs schemes with transition maps being closed immersions (for example an affine formal scheme). We set $\mathcal{O}(X)=\varprojlim_n \mathcal{O}(X_n)$ with its inverse limit topology; this is a linearly topologized ring in the sense of \cite[Tag 07E8]{stacks-project}. Note that the topological ring $\mathcal{O}(X)$ does not depend on the choice of presentation: If $X=\varinjlim_m Y_m$ is another presentation, then the natural map $Y_m \to X$ factors through $X_n$ for some $n \gg 0$ since $Y_m$ is qcqs.  \smallskip

\textbf{Warning:} In the rest of this section we will consider all objects as ind-schemes, including $p$-divisible groups like $\qp/\zp$ which happen to be (non quasi-compact) schemes. In this example our definition gives $\mathcal{O}(\qp/\zp)= \textstyle \prod_{\qp/\zp} R$ with the product topology. 

\begin{Lem} \label{Lem:CompletedKunneth}
Let $R$ be a commutative ring and let $X= \varinjlim_n X_n$ and $Y=\varinjlim_m Y_m$ be ind-$R$-schemes. Then there is a natural isomorphism
    \begin{align}
        \mathcal{O}(X) \widehat{\otimes}_{R} \mathcal{O}(Y) \to \mathcal{O}(X \times_{\spec R} Y),
    \end{align}
    where the completed tensor product is defined as in \cite[Tag 0AMU]{stacks-project}.
\end{Lem}
\begin{proof}
    It follows from the definition that
    \begin{align}
         \mathcal{O}(X \times_{\spec R} Y) = \varprojlim_{n,m} \mathcal{O}(X_n \times_{\spec R} Y_m) = \varprojlim_{n,m} \mathcal{O}(X_n) \otimes_{R} \mathcal{O}(Y_m),
    \end{align}
    which equals $\mathcal{O}({X}) \widehat{\otimes}_{R} \mathcal{O}(Y)$ per definition. 
\end{proof}

\subsubsection{} \label{subsub:HodgeTate} Let $R$ be a commutative ring and let $\mathcal{H}$ be a $p$-divisible group over $\spec R$ (in the sense of \cite{Tate}). Let $\mathcal{H}^{\vee}$ be the Serre-dual of $\mathcal{H}$, which is defined as the $p$-divisible group with $\mathcal{H}^{\vee}[p^n]=\mathcal{H}[p^n]^{D}$, where the inclusions $\mathcal{H}[p^n]^{D} \to \mathcal{H}[p^{n+1}]^{D}$ are induced by the multiplication by $[p]$ map $\mathcal{H}[p^{n+1}] \to \mathcal{H}[p^n]$. Since
\begin{align}
    \mathcal{H}=\varinjlim_n \mathcal{H}[p^n],
\end{align}
it follows that
\begin{align}
    \Hom(\mathcal{H}, \gm) = \varprojlim_n \mathcal{H}^{\vee}[p^n]=T_p \mathcal{H}^{\vee}.
\end{align}
The map $T_p \mathcal{H}^{\vee}=\Hom(\mathcal{H}, \gm) \to \omega_{H}$ sending $f \mapsto f^{\ast} \tfrac{\mathrm{d}t}{1+t}$ is called the \emph{Hodge--Tate map}. 

\subsubsection{} Recall that $\oh=\varprojlim_n \mathcal{O}(\mathcal{H}[p^n])$ equipped with the inverse limit topology.  By Lemma \ref{Lem:CompletedKunneth}, the commutative group structure on $\mathcal{H}$ over $R$ induces on $\oh$ the structure of a topological Hopf algebra over $R$. 

\subsubsection{} Write $\oh^{\ast}$ for the continuous $R$-linear dual of $\oh$, so that $\oh^{\ast}=\varinjlim_n \mathcal{O}(\mathcal{H}[p^n])^{\ast}$, and equip $\oh^\ast$ with the weak (equivalently, discrete) topology. Here we are using the fact that a continuous $R$-linear morphism from an inverse limit to a discrete $R$-module factors through one of the terms in the inverse limit. Then the natural map
\begin{align}
    \oh^{\ast} \otimes_{R} \oh^{\ast} \to ( \oh \widehat{\otimes}_{R} \oh)^{\ast}
\end{align}
is an isomorphism, showing that $\oh^{\ast}$ is naturally an Hopf $R$-algebra. We also have a canonical identification
\[ (\oh^{\ast})^\ast = \varprojlim_n (\mathcal{O}(\mathcal{H}[p^n])^{\ast})^\ast = \varprojlim_n \mathcal{O}(\mathcal{H}[p^n]) = \oh. \]

Using the group structure on $T_p \mathcal{H}$, we find $\mathcal{O}(T_p \mathcal{H})=\varinjlim_n \mathcal{O}(\mathcal{H}[p^n])$ is naturally an Hopf $R$-algebra. We equip $\mathcal{O}(T_p \mathcal{H})^{\ast} = \varprojlim_n \mathcal{O}(\mathcal{H}[p^n])^{\ast}$ with the inverse limit topology (equivalently, the weak topology). The natural map 
\[ \mathcal{O}(T_p \mathcal{H})^{\ast} \widehat{\otimes}_R \mathcal{O}(T_p \mathcal{H})^{\ast} \rightarrow \left(\mathcal{O}(T_p \mathcal{H}) \otimes_R \mathcal{O}(T_p \mathcal{H}) \right)^{\ast} \]
is an isomorphism, showing that $\mathcal{O}(T_p \mathcal{H})^{\ast}$ is a topological Hopf algebra over $R$. We also have a canonical identification
\begin{multline*}(\mathcal{O}(T_p \mathcal{H})^{\ast})^\ast =  (( \varinjlim_n \mathcal{O}(\mathcal{H}[p^n]))^{\ast})^\ast = (\varprojlim_n \mathcal{O}(\mathcal{H}[p^n])^{\ast})^{\ast}\\=\varinjlim_n (\mathcal{O}(\mathcal{H}[p^n])^{\ast})^{\ast} = \varinjlim_n \mathcal{O}(\mathcal{H}[p^n])=\mathcal{O}(T_p \mathcal{H}). \end{multline*}

\subsubsection{} There is a canonical pairing
\begin{align}
    \kappa: \mathcal{H} \times T_p \mathcal{H}^{\vee} \to \gm
\end{align}
giving us an element (see Lemma \ref{Lem:CompletedKunneth})
\begin{align}
    \kappa \in \oh \widehat{\otimes}_{R} \mathcal{O}(T_p \mathcal{H}^{\vee}). 
\end{align}
This element induces continuous $R$-linear maps
\begin{align}
    \mathbb{F}^{\mathcal{H}}&:\oh^{\ast}
    \to \mathcal{O}(T_p \mathcal{H}^{\vee}) \\
    \mathbb{F}_{\mathcal{H}}&:\mathcal{O}(T_p \mathcal{H}^{\vee})^{\ast} \to \oh.
\end{align}
\begin{Prop} \label{Prop:IntegralFourierDiscrete}
The morphisms $ \mathbb{F}_{\mathcal{H}}$ and $\mathbb{F}^{\mathcal{H}}$ are dual isomorphisms of topological Hopf $R$-algebras.
\end{Prop}
\begin{proof}
The map $\mathbb{F}_{\mathcal{H}}$ is a direct limit over $n$ of the maps $\mathbb{F}_{\mathcal{H}[p^n]}$ from Lemma \ref{Lem:CartierDualityFiniteFlat}, and similarly $\mathbb{F}^{\mathcal{H}}$ is an inverse limit over $n$ of the maps $\mathbb{F}^{\mathcal{H}[p^n]}$ from Lemma \ref{Lem:CartierDualityFiniteFlat}. The result thus follows directly from Lemma \ref{Lem:CartierDualityFiniteFlat}.
\end{proof}

\begin{Rem}
    Note that the topologies on $\oh^{\ast}$ and $ \mathcal{O}(T_p \mathcal{H}^{\vee})$ are discrete, so that $\mathbb{F}_{\mathcal{H}}$ is an isomorphism between discrete Hopf $R$-algebras. 
\end{Rem}

\subsubsection{} Let $R$ be a $p$-adically complete and separated ring, and $\mathcal{H}$ a $p$-divisible group over $\spf R$. Then $\mathcal{H}$ is an ind-scheme with presentation $\mathcal{H}=\varinjlim_{n,k} \mathcal{H}[p^n]_{R/p^k}$ and thus 
 \[ \mathcal{O}(\mathcal{H})=\varprojlim_k \varprojlim_n \mathcal{O} (\mathcal{H}[p^n]_{R/p^k}) \]
with the inverse limit topology. Equivalently, this is 
\[ \mathcal{O}(\mathcal{H})=\varprojlim_k \mathcal{O}(\mathcal{H}_{R/p^k}) \]
 with the inverse limit of the topologies considered above, or, swapping the order, the inverse limit of the $p$-adic topologies on $\mathcal{O} (\mathcal{H}[p^n])$ in
 \[ \mathcal{O}(\mathcal{H}) = \varprojlim_n \mathcal{O} (\mathcal{H}[p^n]). \]
It similarly follows that
\[ \mathcal{O}(T_p \mathcal{H}^{\vee})=\varprojlim_k \mathcal{O}(T_p \mathcal{H}^{\vee}_{R/p^k}) \]
acquires the inverse limit topology (i.e., the $p$-adic topology, since the terms in the limit have the discrete topology). Once again we find that $\oh$, $\oh^{\ast}$, $\mathcal{O}(T_p \mathcal{H}^{\vee})$ and, $\mathcal{O}(T_p \mathcal{H}^{\vee})^{\ast}$ are topological Hopf $R$-algebras, where a superscript $\ast$ denotes the continuous $R$-linear dual equipped with the weak topology.
There is a pairing
\begin{align}
    \kappa: \mathcal{H} \times T_p \mathcal{H}^{\vee} \to \mathbb{G}_{m, \spf R}
\end{align}
giving us an element (see Lemma \ref{Lem:CompletedKunneth})
\begin{align}
    \kappa \in \mathcal{O}( \mathcal{H} \times T_p \mathcal{H}^{\vee}) =\oh \widehat{\otimes}_{R} \mathcal{O}(T_p \mathcal{H}^{\vee}). 
\end{align}
This element induces continuous $R$-linear maps
\begin{align}
    \mathbb{F}^{\mathcal{H}}&:\oh^{\ast}
    \to \mathcal{O}(T_p \mathcal{H}^{\vee}) \\
    \mathbb{F}_{\mathcal{H}}&:\mathcal{O}(T_p \mathcal{H}^{\vee})^{\ast} \to \oh.
\end{align}
The following proposition is Theorem \ref{thm.integral-fourier-theory}. 
\begin{Prop} \label{Prop:IntegralFourier}
The morphisms $ \mathbb{F}_{\mathcal{H}}$ and $\mathbb{F}^{\mathcal{H}}$ are isomorphisms of complete linearly topologized Hopf $R$-algebras. 
\end{Prop}
\begin{proof}
We apply Proposition \ref{Prop:IntegralFourierDiscrete} mod $p^k$ for all $k \geq 1$. 
\end{proof}

Finally, we prove the equivariance for the actions of $\Sym^\bullet \Lie \mathcal{H}$. 

\begin{proof}[Proof of Proposition \ref{Prop:IntegralEquivariance}]
The dual Hodge-Tate map can be constructed relatively by viewing $\kappa$ as a character of $\mathcal{H}$ based changed to $T_p \mathcal{H}^\vee$ (noting that $T_p \mathcal{H}^\vee$ is itself an affine $p$-adic formal scheme),
\[ \mathcal{H}_{T_p \mathcal{H}^\vee} \xrightarrow{\kappa} \widehat{\mathbb{G}}_{m, T_p \mathcal{H}^\vee}, \]
and then pulling back $\frac{dt}{1+t}$ to an element of $\omega_{(\mathcal{H}^\vee \times_{\Spf R} T_p \mathcal{H}^\vee )/ T_p \mathcal{H}^\vee}$.

In particular, for $\partial \in \Lie \mathcal{H}$ an invariant derivation, if we view $\kappa$ as a function by the natural inclusion $\gmhat \subseteq \mathbb{A}^1$ we have (cf. the proof of Lemma \ref{Lem.DerivationActionLocAn})
\[ \partial\kappa= \langle \partial, \kappa^* \frac{dt}{1+t}\rangle \kappa = \HT^*(\partial)\kappa.\] 
The result then follows as in the proof of Proposition \ref{Prop:FTSymVstarEquiv}.
\end{proof}

\subsection{Comparison with Fourier theory on the generic fiber}\label{ss.integral-rational-comparison}
\subsubsection{} \label{subsub:IntegralNotation} Let $(R,R^+)/(\mathbb{Q}_p,\mathbb{Z}_p)$ be fiercely v-complete and let $\mathcal{H}$ be a $p$-divisible group over $\spf R^+$ with rigid generic fiber $\mathcal{H}_\eta$ over $Y=\Spa(R,R^+)$.
We write $\HT: T_p \mathcal{H}_\eta^\vee \otimes_{\ul{\mathbb{Z}_p} } \mathcal{O}_{Y_v} \rightarrow \omega_{\mathcal{H}} \otimes_{R^+} \mathcal{O}_{Y_v}$ for the rational Hodge--Tate map, and we view $T_p \mathcal{H}^\vee_{\eta}$ as a v-sheaf. To simplify our notation, below we will write
    $\mathcal{O}^{\HT-\locan}(T_p\mathcal{H}^\vee_\eta) :=\mathcal{O}^{\HT-\locan}_{T_p \mathcal{H}^\vee_\eta / Y}(Y)$, where $Y=\spd(R,R^+)$.

As in \eqref{eq.restriction-map-locally-analytic}, we have a natural $R$-linear restriction map
\[  r^\locan: \mathcal{O}^{\HT-\locan}(T_p \mathcal{H}_\eta^\vee) \hookrightarrow \mathcal{O}(T_p \mathcal{H}_\eta^\vee)\]
that is injective by Lemma \ref{lemma.restriction-map-injective}. 
We also have natural $R$-linear restriction maps
\[ r_{\mathcal{H}}: \mathcal{O}(\mathcal{H})[\tfrac{1}{p}] \rightarrow \mathcal{O}(\mathcal{H}_{\eta}) \textrm{ and }  r^\mathrm{int}: \mathcal{O}(T_p \mathcal{H}^\vee)[\tfrac{1}{p}] \rightarrow \mathcal{O}(T_p \mathcal{H}_\eta^\vee). \]

\begin{Rem}\label{remark.injectivity-r-H}
If $\mathcal{H}$ is an extension of an \'{e}tale $p$-divisible group by a formal group, then $\mathcal{H}$ is representable by a formal scheme by \cite[Lemma 3.1.1]{ScholzeWeinstein} and $r_{\mathcal{H}}$ is injective (as can be verified using the local presentation of $\widehat{\mathcal{H}}$ in \cite[Lemma 3.1.2]{ScholzeWeinstein}). We expect this injectivity to hold in general.  
\end{Rem}

\begin{Eg}
    If $R=\mathcal{O}_K$ for $K/\mathbb{Q}_p$ a non-archimedean extension, then 
    \[ \mathcal{O}(T_p\mathcal{H}^\vee_\eta)= \Cont(T_p \mathcal{H}^\vee(\overline{K}), \overline{K}^\wedge)^{\Gal(\overline{K}/K)}, \]
    where $\overline{K}^{\wedge}$ denotes a completed algebraic closure of $K$.
\end{Eg}

\begin{Rem}\label{remark.non-injectivity}
    The map $r^{\mathrm{int}}$ is an isomorphism if $\mathcal{H}=\mu_{p^\infty}$ so that $T_p \mathcal{H}^\vee=\mathbb{Z}_p$. However, in all other cases we expect the behavior of the map $r^\mathrm{int}$ to be quite subtle. For example, if $\mathcal{H}=\mathbb{Q}_p/\mathbb{Z}_p$ so that $T_p \mathcal{H}^\vee=\mathbb{Z}_p(1)$ and $R=\mathcal{O}_{E^\wedge}$ for $E$ an algebraic extension of $\mathbb{Q}_p$, then the results of \cite{FresneldeMathan.AlgebresL1padiques} imply that:
    \begin{itemize}
        \item If $E$ is deeply ramified (equivalently, $E^\wedge$ is perfectoid), then $r^\mathrm{int}$ is surjective but not injective (its kernel even contains a dense set of nilpotents!).
        \item If $E$ is not deeply ramified (equivalently, $E^\wedge$ is not perfectoid) then $r^{\mathrm{int}}$ is injective with dense image but not surjective. 
    \end{itemize}
We note that the surjectivity in the deeply ramified case is a special case of \cite[Theorem 7.4]{BhattScholzePrisms}. In fact, it is the specific case invalidating \cite[Remark II.2.4]{ScholzeTorsion}. 

Katz \cite[top of p.60]{Katz.FormalGroupsAndPAdicInterpolation} (see also \cite{BergerGaloisMeasures} and \cite{ArdakovBerger}) has also noted that $(r^{\mathrm{int}})^{\ast}$ is injective whenever $R=\mathcal{O}_{E^\wedge}$ for $E$ a discretely valued algebraic extension of $\mathbb{Q}_p$ and $\mathcal{H}$ a one-dimensional $p$-divisible formal group over $R$. When furthermore $E/\mathbb{Q}_p$ is unramified and $\mathcal{H}$ is of height $1$ or $2$, he has given an explicit description of the image of $\mathbb{F}^{\mathcal{H}}[\tfrac{1}{p}] \circ (r^\mathrm{int})^{\ast}$ in \cite[Theorem on p.60]{Katz.FormalGroupsAndPAdicInterpolation}. 

It would be interesting to have a more systematic general understanding of these results!

\end{Rem}
\subsubsection{} We continue with the notation from Section \ref{subsub:IntegralNotation}. 
Below we will also write 
\[ \mathcal{D}(\mathcal{H}_\eta):=\mathcal{D}_{\mathcal{H}_\eta/Y}(Y) \textrm{ and } \mathcal{D}^{\HT-\locan}(T_p \mathcal{H}^\vee_\eta):=\mathcal{D}_{T_p \mathcal{H}^\vee_\eta/Y}^{\HT-\locan}(Y).\]
We note that, when $\Lie \mathcal{H}$ is free, the discussion of \S\ref{sss.solid-hopf-and-duality-discussion-fiercely} implies that
\[ \ul{\mathcal{D}(\mathcal{H}_\eta)}=\ul{\mathcal{O}(\mathcal{H}_\eta)}^* \textrm{ and } \ul{\mathcal{D}^{\HT-\locan}(T_p \mathcal{H}^\vee)}=\ul{\mathcal{O}^{\HT-\locan}(T_p \mathcal{H}^\vee_\eta)}^*,\]
where the superscript $\ast$ denotes the condensed $\ul{R}$-linear dual. Following Remark \ref{remark.etale-expectations}, we expect this equality to hold always. To state our compatibility without establishing this expectation or imposing the condition that $\Lie \mathcal{H}$ be free, we observe that $r_{\mathcal{H}}^*$ and $r_\mathrm{int}^*$ can be glued, by working Zariski locally on $\Spf R^+$ where $\Lie \mathcal{H}$ is free, in order to obtain maps
\[ r_{\mathcal{H}}^*: \mathcal{D}(\mathcal{H}_\eta) \to \mathcal{O}(\mathcal{H})^*[\tfrac{1}{p}] \textrm{ and } r_\mathrm{int}^*: \mathcal{D}^{\HT-\locan}(T_p \mathcal{H}^\vee_\eta) \to \mathcal{O}(T_p \mathcal{H}^\vee)^*[\tfrac{1}{p}] \]
where here the superscript $*$ is the continuous $R^+$-linear dual. 

By Proposition \ref{Prop.TateModule}, we have $\mathcal{H}_\eta = H_{\mathcal{L}}$ for $$\mathcal{L}={(T_p \mathcal{H}_\eta, \Lie \mathcal{H} \otimes_{R^+} \mathcal{O}_{Y_v},  \Lie \mathcal{H} \otimes_{R^+} \mathcal{O}_{Y_v} \hookrightarrow T_p \mathcal{H}_\eta(-1) \otimes_{\ul{\mathbb{Z}_p}} \mathcal{O}_{Y_v})}.$$ 
In particular, taking $\mathcal{L}^{\vee}$ to be the locally analytic character datum associated to $\mathcal{L}$ in \S \ref{subsub:CharacterDatum} the Fourier transforms of $\mathbb{F}^{\mathcal{L}^\vee}$ and $\mathbb{F}_{\mathcal{L}^\vee}$ of \S\ref{Sub:FourierDef} induce the following maps on global sections:
\begin{align*} \mathbb{F}^{\mathcal{H}_\eta} :& \mathcal{D}(\mathcal{H}_\eta)  \rightarrow \mathcal{O}^{\HT-\locan}(T_p \mathcal{H}^\vee_\eta) \\
\mathbb{F}_{\mathcal{H}_\eta} :&  \mathcal{D}^{\HT-\locan}(T_p \mathcal{H}^\vee_\eta)   \rightarrow \mathcal{O}(\mathcal{H}_\eta). 
\end{align*}



\begin{Thm} \label{thm.integral-rational-compatibility}
Suppose $(R,R^+)/(\mathbb{Q}_p,\mathbb{Z}_p)$ is fiercely v-complete. If $\mathcal{H}$ is a $p$-divisible group over $\spf R^+$ with rigid analytic generic fiber $\mathcal{H}_\eta$ over $\Spa(R,R^+)$, then the following diagrams commute

\[\begin{tikzcd}
	{\mathcal{O}(\mathcal{H})^{\ast}[\tfrac{1}{p}]} & {\mathcal{O}(T_p\mathcal{H}^\vee)[\tfrac{1}{p}]} & {\mathcal{O}(\mathcal{H})[\tfrac{1}{p}]} & {\mathcal{O}(T_p \mathcal{H}^\vee)^{\ast}[\tfrac{1}{p}]} \\
	& {\mathcal{O}(T_p \mathcal{H}^\vee_\eta)} && {\mathcal{O}(T_p \mathcal{H}^\vee_\eta)^{\ast}} \\
	{\mathcal{D}(\mathcal{H}_\eta)} & {\mathcal{O}^{\HT-\locan}(T_p \mathcal{H}^\vee_\eta)} & {\mathcal{O}(\mathcal{H}_\eta)} & {\mathcal{D}^{\HT-\locan}(T_p\mathcal{H}^\vee_\eta)}.
	\arrow["{\mathbb{F}^{\mathcal{H}}[\tfrac{1}{p}]}", from=1-1, to=1-2]
	\arrow["{r^{\mathrm{int}}}", from=1-2, to=2-2]
	\arrow["{r_{\mathcal{H}}}", from=1-3, to=3-3]
	\arrow["{\mathbb{F}_{\mathcal{H}}[\tfrac{1}{p}]}"', from=1-4, to=1-3]
	\arrow["{(r^{\mathrm{int}})^{\ast}}"', from=2-4, to=1-4]
	\arrow["{(r^\locan)^{\ast}}", from=2-4, to=3-4]
	\arrow["{r_{\mathcal{H}}^{\ast}}", from=3-1, to=1-1]
	\arrow["{\mathbb{F}^{\mathcal{H}_\eta}}", from=3-1, to=3-2]
	\arrow["{r^{\locan}}"', from=3-2, to=2-2]
	\arrow["{\mathbb{F}_{\mathcal{H}_\eta}}"', from=3-4, to=3-3]
\end{tikzcd}\]
\end{Thm}
\begin{proof}
The diagram is functorial for change of base. Since the generic fiber terms are v-sheaves, it suffices to observe that, when $(R,R^+)$ is perfectoid and $T_p \mathcal{H}^\vee_\eta\cong \ul{\mathbb{Z}_p}^{\oplus h}$ is trivial,  
\[ \kappa \in \mathcal{O}(T_p \mathcal{H}^\vee \times \mathcal{H}) \]
maps to the universal character of Lemma \ref{Lem:UniversalKappaAsSection} inside 
\[ \mathcal{O}(T_p \mathcal{H}^\vee_\eta \times \mathcal{H}_\eta)=\Cont(\mathbb{Z}_p^h, \mathcal{O}(\mathcal{H}_\eta)). \]
But this is clear from the construction.
\end{proof}

As a consequence we obtain a partial section of $r^\mathrm{int}$ (which is very interesting as Remark \ref{remark.non-injectivity} shows that $r^\mathrm{int}$ need not be surjective nor injective!):
\begin{Cor}\label{cor.la-section}
    There is a canonical section $\mathcal{O}^{\HT-\locan}(T_p \mathcal{H}_\eta^\vee) \rightarrow \mathcal{O}(T_p \mathcal{H}^\vee)[\tfrac{1}{p}]$ of $r^\mathrm{int}$. 
\end{Cor}
\begin{proof}
    Since $\mathbb{F}^{\mathcal{H}_\eta}$ is an isomorphism by Theorem \ref{Thm:Main}, we obtain the section as $\mathbb{F}^{\mathcal{H}}[\tfrac{1}{p}] \circ r_{\mathcal{H}}^{\ast} \circ (\mathbb{F}^{\mathcal{H}_\eta})^{-1}$.
\end{proof}

\begin{Eg}
    When $\mathcal{H}=\mathbb{Q}_p/\mathbb{Z}_p$, so $T_p\mathcal{H}^\vee = \mathbb{Z}_p(1)$, the Hodge--Tate map is identically zero (its target is $\omega_{\mathbb{Q}_p/\mathbb{Z}_p}=0$). In particular, when $R=\mathcal{O}_{\mathbb{C}_p}$, the space 
    $\mathcal{O}^{\HT-\locan}(T_p \mathcal{H}_\eta^\vee)$ is given by the locally constant $\mathbb{C}_p$-valued functions on $\mathbb{Z}_p(1)$. Each locally constant function has a canonical expression as a finite linear combination of characters, and this provides the canonical section to $\mathcal{O}(\mathbb{Z}_p(1))[\tfrac{1}{p}]$. In other situations, there are many more locally analytic functions, expressible locally as power series using the Hodge--Tate map, and the existence of the canonical section expresses a non-trivial convergence condition on these series. When $\mathcal{H}$ is, e.g., a Lubin--Tate formal group, the canonical section should be closely related to the description of locally analytic functions in the associated Lubin--Tate extension given in \cite{BergerColmez.Sen}.
\end{Eg}


\section{The global Eisenstein measure} \label{Sec:Eisenstein}

\subsection{Background} \label{Sub:IntroEisenstein}

For $\Lambda \subseteq \mathbb{C}$ a lattice and $k\geq 3$ an integer, consider the series 
\[ A_k(\Lambda)=\sum_{\lambda \in \Lambda \backslash \{0\}}\frac{1}{\lambda^k}. \]
Certain values of $A_k$ can be related to special values of $L$-functions. For example, if $\Lambda=\mathbb{Z}[i]$, these are the Bernoulli--Hurwitz numbers -- in terms of $L$-functions, if we write $\chi$ for the Grossencharacter sending an ideal $I$ of $\mathbb{Z}[i]$ to $z$, for $z$ the unique generator of $I$ such that $z \equiv 1 \mod (1+i)^3$, then 
\[ A_k(\mathbb{Z}[i])=\begin{cases}
    4 L(\chi^{-k}, 0) & \textrm{ if $k \equiv 0 \mod 4$} \\
    0 & \textrm{otherwise}. 
\end{cases}\]
On the other hand, the function $A_k$ defines a modular form, the level one Eisenstein series of weight $k$ (which is identically zero if $k$ is odd) --- viewed as a function on the upper half-plane, it is given by $\tau \mapsto A_k(\mathbb{Z} + \mathbb{Z}\tau)$.

\subsubsection{} In \cites{Katz.p-adic-L-via-moduli, Katz.TheEisensteinMeasureAndpAdicInterpolation}, Katz explained how to construct, for primes $p \equiv 1 \mod 4$, a $p$-adic $L$-function interpolating the values $L(\chi^{-k}, 0)$ into a measure on $\mathbb{Z}_p$ by first interpolating the renormalized Eisenstein series 
\[ G_k := \frac{(-1)^k (k-1)!}{2} A_k \]
into a measure on $\mathbb{Z}_p$ valued in $p$-adic modular forms. One can then specialize at the lemniscate elliptic curve $E_0$ defined by the equation $y^2=4x^3-4x$, whose complex points are isomorphic to $\mathbb{C}/\mathbb{Z}[i]$, in order to obtain a measure whose values on the monomials $z \mapsto z^k$, $k\geq 3$, are renormalized Bernoulli--Hurwitz numbers. The $p$-adic $L$-function is obtained by restricting this measure to $\mathbb{Z}_p^\times$, which modifies an Euler factor at $p$ and allows to evaluate at any character $\kappa$ of $\mathbb{Z}_p^\times$ -- in particular, since these characters satisfy many $p$-adic congruences, so do the renormalized Bernoulli--Hurwitz numbers. 

The basis of this approach is an observation of Deligne that, in order to analyze congruences between the Eisenstein series, one can use the geometry of the modular curve to reduce to interpolating the \emph{positive} Fourier coefficients of the renormalized Eisenstein series. These Fourier coefficients are expressed in terms of divisor power sums, whose congruences can be analyzed trivially using Fermat's little theorem. The Kubota--Leopoldt $p$-adic zeta function is also obtained in this way by evaluating at a cusp instead of a CM point. 

\subsubsection{} This interpolation of Eisenstein series explained above occurs over the ordinary locus, thus yields a $p$-adic $L$-function interpolating Bernoulli--Hurwitz numbers only for primes $p \equiv 1 \mod 4$ (i.e., splitting in $\mathbb{Z}[i]$ so that $E_0$ has ordinary reduction).
In \cites{Katz.FormalGroupsAndPAdicInterpolation, Katz.DivisibilitiesCongruencesAndCartierDuality}, Katz explained a different construction of the $p$-adic $L$-function interpolating the Bernoulli--Hurwitz numbers that is valid also at the inert primes $p\equiv 3 \mod 4$ where $E_0$ has supersingular reduction. This construction exploits Cartier duality and the appearance of the Eisenstein series as coefficients of the Weierstrass $\wp$-function. In our language, the key observation is that, after a small modification to remove the pole at the origin, $\wp$ restricts to a regular function on the $p$-divisible group $E_0[p^\infty]$ and thus by Cartier duality yields a measure on $T_p E_0^\vee$. Katz shows moreover that, in this specific case, $(r^\mathrm{int})^*$ is injective and the measure is in its image (cf. Remark \ref{remark.non-injectivity}), i.e., the measure comes from an element of 
\[ \mathcal{O}(T_p (E_{0,\eta}^\vee))^* = \left(\Cont(T_p E_{0}^{\vee}(\mathbb{C}_p), \mathbb{C}_p)^{\Gal(\overline{\mathbb{Q}}_p/\mathbb{Q}_p)} \right)^*. \]
In the language of \cite{Katz.FormalGroupsAndPAdicInterpolation}, one thus obtains a Galois-equivariant measure; its restriction to $T_p E_{0}^{\vee}(\mathbb{C}_p) \setminus p T_p E_0^{\vee}(\mathbb{C}_p) \cong \mathbb{Z}_{p^2}^\times$ (with the Lubin--Tate Galois action) is then a natural $p$-adic $L$-function interpolating the Bernoulli--Hurwitz numbers.  

In fact, rather than viewing $\mathcal{O}(E_0[p^\infty])$ as  $\mathcal{O}(T_p E_0^\vee)^*$, in \cite{Katz.FormalGroupsAndPAdicInterpolation} Katz exploits that $E_0[p^\infty]$ is connected to view the dual of $\mathcal{O}(E_0[p^\infty])$ as the ring of invariant differential operators, see Remark \ref{remark.integral-artier-duality}; he then argues from this perspective to obtain an element of $\mathcal{O}(T_p (E_{0,\eta}^\vee))^*$. The interpretation via invariant differential operators applies only to formal groups, so cannot be used over the entire modular curve. However, by instead using our Fourier transform to identify $\mathcal{O}(E_0[p^\infty])=\mathcal{O}(T_p E_0^\vee)^*$, we can extend this approach to obtain a global Eisenstein measure. This construction and its consequences are explained in \S\ref{ss.global-eisenstein-measure}. 

\subsubsection{} As observed already by Schneider and Teitelbaum \cite{SchneiderTeitelbaumFourier}, the exotic interpretation of Katz's Bernoulli--Hurwitz $p$-adic $L$-function when $p\equiv 3 \mod 4$ as a Galois equivariant measure becomes much cleaner if one passes to the generic fiber: the $p$-adic $L$-function becomes a $\mathbb{Q}_{p^2}$-analytic distribution on $\mathbb{Z}_{p^2}^\times$. In our global setting, we may also pass to the generic fiber to obtain a Hodge--Tate analytic distribution on the Tate module of the dual of the universal elliptic curve. This distribution specializes at the lemniscate curve to recover the construction of Schneider--Teitelbaum, but also has other applications. Using this distribution we recover the usual overconvergence of Katz's Eisenstein family of $p$-adic modular forms (Example \ref{eg.overconvergent-eisenstein-series}) and construct new overconvergent versions of the Schneider--Teitelbaum $p$-adic $L$-functions that exist on open loci in the supersingular locus (Example \ref{eg.quaternionic-eisenstein-series}). These results are explained in \S\ref{ss.global-eisenstein-distribution}. 


\subsection{The global Eisenstein measure}\label{ss.global-eisenstein-measure}
To state our result, we first introduce some terminology. Let $N \geq 3$ coprime to $p$. Let $\mathfrak{Y}$ be the modular curve over $\spf \zp$ of full level $N$. Let $\mathcal{E}$ be the universal elliptic curve over $\mathfrak{Y}$ and let $\omega=\omega_{\mathcal{E}}$ be the sheaf of invariant differentials relative to $Y$. We denote by $\mathfrak{Y}_{\mathrm{ord}} \subset \mathfrak{Y}$ the open locus where $\mathcal{E}$ is ordinary.

We write $\Igkatz \to \mathfrak{Y}_{\mathrm{ord}}$ for the Katz--Igusa formal scheme parameterizing trivializations $\varphi:\widehat{\mathcal{E}} \xrightarrow{\sim}\gmhat$, or equivalently $(T_p \mathcal{E}^\vee)^\et \xrightarrow{\sim} \ul{\mathbb{Z}_p}$, which is
a profinite \'{e}tale $\mathbb{Z}_p^\times$-torsor over $\mathfrak{Y}_\mathrm{ord}$. There is a canonical section $\omega_\mathrm{can}=\varphi^*\frac{dt}{1+t}$ of $\omega$ over $\Igkatz$, and $\mathbb{V}=\mathcal{O}(\Igkatz)$ is the ring of Katz--Serre $p$-adic modular forms of prime-to-$p$ level $N$. Let $\operatorname{HT} \colon T_p \mathcal{E}^{\vee} \to \omega$ denote the Hodge--Tate map and, for an integer $m \in \mbb{Z}$, we let $\operatorname{HT}^m \colon T_p \mathcal{E}^{\vee} \to \omega^{\otimes m}$ be the $m$-th fold tensor product of $\operatorname{HT}$. We can view $\operatorname{HT}^m \in \mathcal{O}(T_p\mathcal{E}^{\vee}) \otimes_{H^0(\mathfrak{Y}, \mathcal{O})} H^0(\mathfrak{Y}, \omega^m)$. 

\begin{Thm} \label{thm.integral-eisenstein}
Let $p>3$ be an integer prime. For any integer $n > 1$  coprime to $p$, there is an element 
\[ \Eis^{(n)} \in H^0(\mathfrak{Y}, \omega^2) \otimes_{H^0(\mathfrak{Y}, \mathcal{O})} \mathcal{O}(T_p \mathcal{E}^\vee)^*, \]
i.e., a weight $2$ modular form $\Eis^{(n)}$ over $\Spf \mathbb{Z}_p$ valued in measures on $T_p \mathcal{E}^\vee$, such that: For $k \geq 3$, we have
\[ 
\int \HT^{k-2} d\Eis^{(n)} = 2(1-n^k)G_{k}
\]
and $\int 1 d\Eis^{(n)} = 0$ (here we are considering $G_k$ as an element of $H^0(\mathfrak{Y}, \omega^k)$ in the usual way).
\end{Thm}
\begin{proof}
Consider the weight $2$ modular form which sends a non-vanishing differential $\eta$ to the meromorphic function $x$ in the unique Weierstrass equation $y^2=4x^3-g_2 x-g_3$ with $\eta=\frac{dx}{y}$, see \cite[Section 2.2]{KatzMazur}. The function $x^{(n)}:=x - n^2[n]^*x$, where $[n]:\mathcal{E} \to \mathcal{E}$ is the multiplication by $n$ map, has poles at the non-trivial $n$-torsion points (one can see that the poles at the identity of $\mathcal{E}$ cancel, e.g., from the transcendental computation given below). In particular, $x^{(n)}|_{\mathcal{E}[p^\infty]} \in \mathcal{O}(\mathcal{E}[p^\infty])$, and we obtain the weight $2$ modular form $\Eis^{(n)}$ as $(\mathbb{F}^{\mathcal{E}[p^\infty]})^{-1}(x^{(n)}|_{\mathcal{E}[p^\infty]})$, for $\mathbb{F}^{\mathcal{E}[p^\infty]}$ the integral Fourier transform as in Theorem \ref{thm.integral-fourier-theory}. 

We explain the computation for Theorem \ref{thm.integral-eisenstein}. First, unwinding the definitions, one finds that $\int \HT^{j}d\Eis^{(n)}$ is the weight $j+2$ modular form that sends a non-vanishing differential $\eta$ with dual $\partial$ to $\partial^{j} x^{(n)}|_{x=1}$, where $x^{(n)}$ is as above. This is a section of $\omega^{j+2}$ defined over $\mathbb{Z}[1/6N]$, and thus we can verify the claimed identity over $\mathbb{C}$. Then, taking $x^{(n)}$ corresponding to $(\mathbb{C}/\Lambda, dz)$ and using the expansion (see \cite[Theorem 3.5]{Silverman})
\[ 
x(z)=\wp_{\Lambda}(z)= \frac{1}{z^2} + \sum_{k\geq 3} (k-1)A_{k}(\Lambda) z^{k-2}, 
\] 
we find 
\[ x^{(n)}(z) = \wp_{\Lambda}(z)-n^2\wp_{\Lambda}(nz) = \sum_{k \geq 3} (1-n^{k})(k-1)A_k(\Lambda)z^{k-2}. \]
In particular, the constant term is zero, and for $k \geq 3$, differentiating $k-2$ times with respect to $z$ we obtain the constant term $(1-n^{k})(k-1)!A_k=2(1-n^k)G_k$, as desired.  
\end{proof}
\subsubsection{} Given a map $\spf R \to \mathfrak{Y}$, which corresponds to an elliptic curve $E \to \spf R$ (with full level $N$ structure), and a non-vanishing differential $\eta \in \omega_E$, we let $\Eis^{(n)}(E, \eta)$ denote the element of $\mathcal{O}(T_p \mathcal{E}^{\vee})^*$ given by pullback along $\spf R \to \mathfrak{Y}$ and using the trivialization $\omega_E \cong R$ given by $\eta$. Let $\mu^{(n)}:C^0(\zp,\zp) \to \mathbb{V}^{\mathrm{GL}_2(\mathbb{Z}/N\mathbb{Z})}$ be the Eisenstein measure of \cite{Katz.p-adic-L-via-moduli}. 
\begin{Thm} \label{thm.integral-eisensteinII}
Let $\pi: T_p \mathcal{E}^\vee|_{\Igkatz} \rightarrow \ul{\mathbb{Z}_p}$ be the natural map induced by $\varphi$. Then for $f \in C^0(\mathbb{Z}_p, \mathbb{Z}_p)$ and $z$ the identity function $\mathbb{Z}_p \rightarrow \mathbb{Z}_p$, we have
\[ \int_{\zp} f \; \mathrm{d}\left(\pi_* \Eis^{(n)}(\mathcal{E}|_{\Igkatz}, \omega_\mathrm{can})\right) = \int_{\zp} z \cdot \left(f(z)-f(0)\right) \;  \mathrm{d}\mu^{(n)}. \]
\end{Thm}
\begin{proof}
Since $\mathbb{V}$ is $p$-torsion free, it suffices to verify the statement on $f=z^j$, $j \geq 0$. For $j=0$, both sides give zero. For $j\geq 1$, the left-hand side gives $2(1-n^{j+2})G_{j+2}(\omega_\mathrm{can})$ by Theorem \ref{thm.integral-eisenstein}. For $j \geq 1$, the right-hand side is $\int z^{j+1}d\mu^{(n)}$, which agrees by \cite[Theorem on p.501]{Katz.p-adic-L-via-moduli}. 
\end{proof}

\begin{Rem}
    We have introduced level $N$ structure just to have a moduli scheme instead of a moduli stack, but are only interpolating the level $1$ Eisenstein series. It is also possible to construct more general global Eisenstein measures interpolating all of the level $N$ Eisenstein series and specializing to the measures of \cite{Katz.TheEisensteinMeasureAndpAdicInterpolation}; a natural way to accomplish this is to restrict the Weierstrass function to $(\mathcal{E}[p^\infty] \times \mathcal{E}[N]) \backslash (\mathcal{E}[p^\infty] \times 0)$ to obtain a measure on $T_p \mathcal{E}^\vee \times \mathcal{E}^\vee[N]$ supported on the complement of $T_p \mathcal{E}^\vee \times 0$. We leave the details to the interested reader. 
\end{Rem}

\begin{Eg}
In the setting of Theorem \ref{thm.integral-eisensteinII}, the usual weight families of $p$-depleted Eisenstein series parameterized by characters of $\mathbb{Z}_p^\times$ are obtained by restricting the measure $\mu^{(n)}$ from $\mathbb{Z}_p$ to $\mathbb{Z}_p^\times$ 
(i.e., taking the measure on $\mathbb{Z}_p^\times$ given by evaluating $\mu^{(n)}$ on elements of $\Cont(\mathbb{Z}_p^\times, \mathbb{Z}_p)$ by extending by zero). In particular, the constant term discrepancy and multiplication by $z$ in (2) do not change these resulting families: In other words, the usual weight family can be recovered from $\Eis^{(n)}$ by
\[ \kappa \mapsto \int_{\mathbb{Z}_p^\times} z^{-1}\kappa \; \mathrm{d} \left(\pi_* \Eis^{(n)}(\mathcal{E}|_{\Igkatz}, \omega_\mathrm{can})\right).\]
\end{Eg}

\begin{Eg}\label{e.g.p-equiv-3-mod-4}
For $p \equiv 3 \mod 4$, the measure $\Eis^{(n)}(E_0, \frac{dx}{y})$ is, by a direct comparison of constructions, the measure obtained by applying $(r^\mathrm{int})^*$ (as in Theorem \ref{thm.integral-rational-compatibility}) to the Galois-equivariant measure on $T_p E_0^{\vee}(\mathbb{C}_p)$ constructed in \cite{Katz.FormalGroupsAndPAdicInterpolation}.
\end{Eg}

\subsection{The global Eisenstein distribution}\label{ss.global-eisenstein-distribution}
Passing to the generic fiber $\mathfrak{Y}_\eta$ (the good reduction locus inside the rigid analytic modular curve of level $N$), we obtain a Hodge--Tate analytic distribution $\Eis^{(n)}_\eta$ on $T_p \mathcal{E}^\vee_\eta$, the Tate module of the universal elliptic curve over $\mathfrak{Y}_\eta$. Applying Theorem \ref{thm.integral-rational-compatibility}, we find it could also be described directly by applying the inverse Fourier transform on the generic fiber to the same restriction of the modified Weierstrass function. We explain now how to use $\Eis^{(n)}_\eta$ to construct interesting weight families. 

\begin{Eg}\label{eg.overconvergent-eisenstein-series} For $\epsilon=p^{-n}$, consider the $\epsilon$ neighborhood $\mathbb{Z}_{p,\epsilon}$ of $\ul{\mathbb{Z}_p}$ in $\mathbb{A}^1$ representing the functor $(R,R^+) \mapsto \ul{\zp}(R,R^+) + p^{n}R^{+}$. We also consider the subfunctor $\mathbb{Z}_{p,\epsilon}^{\times} \subset \mathbb{Z}_{p,\epsilon}$ representing $(R,R^+) \mapsto \ul{\zp^{\times}}\cdot (1+p^n R^+)$; this is an abelian group under multiplication.

For $\Spa (R,R^+)/ \Spa (\mathbb{Q}_p, \mathbb{Z}_p)$ affinoid perfectoid and a pair $(E, \eta)$ consisting of an elliptic curve $E/R^{+}$ and a non-vanishing differential $\eta$ on $E$, we say $(E,\eta)$ is $\epsilon$-ordinary if $\mathbb{Z}_{p,\epsilon} \cdot \HT(T_p E^\vee) = \mathbb{Z}_{p,\epsilon} \cdot \eta$. For a character $\kappa:\mathbb{Z}_{p,\epsilon}^{\times} \to \mathbb{G}_{m}^{\mathrm{an}}$, a $\mathbb{Z}_{p,\epsilon}$-overconvergent modular form $F$ of weight $\kappa$ is a rule assigning to any $\epsilon$-ordinary pair $(E, \eta)$ over $(R,R^+)$ an element $F(E,\eta) \in R$ such that $F(E,c^{-1}\eta)=\kappa(c)F(E,\eta)$ for $c \in \mathbb{Z}_{p,\epsilon}^\times(R)$. We obtain for any $\kappa$ as above a $\mathbb{Z}_{p,\epsilon}$-overconvergent $p$-adic modular form of weight $\kappa \cdot z^2$ by 
\[ (E, \eta) \mapsto \int_{T_p E^\vee} \kappa_! \circ \frac{\HT}{\eta} \cdot d\Eis^{(n)}(E,\eta),\]
where $\kappa_!$ is the extension by zero of $\kappa$ from $\mathbb{Z}_{p,\epsilon}^\times$ to $\mathbb{Z}_{p,\epsilon}$. This overconverges the Eisenstein series of weight $\kappa \cdot z^2$ over the closure of the ordinary locus ($\epsilon=0$) as obtained from the integral theory above.
\end{Eg}

\begin{Eg}\label{eg.quaternionic-eisenstein-series}
For $A$ an order in a quadratic extension $L/\mathbb{Q}_p$ and for $\epsilon=p^{-n}$, consider the $\epsilon$-neighborhood $A_\epsilon$ of $\ul{A}$ in $\mathbb{A}^1_L$ as above, and similarly consider $A_{\epsilon}^{\times}$. We say a pair $(E,\eta)$ over an affinoid perfectoid $\Spa(R,R^+)/\Spa (L, \mathcal{O}_L)$ is $A_\epsilon$-adapted if $A_\epsilon \cdot \HT(T_p E^\vee)= A_\epsilon \cdot \eta$. For $\kappa:A_\epsilon^\times \to \mathbb{G}_m^{\mathrm{an}}$ a character, an $A_\epsilon$-overconvergent modular form of weight $\kappa$ is a rule assigning to any $A_\epsilon$-adapted $(E,\eta)$ over $(R,R^+)$ an element $F(E,\eta) \in R$ such that $F(E, c^{-1}\eta)=\kappa(c)F(E,\eta)$ for $c \in A_{\epsilon}^\times(R)$. We obtain for any $\kappa$ an $A_\epsilon$-overconvergent $p$-adic modular form of weight $\kappa \cdot z^2$ by 
\[ (E, \eta) \mapsto \int_{T_p E^\vee} \kappa_! \circ \frac{\operatorname{HT}}{\eta}\cdot d\Eis^{(n)}{(E,\eta)},\]
where $\kappa_!$ is the extension by zero of $\kappa$ from $A_{\epsilon}^\times$ to $A_\epsilon$. This overconverges a modular form on the $A$-formal CM locus ($\epsilon=0$), a (twisted) profinite subset of the supersingular locus of the rigid analytic $p$-adic modular curve over $L$ isomorphic\footnote{This isomorphism follows, e.g., from \cite[Corollary 3.4.7, proof of Lemma 5.6.1]{HoweThesis}.} after an extension of scalars to
\[ D^\times(\mathbb{Q}) \backslash D^\times(\mathbb{A}_f) / (A^\times \times K^p),\]
where $D$ is a quaternion algebra over $\mathbb{Q}$ ramified at $p$ and $\infty$. Note that, by construction, the characters of $A^\times$ that extend to some $A_\epsilon^\times$ are precisely the $L$-analytic characters of $A^\times$. Note also that the existence of these analytic Eisenstein series on the quaternionic double quotient is already new. Specializing to genuine CM points inside the formal CM locus, one recovers the Schneider--Teitelbaum $p$-adic $L$-functions.
\end{Eg}

