\end{Q}


\appendix 
\section{Comparison with classical functional analysis}
\label{App:A}
In this appendix, we compare the constructions of Section \ref{Sec:Condensed} with those appearing in classical functional analysis. In particular, we extend (parts of) \cite{RJRC} to the setting where the base is a general $\mbb{Q}_p$-Banach algebra (not just a finite extension of $\qp$). These comparison results are used throughout the main body in the text (e.g. in the proof of Lemma \ref{Lem:TheAmiceCase}), and in \S \ref{Sub:Field},\ref{Sub:STComparison}. In \S \ref{sub:TheAmiceTransform}. we discuss the classical Amice transform as it is used in the proof of Theorem \ref{Thm:Main}.

\subsection{Comparison with classical functional analysis}
\label{subsec:ComparisonWithClassicalFA}

\subsubsection{} \label{subsub:ClassicalObjectDefs}
We first recall some objects which appear in classical functional analysis. Let $(R,R^+)$ be a uniform Huber pair over $(\qp,\zp)$. A topological $R$-module $M$ is \emph{Banach} if $M=M^+[\tfrac{1}{p}]$ where $M^+$ is a $p$-torsion free $p$-adically complete and separated $R^+$-module with the $p$-adic topology. A topological $R$-module $M$ is \emph{orthonomalizable Banach} (resp. \emph{free Smith}) if $M$ is isomorphic, as a topological $R$-module, to $\widehat{\bigoplus}_I R$ (resp. $\left( \prod_{I} R^+ \right)[\tfrac{1}{p}]$). Here the former module is equipped with the $p$-adic topology, and the topology on the latter module is induced from the product topology. We say such a module is \emph{countably orthonormalizable Banach} (resp. \emph{countably free Smith}) if the index set $I$ can be taken to be a countable set. 

\begin{Lem} \label{Lem:BanachSmithAEquiv}
    The functor $\operatorname{Mod}_R^{\operatorname{cond}} \to R\mathrm{-Mod}$ given by $M \mapsto M(*)_{\operatorname{top}}$ induces an equivalence (with inverse $V \mapsto \underline{V}$) between solid and classical $?$ modules, where $?$ can be:
    \begin{itemize}
        \item direct summands of orthonormalizable Banach;
        \item direct summands of countably free Smith.
    \end{itemize}
\end{Lem}
\begin{proof}
    It is enough to establish the proposition for orthonormalizable/free Banach/Smith modules. In this case, it follows from Lemma \ref{Lem:CompactlyGenerated} and Lemma \ref{Lem:Fullyfaithful}, together with the fact that the counit of the adjunction $(-)(*)_{\operatorname{top}} \dashv \underline{(-)}$ is a natural isomorphism on compactly-generated topological spaces.  
\end{proof}

\subsubsection{} We call a topological $R$-module $M$ \emph{strongly (countably) Fr\'echet} if it is isomorphic, as a topological $R$-module, to an inverse limit $\varprojlim_{n \in \mathbb{Z}_{\ge 0}} M_n$ of topological direct summands of (countably) orthonomalizable Banach modules $M_n$ with dense transition maps.  We have the following analogue of Lemma \ref{Lem:BanachSmithAEquiv} for strongly countably Fr\'echet spaces. 
\begin{Prop} \label{Prop:FrechetVSClassicalFrechet}
    The functor $\operatorname{Mod}_R^{\operatorname{cond}} \to R\mathrm{-Mod}$ given by $M \mapsto M(*)_{\operatorname{top}}$ induces an equivalence (with inverse $V \mapsto \underline{V}$) between solid and classical strongly (countably) Fr\'echet modules. 
\end{Prop}
\begin{proof}
    Since the index sets are countable, strongly countably Fr\'echet spaces are compactly-generated topological spaces. By Lemma \ref{Lem:Fullyfaithful}, it therefore suffices to prove the essential image of the functor $V \mapsto \underline{V}$ from (classical) strongly countably Fr\'echet spaces coincides with the category of condensed strongly countably Fr\'echet spaces. But this follows from Lemma \ref{Lem:BanachSmithAEquiv} and the fact that $\underline{(-)}$ commutes with inverse limits. 
\end{proof}

\begin{Rem}
    The reason we do not define LB spaces over a general $R$ is because of subtleties with direct limits of topological $R$-modules. Over a field, one works with the locally convex inductive limit, and developing this theory over an arbitrary Banach $\qp$-algebra $R$ is beyond the scope of this appendix.
\end{Rem}

\subsubsection{} If $M=M^+[\tfrac{1}{p}],N=N^+[\tfrac{1}{p}]$ are Banach $R$-modules, then we define their completed projective tensor product to be
\begin{align}
    M \widehat{\otimes}_{R} N := \left( M^+ \widehat{\otimes}_{R^+} N^+ \right)[\tfrac{1}{p}], 
\end{align}
where $\widehat{\otimes}_{R^+}$ denotes the $p$-adically completed tensor product. This does not depend on $M^+$ and $N^+$.

\begin{Lem} \label{Lem:DenseImageTensorTopological}
Let $M_1, M_2$ and $N$ be Banach $R$-modules. If $f:M_1\to M_2$ is a continuous $R$-linear morphism with dense image, then the map
    \begin{align}
       M_1 \widehat{\otimes}_{R} N \to M_2 \widehat{\otimes}_{R} N
    \end{align}
    has dense image.
\end{Lem}
\begin{proof}
Write $N=N^+[\tfrac{1}{p}]$ and $M_i=M_i^+[\tfrac{1}{p}]$. The density of $f$ is equivalent to the property that for all $k \in \mathbb{Z}$, the induced map
\[
g \colon M_1 \to M_2/p^k M_2^+
\]
is surjective. We therefore see that 
\begin{align*}
M_1 \otimes_{R^+} N^+ &\to \left( M_2/p^k M_2^+ \right) \otimes_{R^+} N^+ \\ 
&= (M_2 \otimes_{R^+} N^+)/p^k (M_2^+ \otimes_{R^+} N^+) \\ 
&= (M_2 \otimes_{R} N)/p^k (M_2^+ \otimes_{R^+} N^+) \\ 
&= (M_2 \widehat{\otimes}_R N)/p^k(M_2^+ \widehat{\otimes}_{R^+} N^+)
\end{align*}
is surjective, where the first equality uses that $M_2^+$ is $p$-torsion free (here, by abuse of notation $(M_2 \otimes_{R^+} N^+)/p^k (M_2^+ \otimes_{R^+} N^+)$ means quotient by the image of $p^k (M_2^+ \otimes_{R^+} N^+)$ in $M_2 \otimes_{R^+} N^+$), and the second equality uses that (the image of) $M_2^+ \widehat{\otimes}_{R^+} N^+$ is a lattice in $M_2 \widehat{\otimes}_R N$. This map is the natural one; in particular it factors through $M_1 \widehat{\otimes}_R N$ and the natural map
\[
M_1 \widehat{\otimes}_R N \to (M_2 \widehat{\otimes}_R N)/p^k(M_2^+ \widehat{\otimes}_{R^+} N^+)
\]
is surjective for all $k \in \mathbb{Z}$. This implies that $g \otimes 1 : M_1 \widehat{\otimes}_R N \to M_2 \widehat{\otimes}_R N$ has dense image. 
\end{proof}

\subsubsection{} \label{subsub:weakdual} Now assume that $R=K$ is a field and let $V$ denote a locally convex topological $K$-vector space in the sense of \cite[Section 4]{SchneiderFA}. We will write $V'_{w}$ for the $K$-vector space of continuous linear functions $M \to K$ equipped with the weak topology, and $V'_{b}$ for the same $K$-vector space equipped with the strong topology (see \cite[Section 6]{SchneiderFA}). 
\begin{Lem} \label{Lem:TopologicalDuals}
    If $M$ is a topological direct summand of a orthonormalizable Banach $K$-module, then there is a natural isomorphism
    \begin{align}
        \ul{M'_{w}} \simeq \Hom_{\ul{K}}(\ul{M}, \ul{K}).
    \end{align}
    If $N$ is a topological direct summand of a countably free Smith $K$-module, then there is a natural isomorphism
    \begin{align}
        \ul{N'_{b}} \simeq \Hom_{\ul{K}}(\ul{N}, \ul{K}).
    \end{align}
\end{Lem}
\begin{proof}
Using Proposition \ref{Prop:DualityCondensed} and the exactness of idempotent projection, it is enough to verify that the weak dual of $\widehat{\bigoplus}_I K$ (resp. the strong dual of $(\prod_I K^+)[1/p]$) coincides with $(\prod_I K^+)[1/p]$ (resp. $\widehat{\bigoplus}_I K$). The former is a direct computation, and the latter follows from the former and \cite[Corollary 13.8]{SchneiderFA}.
\end{proof}

\subsection{The Amice transform}  \label{sub:TheAmiceTransform}
For $V$ a $\mathbb{Q}_p$-Banach space, we write $\Cont(\zp, V)$ for the space of continuous functions from $\zp$ to $V$, equipped with the compact-open topology, so that $\Cont(\zp, V_0)$ is an open bounded lattice for any open bounded lattice in $V_0$, see Lemma \ref{Lem:CompactOpen} (if we put a norm on $V$, this is the topology induced by  the sup norm). For $h \geq 1$, we write $\mathrm{LA}_h(\zp, V)$ for the functions that are  analytic on each closed disk of radius $1/p^h$. We may write $\mathrm{LA}_h(\zp, V)=\bigoplus \mathrm{LA}_h(x + p^h\mathbb{Z}_p^h, V)$ as $x$ runs over residue classes for $\mathbb{Z}/p^h\mathbb{Z}$, and on each of these an open bounded lattice is given by formal sums with coefficients in $V_0$ going to zero of monomials in $(\frac{(z-x)}{p^h})$, for $V_0$ an open bounded lattice in $V$ (if we equip $V$ with the gauge norm associated to $V_0$, then this is the unit ball for the sup norm on coefficients).  

\begin{Lem}\label{lemma.completed-tensor-product-cont-and-la}
\[ \Cont(\zp, V)= \Cont(\zp, \mathbb{Q}_p) \widehat{\otimes}_{\mathbb{Q}_p} V \textrm { and } \mathrm{LA}_h(\zp, V) = \mathrm{LA}_h(\zp, \mathbb{Q}_p) \widehat{\otimes}_{\mathbb{Q}_p} V \]
\end{Lem}
\begin{proof}
We fix an orthonormal basis $e_i$ for $\Cont(\zp, \mathbb{Q}_p)$ by lifting a basis for $\Cont(\zp, \mathbb{F}_p)$ to locally constant functions on $\mathbb{Z}_p$. We fix a bounded open lattice $V_0$ in $V$ and an orthonormal basis $v_j$ for $V$ by lifting an $\mathbb{F}_p$-basis of $V_0/p$. Then, the functions $e_i \cdot v_j: z \mapsto e_i(z)v_j$ are an orthonormal basis for $\Cont(\zp, V)$ since they lie in the bounded open lattice $\Cont(\zp, V_0)$ and reduce mod $p$ to a basis of $\Cont(\zp, V_0/p)$. Thus the natural map 
\[ \Cont(\zp, \mathbb{Q}_p) \widehat{\otimes}_{\mathbb{Q}_p} V \rightarrow \Cont(\zp, V) \]
induced by the pairing $(f,v) \mapsto f \cdot v: z \mapsto f(z) v$ is an isomorphism. 

For $\mathrm{LA}_h(\mathbb{Z}_p, \bullet)$, it suffices to treat each $\mathrm{LA}_h(x+p^h \mathbb{Z}_p, \bullet)$ separately, where we find immediately that the $\frac{(z-x)}{p^h}^m v_j$ are an orthonormal basis and we conclude as above. 
\end{proof}  

\begin{Lem}[Mahler--Amice]\label{lemma.mahler-amice-bases}
The binomial coefficients $c_n: \zp \rightarrow \zp$, $c_n(z)=\binom{z}{n}$ are an orthonormal basis for $\Cont(\zp, \qp)$. The multiples $c_{n,h}=[\frac{n}{p^h}]! c_n$ are an orthonormal basis for $\LA_h(\zp, \qp)$. 
\end{Lem}
It follows, in particular, that the natural map $\mathrm{LA}(\zp, \qp) \rightarrow \Cont(\zp, \qp)$ is injective, and any $f \in \mathrm{LA}(\zp, \qp)$ has a unique M\"{a}hler expansion 
\[ f = \sum_{n \in \mathbb{Z}_{\geq 0}} a_n(f) \cdot c_{n} \textrm{ where } c_{n}(z)=\binom{z}{n}.  \] 

\subsubsection{} Let $\widehat{\mathbb{G}}_m$ be the formal multiplicative group over $\spf \zp$ and let $\gmhateta$ be its rigid generic fiber. We note that any $f \in \mathcal{O}(\gmhateta)$ has a unique power series expansion
\[ f=\sum_{n \in \mathbb{Z}_{\geq 0}}  a_n(f) \cdot t^{n}. \]
We have the universal character 
\[ \kappa=(1+t)^{z}=1+\binom{z}{1} t + \binom{z}{2} t^2 + \ldots = \sum_{n \in \mathbb{Z}_{\geq 0}} c_n \cdot t^{n} \in \Cont(\zp, \zp[[t]]). \]

\subsubsection{} For $r<1$ a rational power of $p$, we write $D_{r} \subseteq \gmhateta$ for the affinoid disk $|t| \leq p^{1/r}$. By restriction, we obtain an element $\kappa^{\locan}$ of
\[ \varprojlim_r \varinjlim_h \mathrm{LA}_h(\zp, \mathcal{O}(D_{r})). \]
Using Lemma \ref{lemma.completed-tensor-product-cont-and-la}, we may view $\kappa^\locan$ as an element of 

\begin{align} \varprojlim_r \varinjlim_h \mathrm{LA}_h(\zp, \mathcal{O}(D_{r})) & = \varprojlim_r \varinjlim_h \mathrm{LA}_h(\zp, \qp)\widehat{\otimes}_{\qp} \mathcal{O}(D_{r}).
\end{align}

\subsubsection{} Write $\mathrm{LA}(\zp, \qp)'_{b}$ for the continuous $\qp$-linear dual of $\mathrm{LA}(\zp, \qp)$ equipped with the strong topology. We let 
\[ \mathbb{F}_{\gmhateta}: \mathrm{LA}(\zp, \qp)'_{b} \rightarrow \varprojlim_r \mathcal{O}(\mathbb{D}_r) \]
denote the map obtained by contracting $\kappa^\locan$ with $\mu \in \mathrm{LA}(\zp, \qp)'$ (which induces a compatible family of elements $\mu_h$ in  $\mathrm{LA}_h(\zp, \mathbb{Q}_p)$). 

\begin{Cor}\label{cor.amice-bijections}
The map $\mathbb{F}_{\gmhateta}$ is a bijection.
\end{Cor}
\begin{proof}
The map can be described explicitly by 
\[ \mathbb{F}_{\gmhateta}(\mu)= \sum_{n \in \mathbb{Z}_{\geq 0}} \mu(c_n) t^n, \]
where we recall that $c_n$ is the binomial function. Comparing the growth conditions allowed on each side (using the Amice basis for locally analytic functions), one finds it is a bijection, cf. \cite[Theorem 1.8.4]{Colmeznotes}. 
\end{proof}



