f_{K} = 155.7~\text{\cite{PDG:2024cfk}}, \quad 
f_{\eta} = (181.14)~\text{\cite{Dowdall:2013rya}}, \quad 
f_{D} = 203.8~\text{\cite{PDG:2024cfk}}, \\
&f_{D_s} = 250.1~\text{\cite{PDG:2024cfk}}, \quad 
f_{\eta_c} = 335~\text{\cite{PDG:2024cfk}}, \quad 
f_{\rho} = (210)~\text{\cite{Bharucha:2015bzk}}, \quad 
f_{K^{*}} = (204)~\text{\cite{Bharucha:2015bzk}}, \\
&f_{\phi} = (228.5)~\text{\cite{Chakraborty:2017hry}}, \quad 
f_{D^{*}} = (223.5)~\text{\cite{Lubicz:2017asp}}, \quad 
