			\label{eA4}
			\widetilde{f}(x_1, {\bm{k}}_{\perp}^{\prime}, q^2) = & -2\Big\{
			-(m_1^{\prime}+m_1^{\prime\prime})^2 (m_1^{\prime}-m_2) +(x_1m_2-x_2m_1^{\prime}) M^{\p 2} +(x_1m_2+x_2m_1^{\prime}) M^{\prime\prime 2} \nonumber\\& -x_1(m_2-m_1^{\prime} )(M_0^{\p 2}+M_0^{\prime\prime 2}) + 2x_1m_1^{\prime\prime}M_0^{\p 2} -4 (m_1^{\prime}-m_2)\Big({k}_{\perp}^{\p 2} +\frac{({\bm{k}}_{\perp}^{\prime} \cdot {\bm{q}}_{\perp})^2}{q^2}\Big) \nonumber\\& - m_2 q^2 -(m_1^{\prime}+m_1^{\prime\prime})(q^2+q\cdot p)\frac{{\bm{k}}_{\perp}^{\prime}\cdot {\bm{q}}_{\perp}}{q^2} +4 (m_1^{\prime}-m_2) B_1^{(2)} +\frac{2}{D_{V, con}^{\prime\prime}} \Big[ \Big({k}_{\perp}^{\p 2} \nonumber\\& +\frac{({\bm{k}}_{\perp}^{\prime} \cdot {\bm{q}}_{\perp})^2}{q^2}\Big) \Big((x_1-x_2)M^{\p 2} + M^{\prime\prime 2} -2(m_1^{\prime}-m_1^{\prime\prime})(m_1^{\prime}-m_2) +2x_1M_0^{\p 2} \nonumber\\& -q^2 -2 (q^2 +q\cdot p)\frac{{\bm{k}}_{\perp}^{\prime}\cdot {\bm{q}}_{\perp}}{q^2}\Big) - \Big(M^{\p 2} +M^{\prime\prime 2} -q^2 + 2(m_1^{\prime}-m_2)(m_1^{\prime\prime} \nonumber\\& +m_2)\Big) B_1^{(2)} +2 B_3^{(3)}\Big]\Big\}, 	\end{align}
		\begin{align}
			\label{eA5}
			\widetilde{a}_{+}(x_1, {\bm{k}}_{\perp}^{\prime}, q^2) = & 2\Big\{(m_1^{\prime\prime} -2x_1m_1^{\prime} +m_1^{\prime} +2x_1m_2)\frac{{\bm{k}}_{\perp}^{\prime}\cdot {\bm{q}}_{\perp}}{{q}_{\perp}^2} + (x_1-x_2)(x_2m_1^{\prime} +x_1m_2) \nonumber\\& +\frac{2}{D_{V, con}^{\prime\prime}} \frac{{\bm{k}}_{\perp}^{\prime\prime}\cdot {\bm{q}}_{\perp}}{x_2 {q}_{\perp}^2} \Big[{\bm{k}}_{\perp}^{\prime}\cdot{\bm{k}}_{\perp}^{\prime\prime}+ (x_1m_2 - x_2m_1^{\prime\prime})(x_1m_2+ x_2m_1^{\prime})\Big] \Big\},
		\end{align}
		\begin{align}
			\label{eA6}
			\widetilde{a}_{-}(x_1, {\bm{k}}_{\perp}^{\prime}, q^2) = & -2\Big\{(3-2x_1)(x_2m_1^{\prime}+x_1m_2) -\Big[(6x_1-7)m_1^{\prime}+(4 -6x_1)m_2 +m_1^{\prime\prime}\Big]\frac{{\bm{k}}_{\perp}^{\prime} \cdot {\bm{q}}_{\perp}}{q^2}\nonumber\\& + 4(m_1^{\prime} - m_2) \Big[ 2 \Big( \frac{{\bm{k}}_{\perp}^{\prime} \cdot {\bm{q}}_{\perp}}{q^2}\Big)^2 + \frac{{k}_{\perp}^{\p 2}}{q^2}\Big] {- 4 \frac{(m_1^{\prime} - m_2)}{q^2} B_1^{(2)}} + \frac{1}{D_{V, con}^{\prime\prime}} \Big[-2\big(M^{\p 2} \nonumber\\& +M^{\prime\prime 2} -q^2 + 2(m_1^{\prime}-m_2)(m_1^{\prime\prime}+m_2)\big) \big(A_3^{(2)} + A_4^{(2)} - A_2^{(1)} \big) + \Big(2M^{\p 2} -q^2 \nonumber\\& -x_1(M^{\p2} - M_0^{\p2}) +x_1(M^{\prime\prime2} - M_0^{\prime\prime2})- 2(m_1^{\prime} -m_2)^2 +(m_1^{\prime} +m_1^{\prime\prime})^2 \Big)\big(A_1^{(1)}\nonumber\\& + A_2^{(1)} -1\big) +2Z_2\big(2A_4^{(2)} -3A_2^{(1)} +1\big) + 2 \frac{q\cdot p}{q^2} \big(4 A_2^{(1)}A_1^{(2)} - 3A_1^{(2)}\big) \nonumber\\& +\frac{2}{q^2}\Big(\big(M^{\p 2} + M^{\prime\prime 2} -q^2 + 2(m_1^{\prime}-m_2)(m_1^{\prime\prime}+m_2)\big) B_1^{(2)} -2 B_3^{(3)}\Big)\Big] \Big\}.
		\end{align}
	\end{itemize}
	The coefficients $A^{(i)}_{j}$ and $B^{(i)}_{j}$ are given as \cite{S:2024adt},
	\begin{equation} \label{eA7}
		\begin{gathered}
			A_1^{(1)} = \frac{x_1}{2}, \hspace{0.5cm}
			A_1^{(2)} = -{k}_{\perp}^{\p 2} - \frac{({\bm{k}}_{\perp}^{\prime}\cdot{\bm{q}}_{\perp})^2}{q^2}, \hspace{0.5cm}
			A_2^{(1)} = A_1^{(1)} - \frac{{\bm{k}}_{\perp}^{\prime}\cdot{\bm{q}}_{\perp}}{q^2}, \\
			A_3^{(2)} = A_1^{(1)}A_2^{(1)}, \hspace{0.5cm}
			A_4^{(2)} = (A_2^{(1)})^2 - \frac{1}{q^2}A_1^{(2)}, \\
			B_1^{(2)} = A_1^{(1)}Z_2 - A_2^{(1)},\hspace{0.5cm}
			B_3^{(3)} = B_1^{(2)}Z_2 + (p^2 -\frac{(q\cdot p)^2}{q^2})A_1^{(1)}A_1^{(2)}, ~\text{ and}
		\end{gathered}
	\end{equation}
	\begin{equation} \label{eA8}
		Z_2 = x_1(M^{\p2} - M_0^{\p2}) + m_1^{\p 2} -m_2^2 +(1-2x_1)M^{\p 2} + (q^2 + q\cdot p)\frac{{\bm{k}}_{\perp}^{\prime}\cdot{\bm{q}}_{\perp}}{q^2}. 
	\end{equation}
	It is important to emphasize that the above expressions for the form factors are derived within the Type-I scheme. The corresponding Type-II expressions can be obtained by replacing $M^{\p(\p\p)}$ with $M_0^{\p(\p\p)}$, as detailed in Ref.~\cite{Chang:2019mmh, S:2024adt}. Furthermore, these expressions are specific to the longitudinal polarization case ($\lambda = 0$); for transverse polarizations ($\lambda = \pm$), the results can be derived by excluding all terms involving the $B^{(i)}_{j}$ functions.
