\subsection{Heston model}
We have already examined several models, each incorporating different aspects of market behavior, such as stochastic jumps. Now, we turn to the Heston stochastic volatility model, which introduces both stochastic volatility and mean reversion to better capture the market uncertainty \citep{heston1993closed}. This model has five parameters: $\theta$ -- long variance, $\kappa$ --
speed of mean reversion of $v(t)$, $\sigma$ -- volatility of the volatility, $\rho$ -- correlation of Wiener
processes, $v_0$ -- initial variance.
The price process follows the diffusion process:
\begin{equation} d S_t = \mu S_t \,dt + \sqrt{\nu_t}S_t\,dW_{1_t}, \end{equation} where $W_{1_t}$ is a Wiener process. When volatility follows the Ornstein--Uhlenbeck process, we obtain: 
\begin{equation} d \sqrt{\nu_t} = - \beta \sqrt{\nu_t} \,dt + \delta \,d W_{2_t}, \end{equation} 
where $W_{2_t}$ is a Wiener process, which has correlation $\rho$ with $W_{1_t}$. Hence, from It\^{o}'s lemma: 
\begin{equation} 
d \nu_t = (\delta^2 - 2\beta \nu_t) \,dt + 2\delta \sqrt{\nu_t} \,d W_{2_t}, 
\end{equation}
which can be written as: 
\begin{equation} 
d \nu_t = \kappa (\theta - \nu_t) \,dt + \sigma \sqrt{\nu_t} \,d W_{2_t}. 
\end{equation}
% In Heston model the characteristic function is expressed as:
% \begin{equation}
% \phi(u) = \exp \left( i u \mu t \right) \exp \left( A(u) + B(u) \right),
% \end{equation}
% \begin{equation} 
% \varphi_X(u, t) = \exp \left( i u \mu t + A(u, t) + B(u, t) \cdot v_0 \right), 
% \end{equation}
% where
% \begin{equation}
% A(u) = \frac{\kappa \theta}{\sigma^2} \frac{1 - \exp(-\kappa t)}{1 - i \rho u},
% \end{equation}
% and
% \begin{equation}
% B(u) = \frac{(i u \rho \sigma)^2}{2} \frac{1 - \exp(-\kappa t)}{1 - i \rho u}.
% \end{equation}
The characteristic function of the log-price process $X_t$ under the Heston model is given by:
\begin{equation}
\varphi_X(u, t) = \exp\left( C(T - t, u) + D(T - t, u) \cdot v_0 + i u x \right),
\end{equation}
where $x = \log{S_t}$, and:
\begin{equation}
\begin{cases}
C(T - t, u) = i u r (T - t) + \frac{\kappa \theta}{\sigma^2} \left[ (\kappa - \rho \sigma i u + d)(T - t) - 2 \ln\left( \frac{1 - g e^{d(T - t)}}{1 - g} \right) \right], \\[10pt]
D(T - t, u) = \frac{\kappa - \rho \sigma i u + d}{\sigma^2} \cdot \frac{1 - e^{d(T - t)}}{1 - g e^{d(T - t)}}, \\[10pt]
d = \sqrt{ (\rho \sigma i u - \kappa)^2 + \sigma^2 (i u + u^2) }, \\[10pt]
g = \frac{\kappa - \rho \sigma i u + d}{\kappa - \rho \sigma i u - d}.
\end{cases}
\end{equation}

