	\begin{aligned}
	 \sum_{c=1}^C&{\lVert \frac{1}{n_{S}^{\left( c \right)}}\sum_{csi_i\in \mathbf{X}_{S}^{\left( c \right)}}{f\left( A^T\mathbf{z}_i \right)}-
