The main result of this section is Lemma~\ref{L.names}, a fact probably well-known to experts, which provides a description of elements in $M^\bbA$, for $\bbA$ the measure algebra of $(\Omega, \mu)$,  in terms of functions in $L^1(\Omega, M)$, with a correspondence analogous to that of names for elements of a Polish space as spaces of functions with possibly infinite values from \cite{jech1985abstract, vaccaro2017generic}. Lemma~\ref{L.names} expands some of the ideas therein to the framework of continuous logic, bringing to light a natural interpretation of $\sfrac{M^\bbA}{\sim}$ as an $\cLR$-structure isomorphic to  the randomization $(\widehat M, \widehat \bbA)$ of $M$. This connection, isolated in Proposition \ref{prop:random},  will be essential for the proof of  Theorem \ref{T.isomorphic_randomizations} in the next section.


%It is probably taken as evident by the experts in forcing but we provide a proof. For the structure $L^1(\Omega,X)$ see Definition~\ref{Def.L1}. 

\begin{lemma} \label{L.names} Let $(\Omega, \mu)$ be a probability measure space, let $\bbA$ be its measure algebra and a let $M$ be a metric structure in some language $\cL$. Then there exists functions
\begin{align*}
\Xi \colon L^1(\Omega,M) &\to M^\bbA 
& 		\Theta \colon M^\bbA& \to L^1(\Omega, M)\\
f &\mapsto f(\rAG) 
&  \dot a &\mapsto \Theta_{\dot a}
\end{align*}
such that
	\begin{enumerate}[label=(\alph*)]
	\item \label{2.names}  For every $f \in L^1(\Omega, M)$, $b \in M$, $A \in \bbA$ and $t \in \bbQ_+$
\begin{equation*}
A \fA d^{M^\ast}(f(\rAG), \check b) \le \check t  \qquad \Leftrightarrow \qquad d^M (f(\omega), b) \le t, \quad \muae \omega \in A.
\end{equation*}
		%\item \label{2.names} $\fA  \Theta^\ast_{F^{M^\ast}(\dot x_0, \dots, \dot x_{n-1})}(\rAG)=F^{M^\ast}(\Theta^\ast_{\dot x_0}(\rAG), \dots , \Theta^\ast_{\dot x_{n-1}}(\rAG))$ for every $n$-ary function symbol $F$ in the language of $M$  and all $\dot x_0,\dots, \dot x_{n-1} \in M^\bbA$.  
		%\item \label{3.names} $\fA R^{M^\ast}(\dot x_{0},\dots, \dot x_{n-1})=R^{M^\ast}(\Theta^\ast_{\dot x_0}(\rAG), \dots ,\Theta^\ast_{\dot x_{n-1}}(\rAG))$ for every $n$-ary relation symbol $R$ (including the distance symbol) in the language of $M$ and all $\dot x_0,\dots, \dot x_{n-1} \in M^\bbA$.  
		\item \label{3.names} Suppose that $\phi(x_0, \dots, x_{k-1}) \in \cL_{\bar x}$, that $f_0, \dots, f_{k-1} \in L^1(\Omega, M)$, that $A \in \bbA$ and $t \in \bbQ_+$. The following are equivalent:
		\begin{enumerate}[label=(\roman*)]
		\item \label{item:i} $A \fA \phi^{M^\ast} (f_0(\rAG), \dots, f_{k-1}(\rAG)) \le \check t$,
		\item \label{item:iii} $ \phi^M(f_0(\omega), \dots , f_{k-1}(\omega)) \le t$ for $\muae \omega \in A$.
		\end{enumerate}	
		\item \label{4.names}  For every $\dot a\in M^{\bbA}$ we have  
		  $\fA \dot a = \Theta_{\dot a}(\rAG)$.
		\item \label{1.names}
		For every $f \in L^1(\Omega, M)$ we have  $f = \Theta_{f(\rAG)}$ $\muae$in $\Omega$.
		\end{enumerate} 
\end{lemma}

\begin{proof}
Fix $f \in L^1(\Omega, M)$. We begin by defining a name $f(\rAG)$ that satisfies condition \ref{2.names}. If $f = \sum_{i < k} a_i \mathbf{1}_{A_i}$ is simple, then let $f(\rAG)$ be the $\bbA$-name such that $A_i \fA f(\rAG) = \check a_i$ for all $i < n$. It is immediate to check that \ref{2.names} holds in this case.

Suppose next that $f$ is not simple. There exists thus a sequence $(f_n)_{n \in \bbN}$ of simple functions that converges pointwise to $f$ $\muae$in $\Omega$. Note that, up to a measure zero set, the range of all $f_n$'s is contained in a separable subset of $M$, whose completion also contains the range of $f$. We can then apply the Egoroff theorem, which, given $\e > 0$, asserts the existence of $B \in \bbA$ such that $\mu (\Omega \setminus B) < \e$ and such that $\sup_{\omega \in B} d^M(f_n(\omega), f(\omega)) \to 0$ as $n \to \infty$, which is to say that $(f_n)_{n \in \bbN}$ converges uniformly to $f$ in $B$. By \ref{2.names} this entails $B \fA ` `(f_n(\rAG))_{n \in \bbN}$ is Cauchy'', and since $\fA ` `M^\ast$ is complete and Hausdorff'', we obtain
\[
B \fA ` `\lim_{n \to \infty}f_n(\rAG) \text{ exists and is unique}''.
\]
Fix now some $A \in \bbA$. By choosing $\e >0$ sufficiently small, we can choose $B$ so that $ B \cap A$ has positive measure. This means that for every $A \in \bbA$ there exists a nonzero $C\subseteq A$ which forces that $\lim_{n \to \bbN} f_n(\rAG)$ exists and is unique. By Proposition \ref{P.forcing}.\ref{4.1.forcing}  we deduce $\fA  ` `\lim_{n \to \infty}f_n(r_\bbA)$ exists and is unique''. Using Proposition \ref{P.forcing}.\ref{0.forcing}, we let $f(\rAG) \in M^\bbA$ be an $\bbA$-name for such limit. Note that $f(\rAG)$ does not depend on the sequence $(f_n)_{n \in \bbN}$.

We show that the name $f(\rAG)$ so defined satisfies \ref{2.names}. Fix then $b \in M$, $A \in \bbA$ and $t \in \bbQ_+$. Let $(f_n)_{n \in \bbN}$ be a sequence of simple functions that converge pointwise to $f$ $\muae$in $\Omega$. The equivalence follows by continuity of the distance:
\begin{align*}
d^M(f(\omega), b) \le t &\iff d^M\left(\lim_{n \to \infty}f_n(\omega), b\right) \le t, \quad \muae \omega \in A \\
&\iff \lim_{n \to \infty} d^M(f_n(\omega), b) \le t , \quad \muae \omega \in A \\
& \iff A \fA \lim_{n \to \infty} d^{M^\ast}(f_n(\rAG), \check b) \le \check t \\
& \iff A \fA d^{M^\ast}\left( \lim_{n \to \infty} f_n(\rAG), \check b\right) \le \check t \\
& \iff A \fA ^{M^\ast}( f(\rAG), \check b) .
\end{align*}


The equivalence in \ref{3.names} is a direct consequence of \ref{2.names} if $f_0, \dots, f_{k-1}$ are simple functions. The general case follows using uniform continuity of $\phi$ and density of simple functions in $L^1(\Omega, M)$, similarly to what we showed above for the distance symbol.

To prove \ref{4.names}, fix $\dot a\in M^\bbA$. Since $\fA ` `M$ is dense in $M^\ast$'', and since $\bbA$ has the c.c.c., for every $n \ge 1$ there is a countable maximal antichain $\cA_n$ and $(a_{B,n})_{B\in \cA_n} \subseteq M$ such that 
\begin{equation} \label{eq:approximate}
B\fA d^{M^\ast}(\dot a, \check a_{B,n}) < \frac{1}{\check n}, \quad  B\in \cA_n.
\end{equation}

Let $\theta_n \in L^1(\Omega, M)$ be defined on $\bigcup_{B\in \cA_n}B$ as:
\[
\theta_n(\omega) = a_{B,n}, \quad   \omega \in B, \, B\in \cA_n,
\]
and define $\theta_n(\omega) = a$ for some $a \in M$, whenever $\omega \in \Omega \setminus \bigcup_{B\in \cA_n}B$. Note that $B \fA \theta_n(\rAG) = \check a_{B,n}$ for all $B \in \cA_n$, so $\fA d^{M^\ast}(\dot a, \theta_n(r_\bbA)) < 1/\check n$ by \eqref{eq:approximate}, and therefore
\begin{equation}\label{eq:limit}
\fA \lim_{n \to \infty}\theta_n(r_\bbA) = \dot a.
\end{equation}

For all $m > n \ge 1$, $B_0\in \cA_m$, $B_1\in \cA_n$, by \eqref{eq:approximate} we have
\begin{equation*}
d^M(\theta_m(\omega),\theta_n(\omega))  <\frac 1m+\frac 1n, \quad \muae \omega \in B_0 \cap B_1.
\end{equation*}
This implies in particular that $d^{L^1(\Omega, M)}(\theta_m, \theta_n) \leq \frac 1m+\frac 1n \le \frac2n$, thus $(\theta_n)_{n =1}^\infty$ is a Cauchy sequence in $L^1(\Omega, M)$. Let $\Theta_{\dot a}$ be its limit in $L^1(\Omega, M)$. Then $\fA \Theta(\rAG) = \lim_{n \to \infty}\theta_n(r_\bbA)$, so $\fA \Theta(\rAG) = \dot a$ by \eqref{eq:limit}.

Finally, to prove \ref{1.names}, note that by \ref{4.names} we have $\fA \Theta_{f(\rAG)}(\rAG) = f(\rAG)$, which, by \ref{3.names}, implies $\Theta_{f(\rAG)} = f$ for $\muae \omega \in \Omega$, as desired.
		\end{proof}

Lemma  \ref{L.names} implies that if $\dot a, \dot b \in M^\bbA$, then $\fA \dot a = \dot b$ if and only if $\Theta_{\dot a} = \Theta_{\dot b}$. From here on, we will systematically  identify elements of $M^\bbA$ with their classes in $\sfrac{M^\bbA}{\sim}$. We moreover retain the notation $\Theta$ for the induced map $\sfrac{M^\bbA}{\sim} \to L^1(\Omega, M)$. Note that, after modding out by $\sim$, $\Theta$ is a bijection with inverse $\Xi$.
By means of this correspondence, we can naturally transpose the $\cLR$-structure defined on $L^1(\Omega, M)$ in \S\ref{S.random} to $\sfrac{M^\bbA}{\sim}$ as follows.

\begin{definition} \label{def:random}
Let $M$ be a metric structure over a language $\cL$ and let $\bbA$ be the measure algebra of a probability space $(\Omega, \mu)$. Using $L^1(\Omega, [0,1])$ as an auxiliary sort, and letting $\Theta \colon \sfrac{M^\bbA}{\sim} \to L^1(\Omega, M)$ be the map defined in Lemma \ref{L.names}, we interpret $\sfrac{M^\bbA}{\sim}$ as an $\cL^\mathsf{R}$-structure as follows:
\begin{enumerate}
\item If $\dot a, \dot b \in \sfrac{M^\bbA}{\sim}$, then $d^{\sfrac{M^\bbA}{\sim}}(\dot a, \dot b) \coloneqq d^{L^1(\Omega, M)}(\Theta_{\dot a}, \Theta_{\dot b})$.
\item If $F \in \cL$ is a function $k$-ary symbol and $\dot a_0, \dots, \dot a_{k-1} \in \sfrac{M^\bbA}{\sim}$, we set
\[ 
F^{\sfrac{M^\bbA}{\sim}}(\dot a_0, \dots, \dot a_{k-1}) \coloneqq F^{L^1(\Omega, M)}(\Theta_{\dot a_0}, \dots, \Theta_{\dot a_{k-1}}) (\rAG).
\]
\item If $R$ is a $k$-ary predicate symbol in $\cL$ and $\dot a_0, \dots, \dot a_{k-1} \in M^\bbA$, then we define
\[
\Boo{R(\dot a_0, \dots, \dot a_{k-1})} \coloneqq \Boo{R^{L^1(\Omega, M)}(\Theta_{\dot a_0}, \dots, \Theta_{\dot a_{k-1}})}.
\]
\end{enumerate}
\end{definition}

We note that the interpretation of $\sfrac{M^\bbA}{\sim}$ as an $\cLR$-structure described above can be also recovered in a more direct and natural way, without relying as much on Lemma~\ref{L.names}. Indeed, if $F \in \cL$ is a function $k$-ary symbol and $\dot a_0, \dots, \dot a_{k-1} \in \sfrac{M^\bbA}{\sim}$, then $\fA F^{M^\ast}(\dot a_0, \dots, \dot a_{k-1}) \in M^\ast $ hence, by Proposition \ref{P.forcing}.\ref{0.forcing}, there exists $\dot b\in M^\bbA$ forced to be equal to $F^{M^\ast}(\dot a_0, \dots, \dot a_{k-1})$, and we can take such $\dot b$ to be the interpretation of $F^{\sfrac{M^\bbA}{\sim}}(\dot a_0, \dots, \dot a_{k-1})$. This is equivalent to what is done in Definition~\ref{def:random}, since~$\dot b$ would be in the same $\sim$-class of $F^{L^1(\Omega, M)}(\Theta_{\dot a_0}, \dots, \Theta_{\dot a_{k-1}}) (\rAG)$.

Similarly, if $R \in\cL$ is a  $k$-ary predicate symbol in $\cL$ and $\dot a_0, \dots, \dot a_{k-1} \in M^\bbA$, then $\fA R^{M^\ast}(\dot a_0, \dots, \dot a_{k-1}) \in [0,1]$. We can then interpret $R^{M^\ast}(\dot a_0, \dots, \dot a_{k-1})$ as an $\bbA$-name for a real number which, applying Lemma \ref{L.names} to $M = [0,1]$ as a metric structure in the empty language, naturally corresponds to some element of $L^1(\Omega, [0,1])$. In hindsight, this can be checked to be, up to a measure zero set, precisely the function $\Boo{R^{L^1(\Omega, M)}(\Theta_{\dot a_0}, \dots, \Theta_{\dot a_{k-1}})}$.

The following is an immediate consequence of Definition \ref{def:random}.

\begin{proposition} \label{prop:random}
Let $M$ be a metric structure in a language $\cL$, suppose that $(\Omega, \mu)$ is a probability measure space and let $\bbA$ be its measure algebra. The map $\Theta$ defined in Lemma \ref{L.names}, paired with the identity map on the auxiliary sort  induces an isomorphism of $\cLR$-structures from $(\widehat M, \widehat \bbA)$ onto $\sfrac{M^\bbA}{\sim}$. In particular, for every  $\phi(\bar x) \in \cL_{\bar x}$ and $\dot a_0, \dots, \dot a_{| \bar x | -1} \in \sfrac{M^\bbA}{\sim}$, we have
\begin{equation} \label{eq:equal_random}
\Boo{\phi(\dot a_0, \dots, \dot a_{| \bar x |-1})} = \Boo{\phi^{L^1(\Omega, M)}(\Theta_{\dot a_0}, \dots, \Theta_{\dot a_{| \bar x |-1}})}.
\end{equation}
 \end{proposition}

