	\subsection{Indecomposability by type II$_1$ components}\label{S.Popa}
The following subsection is based on a suggestion by Stefaan Vaes and it is included with his kind permission. The main result is Proposition~\ref{P.CHaar}, stating that countably quantifier-free saturated type II$_1$ von Neumann algebras cannot be decomposed as tensor product of two type II$_1$ von Neumann algebras, and using the key result due to Popa \cite[Corollary~2.6]{popa1983orthogonal}. 

Recall that a unitary $u$ in a II$_1$ factor $(N, \tau)$ is called a \emph{Haar unitary} if $\tau(u^k)=0$ for all $k\geq 1$. 
In the following, we denote by $Z(M)$ the center of a tracial von Neumann algebra $M$, and we let  $E_{Z(M)}$ denote the unique center-valued trace from $M$ onto $Z(M)$ (see e.g. \cite[III.2.5]{blackadar}).

\begin{definition}\label{Def.CHaar}
	Suppose that $M$ is a tracial von Neumann algebra. A unitary $u$ in $M$ is \emph{uniformly Haar} if $E_{Z(M)}(u^k)=0$ for all $k\geq 1$.  
\end{definition}

The terminology \emph{uniformly Haar} is justified by the fact that $E_{Z(M)}(u^k)=0$ for all $k\geq 1$ if and only if $\tau(u^k)=0$  for all tracial states $\tau$ in $M$ and all $k\geq 1$ (see e.g. \cite[\S III.2.5.7]{blackadar}).
In case $M$ is a II$_1$ factor, a unitary is uniformly Haar if and only if it is Haar. More generally, if $M=\int^\oplus_\Omega M_\omega \, d\mu(\omega)$ is a direct integral of II$_1$ factors, then a unitary $u=\int_\Omega u_\omega \, d\mu(\omega)$ in $M$ is uniformly Haar if and only if $u_\omega$ is a Haar unitary in $M_\omega$ for $\mu$-almost all $\omega$. 

\begin{lemma}\label{L.CHaar.0}
	Every type II$_1$ von Neumann algebra contains a uniformly Haar unitary.
	\end{lemma}
\begin{proof}
	Let $\cR$ be the hyperfinite II$_1$ factor and let $u \in \cR$ be a Haar unitary. If $M$ is a type II$_1$ von Neumann algebra, then it contains a unital copy of $\cR$ (see \cite{argerami_overflow} for a detailed proof). We therefore have that $u$  is a uniformly Haar unitary in $M$:  for $k \in \bbN$ we have $E_{Z(M)}(u^k) = 0$ if and only if $\tau(u^k) = 0$ for every trace $\tau$ in $M$, and the conclusion follows since every trace in $M$ restricts to the unique trace $\tau_\cR$ in $\cR$, and $u$ has been chosen so that $\tau_\cR(u^k) = 0$ for every $k \in \bbN$.
		\end{proof}

For countable quantifier-free saturation see \S\ref{S.cqf-saturated}.
\begin{lemma}\label{L.CHaar}
	Suppose that $u$ and $v$ are uniformly Haar unitaries in a countably quantifier-free saturated tracial von Neumann algebra $(M,\tau)$. Then $u$ and $v$ are unitarily equivalent. 
\end{lemma}

\begin{proof}
	It suffices to prove that the type $\bt(x)$ whose (quantifier-free) conditions are $\|x^*x-1\|_2=0$ and $\|xux^\ast -v\|_2=0$ is approximately satisfiable in $M$.
	For this it suffices to prove that there is a sequence of unitaries $(w_n)_{n \in \bbN}$ in $M$ such that $\|w_n u w_n^*-v\|_{2,\tau}\to 0$ as $n\to \infty$. 

Let $M_0$ be an elementary submodel of $M$ with separable predual that contains $u$ and $v$. We thus have $M_0= \int_\Omega^\oplus M_\omega \, d\mu(\omega)$, with $M_\omega$ a II$_1$ factor for $\mu$-a.e. $\omega \in \Omega$, and $Z(M_0) \cong L^\infty(\Omega , \mu)$, with $\mu$ being the measure induced by $\tau$ (alternatively, we could also apply disintegration of nonseparable von Neumann algebras as in \cite[\S 8]{benyaacov2024extremal}). In particular, we can assume that $u=\int_\Omega u_\omega\, d\mu(\omega)$ and $v=\int_\Omega v_\omega\, d\mu(\omega)$, where $u_\omega$ and $v_\omega$ are Haar unitaries for $\mu$-a.e. $\omega \in \Omega$.

For $n\geq 2$ and $0\leq k<n$ let
\[
J_{n,k}\coloneqq \left\{\exp(i\zeta) \mid \frac{2\pi k} n\leq \zeta<\frac {2\pi(k+1)}n\right\}
\]
	and define $f_n\colon \bbT\to \bbT$ by 
	\[
	f_n(\exp(i\zeta))\coloneqq \exp(2\pi i k/n), \quad \text{if } \zeta\in J_{n,k}. 
	\]
If $\omega \in \Omega$ is such that $M_\omega$ is a factor and both $u_\omega$, $v_\omega$ are Haar unitaries, then $f_n(u_\omega) = \sum_{j < n} \lambda_j p_{j,n}$ and $f_n(v_\omega) = \sum_{j < n} \lambda_j q_{j,n}$, where $\lambda_0, \dots, \lambda_{n-1} \in \bbT$ and
\begin{enumerate}[label=(\roman*)]
\item $\sum_{j < n} p_{j,n} = \sum_{j < n} q_{j,n} = 1_{M_\omega}$,
\item  $\tau_{M_\omega}(p_{j,n}) = \tau_{M_\omega}(q_{j,n}) = \frac1n$, for every $j < n$, where $\tau_{M_\omega}$ is the unique trace on $M_\omega$.
\end{enumerate}
	There exists therefore a unitary $w_{\omega,n} \in M_\omega$ conjugating the tuples $(p_j)_{j < n}$ to $(q_j)_{j < n}$ (see e.g. \cite[Lemma 4.1]{fang2006central}), and as a consequence $w_{\omega,n} f_n(u_\omega) w_{\omega,n}^\ast = f_n(v_\omega)$.

	In other words, if $\phi(x,y) \coloneqq \inf_z \| z^\ast z - 1 \|_2 + \| z x z^\ast - y \|_2$, then
	\[
	\phi^{M_\omega}(f_n(u_\omega), f_n(v_\omega)) = 0, \quad
	 \muae \omega \in \Omega.
	 \]
	 By \cite[Theorem 8.11]{benyaacov2024extremal} we then get
	\[
	\phi^M(f_n(u),f_n(v)) = \phi^{M_0}(f_n(u),f_n(v)) = \int_\Omega \phi^{M_\omega}(f_n(u_\omega), f_n(v_\omega)))\, d \mu(\omega) = 0.
	\]
	By quantifier-free saturation of $M$ this actually gives a unitary $w_n \in M$ such that $w_n f_n(u) w_n^\ast = f_n(v)$.

	 Since $\|f_n(u) -u\|_{2,\tau} \to 0$ and $\|f_n(v)-v\|_{2,\tau}\to 0$ as $n \to \infty$, we therefore get $\|w_n u w_n^*-v\|_2\to 0$ as $n\to \infty$. Finally, by quantifier-free saturation of $M$, $u$ and $v$ are  unitarily conjugate. 
\end{proof}

\begin{proposition}\label{P.CHaar}
	If $(M, \tau)$ is a countably quantifier-free saturated tracial von Neumann algebra of type II$_1$, then $M$ is not isomorphic to the tensor product of two type II$_1$ von Neumann algebras. 
\end{proposition}

\begin{proof}
	Assume otherwise, so $M\cong P\bar \otimes Q$ with both $P$ and $Q$ of type II$_1$. By Lemma~\ref{L.CHaar.0}, there are uniformly Haar unitaries $u_0 \in P$ and $v_0 \in Q$. Note that both $u \coloneqq u_0 \otimes 1_Q$ and $v \coloneqq 1_P \otimes v_0$ are uniformly Haar in $M$ since $E_{Z(M)}(u) = E_{Z(P)}(u_0) \otimes 1_Q$ and $E_{Z(M)}(v) = 1_P \otimes E_{Z(Q)}(v_0)$.

	By Lemma~\ref{L.CHaar}, there is a unitary $w\in M$ such that $wuw^*=v$. In particular, $wuw^*$ is \emph{orthogonal} to $P\bar\otimes 1_Q$, in the sense that $\tau(wuw^\ast a) = 0$ for every $a \in P \bar \otimes 1_Q$.
		By \cite[Corollary~2.6]{popa1983orthogonal}, this implies that $w$ is orthogonal to the normalizer of $P\otimes 1_Q$ in $P\bar \otimes Q$ which, as a von Neumann algebra, generates the whole algebra $ P \bar \otimes Q$, which is a contradiction.
\end{proof}



Popa's \cite[Corollary~2.6]{popa1983orthogonal} has other strong consequences to the structure of countably quantifier-free saturated~II$_1$ factors $M$, usually stated in terms of ultrapowers of II$_1$ factors associated with a nonprincipal ultrafilter on $\bbN$. Such   $M$  cannot be  a crossed product of a diffuse tracial von Neumann algebra by an infinite group, it does not have a Cartan subalgebra (\cite{popa2022topics}), it has no separable maximal abelian subalgebras (\cite{popa2014independence}), and it is not a nontrivial amalgamated free product (see \cite[Proposition 3.16]{gao2024conjugacy}, which also  includes proofs of the previous statements). See also \cite[\S 4.4]{Fa:STCstar} for applications of \cite[Corollary~2.6]{popa1983orthogonal} to \cstar-algebras. 


\subsection{Indecomposability}\label{S.Indecomposability}
We are almost ready to prove Theorem \ref{T.UltrapowerTensoriallyIndecomposable}.
	Before doing so, we prove an elementary preliminary lemma. Given a probability measure space $(\Omega, \mu)$, in what follows we use $\tau_\mu$ to denote the trace on $L^\infty(\Omega, \mu)$ induced by~$\mu$.

\begin{lemma}\label{L.commutator.estimate}
Let $(M,\tau)$ be a tracial von Neumann algebra, let $(\Omega, \mu)$ be a probability space. Suppose that $p \in L^\infty(\Omega, \mu) \bar \otimes M$ is a projection and that $w \in L^\infty(\Omega, \mu) \bar \otimes M$ is a unitary. Then $\|[w,p]\|_{2, \tau_\mu \otimes \tau}=1$ if and only if $\|[w(\omega),p(\omega)]\|_{2, \tau}=1$, for $\mu$-a.e. $\omega \in \Omega$.  
\end{lemma}

\begin{proof} Only the direct implication requires a proof. 
This follows from the general fact that if $w$ and $p$ are a unitary  and a projection in a tracial von Neumann algebra $(N, \sigma)$, then $\|[w,p]\|_{2,\sigma} \leq 1$. Note first that, since $[w,p]=[w,1-p]$, we may assume $\sigma(p)\leq 1/2$. We moreover have
\begin{align*}
\|[w,p]\|_2^2 &=\tau((wp-pw)^*(wp-pw))\\
& = \tau(2p)-2\tau(pw^*pwp).
\end{align*}
As $pw^*pwp\geq 0$, we deduce that $\|[w,p]\|_2^2 \le 2\tau(p)\leq 1$. 

If $N = L^\infty(\Omega, \mu) \bar \otimes M$ then $\|[w,p]\|_{2,\tau_\mu \otimes \tau}=\int_\Omega\|[w(\omega),p(\omega)]\|_{2,\tau}\, d\mu(\omega)$, which implies the desired conclusion. 	
\end{proof}

The following proposition implies Corollary \ref{T.ultrapower} from the introduction, and it is the last ingredient needed to prove Theorem \ref{T.UltrapowerTensoriallyIndecomposable}.
	\begin{proposition}
		\label{L.qf-saturated}
		Suppose that $(P,\tau_P)$ is a tracial type II$_1$ von Neumann algebra and let $(\Omega , \mu)$ be a diffuse probability measure space. Then $M \coloneqq L^\infty(\Omega , \mu) \bar \otimes P$ is not quantifier-free countably saturated.  In particular $M$ cannot be a nontrivial ultraproduct of tracial von Neumann algebras or a relative commutant of a separable subalgebra in one. 
			\end{proposition}

	\begin{proof}
%Assume otherwise and let $M=Q\bar \otimes P$ be a tracial von Neumann algebra with trace $\tau_M$. Since $M$ is not of type I, at least one of $P$ or  $Q$ is not of type I; we may assume that $P$ is not of type I. Since the corner of a quantifier-free countably saturated tracial von Neumann algebra is quantifier-free countably saturated,   by replacing $P$ by such corner, we may assume that it is of type II$_1$, and we denote by $\tau_P$ the trace induced by $\tau_M$. 
%On the other hand, since the closed unit ball of $Q$ is not compact in the 2-norm, there is  a projection $q\in Q$ such that the corner $qQq$ is diffuse (and nontrivial), hence we may assume that $Q$ is diffuse.


Since $L^\infty(\Omega , \mu)$ is diffuse, we can choose pairwise commuting projections $(q_n)_{n \in \bbN}$ in it such that for all disjoint finite subsets $F$ and $G$ of $\bbN$ we have (with the convention that $\prod_{n\in \emptyset} q_n=\prod_{n\in \emptyset} (1-q_n)=1_Q$)
\[
\textstyle\tau_\mu( \prod_{n\in F} q_n\prod_{n\in G} (1-q_n) )=2^{-|F|-|G|}. 
\]

The following part of the proof is based on the proof that the theory of II$_1$ factors has the order property (\cite[Lemma~3.2]{FaHaSh:Model1}). 
Since $P$ is of type II$_1$, it contains a unital copy of the hyperfinite II$_1$ factor $\cR$. 
Identify $\cR$ with $\overline\bigotimes_{n \in \bbN} P_n$, where $P_n\cong M_2(\bbC)$ and identify each $P_n$ with a unital subalgebra of $P$. 
For every $n \in \bbN$, consider the projections $p_n^0$, $p_n^1 \in P_n$ corresponding to
\[
p_n^0 \coloneqq  \begin{pmatrix} 1& 0 \\ 0 & 0 \end{pmatrix}, \quad p_n^1\coloneqq \begin{pmatrix} 1/2& 1/2 \\ 1/2 & 1/2\end{pmatrix}.
\] 
Finally consider the projections in $L^\infty(\Omega, \mu) \bar \otimes \cR \subseteq M$ defined as 
\[
s^0_n \coloneqq q_n\otimes p_n^0+({1}-q_n)\otimes p_n^1, \quad n \in \bbN.
\]
\[
s^1_n \coloneqq q_n\otimes p_n^1+({1}-q_n)\otimes p_n^0, \quad n \in \bbN.
\]
%Thus $r_n^0$ is a projection whose image under the center-valued trace is the scalar $1/2$. 


Let $\bt(x)$ be the type over $Q\bar\otimes P$ defined as
\[
\bt(x) \coloneqq \{ \|x^*x-1\|_2=0, \, \|[x,s^0_n]\|_2=0, \, \| [x,s^1_n]\|_2=1, \, n \in \bbN \}
\]
We show that $\bt$ is consistent in $M$.  Towards this, consider the unitaries in $P_n$
\[
u_n^0\coloneqq\begin{pmatrix} 1 & 0 \\ 0 & -1\end{pmatrix}, \quad 
u_n^1\coloneqq\begin{pmatrix} 0 & 1 \\ 1 & 0\end{pmatrix}, \quad n \in \bbN.
\]
Then $\|[u_n^0, p_n^0]\|_{2,\tau_P}=\|[u_n^1,p_n^1]\|_{2,\tau_P}=0$  and 
$\|[u_n^0, p_n^1]\|_{2,\tau_P}=\|[u_n^1,p_n^0]\|_{2,\tau_P}=1$. 

Since $u_n^i$ and $p_{m}^j$ commute for  all $n\neq m$ and all $i,j = 0,1$, 
the sequence of unitaries
\[
v_n=\prod_{k<n} (q_k \otimes u_k^0+(1-q_k)\otimes u_k^1), \quad n \in\bbN.
\]
shows that every finite subset of $\bt(x)$ is satisfiable in $M$.

We deduce that $\bt(x)$ is consistent in $M$. Assume by contradiction that $M$ is countably quantifier-free saturated, and therefore that $\bt(x)$ is realized by some unitary $w \in M$.

We apply now Lemma~\ref{L.names}, and view all $s^i_n$ and $w$  as $\bbA$-names in $P^\bbA$, where $\bbA$ is the measure algebra associated to $(\Omega, \mu)$. After identifying each $q_n$ with the element in $\bbA$ corresponding to its range, by Lemma~\ref{L.names} we get
\begin{equation}
\label{eq.qn}
q_n\fA s_n^0(\rAG)=\check p_n^0,\quad 
\mathbf{1}_\Omega-q_n\fA s_n^1(\rAG)=\check p_n^0, \quad n \in \bbN.
\end{equation}
By  Lemma \ref{L.commutator.estimate} we moreover obtain
\begin{equation*}
\| [w(\omega), s_n^0(\omega) ] \|_{2, \tau_P} = 0, \quad \| [w(\omega), s_n^1(\omega) ] \|_{2, \tau_P} = 1, \quad \muae \omega \in \Omega, \, n \in \bbN.
\end{equation*}
Therefore, Lemma~\ref{L.names}, along with \eqref{eq.qn}, implies
\begin{equation*}
q_n \fA \|[w(\rAG), \check p^0_n] \|_{2, \tau_{P^\ast}} = 0,  \quad\mathbf{1}_\Omega - q_n \fA \|[w(\rAG), \check p^0_n] \|_{2, \tau_{P^\ast}} = 1, \quad n \in \bbN.
\end{equation*}

As a consequence, in the generic extension $V[G]$ we get that the evaluation $w(\dot r_\bbA)_G$ belongs to $P^{V[G]}$, and, more importantly,
\[
[w(\dot r_\bbA)_G, p_n^0] = 0 \text{ if and only if }q_n \in G.
\]
Since $P$ is dense in $P^{V[G]}$, let $w_0 \in P$ be such that $\| w_0 - w(\dot r_\bbA)_G \|_{2, \tau_P^{V[G]}} < 1/4$. We therefore get
\[
Z(G) \coloneqq \{ n \in \bbN : q_n \in G \} = \{ n \in \bbN : \| [w_0, p_n^0] \|_{2, \tau_P} < 1/2 \}.
\]
Since the set on the right-hand side belongs to $V$, we obtain a contradiction by Proposition \ref{P.forcing}.\ref{5.forcing}.
	\end{proof}


	\begin{theorem}
		\label{T.CountablySaturated} Suppose that $M$ is a diffuse, countably quantifier-free  saturated, tracial von Neumann algebra. Then $M$ is tensorially prime if and only if it is of type I. 
	\end{theorem}


	\begin{proof} We first prove that every countably quantifier-free saturated tracial von Neumann algebra $M$ that is not type I is prime.
	Assume otherwise, so $M=Q\bar \otimes P$ where each one of $P$ and $Q$ has a unit ball that is not compact in the 2-norm. Since $M$ is not of type I, at least one of $P$ or  $Q$ is not of type I; we may assume that $P$ is not of type I. Since the corner of a countably quantifier-free saturated tracial von Neumann algebra is countably quantifier-free saturated,   by replacing $P$ with its corner, we may assume it is of type II$_1$. 
	Since the unit ball of $Q$ is not compact in the 2-norm, there is  a nonzero projection $q_0\in Q$ such that the corner $q_0Qq_0$ is diffuse. By type decomposition, there is a nonzero projecion $q_1\leq q_0$ such that $q_1 Q q_1$ is of type I or of type II$_1$.  We may therefore assume that $Q$ is diffuse and of type I or of type II$_1$. 
	In the former case, Proposition~\ref{L.qf-saturated} leads to contradiction. 
	In the latter case, Proposition~\ref{P.CHaar} leads to contradiction. 


			For the second part of the theorem, fix a type I countably quantifier-free saturated tracial von Neumann algebra $M$. By a combination of characterization of type I tracial von Neumann algebras and Proposition~\ref{P.Abelian-tvNa}, we have that $M$ is isomorphic to a direct sum of von Neumann algebras of the form $M_n(A_\kappa)$,  where $n\geq 1$ and $A_\kappa=L^\infty(\{0,1\}^\kappa,\mu_\kappa)$. 
			Since $M$ is countably quanifier-free saturated, so is each of its summands. As $M$ is diffuse, so is each of its summands. Being countably quantifier-free saturated and diffuse, these summands are  necessarily nonseparable.
			For infinite cardinals $\kappa$ and $\lambda$ we have $A_\kappa\bar\otimes A_\lambda\cong A_{\max(\kappa,\lambda)}$. Hence each of the direct summands  of $M$ absorbs $L^\infty[0,1]$ tensorially, and therefore so does $M$.
	\end{proof}

		\begin{proof}[Proof of Theorem~\ref{T.UltrapowerTensoriallyIndecomposable}]  	
			Suppose that $M$ is an ultraproduct  of tracial von Neumann algebras associated with a countably incomplete ultrafilter on $\bbN$. Then $M$ is countably quantifier-free saturated, and so is $M\cap N'$ for every \wstar-subalgebra $N$ of $M_0$ with separable predual. 
Therefore the conclusion follows by Theorem~\ref{T.CountablySaturated}. 
				\end{proof}


		\section{Concluding remarks}\label{S.Concluding}

		We ought to mention that this is not the first direct application of forcing to operator algebras. In \cite{ozawa1985nonuniqueness}, M. Ozawa  proved that for every pair of infinite cardinals $\kappa<\lambda$ there is an \awstar{} algebra which is both $\kappa$-homogeneous and $\lambda$-homogeneous.  The proof uses the L\' evy poset $\bbP$ for collapsing $\lambda$ to $\kappa$ with conditions of cardinality $<\kappa$. Taking $\cB$ to be the complete Boolean algebra of regular open subsets of $\bbP$, the required \awstar{} algebra is obtained directly by Stone and Gelfand--Naimark dualities: it is $C(X)$, where $X$ is the Stone space of $\cB$. 




		\subsection*{Ozawa's `exercise'}\label{Ex.Ozawa}
		Ozawa's infamous `exercise' on von Neumann algebra tensor products asks  whether for von Neumann factors $M$ and $N$, $L^\infty([0,1])\bar\otimes M\cong L^\infty([0,1])\bar\otimes N$ implies $M\cong N$ (\cite{ozawa2017exercise}; 
		 see \cite{gao2023topics} for some partial answers). The following instance of Corollary~\ref{C2} gives some limitations on what a counterexample may look like. 

		\begin{corollary} \label{C3} Suppose that $M$ and $N$ are II$_1$ factors. 
			\begin{enumerate}
				\item \label{1.C3} Then  $L^\infty[0,1]\bar\otimes M\cong L^\infty[0,1]\bar\otimes N$ if and only if $\Vdash_\bbL M^\ast \cong N^\ast$, where $\bbL$ is the Lebesgue measure algebra on $[0,1]$. 
				\item \label{2.C3} Suppose that $L^\infty[0,1]\bar\otimes M\cong L^\infty[0,1]\bar\otimes N$. Let $\kappa$ be the maximum of density characters of $M$ and $N$ in the strong operator topology. If the real line cannot be covered by $\kappa$ Lebesgue null sets, then  $M\cong N$. 
			\end{enumerate} 
		\end{corollary}

		\begin{proof}  The theory of tracial von Neumann algebras is non-trivial and simplicial, and its extreme models are precisely the finite factors by \cite[Theorem~29.7]{benyaacov2024extremal}.
			Let~$\tau$ denote the tensor product of the Lebesgue measure $\lambda$ on $L^\infty[0,1]$ and the unique trace on $M$, and consider $L^\infty[0,1]\bar \otimes M$ with the $L^1$-norm $\|a\|_1=\tau(|a|)$. By \cite[Lemma 29.1]{benyaacov2024extremal}, the associated metric is compatible with the strong operator topology on bounded balls, which are thus complete. Therefore $L^\infty[0,1]\bar\otimes M$ can be identified with $L^1([0,1], \lambda,M)$. 
			Therefore 	this is a special case of Corollary~\ref{C2}.		\end{proof}



		\subsection*{Probably isomorphic structures}
		If the Lebesgue measure algebra forces the completions of two structures $M$ and $N$ of the same language to be isomorphic,\footnote{Since the Lebesgue measure algebra is homogeneous as a forcing notion, this does not depend on the choice of the generic filter.} we say that $M$ and $N$ are \emph{probably isomorphic}.  Theorem~\ref{T.isomorphic_randomizations} implies that if $M$ and $N$ are discrete structures, or  extremal models of the same non-degenerate, simplicial theory, then they are probably isomorphic if and only if $L^1([0,1],\lambda,  M) \cong L^1([0,1],\lambda, N)$.

		\begin{question}\label{Q1}
			Is there a characterization of theories that admit probably isomorphic, but not isomorphic models? 
		\end{question}

		One such theory is the theory of dense linear orders, because by  \cite[Example~5.1]{laskowski1996forcing}, linear orderings $\bbR$ and $\bbR\setminus \{0\}$ are probably isomorphic but not isomorphic. This example was used in the proof of Corollary~\ref{C1}.  By Theorem~\ref{T.isomorphic_randomizations},  Ozawa's `exercise' \cite{ozawa2017exercise} literally asks whether the theory of II$_1$ factors has this property. 
		The study of nonisomorphic models such that a forcing with the countable chain condition makes them isomorphic was initiated in \cite{baldwin1993forcing} and \cite{laskowski1996forcing}  and more recently the analogous question for $\sigma$-closed forcings was studied in \cite{shelah2025twins}. 

		Questions analogous to Question~\ref{Q1} can be asked for Cohen forcing and other `nice' forcing notions, although we are not aware of natural analogs of Theorem~\ref{T.isomorphic_randomizations} in other contexts. 


		\subsection*{Probably isomorphic ICC groups}

		A discrete group $\Gamma$ has  ICC (infinite conjugacy classes) if every conjugacy class except that of the identity is infinite. A group~$\Gamma$ is ICC if and only if the group von Neumann algebra $L(\Gamma)$ is a II$_1$ factor (see \cite{anantharaman2017introduction}). 

		\begin{question} Are there nonisomorphic ICC groups $\Gamma_0$  and $\Gamma_1$ such that the Lebesgue measure algebra forces $\Gamma_0\cong \Gamma_1$?
		\end{question}

		An affirmative answer to this question would not outright imply that there are nonisomorphic II$_1$ factors that can be forced to be isomorphic, as it is well-known that group factors associated to  non-isomorphic ICC groups can be isomorphic. For example, each amenable ICC group gives rise to a hyperfinite II$_1$ factor, and there is a unique hyperfinite II$_1$ factor with separable predual (i.e., whose unit ball is separable in the $\|\cdot\|_2$-norm). The question whether all von Neumann factors associated with nonabelian (countable) free groups are isomorphic, is one of the most prominent questions in the theory of von Neumann algebras. Since $L(F_n)$ is isomorphic to the free product of $n$ copies of $L^\infty[0,1]$,  this leads to the question whether for a  given abelian tracial von Neumann algebra $A$ and $m\neq n$ a free product of $m$ copies of~$A$
		can be isomorphic to the free product of $n$ copies of~$A$. The case when $A$ is nonseparable has a negative answer by \cite{boutonnet2024non}. 

		\subsection*{Continuous ultrapowers}
		The generic section of $A\bar\otimes P$ for an abelian tracial von Neumann algebra $A$ and II$_1$ factor $P$, used implicitly in the proof of Lemma~\ref{L.qf-saturated}, is equal to the completion $P^{V[G]}$ of $P$ in the forcing extension.   
 This construction appears to be related to the continuous ultrapower $M^{/E,\cU}$ as in \cite[Definition~2.1]{gao2024elementary}.\footnote{In this notation $M$ is a direct  integral of tracial von Neumann algebras, $E$ is the conditional expectation to its center $Z(M)$, and $\cU$ is a character on $Z(M)$.} However, while the Gao--Jekel continuous ultrapower is countably saturated (\cite[Proposition~5.7]{gao2024elementary}), generic section of $L^\infty[0,1]\bar\otimes P$ is isomorphic to $P$ and therefore not countably saturated unless $P$ is.   %This property was crucial in the proof of Theorem~\ref{T.UltrapowerTensoriallyIndecomposable}.  


\subsection*{Non-structure}
		Shelah’s non-structure theory (\cite{shelah2023general}) was used in  \cite{FaKa:NonseparableII} to define a functor from the category of linear orderings into II$_1$ factors such that sufficiently different linear orderings are sent to nonisomorphic hyperfinite II$_1$ factors. This was used  to prove that in every uncountable density character $\kappa$ there are $2^\kappa$ nonisomorphic hyperfinite II$_1$ factors. 
		However, the nonisomorphic linear orderings such that the Lebesgue measure algebra forces that they are isomorphic from \cite{laskowski1996forcing} andused in Corollary~\ref{C1} are not sufficiently different. More precisely,   being separable, they have the same isomorphism invariant that is usually used to distinguish the corresponding Ehrenfeucht--Mostowski models (see e.g., \cite{shelah2023general} or \cite{FaSh:Dichotomy}). 
		Moreover, \emph{sufficiently different} is defined using an invariant that codes the gap structure of a given linear ordering, and this structure cannot be changed by any Lebesgue measure algebra, or any ccc forcing. It is however not obvious  whether the II$_1$ factors associated with $\bbR$ and $\bbR\setminus \{0\}$ are isomorphic.   



	A first-order  theory $T$ has the \emph{independence property} (a common expression is that $T$ does not have  NIP, where NIP stands for `no independence property') if there is a formula $\varphi(\bar x,\bar y)$ such that in every model $M$ of $T$, for every $n$ there are $\bar a_i$, for $i<n$ such that for all $s\subseteq n$ there is $\bar b_s$ such that $M\models \varphi(\bar a_i,\bar b_s)$ if and only if $i\in s$ (\cite{shelah1990classification}). 


	The proof of Proposition~\ref{L.qf-saturated} provides some evidence for the following.  


	\begin{conjecture}\label{C.IP} If $M$ has the independence property witnessed by an affine quantifier-free formula, $(\Omega, \mu)$ is a diffuse probability space, and $\cU$ is a countaby incomplete ultrafilter, $L^1(\Omega,M)^{\cU}$ is not isomorphic to $L^1(\Lambda,N)$ for any diffuse measure space $\Lambda$ and any structure $N$. 
	\end{conjecture}	

	\appendix

		\section{Ioana's proof of Theorem~\ref{T.UltrapowerTensoriallyIndecomposable}} \label{S.def/rg}

	Proposition~\ref{P.def/rg} subsumes Proposition~\ref{P.CHaar} and Proposition~\ref{L.qf-saturated}. Its proof, due to Adrian Ioana,  uses only standard methods of Popa's deformation/rigidity theory. Together with the first paragraph of the proof of Theorem~\ref{T.CountablySaturated} it gives a proof of Theorem~\ref{T.UltrapowerTensoriallyIndecomposable}.   	

		\begin{proposition}\label{P.def/rg}
Suppose that $(P,\tau_P)$ and $(Q, \tau_Q)$ are diffuse tracial von Neumann algebras, and assume that $P$ is not of type I. Then the tensor product von Neumann algebra $M=P\bar\otimes Q $ is not countably quantifier-free saturated. 		
\end{proposition}

\begin{proof}	
		Assume otherwise. By Lemma~\ref{L.CHaar.0} choose a uniformly Haar unitary  $w_0 \in P$  and a Haar unitary  $w_1\in Q$. We claim that both $u_0\coloneqq w_0\otimes 1_Q$  and $u_1\coloneqq w_0 \otimes w_1$ are uniformly Haar unitaries in $M$. For $u_0$, this is shown in the proof of Proposition~\ref{P.CHaar}. For $u_1$, this follows by observing that, since $E_{Z(P)}(w_0^k)=0$, we have    $E_{Z(M)}(u_1^k)=E_{Z(P)}(w_0^k)\otimes E_{Z(Q)}(w_1^k)=0$ for all $k\geq 1$. 

		By countable quantifier-free saturation, Lemma~\ref{L.CHaar}, implies that $u_0$ and $u_1$ are unitarily equivalent. Fix a unitary $v\in M$ such that $vu_1 v^*=u_0$. Then $v(w_0\otimes w_1)v^*=w_0\otimes 1_Q$, hence $v(w_0^k\otimes w_1^k)v^*=w_0^k\otimes 1_Q$ for every $k\geq 1$. This implies that $\|E_{P\otimes 1_Q}(v(w_0^k\otimes w_1^k)v^*)\|_{2, \tau_P}=1$ for every $k\geq 1$, where $E_{P \otimes 1_Q} \colon M \to P$ is the unique conditional expectation mapping $a \otimes b$ to $\tau_Q( b) a$.

		\begin{claim} \label{claim} For all $ a,b \in M$ we have  $\lim_{k\to \infty}\|E_{P\otimes 1}(a(w_0^k\otimes w_1^k)b)\|_{2,\tau_P}=0$.
	\end{claim}
	\begin{proof}
		It suffices to prove this for a $\|\cdot\|_{2, \tau_P \otimes \tau_Q}$-dense set of pairs $a,b$ of elements in $M$, and by linearity it suffices to prove the claim for elementary tensors.  
We may therefore assume that $a=a_0\otimes a_1$ and $b=b_0\otimes b_1$ for some $a_0, b_0 \in P$ and $a_1, b_1 \in Q$. Then, for every $k \in \bbN$, we have $a(w_0^k\otimes w_1^k)b=(a_0w_0^kb_0)\otimes (a_1w_1^kb_1)$, hence 
		\[
		E_{P\otimes 1}(a(w_0^k\otimes w_1^k)b)=\tau_Q(a_1w_1^kb_1) a_0w_0^nb_0.
		\] 
		Since~$w_1$ is a Haar unitary, by a standard and easily checked fact $w_1^k$ converges to $0$ weakly, therefore $\lim_{k\to \infty}\tau_Q(a_1w_1^kb_1)=\langle w_1^k,b_1 a_1^\ast\rangle_{\tau_Q}=0$. Together with the previous calculation this implies 
		\[
		\lim_{n\to \infty}\|E_{P\otimes 1}(a(w_0^k\otimes w_1^k)b)\|_{2,\tau_P}=0.
		\]
		\end{proof}

		 The instance of the claim when $a=v$ and $b=v^*$ gives contradiction and completes the proof.  
		 \end{proof} 

		 As Adrian Ioana also pointed out, Claim \ref{claim} has another interesting consequence stated in terms of Popa's deformation and rigidity theory (see e.g., \cite[\S 2]{popa2006strong}).  
		 Using the terminology and notation from the proof of Proposition~\ref{P.def/rg},  Claim \ref{claim} shows that $\wst(w_0\otimes w_1)$ does not intertwine into $P\otimes 1_Q$, and therefore not into $\wst(w_0\otimes 1_Q)$, inside $M$. 



