\section{RELATIONS BETWEEN PARAMETERS IN MDI3Y AND M3Y-P$n$ INTERACTIONS}
\label{sec:Nakada}
The central part of the two-body interaction in M3Y-P$n$~\cite{Nakada:2003fw,Nakada:2008eh,Nakada:2009xh,Nakada:2012sq} is written as
\begin{equation}
\begin{aligned}
\label{eq:Nakada_C}
V_{\mathrm{M3Y}}^{C}(\vec{r}_1,\vec{r}_2) =& \sum_{i=1}^{3}  \bigg[   t_{i}^{(\mathrm{SE})}P_{\mathrm{SE}} + t_{i}^{(\mathrm{TE})}P_{\mathrm{TE}} \\ &+ t_{i}^{(\mathrm{SO})}P_{\mathrm{SO}} + t_{i}^{(\mathrm{TO})}P_{\mathrm{TO}}\bigg]
\frac{e^{-\mu_{i}\left|\vec{r}_1-\vec{r}_2\right|}}{\mu_{i}\left|\vec{r}_1-\vec{r}_2\right|},
\end{aligned}
\end{equation}
where the projection operators on the singlet-even (SE), triplet-even (TE), singlet-odd (SO), and triplet-odd (TO) states are
\begin{equation}
\label{eq:STproj}
\begin{aligned}
P_{\mathrm{SE}}&=\frac{1-P_\sigma}{2}\frac{1+P_\tau}{2},~~
P_{\mathrm{TE}}=\frac{1+P_\sigma}{2}\frac{1-P_\tau}{2},  \\
P_{\mathrm{SO}}&=\frac{1-P_\sigma}{2}\frac{1-P_\tau}{2},~~
P_{\mathrm{TO}}=\frac{1+P_\sigma}{2}\frac{1+P_\tau}{2}. \\
\end{aligned}
\end{equation}
By substituting Eq.~(\ref{eq:STproj}) into Eq.~(\ref{eq:Nakada_C}) and comparing with Eq.~(\ref{eq:v3Y}), we can obtain the relations between the parameters as~\cite{Nakada:2003fw}
\begin{equation}
\label{eq:C_rlts}
\begin{aligned}
t_{i}^{(\mathrm{SE})} =& W_i -B_i -H_i +M_i , \\
t_{i}^{(\mathrm{TE})} =& W_i +B_i +H_i +M_i ,\\
t_{i}^{(\mathrm{SO})} =& W_i -B_i +H_i -M_i ,\\
t_{i}^{(\mathrm{TO})} =& W_i +B_i -H_i -M_i .
\end{aligned}
\end{equation}
The first version of M3Y-P$n$ interactions~\cite{Nakada:2003fw} introduced the DD term as Eq.~(\ref{eq:V_DD}) with $n=1$.
In the subsequent versions of M3Y-P$n$~\cite{Nakada:2008eh,Nakada:2009xh,Nakada:2012sq}, the DD term was replaced by
\begin{equation}
\label{eq:Nakada_DD}
\begin{aligned}
V_{\mathrm{M3Y}}^{\mathrm{DD}}=& \Big(t_{\rho}^{(\mathrm{SE})} P_{\mathrm{SE}}[\rho(\vec{R})]^{\alpha^{(\mathrm{SE})}}  \\
& +  t_{\rho}^{(\mathrm{TE})} P_{\mathrm{TE}}[\rho(\vec{R})]^{\alpha^{(\mathrm{TE})}} \Big)
\delta(\vec{r}_{1}-\vec{r}_{2}),
\end{aligned}
\end{equation}
with $\alpha^{(\mathrm{TE})}=1/3$ and $\alpha^{(\mathrm{SE})}=1$.
The Eq.~(\ref{eq:V_DD}) can be rewritten as
\begin{equation}
\label{eq:V_DD_ST}
\begin{aligned}
V^{\mathrm{DD}}=&\sum_{n=1,3,5} \frac{1}{6}t_{3}^{[n]} \Big[
(1-x_{3}^{[n]})(P_{\mathrm{SE}}+P_{\mathrm{SO}}) \\
&+ (1+x_{3}^{[n]})(P_{\mathrm{TE}}+P_{\mathrm{TO}}) \Big] \rho^{n/3}(\vec{R}) \delta(\vec{r}_{1}-\vec{r}_{2}).
\end{aligned}
\end{equation}
Considering that $V^{\mathrm{DD}}$ has no contributions to the SO and TO channels when calculating Eq.~(\ref{eq:E_pot}), Eq.~(\ref{eq:V_DD_ST}) will reduce to Eq.~(\ref{eq:Nakada_DD}) when taking $x_{3}^{[1]}=1$, $x_{3}^{[3]}=-1$, and $t_{3}^{[5]}=0$.
We then obtain $t_{\rho}^{(\mathrm{TE})} = \frac{1}{3} t_{3}^{[1]}$ and $t_{\rho}^{(\mathrm{SE})} = \frac{1}{3} t_{3}^{[3]}$.

\section{HARTREE-FOCK CALCULATIONS WITH FINITE-RANGE INTERACTION}
\label{sec:HF_DME}
\subsection{HAMILTONIAN DENSITY}
\label{sec:Vc_HF}
The contribution from the finite-range interaction $V^C$ in Eq.~(\ref{eq:E_pot}) can be obtained as
\begin{equation}
\label{eq:E_pot_Vc}
E_r =  E_{r}^{D} + E_{r}^{E},
\end{equation}
where
\begin{equation}
\small
\label{eq:E_pot_Vc_D}
\begin{aligned}
E_{r}^{D} = & \frac{1}{2} \sum_{i,j} \langle i j| V^{C} |ij\rangle \\
=& \frac{1}{2} \sum_{i=1}^{3} \int \! \! \! \! \int \mathrm{d}^3 r_1 \mathrm{d}^3 r_2
\frac{e^{-\mu_i |\vec{r}_1 - \vec{r}_2|}}{\mu_i |\vec{r}_1 - \vec{r}_2|}\bigg\{ (W_i + \frac{B_i}{2}-H_i-\frac{M_i}{2}) \\
&\times  \Big[ \rho_{n}(\vec{r}_1) \rho_{n}(\vec{r}_2) + \rho_{p}(\vec{r}_1) \rho_{p}(\vec{r}_2)\Big] \\
&+ 2 (W_i+\frac{B_i}{2}) \rho_{n}(\vec{r}_1) \rho_{p}(\vec{r}_2)
\bigg\},
\end{aligned}
\end{equation}
and
\begin{equation}
\small
\label{eq:E_pot_Vc_E}
\begin{aligned}
E_{r}^{E} = & \frac{1}{2} \sum_{i,j} \langle i j| V^{C} (-P_M P_\sigma P_\tau) |ij\rangle \\
=& \frac{1}{2} \sum_{i=1}^{3} \int \! \! \! \! \int \mathrm{d}^3 r_1 \mathrm{d}^3 r_2
\frac{e^{-\mu_i |\vec{r}_1 - \vec{r}_2|}}{\mu_i |\vec{r}_1 - \vec{r}_2|}\bigg\{ (M_i + \frac{H_i}{2}-B_i-\frac{W_i}{2}) \\
&\times  \Big[ \rho_{n}(\vec{r}_1,\vec{r}_2) \rho_{n}(\vec{r}_2,\vec{r}_1) + \rho_{p}(\vec{r}_1,\vec{r}_2)
\rho_{p}(\vec{r}_2,\vec{r}_1)\Big] \\
&+ 2 (M_i+\frac{H_i}{2}) \rho_{n}(\vec{r}_1,\vec{r}_2)
\rho_{p}(\vec{r}_2,\vec{r}_1)
\bigg\},
\end{aligned}
\end{equation}
represent the direct and exchange contributions, respectively.
In the derivations of Eqs.~(\ref{eq:E_pot_Vc_D}) and (\ref{eq:E_pot_Vc_E}), $P_\tau$ is replaced by $\delta_{\tau_1 \tau_2}$ since there is no isospin mixing state, and the effect of $P_\sigma$ is simply replaced by a factor of $\frac{1}{2}$ for the spin-averaged quantities.
The matrix element of the density operator $\hat \rho_{\tau} = \sum_i | i \tau\rangle \langle i \tau|$ is expressed as $\rho_{\tau}(\vec{r}_1,\vec{r}_2)= \langle \vec{r}_1 | \hat \rho_{\tau} | \vec{r}_2 \rangle $, which reduces to the local density when $\vec{r}_1 = \vec{r}_2$.

To obtain the energy density functional from finite-range interaction, we introduce the coordinate transformation:
\begin{equation}
\label{eq:coord_trans}
\vec{r}=(\vec{r}_{1}+\vec{r}_{2})/2, ~~
\vec{s}=\vec{r}_{1}-\vec{r}_{2}.
\end{equation}
The direct contribution can be expressed as
\begin{equation}
E_{r}^{D} = \int \mathrm{d}^3 r \mathcal{H}_{r}^{D}(\vec{r}),
\end{equation}
where
\begin{equation}
\label{eq:Hdr_general}
\begin{aligned}
\mathcal{H}_{r}^{D}(\vec{r})
=& \frac{1}{2} \sum_{i=1}^{3} \int \mathrm{d}^3 s
\frac{e^{-\mu_i s}}{\mu_i s}\bigg\{ (W_i + \frac{B_i}{2}-H_i-\frac{M_i}{2}) \\
&\times  \Big[ \rho_{n}(\vec{r}+ \frac{\vec{s}}{2}) \rho_{n}(\vec{r}- \frac{\vec{s}}{2}) + \rho_{p}(\vec{r}+ \frac{\vec{s}}{2}) \rho_{p}(\vec{r}- \frac{\vec{s}}{2})\Big] \\
&+ 2 (W_i+\frac{B_i}{2}) \rho_{n}(\vec{r}+ \frac{\vec{s}}{2}) \rho_{p}(\vec{r}- \frac{\vec{s}}{2})
\bigg\}.
\end{aligned}
\end{equation}
With the integral $\int \mathrm{d}^3 s e^{-\mu s}/s = 4 \pi/\mu^2 $, direct contribution reduces to the Skyrme type for uniform nuclear matter:
\begin{equation}
\label{eq:Hdr_general_NM}
\begin{aligned}
\mathcal{H}_{r}^{D}(\vec{r}) =& \bigg[ \sum_{i=1}^{3} \frac{4\pi}{\mu_{i}^{3}} (W_i + \frac{B_i}{2} - H_i-\frac{M_i}{2})\bigg]
\frac{\rho_{n}^{2}+\rho_{p}^{2}}{2} \\
&+ \bigg[ \sum_{i=1}^{3} \frac{4\pi}{\mu_{i}^{3}} (W_i + \frac{B_i}{2}) \bigg] \rho_n \rho_p,
\end{aligned}
\end{equation}
which is denoted as $\mathcal{H}^{\mathrm{loc}}(\vec{r})$ [Eq.~(\ref{eq:H_loc})] in the main text.

Expressing the density matrix in terms of the Wigner function through the Fourier transform:
\begin{equation}
\begin{aligned}
&f_{\tau}(\vec{r},\vec{p}) = \frac{1}{(2\pi\hbar)^3} \int
\rho_{\tau}(\vec{r}+ \frac{\vec{s}}{2},\vec{r}- \frac{\vec{s}}{2})
e^{- \mathrm{i} \vec{p} \cdot \vec{s}/\hbar} \mathrm{d}^3 s, \\
&\rho_{\tau}(\vec{r}+ \frac{\vec{s}}{2},\vec{r}- \frac{\vec{s}}{2}) = \int f_{\tau}(\vec{r},\vec{p}) e^{\mathrm{i}  \vec{p} \cdot \vec{s}/\hbar}  \mathrm{d}^3 p,
\end{aligned}
\end{equation}
the integrals in the exchange contribution can be rewritten as
\begin{equation}
\begin{aligned}
& \int \mathrm{d}^3r \mathrm{d}^3s \frac{e^{-\mu s}}{\mu s}
\rho_{\tau}(\vec{r}+ \frac{\vec{s}}{2},\vec{r}- \frac{\vec{s}}{2})
\rho_{\tau^\prime}(\vec{r}- \frac{\vec{s}}{2},\vec{r}+ \frac{\vec{s}}{2}) \\
=& \int \mathrm{d}^3r  \mathrm{d}^3 p \mathrm{d}^3 p^{\prime} \mathrm{d}^3s\frac{e^{-\mu s}}{\mu s}
f_{\tau}(\vec{r},\vec{p}) e^{\mathrm{i}  \vec{p} \cdot \vec{s}/\hbar}
f_{\tau^\prime}(\vec{r},\vec{p}^{\, \prime}) e^{-\mathrm{i} \vec{p}^{\, \prime} \cdot \vec{s}/\hbar} \\
=& \int \mathrm{d}^3r \mathrm{d}^3 p \mathrm{d}^3 p^{\prime}
\frac{4 \pi}{\mu^3} \frac{f_{\tau}(\vec{r},\vec{p}) f_{\tau^\prime}(\vec{r},\vec{p}^{\, \prime}) }{1+\left(\vec{p}-\vec{p}^{\, \prime}\right)^2 / (\hbar \mu)^2},
\end{aligned}
\end{equation}
where we have used the integral
\begin{equation}
\int \mathrm{d}^3 s e^{\mathrm{i} (\vec{p}-\vec{p}^{\, \prime})\cdot \vec{s}/\hbar} \frac{e^{-\mu s}}{\mu s} = \frac{4 \pi}{\mu^3}
\frac{1}{1+\left(\vec{p}-\vec{p}^{\, \prime}\right)^2 / (\hbar \mu)^2}.
\end{equation}
The exchange contribution can then be expressed as
\begin{equation}
E_{r}^{E} = \int \mathrm{d}^3 r \mathcal{H}_{r}^{E}(\vec{r}),
\end{equation}
where
\begin{equation}
\label{eq:Her_f}
\begin{aligned}
\mathcal{H}_{r}^{E}(\vec{r}) =& \frac{1}{2} \sum_{i=1}^{3} \frac{4 \pi}{\mu_{i}^{3}} \int \! \! \! \! \int \frac{\mathrm{d}^3 p \mathrm{~d}^3 p^{\prime}}{1+\left(\vec{p}-\vec{p}^{\, \prime}\right)^2 / (\hbar \mu_i)^2} \\
&\times \bigg\{(M_i + \frac{H_i}{2} -B_i -\frac{W_i}{2}) \\
& \times \Big[ f_n(\vec{r}, \vec{p}) f_n\left(\vec{r}, \vec{p}^{\, \prime}\right) + f_p(\vec{r}, \vec{p}) f_p\left(\vec{r}, \vec{p}^{\, \prime}\right)  \Big] \\
&+2(M_i + \frac{H_i}{2}) f_n(\vec{r}, \vec{p}) f_p\left(\vec{r}, \vec{p}^{\, \prime}\right) \bigg\},
\end{aligned}
\end{equation}
which is denoted as $\mathcal{H}^{\mathrm{MD}}(\vec{r})$ [Eq.~(\ref{eq:H_MD})] in the main text.

\subsection{DENSITY MATRIX EXPANSION}
\label{sec:DME}
Based on the density matrix expansion~\cite{Negele:1972zp} and by analogy with the results for the MDI model~\cite{Xu:2010ce}, the exchange energy density $\mathcal{H}_{r}^{E}(\vec{r})$ from finite-range interaction can be approximated by the Skyrme-like zero-range energy density $\mathcal{H}_{\mathrm{SL}}^{E}(\vec{r})$, which is expressed in terms of densities $\rho_{\tau}(\vec{r})$ as well as kinetic energy densities $\uptau_{\tau}(\vec{{r}})=\sum_{i}|\bm{\nabla} \langle \vec{r} | i \tau\rangle|^{2}$:
\begin{equation}
\label{eq:H_SL}
\begin{aligned}
\mathcal{H}_{\mathrm{SL}}^{E}(\vec{r}) = &
A[\rho_{n}(\vec{r}),\rho_{p}(\vec{r})] \\
&+B[\rho_{n}(\vec{r}),\rho_{p}(\vec{r})]\uptau_{n}(\vec{{r}})
+B[\rho_{p}(\vec{r}),\rho_{n}(\vec{r})]\uptau_{p}(\vec{{r}}) \\
&+C[\rho_{n}(\vec{r}),\rho_{p}(\vec{r})] |\bm{\nabla} \rho_{n}(\vec{r})|^{2} \\
&+C[\rho_{p}(\vec{r}),\rho_{n}(\vec{r})] |\bm{\nabla} \rho_{p}(\vec{r})|^{2} \\
&+D[\rho_{p}(\vec{r}),\rho_{n}(\vec{r})] \bm{\nabla} \rho_{n}(\vec{r}) \cdot \bm{\nabla} \rho_{p}(\vec{r}),
\end{aligned}
\end{equation}
where
\begin{align}
A(\rho_{n},\rho_{p}) =& V_{\mathrm{NM}}(\rho_n,\rho_p) - \frac{3}{5} (3\pi^2)^{2/3} [\rho_{n}^{5/3} B(\rho_n,\rho_p) \nonumber \\
& + \rho_{p}^{5/3} B(\rho_p,\rho_n)], \\
B(\rho_{n},\rho_{p}) =& -2[\rho_n V^{L}(\rho_n)+\rho_{p}V^{U}(\rho_p,\rho_n)], \\
C(\rho_{n},\rho_{p}) =& -\frac{\partial F(\rho_{n},\rho_{p})}{\partial \rho_n}, \\
D(\rho_{n},\rho_{p}) =& -\frac{\partial F(\rho_{n},\rho_{p})}{\partial \rho_p} - \frac{\partial F(\rho_{p},\rho_{n})}{\partial \rho_n}.
\end{align}
We have defined that
\begin{equation}
\begin{aligned}
V_{\mathrm{NM}}(\rho_n,\rho_p) =& \rho_{n}^{2} V_{\mathrm{NM}}^{L}(\rho_n) + \rho_{p}^{2} V_{\mathrm{NM}}^{L}(\rho_p) \\
&+ 2 \rho_n \rho_p V_{\mathrm{NM}}^{U}(\rho_n,\rho_p),
\end{aligned}
\end{equation}
with
\begin{equation}
\begin{aligned}
V_{\mathrm{NM}}^{L}(\rho_\tau) =& \frac{1}{2} \sum_{i=1}^{3} (M_i+\frac{H_i}{2}-B_i-\frac{W_i}{2} ) \\
&\times \int \mathrm{d}^3 s \rho_{\mathrm{SL}}^{2}(k_{\tau} s) \frac{e^{- \mu_i s}}{\mu_i s},
\end{aligned}
\end{equation}
\begin{equation}
\begin{aligned}
V_{\mathrm{NM}}^{U}(\rho_\tau,\rho_{\tau^{\prime}}) =& \frac{1}{2} \sum_{i=1}^{3} (M_i+\frac{H_i}{2} ) \\
&\times \int \mathrm{d}^3 s \rho_{\mathrm{SL}}(k_{\tau} s) \rho_{\mathrm{SL}}(k_{\tau^{\prime}} s) \frac{e^{- \mu_i s}}{\mu_i s}.
\end{aligned}
\end{equation}
Other terms are defined as
\begin{equation}
F(\rho_\tau,\rho_{\tau^{\prime}}) =
\frac{1}{2} V^L(\rho_\tau) \rho_\tau  + \frac{1}{2} V^U(\rho_\tau,\rho_{\tau^{\prime}}) \rho_{\tau^{\prime}},
\end{equation}
\begin{equation}
\begin{aligned}
V^L(\rho_\tau) = & \frac{1}{2} \sum_{i=1}^{3} (M_i+\frac{H_i}{2}-B_i-\frac{W_i}{2} ) \\
& \times \int \mathrm{d}^3 s s^2 \rho_{\mathrm{SL}}(k_{\tau} s) g(k_{\tau} s) \frac{e^{- \mu_i s}}{\mu_i s},
\end{aligned}
\end{equation}
\begin{equation}
\begin{aligned}
V^U(\rho_\tau,\rho_{\tau^\prime}) =& \frac{1}{2} \sum_{i=1}^{3} (M_i + \frac{H_i}{2}) \\
& \times \int \mathrm{d}^3 s s^2 \rho_{\mathrm{SL}}(k_{\tau} s) g(k_{\tau^\prime} s) \frac{e^{- \mu_i s}}{\mu_i s},
\end{aligned}
\end{equation}
where
\begin{align}
\rho_{\mathrm{SL}}(k_{\tau} s) =& \frac{3}{k_{\tau} s} j_1 (k_{\tau} s),\\
g(k_{\tau} s) =& \frac{35}{2(k_{\tau} s)^3} j_3 (k_{\tau} s),
\end{align}
with $j_1$ and $j_3$ being, respectively, the first- and third-order spherical Bessel functions and $k_\tau=(3\pi^2 \rho_\tau)^{1/3}$ being the Fermi wave number.
It is seen that $A(\rho_n,\rho_p)$ and $D(\rho_n,\rho_p)$ are symmetric in $\rho_n$ and $\rho_p$, while $B(\rho_n,\rho_p)$ and $C(\rho_n,\rho_p)$ are not.

\begin{widetext}
The single nucleon potential from finite-range interaction can be expressed as
\begin{equation}
U_{r,\tau}(\rho_n,\rho_p) = U_{r,\tau}^{D}(\rho_n,\rho_p) + U_{r,\tau}^{E}(\rho_n,\rho_p),
\end{equation}
with the direct contribution being
\begin{equation}
\begin{aligned}
U_{r,\tau}^{D}(\rho_n,\rho_p) = \frac{\partial \mathcal{H}_{r}^{D}(\rho_n,\rho_p)}{\partial \rho_\tau}
=\sum_{i=1}^{3}
\int \mathrm{d}^3 r^\prime \frac{e^{- \mu_i |\vec{r}-\vec{r}^{\, \prime}|}}{\mu_i |\vec{r}-\vec{r}^{\, \prime}|} \bigg[
(W_i +\frac{B_i}{2}-H_i-\frac{M_i}{2}) \rho_{\tau}(\vec{r}^{\, \prime})
+ (W_i +\frac{B_i}{2}) \rho_{-\tau}(\vec{r}^{\, \prime})
\bigg] ,
\end{aligned}
\end{equation}
which reduces to $(A_l \rho_\tau + A_u \rho_{-\tau})/\rho_0 $ in the uniform nuclear matter, as given in Eq.~(\ref{eq:Utau}).
Since $\mathcal{H}_{\mathrm{SL}}^{E}(\vec{r})$ includes terms with density gradients, the exchange contribution can be calculated as~\cite{Kolomietz:2017qkb}
\begin{equation}
\begin{aligned}
U_{r,\tau}^{E}(\rho_n,\rho_p) =& \frac{\partial \mathcal{H}_{\mathrm{SL}}^{E}(\rho_n,\rho_p)}{\partial \rho_\tau} - \bm{\nabla} \cdot \frac{\partial \mathcal{H}_{\mathrm{SL}}^{E}(\rho_n,\rho_p)}{\partial ( \bm{\nabla} \rho_\tau)} \\
=& \frac{\partial A(\rho_n,\rho_p)}{\partial \rho_\tau}
+ \frac{\partial B(\rho_n,\rho_p)}{\partial \rho_\tau} \uptau_n
+ \frac{\partial B(\rho_p,\rho_n)}{\partial \rho_\tau} \uptau_p \\
&+ \frac{\partial C(\rho_n,\rho_p)}{\partial \rho_\tau} (\bm{\nabla} \rho_n)^2
+ \frac{\partial C(\rho_p,\rho_n)}{\partial \rho_\tau} (\bm{\nabla} \rho_p)^2
+ \frac{\partial D(\rho_n,\rho_p)}{\partial \rho_\tau}  \bm{\nabla} \rho_n \cdot \bm{\nabla} \rho_p \\
&-2 \delta_{\tau,n} \bigg[ \frac{\partial C(\rho_n,\rho_p)}{ \partial \rho_n} (\bm{\nabla} \rho_n)^2
+ \frac{\partial C(\rho_n,\rho_p)}{ \partial \rho_p} \bm{\nabla} \rho_n \cdot \bm{\nabla} \rho_p
+ C(\rho_n,\rho_p) \nabla^2 \rho_n
\bigg] \\
&-2 \delta_{\tau,p} \bigg[ \frac{\partial C(\rho_p,\rho_n)}{ \partial \rho_p}  (\bm{\nabla} \rho_p)^2
+ \frac{\partial C(\rho_p,\rho_n)}{ \partial \rho_n} \bm{\nabla} \rho_n \cdot \bm{\nabla} \rho_p
+ C(\rho_p,\rho_n) \nabla^2 \rho_p
\bigg] \\
&- \bigg[ \frac{\partial D(\rho_n,\rho_p)}{ \partial \rho_n} \bm{\nabla} \rho_n \cdot \bm{\nabla} \rho_{-\tau}
+ \frac{\partial D(\rho_n,\rho_p)}{ \partial \rho_p} \bm{\nabla} \rho_p \cdot \bm{\nabla} \rho_{-\tau}
+ D(\rho_n,\rho_p) \nabla^2 \rho_{-\tau}
\bigg].
\end{aligned}
\end{equation}
With the extended Thomas-Fermi approximation~\cite{Brack:1985vp,Jen76}:
\begin{equation}
\uptau_\tau = a \rho_{\tau}^{5/3} + b\frac{(\bm{\nabla} \rho_\tau)^2}{\rho_\tau} + c \nabla^2 \rho_\tau,
\end{equation}
where $a=\frac{3}{5}(3\pi^2)^{2/3}$, $b=1/36$, and $c=1/3$, the single-nucleon potential from finite-range interaction can then be written as
\begin{equation}
U_{r,\tau}(\rho_n,\rho_p) = U_{r,\tau}^{D}(\rho_n,\rho_p) + U_{r,\tau}^{0}(\rho_n,\rho_p) + U_{r,\tau}^{\nabla}(\rho_n,\rho_p),
\end{equation}
where
\begin{equation}
U_{r,\tau}^{0}(\rho_n,\rho_p) =
\frac{\partial A(\rho_n,\rho_p)}{\partial \rho_\tau}
+ a \frac{\partial B(\rho_n,\rho_p)}{\partial \rho_\tau} \rho_{n}^{5/3}
+ a \frac{\partial B(\rho_p,\rho_n)}{\partial \rho_\tau} \rho_{p}^{5/3},
\end{equation}
\begin{equation}
\begin{aligned}
U_{r,\tau}^{\nabla}(\rho_n,\rho_p) =
G_{\tau}^{nn1} (\bm{\nabla}\rho_n)^2
+ G_{\tau}^{pp1} (\bm{\nabla}\rho_p)^2
+ G_{\tau}^{np} \bm{\nabla}\rho_n \cdot \bm{\nabla}\rho_p
+ G_{\tau}^{nn2} \nabla^2 \rho_n + G_{\tau}^{pp2} \nabla^2 \rho_p,
\end{aligned}
\end{equation}
with
\begin{equation}
G_{\tau}^{nn1} = \frac{b}{\rho_n} \frac{\partial B(\rho_n,\rho_p)}{\partial \rho_\tau}
+ (1-2\delta_{\tau,n}) \frac{\partial C(\rho_n,\rho_p)}{\partial \rho_\tau}
- \delta_{\tau,p} \frac{\partial D(\rho_n,\rho_p)}{\partial \rho_n},
\end{equation}
\begin{equation}
G_{\tau}^{pp1} = \frac{b}{\rho_p} \frac{\partial B(\rho_p,\rho_n)}{\partial \rho_\tau}
+ (1-2\delta_{\tau,p}) \frac{\partial C(\rho_p,\rho_n)}{\partial \rho_\tau}
- \delta_{\tau,n} \frac{\partial D(\rho_n,\rho_p)}{\partial \rho_p},
\end{equation}
\begin{equation}
G_{\tau}^{np} = -2 \frac{\partial C(\rho_\tau,\rho_{-\tau})}{\partial \rho_{-\tau}},
\end{equation}
\begin{equation}
G_{\tau}^{nn2} = c \frac{\partial B(\rho_n,\rho_p)}{\partial \rho_\tau}
- 2\delta_{\tau,n} C(\rho_n,\rho_p)
- \delta_{\tau,p} D(\rho_n,\rho_p),
\end{equation}
\begin{equation}
G_{\tau}^{pp2} = c \frac{\partial B(\rho_p,\rho_n)}{\partial \rho_\tau}
- 2\delta_{\tau,p} C(\rho_p,\rho_n)
- \delta_{\tau,n} D(\rho_n,\rho_p).
\end{equation}


