The fourth-order symmetry energy can be expressed as
\begin{equation}
\label{eq:Esym4}
\begin{aligned}
E_{\mathrm{sym},4}(\rho) \equiv \left. \frac{1}{4!} \frac{\partial^{4} E(\rho,\delta)}{\partial \delta^{4}} \right|_{\delta=0}
=& \frac{a^{2} \hbar ^2}{162m} \rho^{2/3} + \sum_{i=1}^{3} \frac{p_{F}}{108 p_{F_0}^{3}} \Bigg[ C_{u,i}  \left( 2p_{F}^{2} + 7\Lambda_{i}^{2} \right) +C_{l,i} \Lambda_{i}^{2}  \frac{40p_{F}^{4} + 42p_{F}^{2} \Lambda_{i}^{2} +7\Lambda_{i}^4 }{\left( 4p_{F}^{2} + \Lambda_{i}^{2} \right)^{2}} \\
&-\frac{\Lambda_{i}^{2}}{4p_{F}^2} \left(16 C_{u,i} p_{F}^{2} +7C_{l,i} \Lambda_{i}^{2} + 7C_{u,i} \Lambda_{i}^{2} \right)  \ln \frac{4 p_{F}^{2} + \Lambda_{i}^{2}}{\Lambda_{i}^{2}} \Bigg].
\end{aligned}
\end{equation}

In the MDI3Y model, the nucleon effective mass can be generally expressed as
\begin{equation}
\label{eq:mtau_exp}
\begin{aligned}
\left[\frac{m_{\tau}(\rho,\delta,p)}{m}\right]^{-1} \equiv & 1 + \frac{m}{p} \frac{\mathrm{d}U_{\tau}(\rho,\delta,p)}{\mathrm{d}p} \\
=& 1 + \frac{m}{4 \pi^2 \hbar^3 \rho_0} \sum_{i=1}^{3} C_{l,i} \frac{\Lambda_{i}^{2}}{ p^3} \left[ 4 p \, p_{F,\tau} - (p^2 + p_{F,\tau}^{2} + \Lambda_{i}^{2}) \ln \frac{(p+p_{F,\tau})^2 +\Lambda_{i}^{2}}{(p-p_{F,\tau})^2 +\Lambda_{i}^{2}} \right] \\
&+ \frac{m}{4 \pi^2 \hbar^3 \rho_0} \sum_{i=1}^{3} C_{u,i} \frac{\Lambda_{i}^{2}}{ p^3} \left[ 4 p \, p_{F,-\tau} - (p^2 + p_{F,-\tau}^{2} + \Lambda_{i}^{2}) \ln \frac{(p+p_{F,-\tau})^2 +\Lambda_{i}^{2}}{(p-p_{F,-\tau})^2 +\Lambda_{i}^{2}} \right].
\end{aligned}
\end{equation}
The isoscalar nucleon effective mass $m_{s}^{\ast}$ is the nucleon effective mass in SNM, i.e.,
\begin{equation}
\label{eq:ms_exp}
\begin{aligned}
\left( \frac{m_{s}^{\ast}}{m} \right)^{-1} \equiv &  1 + \frac{m}{p} \frac{ \mathrm{d}U_{0}(\rho,p)}{\mathrm{d}p} \bigg|_{p=p_{F,\tau}=p_F} \\
=& 1 + \frac{m}{4 \pi^{2} \hbar^{3} \rho_{0}} \sum_{i=1}^{3} \left( C_{l,i}+C_{u,i} \right)  \frac{\Lambda_{i}^{2}}{p_{F}^3}   \left[4 p_{F}^2 - (2 p_{F}^2 + \Lambda_{i}^{2} ) \ln \frac{4 p_{F}^2 +\Lambda_{i}^{2}}{\Lambda_{i}^{2}} \right],
\end{aligned}
\end{equation}
while the isovector nucleon effective mass $m_{v}^{\ast}$ equals to the effective mass of proton (neutron) in pure neutron (proton) matter, i.e.,
\begin{equation}
\label{eq:mv}
\begin{aligned}
\left(\frac{m^{\ast}_{v}}{m}\right)^{-1} \equiv 1 + \frac{m}{p} \frac{\mathrm{d} U_{\tau}(\rho,\delta=-\tau,p)}{\mathrm{d}p} \bigg|_{p=p_{F,\tau}=0}
= 1- \frac{8 m}{3\pi^2 \hbar^3 \rho_0} \sum_{i=1}^{3} C_{u,i} \frac{p_{F}^{3} \Lambda_{i}^{2}}{(2^{2/3} p_{F}^{2} +\Lambda_{i}^{2} )^{2}}.
\end{aligned}
\end{equation}
The linear isospin splitting coefficient $\Delta m^{\ast}_{1}(\rho)$ can be expressed as
\begin{equation}
\label{eq:Dm1}
\begin{aligned}
\Delta m^{\ast}_{1}(\rho) \equiv \left. \frac{\partial \msplast(\rho,\delta)}{\partial \delta} \right|_{\delta=0} = \frac{8}{3} p_{F}^{5} \frac{ \mathcal{A}(\rho) }{ \left[ \mathcal{B}(\rho) \right]^2 },
\end{aligned}
\end{equation}
where
\begin{equation}
\label{eq:Arho}
\begin{aligned}
\mathcal{A}(\rho) = \sum_{i=1}^{3} \Lambda_{i}^{2} \left\{ \left( 2\Tilde{C}_{l,i} +3\Tilde{C}_{u,i} \right) + \Tilde{C}_{l,i} \frac{\Lambda_{i}^{2}}{4p_{F}^{2}+\Lambda_{i}^{2}}
-\left[ \frac{1}{2} \left( \Tilde{C}_{l,i} +3\Tilde{C}_{u,i} \right) + \frac{3}{4} \left( \Tilde{C}_{l,i} +\Tilde{C}_{u,i} \right) \frac{\Lambda_{i}^{2}}{p_{F}^{2}} \right] \ln \frac{4 p_{F}^{2} + \Lambda_{i}^{2}}{\Lambda_{i}^{2}} \right\},
\end{aligned}
\end{equation}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
and
\begin{equation}
\label{eq:Brho}
\begin{aligned}
\mathcal{B}(\rho) = p_{F}^{3} + \sum_{i=1}^{3} \Lambda_{i}^{2} \left[ 4(\Tilde{C}_{l,i}+\Tilde{C}_{u,i}) p_{F}^{2} -(\Tilde{C}_{l,i}+\Tilde{C}_{u,i}) \left( 2p_{F}^{2} + \Lambda_{i}^{2} \right) \ln \frac{4 p_{F}^{2} + \Lambda_{i}^{2}}{\Lambda_{i}^{2}} \right],
\end{aligned}
\end{equation}
with $\Tilde{C}_{l,i}=\frac{3m}{8 p_{F_0}^{3}} C_{l,i}$ and $\Tilde{C}_{u,i}=\frac{3m}{8 p_{F_0}^{3}} C_{u,i}$.

