\begin{subfigure}[b]{0.5\textwidth}
    \centerline{\includegraphics[width=1\textwidth]{active_part.png}}
\caption{No. of Active Participants}
\label{fig1a}
\end{subfigure}
\begin{subfigure}[b]{0.5\textwidth}
    \centerline{\includegraphics[width=1\textwidth]{auc_cost_0.png}}
\caption{Auction Cost} %[\emph{n}=100,\emph{w}=20, \emph{S}=0.5, \emph{c}=0.005]
