%The paper is organized as follows. 

The plan of the paper is as follows.
In Sect. \ref{sect:reg} we collect all the information on regularity of the function $\psi$ 
necessary for the proofs of the main theorems. 
A short Sect. \ref{sect:compact} gathers definitions and elementary properties of 
classes $\BS_{p, \infty}$ of compact operators. 
In Sect. \ref{sect:int} we derive spectral estimates for integral operators. These 
estimates are used to prove Theorems 
\ref{thm:main} and \ref{thm:main0} in Sect. \ref{sect:proof}.  


We conclude the introduction with some general notational conventions.  

\textit{Coordinates.} 
As mentioned earlier, we use the following standard notation for the coordinates: 
$\bx = (x_1, x_2, \dots, x_N)$,\ where $x_j\in \R^3$, $j = 1, 2, \dots, N$. 
The vector $\bx$ is usually represented in the form 
$\bx = (\hat\bx, x)$ with  
$\hat\bx = (x_1, x_2, \dots, x_{N-1})\in\R^{3N-3}$,\, $x = x_N$.   
The notation $B(t, R)\subset\R^d$ is used for the open ball of radius $R>0$ centred at $t\in \R^d$, 
and $|B(t, R)|$ denotes its volume ($d$-dimensional Lebesgue measure).  
For instance, $B(\bx, R)\subset \R^{3N}$ and $B(\hat\bx, R)\subset \R^{3N-3}$. 


\textit{Indicators.} For any set $\L\subset\R^d$ we denote by $\1_{\L}$ its indicator function (or indicator).

\textit{Derivatives.} 
Let $\mathbb N_0 = \mathbb N\cup\{0\}$.
If $x = (x', x'', x''')\in \R^3$ and $m = (m', m'', m''')\in \mathbb N_0^3$, then 
the derivative $\p_x^m$ is defined in the standard way:
\begin{align*}
\p_x^m = \p_{x'}^{m'}\p_{x''}^{m''}\p_{x'''}^{m'''}.
\end{align*} 

\textit{Bounds.} 
For two non-negative numbers (or functions) 
$X$ and $Y$ depending on some parameters, 
we write $X\lesssim Y$ (or $Y\gtrsim X$) if $X\le C Y$ with 
some positive constant $C$ independent of those parameters. 
If $X\lesssim Y\lesssim X$, then  we say that $X\asymp Y$. 
To avoid confusion we may sometimes comment on the nature of 
(implicit) constants in the bounds. 

\textit{Integral operators.}
We introduce the notation $\iop(T):\plainL2(\R^3)\mapsto \plainL2(\R^{3N-3})$   
for the integral operator with the kernel $T(\hat\bx, x)$. 
%From the 
%context it will be clear in which spaces this operator acts. 


\section{Regularity of $\psi$}\label{sect:reg}

In this section we collect the pointwise 
bounds for derivatives of the eigenfunction $\psi$ of arbitrary order with explicit dependence 
on the distance to the coalescence points.  

\subsection{Bounds
%A bound by S. Fournais and T. S\o rensen
}
Denote by $\Sigma$ the coalescence set:
\begin{align*}
\Sigma = \bigg\{\bx = (\hat\bx, x)\in\R^{3N}: |x| 
\prod_{1\le k\le N-1}|x_k-x| = 0\bigg\}.
\end{align*}
Then 
\begin{align}\label{eq:dq}
\dc(\bx) = \min\{|x|, \frac{1}{\sqrt 2}
|x-x_k|: \ 1\le k\le N-1\},
%\quad \l(\bx) = \min\{1, \dc_j(\bx)\}.
\end{align}
defines the distance from $\bx$ to $\Sigma$. 
Introduce also the capped distance $\l(\bx) := \min\{1, \dc(\bx)\}$.  
The functions $\dc(\,\cdot\,)$ and $\l(\,\cdot\,)$ are 
Lipschitz with Lipschitz constant $=1$ 
(see \cite[Lemma 4.2]{HearnSob2023}):  for all $\bx, \by\in\R^{3N}$ we have 
\begin{align}\label{eq:lip}
|\dc(\bx) - \dc(\by)|\le |\bx-\by|,\ \quad |\l(\bx) - \l(\by)|\le |\bx-\by|.
\end{align}
The following bound for the derivatives of $\psi$ 
is a consequence of \cite[Corollary 1.2]{FS2021}.  

\begin{prop}\label{prop:FS} 
For all $\bx\notin\Sigma$, and for 
arbitrary $R >0$, we have the bound 
\begin{align}\label{eq:FS}
|\p_{x}^{m}\psi(\hat\bx, x)|\lesssim \big(1+\l(\bx)^{1-|m|}\big)\, \|\psi\|_{\plainL2(B(\bx, R))}, 
\, \quad \textup{for all}\quad m\in\mathbb N_0^{3},
\end{align}
with a constant that does not depend on $\bx$ and $\psi$, but may depend on $m$ and $R$.
\end{prop}

The estimate \eqref{eq:FS} will be sufficient for the proof of Theorem \ref{thm:main}. 
With regard to Theorem \ref{thm:main0}, 
%
%we need to examine further the structure of $\psi$. 
%
we shall see 
that under the assumption \eqref{eq:van}  the function $\psi$ has ``enhanced" regularity at the 
coalescence points $x = x_k$, $k = 1, 2, \dots, N-1$, 
but not at $x = 0$. To account for the singularity at $x = 0$ 
we introduce the Lipschitz function 
\begin{align}\label{eq:F0}
F_0(x) = -\frac{Z}{2}|x|\,\t(x),
\end{align}
where $\t\in \plainC\infty_0(\R^3)$ is such that $\t(x) = 1$ for $|x|<1$. 
Then we have the following result:

\begin{thm}\label{thm:varphider} Assume that \eqref{eq:van} holds. 
Then for any $R>0$ and for all $\bx\notin\Sigma$, we have   
\begin{align}\label{eq:varphider}
|\p_x^m\, \big(e^{-F_0(x)}\,\psi(\bx)\big)|
\lesssim (1+\l(\bx)^{2- |m|}) \, \|\psi\|_{\plainL2(B(\bx, R))}, 
\end{align}
for all $m\in\mathbb N_0^3$.
\end{thm}

The constants in \eqref{eq:varphider} depend on  
the function $\t$ but we assume that $\t$ is fixed throughout the paper 
and ignore the dependence on $\t$ in this and all the subsequent inequalities.


The rest of this section is focused on the proof of Theorem \ref{thm:varphider}. 
It requires detailed information 
on the structure of the function $\psi$, which is discussed next. 

\subsection{The Jastrow factors} 
The starting point of analysis in \cite{FHOS2005, FHOS2009, FS2021, HOS2001} 
and in many other papers on the subject, is the representation $\psi = e^F \phi$, where $F$ is a 
function that satisfies 
$F, \nabla F\in \plainL\infty_{\tiny {\rm loc}}(\R^{3N})$ and 
that captures the main singularity of the solution, so that 
$\phi$ is more regular than $\psi$. 
In the mathematical physics literature the function $e^F$ is often called 
a \textit{Jastrow factor}, see e.g. \cite{HaKlKoTe2012}.  
After the substitution the equation \eqref{eq:eigen} rewrites as 
\begin{align}\label{eq:jastrow}
-\Delta \phi - 2\nabla F\cdot \nabla\phi + (V- \Delta F - |\nabla F|^2-E)\phi = 0. 
\end{align}
More precisely,  if $\psi\in \plainW{1, 2}_{\tiny {\rm loc}}(\R^{3N})$ is a weak 
solution of \eqref{eq:eigen}, 
then we also have $\phi\in \plainW{1, 2}_{\tiny {\rm loc}}(\R^{3N})$ 
and $\phi$ is a weak solution of \eqref{eq:jastrow}.  
 If one chooses $F$ to be 
\begin{align}\label{eq:oldF}
\sum_{j=1}^N \bigg(-\frac{Z}{2}|x_j| 
+ \frac{1}{4}\sum_{j<k\le N}|x_j-x_k|\bigg),
\end{align} 
as in \cite{Leray1984}, 
then $\nabla F$ is bounded,  
$\Delta F = V$, and hence all the coefficients in \eqref{eq:jastrow} are uniformly bounded. 
The  function $F$ itself however is not bounded. To remedy this, 
we take the following regularized variant of \eqref{eq:oldF}. 
Let $\t\in \plainC\infty_0(\R^3)$ be as in the definition 
\eqref{eq:F0}. 
From now on we assume that $F$ is given by 
\begin{align}\label{eq:jascut}
F(\bx) = -\frac{Z}{2}\sum_{j=1}^N |x_j|\t(x_j) 
+ \frac{1}{4}\sum_{1\le j<k\le N}|x_j-x_k| \t(x_j-x_k), 
\end{align}
so that 
\begin{align}\label{eq:Finf}
F,\, \nabla F,\, \nabla^k (V-\Delta F)\in \plainL\infty(\R^{3N}),\quad \textup{for all}
\quad k = 0, 1, \dots.
\end{align} 
A different regularization (still satisfying \eqref{eq:Finf}) of the Jastrow factor was used in 
\cite{HOS2001}, \cite{FHOS2002}, \cite{FHOS2004} and \cite{FS2021}. 
The function $F(\hat\bx, x)$ naturally splits into two components:
$F(\hat\bx, x) = F_0(x) + F_1(\bx)$, where $F_0$ is as defined in \eqref{eq:F0} and 
\begin{align}\label{eq:F1}
F_1(\bx) = &\ 
\frac{1}{4}\sum_{1\le k \le N-1}|x-x_k|\, \t(x-x_k) \notag\\
&\ \quad\quad -\frac{Z}{2}\sum_{j=1}^{N-1} |x_j|\,\t(x_j) 
 + 
\frac{1}{4}\sum_{1\le j<k\le N-1}|x_j-x_k|\, \t(x_j-x_k).
\end{align} 
%
%
%\subsection{Properties of $\phi$ and $\psi$} 
%
The function $e^F$ is only Lipschitz but, 
since the coefficients in \eqref{eq:jastrow} are bounded, we have 
$\phi \in \plainC{1,\mu}_{\tiny{\rm loc}}(\R^{3N})$ for 
all $\mu\in (0,1)$, see \cite[Proposition 1.5]{HOS2001}.  
Moreover, using the factorization 
$\psi = e^F\phi$ it was shown in \cite[Theorem 1.2]{HOS2001} that for all 
$\bx_0\in\R^{3N}$ and for any positive pair $r, R$ such that $r < R$, the bound holds:
\begin{align*}
%\label{eq:hos}
\|\nabla\psi\|_{\plainL\infty(B(\bx_0, r))} \lesssim \|\psi\|_{\plainL\infty(B(\bx_0, R))}, 
\end{align*}
with a constant independent of $\psi$ and $\bx_0$.  
Slightly more general estimates 
were found in 
\cite[Proposition A.2]{FS2021}, see also \cite[Lemma 4.1]{HearnSob2023} for a shorter proof:
\begin{align}\label{eq:grphi}
\|\phi\|_{\plainL\infty(B(\bx_0, r))} + \|\nabla\phi\|_{\plainL\infty(B(\bx_0, r))} 
\lesssim \|\psi\|_{\plainL2(B(\bx_0, R))},
\end{align}
\begin{align}\label{eq:grpsi}
\|\psi\|_{\plainL\infty(B(\bx_0, r))} + \|\nabla\psi\|_{\plainL\infty(B(\bx_0, r))} 
\lesssim \|\psi\|_{\plainL2(B(\bx_0, R))}.
\end{align}
To improve the $\plainC{1, \mu}$-regularity of $\phi$, we 
introduce yet another Jastrow factor, 
\begin{align*}
F_3(\bx) = \frac{2-\pi}{12\pi} Z \sum_{1\le j < k\le N} 
x_j\cdot x_k \ln\big(|x_j|^2 + |x_k|^2\big) \t(x_j)\t(x_k). 
\end{align*}
According to \cite[Theorem 1.1, Remark 1.6]{FHOS2005}, the function $\tilde\phi$ defined as 
\begin{align*}
%\label{eq:phitil}
\tilde\phi(\bx) := e^{-F_3(\bx)} \, \phi(\bx) =  e^{-F(\bx) - F_3(\bx)} \psi(\bx),
\end{align*}
has $\plainC{1,1}(=\plainW{2, \infty})$-regularity:

\begin{prop}\label{prop:f3}
The function $\tilde\phi(\bx)$ 
belongs to $\plainW{2, \infty}(\R^{3N})$ and for any pair $r, R$, $0 < r < R$, and all 
$\bx_0\in\R^{3N}$ the bound holds 
\begin{align*}
\|\tilde\phi\|_{\plainW{2, \infty}(B(\bx_0, r))}\lesssim \| \psi\|_{\plainL\infty(B(\bx_0, R))}, 
\end{align*}
with a constant independent of $\psi$ and $\bx_0$. 
\end{prop}

%Observe that the presence of the function $F_3$ is crucial for the above result. 
%
The function $F_3$ belongs to $\plainW{2,p}(\R^{3N})$ for all 
$p < \infty$, but not for $p=\infty$. This 
is not sufficient for the $\plainW{2, \infty}$-smoothness of $\phi = e^{F_3}\tilde\phi$. 
Nevertheless, the following, slightly weaker fact is true (see  \cite{Hearnshaw2024}).  

\begin{lem} \label{lem:f3}
The derivative $\p_{x}^m \phi(\hat\bx, x)$, $|m|=2$, 
$m\in \mathbb N_0^3$,  
%of the 
%function 
%\begin{align}\label{eq:phidef}
%\phi(\bx) = e^{-F(\bx)} \psi(\bx),
%\end{align}
is globally bounded, and 
for any pair $r, R$, $0 < r < R$, and each $\bx_0\in\R^{3N}$ we have the estimate
\begin{align}\label{eq:nabla2phi}
\|\p_{x}^m\phi\|_{\plainL\infty(B(\bx_0, r))}\lesssim \|\psi\|_{\plainL2(B(\bx_0, R))}, 
\end{align}
with a constant independent of $\psi$ and $\bx_0$. 
\end{lem}

\begin{proof}
The derivatives of the function $F_3(\hat\bx, x)$ with respect to $x$ of first and second order 
are uniformly bounded. Therefore, by Proposition \ref{prop:f3},  
\begin{align*}
\|\p_{x}^m \phi\|_{\plainL\infty((B(\bx_0, r))} = \|\p_{x}^m\big(e^{F_3}\tilde\phi\big)\|_{\plainL{\infty}(B(\bx_0, r))}\lesssim \| \psi\|_{\plainL\infty(B(\bx_0, R))},
\end{align*}
and the bound \eqref{eq:nabla2phi} follows from \eqref{eq:grpsi}. 
\end{proof}

 As a step towards Theorem \ref{thm:varphider}, relying on the above estimates, we  
obtain bounds for higher order derivatives for $\phi$. For the first time 
these bounds were written out in \cite[Proposition 2.1]{Hearnshaw2024}.

\begin{thm}\label{thm:regphi} 
For all 
$\bx\notin\Sigma$, and for 
arbitrary $R >0$, we have the bound 
\begin{align}\label{eq:regphi}
|\p_{x}^m \,\phi(\bx)|
\lesssim \big(1+ \l(\bx)^{2-|m|}\big) \, \|\psi\|_{\plainL2(B(\bx, R))},
\quad m\in\mathbb N_0^{3},
\end{align}
with constants independent of $\psi$ and $\bx\notin\Sigma$. 
\end{thm}

The bound of the form \eqref{eq:regphi} with $\l(\bx)^{1-|m|}$ 
instead of 
$\l(\bx)^{2-|m|}$ was used in  \cite{FS2021} 
to derive \eqref{eq:FS}.

For the sake of completeness we provide a proof of Theorem \ref{thm:regphi}.



\subsection{Proof of Theorem \ref{thm:regphi}} 
First we quote a more general result that serves as a basis for the proof.

Let $u\in\plainW{1,2}$ be a weak solution of the equation 
\begin{align}\label{eq:mod}
-\Delta u + \ba\cdot\nabla u + b u = 0
\end{align}
in the ball $B(\bx_0, R\ell)\subset \R^{3N}$ 
with some $\bx_0\in \R^{3N}$, $0< \ell\le 1$, and 
a fixed $R>0$. Suppose that 
\begin{align}\label{eq:cd}
|\p_x^{m} \ba(\hat\bx, x)| + 
|\p_x^m b(\hat\bx, x)|\lesssim \ell^{-|m|}, \quad \bx\in B(\bx_0, R\ell),
\end{align}
for all $m\in\mathbb N_0^3$, with 
constants potentially depending on $m$, $R$, but not on $\bx_0$ and $\ell$. 
The next proposition that follows from  
\cite[Theorem 3.2]{HearnSob2023}, 
contains bounds for the  derivatives $\p_x^{m} u$  
with explicit dependence on the parameter $\ell\in (0, 1]$. 

\begin{prop}\label{prop:reg} 
Assume the conditions \eqref{eq:cd}, and let $u$ be a weak solution of the equation 
\eqref{eq:mod} in $B(\bx_0, R\ell)$.  
Then for all $m\in\mathbb N_0^3$ and all $r<R$ 
the derivatives $\p_x^m u$ belong to $\plainC{1, \mu}\big(\overline{B(\bx_0, r\ell)}\big)$ 
for all $\mu\in (0, 1)$. 
Furthermore, if $|m|\ge 2$, then   
\begin{align}\label{eq:d2ell}
\|\p_x^m u&\|_{\plainL\infty(B(\bx_0, r\ell))}\notag\\
\lesssim &\ \ell^{2-|m|}\,\big(
\max_{k: |k|=2} \|\p_x^k u\|_{\plainL\infty(B(\bx_0, R\ell))}
+ \|\nabla u\|_{\plainL\infty(B(\bx_0, R\ell))}
+  \|u\|_{\plainL\infty(B(\bx_0, R\ell))}\big).
\end{align}
The implicit constants in \eqref{eq:d2ell} are independent of $\bx_0$ and $\ell$, but may depend 
on the constants $r, R$, order $m$ of the derivative, and the 
constants in \eqref{eq:cd}. 
 \end{prop}

We apply Proposition \ref{prop:reg} to the equation \eqref{eq:jastrow} satisfied by the function 
$\phi$. 
In order to check that 
the coefficients of \eqref{eq:jastrow} satisfy 
the conditions \eqref{eq:cd}  we start with estimates of  
the Jastrow factor. 
Along with the distance function $\dc(\bx)$ defined in \eqref{eq:dq} introduce also 
\begin{align*}
\dc_1(\bx) = \min\{ \frac{1}{\sqrt2}\,|x-x_k|: 1\le k\le N-1\}, \quad \textup{and}\quad 
\l_1(\bx) = \min\{\dc_1(\bx), 1\}.
\end{align*}
Clearly, $\dc(\bx) = \min\{|x|, \dc_1(\bx)\}$, $\l(\bx) = \min\{|x|, \l_1(\bx)\}$.
\begin{lem}\label{lem:nablajas}
Let $F$, $F_1$ be as defined in \eqref{eq:jascut} and \eqref{eq:F1} 
respectively. Then for all 
$\bx\notin\Sigma$ and all 
$m\in\mathbb N_0^3$ we have
\begin{align}\label{eq:nablajas}
\big|\p_{x}^m \nabla F(\bx)\big| 
+ \big|\p_{x}^m |\nabla F(\bx)|^2\big|\lesssim &\ \dc(\bx)^{-|m|},\\[0.2cm]
\big|\p_{x}^m \nabla F_1(\bx)\big| 
+ \big|\p_{x}^m |\nabla F_1(\bx)|^2\big|\lesssim &\ \dc_1(\bx)^{-|m|}.\label{eq:nablajas0}
\end{align}
If $|m|\ge 1$, then  
\begin{align}\label{eq:ef}
\big|\p_{x}^m e^{F(\bx)}\big| \lesssim  \dc(\bx)^{1-|m|},\quad  
\big|\p_{x}^m e^{F_1(\bx)}\big| \lesssim  \dc_1(\bx)^{1-|m|}.
\end{align} 
\end{lem}

\begin{proof} 
Let $\t\in\plainC\infty_0(\R^3)$ be as in definition \eqref{eq:F0}, and let 
$g(x) = \nabla \big(|x| \t(x)\big)$. Then 
\begin{align*}%\label{eq:ediff}
|\p_{x}^m g(x)| + |\p_{x}^m g(x-x_k)|\lesssim &\ \dc(\bx)^{-|m|},\notag\\
\quad  &\ |\p_{x}^m g(x-x_k)|\lesssim \dc_1(\bx)^{-|m|},\quad k = 1, 2, \dots, N-1,
\end{align*}
for all $\bx\notin \Sigma$. This entails the required bounds $\nabla F$ and $\nabla F_1$. 
For $|\nabla F|^2, |\nabla F_1|^2$ 
we use the Leibniz rule, which leads again to \eqref{eq:nablajas}, \eqref{eq:nablajas0}.

To prove the bounds \eqref{eq:ef} consider, for example, 
the derivative $\p_{x}^m e^{F_1}, |m|\ge 1$. The case of the function $F$ is done in the same way. 
Observe that $\p_{x}^m e^{F_1}, |m|\ge 1,$ 
can be written as a linear combination of finitely many terms of the form 
\begin{align*}
 \p_{x}^{k_1}F_1 \, 
 \p_{x}^{k_2}F_1 \cdots 
 \p_{x}^{k_s}F_1 \, e^{F_1},
\end{align*}
where $1 \le |k_j|$, $\sum_{j=1}^s |k_j| = |m|$, $1\le s\le |m|$.
By \eqref{eq:nablajas0} each such term can be estimated by 
\begin{align}\label{eq:dj}
\dc_1(\bx)^{(1-|k_1|) + (1-|k_2|) + \cdots (1-|k_s|) } 
= \dc_1(\bx)^{s - |m|}.
\end{align}
Due to the presence of the cut-off $\t$ in the definition \eqref{eq:F1}, the derivative 
$\p_{x}^m e^{F_1}$ is supported on the set where $\dc_1(\bx)\lesssim 1$. 
Therefore the right-hand side of \eqref{eq:dj} 
does not exceed $\dc_1(\bx)^{1-|m|}$, as required.
\end{proof}

Now we are in a position to prove Theorem \ref{thm:regphi}. 

\begin{proof}[Proof of Theorem \ref{thm:regphi}] 
For $|m| = 0, 1$ the bound \eqref{eq:regphi} holds because of \eqref{eq:grphi}. From now on assume that $|m|\ge 2$.

Further proof follows the idea of \cite[Sect. 2]{FS2021}. 
Let us fix 
$\bx_0\in \R^{3N}\setminus\Sigma$, and denote $\l = \l(\bx_0)$. 
Then for any $R_1\in (0, 1)$ we have   
$B(\bx_0, R_1\l)\subset \R^{3N}\setminus \Sigma$.  
Indeed, by \eqref{eq:lip},  
\begin{align*}
|\l(\bx) - \l|\le |\bx-\bx_0|<R_1\l,\quad \bx\in B(\bx_0, R_1\l),
\end{align*}
which implies that 
\begin{align}\label{eq:lip2}
0 <(1-R_1)\l \le \l(\bx)\le (1+R_1)\l,\quad \textup{for all}\quad \bx\in B(\bx_0, R_1\l),
\end{align} 
and hence proves the claim. 

By \eqref{eq:jastrow}, the function $\phi = e^{-F}\psi$ 
satisfies the equation \eqref{eq:mod} where 
\begin{align*}
\ba = -2\nabla F,\quad b = V- \Delta F - |\nabla F|^2 - E.
\end{align*}
Consider this equation in the ball $B(\bx_0, R_1\l)$ where  $R_1 < \min\{1, R\}$.
%
% and 
%Let us fix a point $\bx_0\notin\Sigma$, a number $R_1\in (0, 1)$, $R_1 < R$, 
%and consider the equation 
%\eqref{eq:mod} in the ball $B(\bx_0, R_1\l)$ where $\l:= \l(\bx_0)$.  
%
%
%
Since 
$B(\bx_0, R_1\l)\subset\R^{3N}\setminus\Sigma$, 
by virtue of \eqref{eq:Finf}, \eqref{eq:nablajas} and \eqref{eq:lip2}, 
the coefficients $\ba$ and $b$ 
satisfy the bound 
\begin{align*}
|\p_x^m\ba(\bx)| + |\p_x^m b(\bx)|\lesssim 1+ \dc(\bx)^{-|m|} 
\lesssim \l^{-|m|},\quad \textup{for all}\quad \bx\in B(\bx_0, R_1\l).
\end{align*}
Thus the condition \eqref{eq:cd} is fulfilled 
 with $\ell = \l\le 1$. By Proposition \ref{prop:reg},  
%$\p_x^m \phi\in \plainC1(\overline{B(\bx_0, r\l)})$ for all $r <R_1$. 
%Moreover, 
if $|m|\ge 2$, then  
\begin{align*}
%\label{eq:phib}
|\p_x^{m}\phi(\bx_0)|\lesssim  \l^{2-|m|}\, \big(&
\max_{l: |l|=2} \|\p_x^l \phi\|_{\plainL\infty(B(\bx_0, R_1\l))}\notag\\
 &\ + 
\|\phi\|_{\plainL\infty(B(\bx_0, R_1\l))}
+ \|\nabla \phi\|_{\plainL\infty(B(\bx_0, R_1\l))}\big).
\end{align*}
Now the bound \eqref{eq:regphi} for $|m|\ge 2$ 
follows from \eqref{eq:grphi} and  \eqref{eq:nabla2phi} since $R_1\l\le R_1< R$. 
The proof is now complete. 
\end{proof}


\subsection{Proof of Theorem \ref{thm:varphider}}
For $|m| = 0, 1$ the required bound follows from \eqref{eq:grpsi}.  

Assume that \eqref{eq:van} holds and that $|m|\ge 2$.  
Since $e^{-F_0} \psi = e^{F_1}\phi$, 
we can write
\begin{align}\label{eq:f0f1}
\p_x^m\big(e^{-F_0} \psi\big) 
= 
\sum_{0\le k < m} {m\choose{k}} \p_x^k e^{F_1}\, \p_x^{m-k}\, \phi
+ \big(\p_x^m e^{F_1}\big)\, \phi
\end{align}
By \eqref{eq:regphi} and \eqref{eq:ef}, each term under the sum is bounded by 
\begin{align}\label{eq:summa}
\big(1+\l_1(\bx)^{1-|k|}\big) \, \big(1+ &\ \l(\bx)^{2-|m|+|k|}\big)
\,\|\psi\|_{\plainL2(B(\bx, R))}\notag\\
&\ \lesssim  
\big(1+\l(\bx)^{2-|m|}\big)\,\|\psi\|_{\plainL2(B(\bx, R))},\quad 0\le k < m,
\end{align}
where we have used that $\l(\bx)\le \l_1(\bx)\le 1$ and that $|k|+1\le |m|$.

To estimate the last term in \eqref{eq:f0f1} assume without loss of generality that 
$R \le 1$ and note that for $\l_1\ge {R}/{2}$ we have 
\begin{align*}
|\big(\p_x^m e^{F_1}\big)\, \phi|\lesssim \|\psi\|_{\plainL2(B(\bx, R))} 
\lesssim R^{|m|-2}\l_1(\bx)^{2-|m|} \, \|\psi\|_{\plainL2(B(\bx, R))}, 
\end{align*} 
by \eqref{eq:ef} and \eqref{eq:grphi}.
It remains to consider the case $\l_1(\bx) \le R/2$. Assume that 
$\l_1(\bx) = \frac{1}{\sqrt2}\, |x-x_j|$ with some $j = 1, 2, \dots, N-1$.
By \eqref{eq:van} we also have $\phi(\hat\bx, x_j) = 0$, so 
\begin{align*}
|\phi(\hat\bx, x)|  = &\ |\phi(\hat\bx, x) - \phi(\hat\bx, x_j)|\\
\le &\ \|\nabla \phi\|_{\plainL\infty(B(\bx, 3R/4))} |x-x_j|
\lesssim \sqrt 2\, \l_1(\bx)\, \|\psi\|_{\plainL2(B(\bx, R))},
\end{align*}
where we have used \eqref{eq:grphi}. Now, using also \eqref{eq:ef}, we obtain that 
\begin{align*}%\label{eq:ksm1}
|(\p_x^m e^{F_1(\bx)}) \phi(\bx)|
\lesssim &\ \l_1(\bx)^{2-|m|}\,  \|\psi\|_{\plainL2(B(\bx, R))}
\lesssim \l(\bx)^{2-|m|}\,  \|\psi\|_{\plainL2(B(\bx, R))}.
\end{align*}
Together with \eqref{eq:summa} the last bound leads to \eqref{eq:varphider}.
\qed

Note that without the assumption \eqref{eq:van}, 
repeating the above proof for the function $\psi$ instead of $e^{-F_0}\psi$, would give 
a proof of Proposition \ref{prop:FS}. 
