\section{Compact operators} \label{sect:compact} 
Here we provide necessary information about compact operators. 
Most of the listed facts can be found in \cite[Chapter 11]{BS}. 
Let $\CH$ and $\mathcal G$ be separable Hilbert spaces.  
Let $A:\CH\to\mathcal G$ be a compact operator. 
If $\CH = \mathcal G$ and $A=A^*\ge 0$, then $\l_k(A)$, $k= 1, 2, \dots$, 
denote the positive eigenvalues of $A$ 
numbered in descending order counting multiplicity. 
For arbitrary spaces $\CH$, $\mathcal G$ and compact $A$, by $s_k(A) >0$, 
$k= 1, 2, \dots$, we denote the singular values of 
$A$ defined by $s_k(A)^2 = \l_k(A^*A) = \l_k(AA^*)$.   
We use the notation $\BS_p, p>0$ for the classical Schatten-von Neumann classes, 
i.e. the classes of compact operators  $A$ such that 
\begin{align*}
\| A\|_p := \bigg[\sum_{k=1}^\infty \, s_k(A)^p\bigg]^{\frac{1}{p}} < \infty. 
\end{align*}
Recall that $\|A\|_p$ defines a norm (resp. quasi-norm) if $p\ge 1$ (resp. $p <1$).
It is clear that $s_k(A)\le k^{-1/p} \|A\|_p$. The following estimate from 
\cite[Chapter 11, Theorem 4.7]{BS} will be useful.

\begin{prop}\label{prop:fr}
Let $A\in \BS_p, 0 < p <\infty$ and ${\rm rank}\, K\le n$. Then 
\begin{align*}
\sum_{k=n+1}^\infty s_k(A)^p \le \|A-K\|_p^p.
\end{align*}
In particular, 
\begin{align*}
s_{2n}(A)\le n^{-\frac{1}{p}}\,\| A - K\|_p. 
\end{align*}
\end{prop}




If $s_k(A)\lesssim k^{-1/p}, k = 1, 2, \dots$, 
with some $p >0$, then we say that $A\in \BS_{p, \infty}$ and denote
\begin{align*}%\label{eq:quasi}
\| A\|_{p, \infty} = \sup_k s_k(A) k^{\frac{1}{p}},
\end{align*}
so that 
\begin{align}\label{eq:star}
\|A^*A\|_{p/2, \infty} = \|A A^*\|_{p/2, \infty} = \|A\|_{p, \infty}^2. 
\end{align}
Clearly, $\BS_p\subset \BS_{p, \infty}$ and $\|A\|_{p, \infty}\le \|A\|_p$.
The class $\BS_{p, \infty}$ is a complete linear space with the quasi-norm $\|A\|_{p, \infty}$. 
For all $p>0$ the functional $\|A\|_{p, \infty}$ 
satisfies the following ``triangle" inequality for  
operators $A_1, A_2\in\BS_{p, \infty}$:
\begin{align}\label{eq:triangle}
\|A_1+A_2\|_{\scalet{p}, \scalel{\infty}}^{{\frac{\scalel{p}}{\scalet{p+1}}}}
\le \|A_1\|_{\scalet{p}, \scalel{\infty}}^{{\frac{\scalel{p}}{\scalet{p+1}}}}
+ \|A_2\|_{\scalet{p, \infty}}^{{\frac{\scalel{p}}{\scalet{p+1}}}}.
\end{align}  
This inequality allows one to estimate quasi-norms of ``block-vector" operators. 
Let $A_j\in\BS_{p, \infty}$ 
be a finite collection of compact operators. Define the operator $\BA:\CH\to\oplus_j \mathcal G$ by  
$\BA = \{A_j\}_{j}$.
Since $\BA^* \BA = \sum_j A_j^*A_j$, 
and $A_j^*A_j\in\BS_{q, \infty}$, $q = p/2$, 
by \eqref{eq:triangle} we have 
\begin{align}\label{eq:blockvec}
\|\BA\|_{p, \infty}^{{\frac{\scalel{2p}}{\scalet{p+2}}}} 
= \|\BA^*\BA\|_{q, \infty}^{{\frac{\scalel{q}}{\scalet{q+1}}}}
\le  \sum_j\|A_j^*A_j\|_{q, \infty}^{{\frac{\scalel{q}}{\scalet{q+1}}}} = 
\sum_j\|A_j\|_{p, \infty}^{{\frac{\scalel{2p}}{\scalet{p+2}}}}.
\end{align}
Consequently, in order to estimate the singular values of $\BA$ it suffices to 
estimate those of its components $A_j$. We use this fact throughout the paper. 
%
%We point out a useful multiplicative inequality: if $A_1\in \BS_{p_1, \infty}$, 
%$A_2\in \BS_{p_2, \infty}$ with some $p_1>0, p_2 >0$, then for $p^{-1} = p_1^{-1} +p_2^{-1}$ 
%we have  
%\begin{align}\label{eq:multipl}
%\| A_1\, A_2\|_{p, \infty}\le \bigg(\frac{p_1}{p}\bigg)^{\frac{1}{p_1}}\, 
%\bigg(\frac{p_2}{p}\bigg)^{\frac{1}{p_2}}\, \|A_1\|_{p_1, \infty}\, 
%\|A_2\|_{p_2, \infty},
%\end{align}  
%see \cite[Chapter 11, Theorem 6.9]{BS}.  

For $p\in (0, 1)$ it is often more convenient to use the following ``triangle" inequality for  
arbitrarily many operators $A_j\in\BS_{p, \infty}$, $j = 1, 2, \dots$:
\begin{align}\label{eq:ptriangle}
\big\|\sum_{j} A_j\big\|_{p, \infty}^p\le (1-p)^{-1}
\sum_j \|A_j\|_{p, \infty}^p,
\end{align}
see 
\cite[Lemmata 7.5, 7.6]{AJPR2002}, \cite[\S 1]{BS1977} and references therein. Under 
the additional assumption
\begin{align}\label{eq:orthog}
A_k A_j^* = 0\quad \textup{or}\quad A_k^*A_j = 0,\quad j\not = k, 
\end{align}   
the inequality of the form \eqref{eq:ptriangle} extends to all $p\in (0, 2)$: 

\begin{prop}\cite[Lemma 1.1]{BS1977}\label{prop:orthog}
Let $p\in (0, 2)$ and let $A_j\in \BS_{p, \infty}$, $j= 1, 2, \dots$, 
be a family of operators satisfying 
\eqref{eq:orthog}. 
Then for the operator $A = \sum_j A_j$ we have the inequality
\begin{align}\label{eq:pnorm}
\|A\|_{\scalet{p}, \scalel{\infty}}^{\scalet{p}}\le 
\frac{2}{2-p}\,
\sum_j \|A_j\|_{\scalet{p}, \scalel{\infty}}^{\scalet{p}}. 
\end{align} 
\end{prop}

\begin{proof} 
It suffices to conduct the proof under the first condition in 
\eqref{eq:orthog} only, so that  
\begin{align*}
A A^* = \sum_j A_j A_j^*. 
\end{align*}
Since $A_j A_j^*\in\BS_{q, \infty}, q = p/2<1$, 
and $\|A_j A_j^* \|_{q, \infty} = \|A_j\|_{p, \infty}^2$, 
the inequality \eqref{eq:ptriangle} leads to the bound 
\begin{align*}
\|A\|_{p, \infty}^p = \|A A^*\|_{q, \infty}^q \le (1-q)^{-1} 
\sum_j \|A_j A_j^*\|_{q, \infty}^q
= (1-p/2)^{-1}\sum_j \|A_j\|_{p, \infty}^p. 
\end{align*}
This inequality coincides with \eqref{eq:pnorm}.
\end{proof}


\section{Singular values of integral operators}\label{sect:int}

\subsection{Main estimate} 
The membership of integrals operators in various classes of compact operators, including 
$\BS_p$ and $\BS_{p, \infty}$, has been comprehensively investigated by   
 M.S. Birman and M.Z. Solomyak, in \cite{BS1977}. In this monograph 
such properties are formulated in terms of functional classes to which the integral kernels 
belong. 
Although the results that we need can be derived from \cite{BS1977}, as in 
\cite{Sobolev2022a, Sobolev2022b},
the integral kernels that we consider admit a more elementary and direct approach, 
which we describe below.  

We are interested in integral operators whose kernels imitate the structure 
of the eigenfunction $\psi$. More precisely, we consider integral operators 
$\iop(T)$ with scalar kernels $T(t, x)$, $t\in \R^l, x\in\R^d$, $l\ge1, d\ge 1$, 
satisfying the following condition. 
Let $z_k: \R^l\mapsto \R^d$,\, 
$k = 1, 2, \dots, N$, be some functions of $t\in\R^l$, 
and let $X(t) = \{z_1(t), z_2(t), \dots, z_N(t)\}\subset \R^d$.
Assume that 
for some $\a > -d$, for a.e. $t\in\R^l$ the function $T(t, x)$ is such that 
\begin{align*}
T(t, \,\cdot\,)\in\plainC\varkappa(\R^d\setminus X(t)),\quad \varkappa = \lfloor\a\rfloor + d + 1, 
\end{align*}
and that it satisfies the bounds 
   \begin{align}\label{eq:kernelexp}
|\p_x^j T(t, x)| \le A(t, x) 
\bigg(1+\sum_{k=1}^N \big(1\wedge |x-z_k(t)|\big)^{\a-|j|}\bigg),\quad  
|j| \le \varkappa,
\end{align}    
with some non-negative function $A(t, x)$. Introduce the notation 
\begin{align}\label{eq:cubes}
\CC^{(r)} = [-r/2, r/2)^d, r>0;\quad \CC^{(r)}_n = \CC^{(r)} + n,\, n\in\Z^d.
\end{align}
If $r=1$ then we omit the superscript ``$(r)$" and write $\CC = \CC^{(1)}$, 
$\CC_n = \CC+n$, $n\in\Z^d$. All constants in the subsequent inequalities may depend 
on the dimensions $l$, $d$, numbers $\a$, $r$ and $N$, but they will not depend on the functions $z_k(t)$ and $A(t, x)$. 
Our main objective in this section is the following theorem.  



\begin{thm}\label{thm:kg} 
Let the kernel $T$ be as specified above, and let 
$a\in\plainL{\infty}_{\textup{\tiny loc}}(\R^d)$. Suppose  
that for each $n\in \Z^d$ the function 
$A_n(t):=\|A(t,\,\cdot\,)\|_{\plainL\infty(\CC^{(2\pi)}_n)}$ is such that 
$A_n \in \plainL2(\R^l)$.
If $\a > -d/2$, then the operator $\iop(T) a$ 
belongs to $\BS_{q, \infty}$ with $q^{-1} = 1+\a d^{-1}$, and 
\begin{align}\label{eq:pivg}
\| \iop(T) a\|_{q, \infty}\lesssim 
\bigg[\sum_{n\in\Z^d}
\| A_n\|_{\plainL2(\R^l)}^q\,\|a\|_{\plainL{\infty}(\CC_n)}^q
\bigg]^{\frac{1}{q}},
\end{align}
under the assumption that the right-hand side of the above inequality is finite. 
The implicit constant in \eqref{eq:pivg} 
does not depend on the functions $z_k$, $A$, $a$.
\end{thm}

\begin{rem}\label{rem:vector}
\begin{enumerate}
\item \label{item:vector}
Although we assume that the kernel $T(t,x)$ in the above theorem is scalar, the estimate 
\eqref{eq:pivg} also holds for vector-valued kernels if the conditions of Theorem 
\ref{thm:kg} are satisfied for each component. To see this it suffices to use the bound \eqref{eq:blockvec}.
\item 
The bound \eqref{eq:pivg} is similar 
to the one obtained in \cite[Theorem 3.4]{Sobolev2022a} with the help of the general 
estimates from \cite{BS1977}. 
In contrast to 
\eqref{eq:pivg}, the bound in \cite{Sobolev2022a} contained 
$\plainL{p}$-norms of $a$ with some $p = p(\a)\ge 2$, instead of 
the $\plainL\infty$-norms of $a$.  
\end{enumerate}
\end{rem}




The proof relies on two lemmata below.

\subsection{Fourier transform} 
First we examine the Fourier transform of functions $u = u(x)$ satisfying a bound similar to \eqref{eq:kernelexp}. 

\begin{lem}\label{lem:fourier} 
Let $X = \{a_1, a_2,\dots, a_N\}$ be a finite collection of points in $\R^d$. 
Let the function $u$ be such that for some $\a > - d$ it satifies  
\begin{align*}
u\in\plainC\varkappa(\R^d\setminus X), \quad \varkappa  = \lfloor\a\rfloor + d + 1, 
\end{align*} 
and the following bounds hold:  
\begin{align}\label{eq:sing}
|\p_x^m u(x)|\lesssim \1_{\CC^{(r)}}(x) \big(1+ \sum_{k=1}^N (|x-a_k|\wedge 1)^{\a-|m|}\big),
\end{align}
with some $r>0$ and   
for all $x\notin X$ and all $|m|\le \varkappa$. 
Then 
\begin{align}\label{eq:fourier}
|\hat u(\xi)|\lesssim \lu\xi\ru^{-\a-d}, \quad \lu \xi\ru = \sqrt{1+|\xi|^2},
\end{align}
where the implicit constant does not depend on the set $X$, 
but may depend on $r$ and $N$. 
\end{lem} 

\begin{proof} 
Clearly, it suffices to prove \eqref{eq:fourier} for $|\xi|\ge 1$. 


First we prove the required estimate for $\a\le 0$, so that 
\eqref{eq:sing} amounts to 
\begin{align}\label{eq:sing1}
|\p_x^m u(x)|\lesssim \1_{\CC^{(r)}}(x) 
\big(1+\sum_{k=1}^N |x-a_k|^{\a-|m|}\big),\quad |m|\le \varkappa.
\end{align}
For each $\varepsilon\in (0, 1]$ 
introduce a smooth partition of unity $\eta(x) = \eta(x, \varepsilon)$,\, 
$\z(x) = \z(x, \varepsilon)$, such that $\eta+\z = 1$, $0\le \eta\le 1$, and 
\begin{align*}
\eta(x; \varepsilon) = 0,\quad & \textup{if}\quad \dist(x; X)\ge \varepsilon;\\
\z(x; \varepsilon) = 0,\quad & \textup{if}\quad \dist(x; X) <  \frac{\varepsilon}{2},
\end{align*} 
and 
\begin{align}\label{eq:tz}
|\p_x^m \eta(x)|\lesssim \varepsilon^{-|m|},\quad 
|\p_x^m \z(x)|\lesssim \varepsilon^{-|m|},\quad m\in \mathbb N_0^d,
\end{align}
where the implicit constants do not depend on the set $X$. 
Represent $\hat u(\xi) = I_0(\xi, \varepsilon) + I_1(\xi, \varepsilon)$ with 
\begin{align*}
I_0(\xi; \varepsilon) = \frac{1}{(2\pi)^{\frac{d}{2}}}\int e^{-ix\cdot\xi}\, u(x)\, 
\eta(x; \varepsilon)\, dx\quad \textup{and}\ 
I_1(\xi; \varepsilon) = \frac{1}{(2\pi)^{\frac{d}{2}}} 
\int e^{-ix\cdot\xi}\, u(x)\, \z(x; \varepsilon)\, dx,
\end{align*}
and estimate $I_0$ and $I_1$ separately. 
Let 
\begin{align*}
\Om_k = \{x\in\CC^{(r)}: \dist(x; X) = |x-a_k|\},\quad k = 1, 2, \dots, N,
\end{align*}
so $\CC^{(r)} = \cup_k\Om_k$. Then, by \eqref{eq:sing1},
\begin{align}\label{eq:i0}
|I_0(\xi, \varepsilon)|\lesssim &\ 
\sum_{k=1}^N\, \int\limits_{\Om_k\cap B(a_k, \varepsilon)} |x-a_k|^\a\, dx\notag\\
\lesssim &\ \sum_{k=1}^N\, \int\limits_{|x-a_k| \le \varepsilon} |x-a_k|^\a\, dx
 \lesssim \varepsilon^{\a+d}.
\end{align}
To estimate $I_1$ 
%
%let 
%\begin{align}\label{eq:el}
% l = \lfloor \a\rfloor + d +1,
%\end{align} 
%so that $\a-l< -d$. Now 
%
integrate by parts $\varkappa$ times 
using the relation $|\xi|^{-2}\, i\xi\cdot\nabla_x\, e^{-ix\cdot\xi} = e^{-ix\cdot\xi}$:
\begin{align*}
I_1 =  \frac{1}{(2\pi)^{\frac{d}{2}}}
\int e^{-ix\cdot\xi} (-|\xi|^{-2}\, i\xi\cdot\nabla_x)^\varkappa\, 
\big(u(x)\, \z(x; \varepsilon)\big)\, dx.  
\end{align*}
It is clear that 
\begin{align*}
|I_1 |\lesssim 
|\xi|^{-\varkappa}\,\sum_{p, s: |p|+|s| = \varkappa}\, 
\int\, |\p_x^s u(x)|\, |\p_x^p \z(x; \varepsilon)|\, dx.
\end{align*}
First estimate the integral with $p = 0$:
\begin{align*}
\int\, |\p_x^s u(x)|\, dx
\lesssim &\  \sum_{k=1}^N\, 
\int_{\Om_k\setminus B(a_k, \varepsilon/2)} (1+|x-a_k|^{\a-\varkappa})\, dx \\
\lesssim &\  \sum_{k=1}^N\, 
\int\limits_{x\in \CC^{(r)}, |x-a_k|>\varepsilon/2} (1+|x-a_k|^{\a-\varkappa})\, dx
\lesssim \varepsilon^{\a-\varkappa+d},
\end{align*}
where we have used the fact that $\a-\varkappa<-d$. Suppose that $|p| \ge 1$. By the definition 
of $\z$, the derivative $\p_x^p\z$ is supported on the set where 
$\varepsilon/2\le  \dist(x, X)\le \varepsilon$. 
Therefore, by \eqref{eq:tz}, 
\begin{align*}
\int\, |\p_x^s u(x)|\, |\p_x^p \z(x; r)|\, dx
\lesssim &\ \sum_{k=1}^N\, \int_{(\Om_k\cap B(a_k, \varepsilon))\setminus B(a_k, \varepsilon/2)}
(1+|x-a_k|^{\a-|s|})\, \varepsilon^{-|p|} dx \\
\lesssim &\ (1+\varepsilon^{\a-|s|}) \varepsilon^{-|p|}  \varepsilon^d
\lesssim  \varepsilon^{\a-\varkappa +d}.
\end{align*}
Consequently, 
\begin{align*}
|I_1(\xi, \varepsilon) |\lesssim |\xi|^{-\varkappa} \varepsilon^{\a-\varkappa+d}.
\end{align*}
Combining this bound with \eqref{eq:i0} we obtain:
\begin{align*}
|\hat u(\xi)|\lesssim \big( \varepsilon^{\a+d} + |\xi|^{-\varkappa} 
\varepsilon^{\a-\varkappa+d}\big). 
\end{align*}
Taking $\varepsilon = |\xi|^{-1}$ we conclude the proof of the claimed bound 
\eqref{eq:fourier} for $\a\le 0$. 

For arbitrary $\a >0$, let 
$m = \lceil \a\rceil < \varkappa$, so that $-1<\a-m\le 0$. 
Rewrite the Fourier transform of $u$ integrating by parts $m$ times:
\begin{align*}
\hat u(\xi) = \frac{1}{(2\pi)^{\frac{d}{2}}}
\int e^{-ix\cdot\xi} (-|\xi|^{-2}\, i\xi\cdot\nabla_x)^m\,  u(x) \, dx,
\end{align*}
so that
\begin{align*}
|\hat u(\xi)|\lesssim |\xi|^{-m} \sum_{|n|=m}
%
%\bigg|\int e^{-ix\xi} \, \p_x^n u(x)\, dx \bigg|
%
|\widehat{(\p^n u)}(\xi)|.
\end{align*}
Since $\b:=\a-m > -1$, the right-hand side is finite for all $\xi\in\R^d$.  
The function 
%
%Since the function  
%
$v = \p^n_x u, |n|=m$, satisfies $v\in\plainC{\om}(\R^d\setminus X)$ 
with $\om = \lfloor\b\rfloor + d+1$, and the bounds hold:
\begin{align*}
|\p_x^s v(x)|\lesssim  (1+ \sum_k |x-a_k|^{\b - s}),\quad |s|\le \om.
\end{align*}
Since $\b\le 0$, it follows from the first part of the proof, 
that 
\begin{align*}
|\hat u(\xi)|\lesssim  |\xi|^{-m} \, |\xi|^{-\b -d} =  |\xi|^{-\a-d},
\end{align*}
which gives \eqref{eq:fourier} and completes the proof.
\end{proof}

\subsection{Operators on the cube} 
The next step towards the proof of Theorem \ref{thm:kg} is the $s$-value estimate 
for integral operators on the cube. 

\begin{lem}\label{lem:cubepi}
Let the kernel $T$ be as in Theorem 
\ref{thm:kg}, and assume that $A(t, x) = A(t, x)\1_{\CC^{(2\pi)}}(x)$. 
Suppose that  
$\tilde A(t):=\|A(t,\,\cdot\,)\|_{\plainL\infty(\CC^{(2\pi)})}$ is such that 
$\tilde A\in\plainL2(\R^l)$.
If $\a > -d/2$, then 
the operator $ \iop(T)$ 
belongs to $\BS_{q, \infty}$, with $q^{-1} = 1+\a d^{-1}$, and 
\begin{align}\label{eq:piv}
\|\iop(T)\|_{q, \infty}\lesssim 
\|\tilde A \|_{\plainL2(\R^l)}.
\end{align} 
The implicit constant in \eqref{eq:piv} does not depend on the functions $z_k$.
\end{lem}

\begin{proof} 
Since $T(t, x) = T(t, x) \1_{\CC^{(2\pi)}}(x)$, we consider 
$\iop(T)$ as an operator acting on $\plainL2(\CC^{(2\pi)})$ . 
Denote
\begin{align*}
\hat T_\nu(t) = \frac{1}{(2\pi)^{\frac{d}{2}}} \int_{\CC^{(2\pi)}} \, 
e^{-i\nu\cdot x}\, T(t, x) \, dx,\quad \nu\in\Z^d.  
\end{align*}
By Lemma \ref{lem:fourier}, $|\hat T_\nu(t)|\lesssim \tilde A(t) \lu \nu\ru^{-\a-d}$, 
so that $\hat T_\nu\in \plainL2(\R^l)$ and  for a.e. $t\in \R^l$ the series 
\begin{align*}
T(t, x) = \frac{1}{(2\pi)^{\frac{d}{2}}} \sum_{\nu\in\mathbb Z^d} \, 
e^{i\nu\cdot x}\, \hat T_\nu(t),
\end{align*}
converges in $\plainL2(\CC^{(2\pi)})$. 
For a fixed $M\ge 1$ the rank of the operator 
$\iop(T_M):\plainL2(\CC^{(2\pi)})\mapsto \plainL2(\R^l)$   
with kernel 
\begin{align*}
T_M(t, x) = \frac{1}{(2\pi)^{\frac{d}{2}}} \sum_{|\nu|\le M} \, 
e^{i\nu\cdot x}\, \hat T_\nu(t),
\end{align*}
does not exceed  
\begin{align*}
m = m(M):= \#\{\nu\in \Z^d: |\nu| \le M\}
\asymp M^d.
\end{align*}
Therefore, by Proposition \ref{prop:fr},
\begin{align}\label{eq:finiterank}
s_{2m}(\iop(T))\le m^{-\frac{1}{2}}\, \| \iop(T) - \iop(T_M)\|_2. 
\end{align}
Estimate the Hilbert-Schmidt norm on the right-hand side:
\begin{align*}
\int_{\R^l}\, \int_{\CC^{(2\pi)}}|T(t, x) - & T_M(t, x)|^2 \, dx dt
=  \sum_{|\nu|>M} \int_{\R^l}\, |\hat T_\nu(t)|^2 \, dt\\
\lesssim  &\ \| \tilde A\|_{\plainL2}^2\, \sum_{|\nu|>M} \, \lu \nu\ru^{-2(\a+d)}
\lesssim  M^{-2\a - d}\| \tilde A\|_{\plainL2}^2\lesssim m^{-\frac{2}{q}+ 1}
\| \tilde A\|_{\plainL2}^2.
\end{align*}
By \eqref{eq:finiterank}, 
\begin{align*}
s_{2m}(\iop(T))\lesssim 
m^{-\frac{1}{2}} \bigg(
m^{-\frac{1}{q} + \frac{1}{2}} \ \|\tilde A\|_{\plainL2}\bigg) = 
m^{-\frac{1}{q}}\, \|\tilde A\|_{\plainL2}.
\end{align*}
Thus for any $k: 2m(M)\le k < 2m(M+1)$, we have 
\begin{align*}
s_k(\iop(T))\le s_{2m(M)}(\iop(T))\lesssim \bigg(\frac{k}{m(M)}\bigg)^{\frac{1}{q}}
k^{-\frac{1}{q}} \|\tilde A\|_{\plainL2}\le \bigg(\frac{2 m(M+1)}{m(M)}\bigg)^{\frac{1}{q}}
k^{-\frac{1}{q}} \|\tilde A\|_{\plainL2}.
\end{align*}
Since $m(M+1)\lesssim m(M)$ with a constant independent of $M$, the singular values satisfy the 
bound $s_k(\iop(T))\lesssim k^{-\frac{1}{q}} \|\tilde A\|_{\plainL2}$ 
 for all $k\ge 2m(1)$. The same bound also holds for all $k: 1\le k\le 2 m(1)$ due to the straighforward estimate $s_k(\iop(T))\le \|\iop(T)\|_2 \lesssim \|\tilde A\|_{\plainL2}$. 
\end{proof}

Now we are ready to prove Theorem \ref{thm:kg}.

\subsection{Proof of Theorem \ref{thm:kg}}
Without loss of generality assume that $a$ is constant on each cube $\CC_n=\CC^{(1)}_n$, and write 
$a_n = a(x)\1_n(x)$ where $\1_n$ is the indicator of $\CC_n$.
Consider the 
kernel $W_n(t, x) = T(t, x) a_n \1_n(x)$, so that
\begin{align*}
\iop(T)\,a = \sum_{n\in\Z^d} \, \iop( W_n).
\end{align*}
Let $\eta\in \plainC\infty_0(\CC^{(2\pi)})$  
be a function such that $\eta(x) = 1$ if $x\in \CC$, and denote 
\[
\widetilde W_n(t, x) = T(t, x)\eta_n(x) a_n,\quad \eta_n(x) = \eta(x-n).
\]
 Clearly,  
$s_k\big(\iop(W_n)\big)\le s_k\big(\iop(\widetilde W_n)\big),\  k = 1, 2, \dots$. 
The kernel $T(t, x)\eta_n(x)$ satisfies \eqref{eq:kernelexp} with the function 
$A(t, x)\1_{\CC^{(2\pi)}_n}(x)$. Thus, 
by Lemma \ref{lem:cubepi}, the operator $\widetilde W_n$ belongs to 
$\BS_{q, \infty}$ with $1/q = 1+ \a/d$, and 
\begin{align*}%\label{eq:wn}
\| \iop(W_n)\|_{q, \infty} 
\le &\  \| \iop(\widetilde W_n)\|_{q, \infty}\notag\\[0.2cm]
\lesssim &\ \|A_n\|_{\plainL2(\R^l)}
 \, |a_n|,
 \quad A_n(t) = \|A(t, \,\cdot\,)\|_{\plainL\infty(\CC^{(2\pi)}_n)}, 
\end{align*} 
with a constant independent of $n$. 
Now observe that $\iop(W_k)\, (\iop W_j)^* = 0$ for $k\not = j$. Furthermore, 
since $\a > -d/2$ we have $q < 2$, and hence by Proposition \ref{prop:orthog},
\begin{align*}
\| \iop(T) a\|_{q, \infty}^q\le &\ 2(2-q)^{-1} \sum_{n\in\mathbb Z^d} 
\|\iop(W_n)\|_{q, \infty}^q\\
\lesssim &\  \sum_{n\in\Z^d}\|A_n\|_{\plainL2(\R^l)}^q
 \, \|a\|_{\plainL{\infty}(\CC_n)}^q.
\end{align*}
This completes the proof of \eqref{eq:pivg}.
\qed



\section{Proof of Theorems \ref{thm:main} and \ref{thm:main0}}\label{sect:proof}

We rely on the factorization \eqref{eq:factor} with operators $\Psi$ 
and $\SV$ that are defined in \eqref{eq:psiv}. First we study $\Psi$ and $\SV$. 


\subsection{The weighted operators $\Psi$ and $\SV$}  
For methodological purposes (e.g. for the study of the eigenvalue asymptotics, 
see \cite{Sobolev2022, Sobolev2022a} )
we obtain estimates for the operators $b \Psi a$ and $b \SV a$ 
with weights $a$ and $b$. 
In what follows we use the notation $ \CC^{(r)}_n, n\in\Z^d, r>0,$ 
that was introduced in \eqref{eq:cubes}. For $f\in\plainL2_{\rm loc}(\R^{3N-3})$ define 
the ``weighted" one-particle density (cf. \eqref{eq:dens}) 
\begin{align*}
\rho[f](x) =  
\int_{\R^{3N-3}} \, |f(\hat\bx)|^2 \, |\psi(\hat\bx, x)|^2   \, d\hat\bx,
\end{align*}
and introduce 
the mean value 
\begin{align*}
\tilde f_R(\hat\bx) = \bigg[ \frac{1}{|B(\hat{\mathbf 0}, R)|} 
\int_{B(\hat\bx, R)} |f(\hat\by)|^2\, d\hat\by\bigg]^{\frac{1}{2}},
\end{align*}
where $B(\hat\bx, R)\subset\R^{3N-3}$ is the ball of radius $R>0$ 
centered at $\hat{\bx}$.
Finally, for functions $f\in\plainL2_{\rm loc}(\R^{3N-3})$ and 
$a\in \plainL\infty_{\rm loc}(\R^3)$ define 
\begin{align*}
M_q(a,f) = \bigg[\sum_{n\in\Z^d}
\|\,\rho[f]\,\|_{\plainL1(\CC^{(4\pi)}_n)}^{\frac{q}{2}}\,\|a\|_{\plainL{\infty}(\CC_n)}^{q}
\bigg]^{\frac{1}{q}},\quad q >0.
\end{align*}
Now we are in a position to state $s$-value bounds for the weighted operators 
$b\, \Psi\, a$ and $b\, \SV\, a$. 
We assume that the coefficients $M_q$ on the right-hand sides of the bounds below, are finite. 

\begin{thm}\label{thm:psifull} 
Assume that $b\in\plainL2_{\rm loc}(\R^{3N-3})$ and 
$a\in \plainL\infty_{\rm loc}(\R^3)$. Let $R>0$ be arbitrary. 
Then  $ b \Psi a\in \BS_{3/4, \infty}$, $ b {\sf V} a\in \BS_{1, \infty}$, and 
\begin{align}\label{eq:psi}
\|b\,\Psi\, a\|_{3/4, \infty}\lesssim 
&\ M_{3/4}(a, \tilde b_R),\\ 
\|b\, {\sf V}\, a\|_{1, \infty}\lesssim 
&\ M_{1}(a, \tilde b_R).\label{eq:v}
\end{align}
If \eqref{eq:van} is satisfied, then $ b \Psi a\in \BS_{3/5, \infty}$, 
$b {\sf V} a\in \BS_{3/4, \infty}$, and 
\begin{align}\label{eq:psi0}
\|b\,\Psi\, a\|_{3/5, \infty}\lesssim 
&\ M_{3/5}(a, \tilde b_R),\\
\|b\, {\sf V}\, a\|_{3/4, \infty}\lesssim 
&\ M_{3/4}(a, \tilde b_R).\label{eq:v0}
\end{align}
The constants in the above bounds do not depend on $\psi, b, a$ but may depend on $R$ and $N$.
\end{thm}

\begin{proof}
We use Theorem \ref{thm:kg} with $d=3$ and $l = 3N-3$. 
By \eqref{eq:FS}, the kernel $T(\hat\bx, x) = b(\hat\bx)\psi(\hat\bx, x)$ 
satisfies the bound \eqref{eq:kernelexp} 
with $\a = 1$, $z_j(x) = x_j, j = 1, 2, \dots, N-1$, 
and 
\begin{align}\label{eq:newa}
A(\hat\bx, x) = |b(\hat\bx)|\|\psi\|_{\plainL2(B(\bx, R))},
\end{align}
$\bx = (\hat\bx, x)$. Without loss of generality assume that $R\le \pi$. 
Therefore 
\begin{align*}
A_n(\hat\bx) = \|A(\hat\bx,\,\cdot\,)\|_{\plainL\infty(\CC^{(2\pi)}_n)}\le 
|b(\hat\bx)| 
\|\psi\|_{\plainL2(B_n(\hat\bx))},\ \quad B_n(\hat\bx) = B(\hat\bx, R)\times \CC^{(4\pi)}_{n}.
\end{align*}
As a consequence, 
\begin{align*}
\|A_n\|_{\plainL2(\R^{3N-3})}^2
\le &\ \int_{\R^{3N-3}} \,  |b(\hat\bx)|^2   
\int_{|\hat\by-\hat\bx|<R}   \int_{\CC^{(4\pi)}_n} |\psi(\hat\by, x)|^2\,   
dx\, d\hat\by  d\hat\bx\\
= &\ \int_{\CC^{(4\pi)}_n}\int_{\R^{3N-3}} \,     
\bigg(\int_{|\hat\by-\hat\bx|<R} |b(\hat\bx)|^2 d\hat\bx\bigg) \, |\psi(\hat\by, x)|^2\,
d\hat\by\, dx\\
\lesssim  &\  \int_{\CC_n^{(4\pi)}}  \, \rho[\tilde b_R](x)  \, dx.
\end{align*}
Now the bound \eqref{eq:psi} follows from \eqref{eq:pivg} where $1/q = 1+ \a/3 = 4/3$. 

The kernel $T(\hat\bx, x) = b(\hat\bx)\nabla\psi(\hat\bx, x)$ 
satisfies \eqref{eq:kernelexp} with the function \eqref{eq:newa} and with $\a = 0$. 
A reference to \eqref{eq:pivg} and 
Remark \ref{rem:vector}\eqref{item:vector} leads to \eqref{eq:v}.

Assume the condition \eqref{eq:van}. Rewrite 
$b\Psi a$ using the function $F_0$ defined in \eqref{eq:F0}:
\begin{align*}
b\,\Psi\, a = \iop(b e^{-F_0} \psi)\, e^{F_0} a.
\end{align*}
By Theorem \ref{thm:varphider}, 
the kernel $be^{-F_0} \psi$ satisfies \eqref{eq:kernelexp} with 
$\a = 2$ and the same function \eqref{eq:newa}. 
Apply \eqref{eq:pivg} with $e^{F_0}a$ instead of $a$. Since  $e^{F_0}\lesssim 1$, 
\eqref{eq:pivg} implies \eqref{eq:psi0}. 
For the proof of \eqref{eq:v0} represent $\nabla_x\psi$ as follows:
\begin{align*}
\nabla_x\psi = e^{F_0} \nabla_x \big(e^{-F_0}\psi\big) + \psi\nabla_x F_0,  
\end{align*}
so that 
\begin{align}\label{eq:np}
b\, \SV\, a = \iop(b\, \nabla_x\psi)\, a 
= \iop\big(b \, \nabla_x (\psi e^{-F_0})\big)\, e^{F_0} a 
+ \iop\big( b\, \psi\big)\, a \nabla_x F_0.
\end{align}
By \eqref{eq:varphider},  
the kernel $b \nabla_x(\psi e^{-F_0})$ satisfies \eqref{eq:kernelexp} with $\a = 1$, and the same function $A(\hat\bx, x)$ as before. 
Using \eqref{eq:pivg} again, we obtain 
\eqref{eq:v0} for the first term in \eqref{eq:np}. Since $|\nabla F_0|\lesssim 1$, the bound 
\eqref{eq:v0} for the second term in \eqref{eq:np} follows from \eqref{eq:psi}. 
Using 
\eqref{eq:triangle} or \eqref{eq:pnorm} for the two terms we arrive at \eqref{eq:v0}.
\end{proof}


\subsection{Proof of Theorems \ref{thm:main} and \ref{thm:main0}}
Let $a = 1$ and $b = 1$, so that $\tilde b_R = 1$. 
Thus, by \eqref{eq:star}, it follows from \eqref{eq:factor} and 
\eqref{eq:psi}, \eqref{eq:v} that 
\begin{align*}
\|\iop(\g)\|_{3/8, \infty}
= &\ \|\Psi\|_{3/4, \infty}^2\lesssim M_{3/4}(1,1)^2,\\
\|\iop(\tau)\|_{2, \infty}
= &\ \|\SV\|_{1, \infty}^2 \lesssim M_{1}(1,1)^2. 
\end{align*}
Since 
\begin{align*}
M_q(1, 1)^2 = \bigg[\sum_{n\in\Z^d}
\|\,\rho\,\|_{\plainL1(\CC^{(4\pi)}_n)}^{\frac{q}{2}}\, \bigg]^{\frac{2}{q}}
\lesssim \bigg[\sum_{n\in\Z^d}
\|\,\rho\,\|_{\plainL1(\CC_n)}^{\frac{q}{2}}\, \bigg]^{\frac{2}{q}} 
= \4\, \rho\, \4\,_{{q}/2} , 
\end{align*}
the above bounds imply Theorem \ref{thm:main}.
The bounds \eqref{eq:gbound0} and \eqref{eq:taubound0} follow from 
\eqref{eq:psi0} and \eqref{eq:v0} in the same way. 
\qed






