\section{Preliminaries}
\label{sec:2}
\subsection{The thermoelastic scattering problem}
\label{sec:2.1}

Let $\Gamma$ denote a smooth open-arc in the plane $\mathbb{R}^2$. The
complement of $\Gamma$ in $\mathbb{R}^2$ is occupied by the medium of propagation, a linear isotropic and homogeneous thermoelastic medium of Biot type, characterized by the Lam\'e
constants $\lambda, \mu$ (satisfying $\mu>0$, $\lambda+\mu>0$),
the constant mass density $\rho>0$, the coefficient of thermal
diffusity $\kappa$ and the coupling constants $\gamma$ and
$\eta$ are given by
\ben
\gamma=(\lambda+\frac{2}{3}\mu)\,\alpha,\quad\eta=\frac{T_0\gamma}{\lambda_0},
\enn
respectively, where $\alpha$ is the volumetric thermal expansion coefficient,
$T_0$ is a reference value of the absolute temperature and $\lambda_0$
is the coefficient of thermal conductivity. Denote by $\epsilon$ :=$\gamma\eta\kappa/(\lambda+2\mu) $
the dimensionless thermoelastic coupling constant which assumes "small" positive values
for most thermoelastic media and $q=i\omega/\kappa$.
Suppressing the time-harmonic dependence
$e^{-i\omega t}$ in which $\omega>0$ is the frequency, the
displacement field $\bm u(\bm x)=(u_1(x_1,x_2), \,u_2(x_1,x_2))^{\top}$ and the temperature variation field $p(\bm x)=p(x_1,x_2)$ can be modeled by the following Biot
system of linearized thermoelasticity
\begin{numcases}{}
\label{navier}
\Delta^*\bm u+\rho\omega^2\bm u-\gamma\nabla p=0 \quad\mbox{in}\quad\R^2\backslash\Gamma,  \\
\label{navier2}
\Delta p+qp+i\omega\eta\nabla\cdot \bm u=0 \quad\mbox{in}\quad\R^2\backslash\Gamma.
\end{numcases}
Here $\Delta^*$ is the Lam\'e operator defined by
\ben
\Delta^* = \mu\,\mbox{div}\,\mbox{grad} + (\lambda + \mu)\,\mbox{grad}\, \mbox{div}\,. \enn
Rewriting (\ref{navier})-(\ref{navier2}) into a matrix form, we obtain
\be
\label{13}
\mathbb{L}\bm U=0, \quad \mathbb{L}=\begin{pmatrix}
  (\mu\Delta + \rho \omega ^2)I_2+(\lambda +\mu )\nabla\nabla\cdot & -\gamma \nabla \\
  q\eta \kappa \nabla\cdot & \Delta +q   \end{pmatrix},
  \quad \bm U=\begin{pmatrix} \bm u\\p \end{pmatrix}\,. \en
On $\Gamma$, four different kinds of boundary conditions \cite{K79,C00} taking the forms $\mathbb{B}_i(\pa,\bm\nu)\bm U=\bm G_i$ on $\Gamma$, $i=1,2,3,4$, will be considered.
\begin{itemize}
\item 1st-kind (Dirichlet-type):
\be \label{14}
\mathbb{B}_1(\pa,\bm\nu)=\mathbb{I}_3
\en
\item 2nd-kind (Neumann-type):
\be \label{15}
\mathbb{B}_2(\pa,\bm\nu)=\begin{pmatrix}
  \bm T(\pa,\bm\nu) & -\gamma\bm\nu \\ 0 & \pa_{\bm\nu}  \end{pmatrix} 
\en
\item 3rd-kind (mixed-type):
\be  \label{17} \mathbb{B}_3(\pa,\bm\nu):=\begin{pmatrix}
  \mathbb{I}_2 & 0 \\0 &\pa_{\bm\nu} \end{pmatrix} \en
\item 4th-kind (mixed-type):
  \be  \label{16} 
\mathbb{B}_4(\pa,\bm\nu):=\begin{pmatrix}
  \bm T(\pa,\bm\nu) & -\gamma\bm\nu \\0 & -1 \end{pmatrix}
 \en
\end{itemize}
Here, $\mathbb{I}_n$ denotes a $n\times n$ identity operator, $\bm T(\pa,\bm\nu)$ is the traction operator on the
boundary defined as \ben \bm T(\pa,\bm\nu)\bm u:=2\mu\,\pa_{\bm\nu}\,\bm u+\lambda \bm\nu\,\mbox{div}\bm u
+\mu\bm\nu\times\mbox{curl}\bm u, \qquad \bm\nu=(\nu_1,\nu_2){^\top}, \enn
in which $\bm\nu$ is the outward unit normal to the boundary $\Gamma$
and $\pa_{\bm\nu}=\bm\nu\cdot\nabla$ is the normal derivative. In addition, to ensure the uniqueness of the thermoelastic problem, the scattered field $\bm U$ is assumed to satisfy appropriate radiation conditions at infinity and we refer to \cite[Theorem 3.1]{C00} for the uniqueness of the four thermoelastic open-arc scattering problems.

\subsection{Boundary integral equations}
\label{sec:2.2}

Now we introduce the solution representations and BIEs associated with the considered thermoelastic scattering problems. Let $\mathbb{E}({\bm x},{\bm y})$ be the fundamental solution of the adjoint operator $\mathbb{L}^*$ of $\mathbb{L}$ in $\mathbb{R}^2$ given by
\ben \mathbb{E}(x,y)=\begin{pmatrix}
  \mathbb{E}_{11}({\bm x},{\bm y}) & \bm E_{12}({\bm x},{\bm y}) \\ \bm E_{21}^{\top}({\bm x},{\bm y}) & E_{22}({\bm x},{\bm y}) \end{pmatrix} ,\enn
with
\begin{align*}
&\mathbb{E}_{11}({\bm x},{\bm y})=\frac{1}{\mu}\gamma_{k_s}({\bm x},{\bm y})I+\frac{1}{\rho \omega^2}\nabla_x \nabla_x^{\top}
[\gamma_{k_s}({\bm x},{\bm y})-\frac{k_p^{2}-k_2^{2}}{k_1^{2}-k_2^{2}}\gamma_{k_1}({\bm x},{\bm y})+\frac{k_p^{2}-k_1^{2}}{k_1^{2}-k_2^{2}}\gamma_{k_2}({\bm x},{\bm y})], \\
&\bm E_{12}({\bm x},{\bm y})=\frac{i\omega\eta}{(k_1^{2}-k_2^{2})(\lambda+2\mu)}\nabla_x [\gamma_{k_1}({\bm x},{\bm y})-\gamma_{k_2}({\bm x},{\bm y})], \\
&\bm E_{21}({\bm x},{\bm y})=-\frac{\gamma}{(k_1^{2}-k_2^{2})(\lambda+2\mu)}\nabla_x[\gamma_{k_1}({\bm x},{\bm y})-\gamma_{k_2}({\bm x},{\bm y})], \\
&E_{22}({\bm x},{\bm y})=-\frac{1}{k_1^{2}-k_2^{2}}[(k_p^{2}-k_1^{2})\gamma_{k_1}({\bm x},{\bm y})-(k_p^{2}-k_2^{2})\gamma_{k_2}({\bm x},{\bm y})], \end{align*}
where $\gamma_k ({\bm x},{\bm y})$ denotes the fundamental solution of the Helmholtz equation in $\R^2$ with wavenumber $k$ which takes the form
\be \label{gak}  \gamma_k({\bm x},{\bm y})=\frac{i}{4}H_0^{(1)}(k|{\bm x}-{\bm y}|),\quad x\neq y.  \en
The wavenumbers $k_1$, $k_2$, corresponding to the elastothermal and thermoelastic
waves respectively, are the roots of the characteristic system
\be k_1^{2}+k_2^{2}=q(1+\epsilon )+k_p^{2}, \quad k_1^{2} k_2^{2}=q k_p^{2}, \quad \mu k_s^{2}=\rho \omega^2, \en
for which $k_p:=\omega \sqrt{\rho /(\lambda+2\mu)}$
is the wavenumber of the longitudinal wave in the absence of thermal coupling and
$k_s:=\omega \sqrt{\rho /\mu}$ is the wavenumber of the uncoupled transverse wave. In particular, $\mathrm{Re}\{k_j\}> 0$ and $\mathrm{Im}\{k_j\}> 0$ \cite{WLXY} for $j=1,2$.

Denote by $\mathbb{B}_i^*(\pa,\bm\nu)$ the adjoint operators of $\mathbb{B}_i(\pa,\bm\nu)$ for $i=1,2,3,4$ associated with the Biot system. It can be derived that
\ben
\mathbb{B}_1^*(\pa,\bm\nu)=\mathbb{B}_1(\pa,\bm\nu),\quad \mathbb{B}_2^*(\pa,\bm\nu):=\begin{pmatrix}
  \bm T(\pa,\bm\nu) & -i\omega \eta \bm\nu \\ 0 &\pa_{\bm \nu}
\end{pmatrix},\\
 \mathbb{B}_3^{*}(\pa,\bm\nu)=\mathbb{B}_3(\pa,\bm\nu), \quad
\mathbb{B}_4^{*}(\pa,\bm \nu):=\begin{pmatrix}
  \bm T(\pa,\bm\nu) & -i\omega \eta \bm\nu \\ 0& -1 \end{pmatrix}.
\enn
Then the solution to the open-arc thermoelastic scattering problems can be represented as
\be
\label{solrep}
\bm U(\bm x)=\mathcal{S}_i[\bm\psi_i](\bm x):=\int _{\Gamma}(\mathbb{B}_i^{*}(\pa_{\bm y},\bm\nu_{\bm y})\mathbb{E}({\bm x},{\bm y}))^{\top}\bm \psi_i ({\bm y})d s_{\bm y}, \quad  {\bm x}\in \R^2\backslash \Gamma, \quad i =1,2,3,4,
\en
with the corresponding unknown potentials $\bm\psi_i=(\bm \varphi_i,\psi_i)$ satisfying the BIE
\be
\label{BIE}
\bm V_i[\bm\psi_i]=\bm G_i\quad\mbox{on}\quad \Gamma,
\en
where $\bm V_i$ is a BIO defined as
\be
\label{operatorVi}
\bm V_i[\bm\psi_i](\bm x)=\int _{\Gamma}\mathbb{B}_i(\pa_{\bm x},\bm\nu_{\bm x})(\mathbb{B}_i^{*}(\pa_{\bm y},\bm\nu_{\bm y})\mathbb{E}({\bm x},{\bm y}))^{\top}\bm \psi_i ({\bm y})d s_{\bm y}, \quad  {\bm x}\in \Gamma, \quad i=1,2,3,4.
\en
\tao{Through out of this paper, the strongly- and hyper-singular boundary integrals appearing in $\bm V_i, i=2,3,4$ and the forthcoming BIOs in the following sections are defined in the sense of Cauchy principle value or Hadmard finite part, respectively.}


Assuming that $\Gamma\subset\partial\Omega$ where $\partial\Omega$ is a smooth
boundary of a bounded domain $\Omega$ in $\mathbb{R}^2$, we denote by $\widetilde H^s(\Gamma)$ the space of all $f\in H^s(\partial\Omega)$ such that $\mathrm{supp}(f)\subset\overline{\Gamma}$. Then it can be shown~\cite[Theorem 4.1]{C00} that $\bm V_1: \widetilde H^{-1/2}(\Gamma)^3\rightarrow H^{1/2}(\Gamma)^3$, $\bm V_2: \widetilde H^{1/2}(\Gamma)^3\rightarrow H^{-1/2}(\Gamma)^3$,  $\bm V_3: \widetilde H^{-1/2}(\Gamma)^2\times\widetilde H^{1/2}(\Gamma) \rightarrow H^{1/2}(\Gamma)^2\times H^{-1/2}(\Gamma)$ and $\bm V_
4: \widetilde H^{1/2}(\Gamma)^2\times\widetilde H^{-1/2}(\Gamma) \rightarrow H^{-1/2}(\Gamma)^2\times H^{1/2}(\Gamma)$ are bicontinuous, i.e., continuous and invertible.

\begin{theorem}
Suppose that $\bm G_1\in H^{1/2}(\Gamma)^3$, $\bm G_2\in H^{-1/2}(\Gamma)^3$, $\bm G_3\in H^{1/2}(\Gamma)^2\times H^{-1/2}(\Gamma)$ and $\bm G_4\in H^{-1/2}(\Gamma)^2\times H^{1/2}(\Gamma)$, the four BIEs admit unique solutions in $\widetilde H^{-1/2}(\Gamma)^3$, $\widetilde H^{1/2}(\Gamma)^3$, $\widetilde H^{-1/2}(\Gamma)^2\times\widetilde H^{1/2}(\Gamma)$ and $\widetilde H^{1/2}(\Gamma)^2\times\widetilde H^{-1/2}(\Gamma)$, respectively.
\end{theorem}

\section{Regularized boundary integral equations}
\label{sec:3}

The fact that the boundary integral operator (BIO) $\bm V_1$ is weakly singular, while the operators $\bm V_i$, $i = 2, 3, 4$, are all hypersingular—due to the presence of second-order derivatives in the operators $T(\partial, \bm \nu)$ and/or $\partial_{\bm \nu}$—introduces several challenges:

\begin{itemize} \item[(1)] The eigenvalues of the single-layer operator $\bm V_1$ and the hypersingular operators $\bm V_i$, $i = 2, 3, 4$, form sequences that accumulate at zero and infinity, respectively. As a result, employing Krylov-subspace iterative solvers such as GMRES to solve the corresponding discretized linear systems typically requires a large number of iterations.

\item[(2)] The solutions to the boundary integral equations (BIEs) \eqref{BIE} exhibit singular behavior near the endpoints of the open arc, depending on the type of boundary conditions. This introduces additional difficulties in achieving high accuracy and reducing the number of GMRES iterations in numerical implementations.

\item[(3)] The numerical evaluation of strongly and hypersingular integrals must be properly regularized to ensure computational efficiency. \end{itemize}

Each of these issues will be addressed in the following subsections.

\subsection{Spectrum for closed boundaries}
\label{sec:3.1}

\jp{To reduce the number of GMRES iterations for the solution of (\ref{BIE}), we rely on analytic preconditioning constructed from the Calder\'on identities for the corresponding BIOs. } 

In this subsection, we let $\Gamma=\Gamma_c$ be a smooth closed-curve which is the boundary of a bounded domain $\Omega^-$, i.e., $\Gamma_c=\partial\Omega^-$. The exterior domain $\mathbb{R}^2\backslash\overline{\Omega^-}$ is denoted by $\Omega^+$. Denote
\begin{align*}
& \bm K[\bm \psi](\bm x)= \int _{\Gamma_c}(\mathbb{B}_2^{*}(\pa_{\bm y},\bm\nu_{\bm y})\mathbb{E}({\bm x},{\bm y}))^{\top}\bm \psi ({\bm y})d s_{\bm y}, \quad  {\bm x}\in \Gamma,\\
& \bm K'[\bm \psi](\bm x)= \int _{\Gamma_c}\mathbb{B}_2(\pa_{\bm x},\bm\nu_{\bm x})\mathbb{E}^\top({\bm x},{\bm y})\bm \psi ({\bm y})d s_{\bm y}, \quad  {\bm x}\in \Gamma,\\
& \bm P[\bm\psi](\bm x)=\int _{\Gamma_c}\mathbb{B}_4(\pa_{\bm x},\bm\nu_{\bm x})(\mathbb{B}_3^{*}(\pa_{\bm y},\bm\nu_{\bm y})\mathbb{E}({\bm x},{\bm y}))^{\top}\bm \psi ({\bm y})d s_{\bm y}, \quad  {\bm x}\in \Gamma,\\
& \bm Q[\bm\psi](\bm x)=\int _{\Gamma_c}\mathbb{B}_3(\pa_{\bm x},\bm\nu_{\bm x})(\mathbb{B}_4^{*}(\pa_{\bm y},\bm\nu_{\bm y})\mathbb{E}({\bm x},{\bm y}))^{\top}\bm \psi ({\bm y})d s_{\bm y}, \quad  {\bm x}\in \Gamma.
\end{align*}
Let us introduce the matrix block of the operators, 
$$
\bm{K}  = \begin{pmatrix}
 \bm{K}_{11} & \bm{K}_{12}\\
 \bm{K}_{21} & \bm{K}_{22}
\end{pmatrix}, \bm{K}'  = \begin{pmatrix}
 \bm{K}_{11}' & \bm{K}_{12}'\\
 \bm{K}_{21}' & \bm{K}_{22}'
\end{pmatrix}, \quad 
\bm{V}_i  = \begin{pmatrix}
 \bm{V}_{i,11} & \bm{V}_{i,12}\\
 \bm{V}_{i,21} & \bm{V}_{i,22}
\end{pmatrix}, \ i = 1,2,3,4.
$$

\begin{lemma}
\label{lemma:repPQ}
The matrix blocks of the operators $\bm{V}_3, \bm{V}_4$, $\bm{P}$ and $\bm{Q}$ are given by:
\begin{align*}
    \bm{V}_3  = \begin{pmatrix}
        \bm{V}_{1,11}  & \bm{K}_{12} \\
         \bm{K}'_{21} & \bm{V}_{2,22}
    \end{pmatrix}, \quad
    \bm{V}_4  = \begin{pmatrix}
        \bm{V}_{2,11}  & -\bm{K}'_{12} \\
        - \bm{K}_{21} & \bm{V}_{1,22}
    \end{pmatrix} , 
\end{align*}
and
\begin{align*}
    \bm{P} = \begin{pmatrix}
    \bm{K}'_{11} & \bm{V}_{2,12} \\
    -\bm{V}_{1,21} & -\bm{K}_{22}
    \end{pmatrix}, \quad \bm{Q} = \begin{pmatrix}
    \bm{K}_{11} & -\bm{V}_{1,12} \\
    \bm{V}_{2,21} & -\bm{K}'_{22}
    \end{pmatrix}.
\end{align*}
\end{lemma}
\begin{proof}
The result can be obtained by directly computing the associated singular kernels for each of the BIOs. The details are omitted, as they do not provide meaningful information.
\end{proof}

