\begin{lemma}
\label{lem-jump}
Define
\ben
\mathbb{B}_i^{\pm}\bm v(\bm x)= \lim_{h\rightarrow 0^+, \bm z=\bm x\pm h\bm\nu_{\bm x}} \mathbb{B}_i(\pa_{\bm z},\bm\nu_{\bm x})\bm v(\bm z),\quad x\in\Gamma.
\enn
Then the following jump relations hold:
\begin{align}
\label{jump1}
& \mathbb{B}_2^{\pm} \mathcal{S}_1[\bm\psi]  = \bm{K}'[\bm \psi]\mp \frac{1}{2} \bm \psi,\\
\label{jump2}
& \mathbb{B}_1^{\pm} \mathcal{S}_2[\bm\psi] =  \bm{K}[\bm \psi]\pm \frac{1}{2}\bm \psi,\\
\label{jump3}
& \mathbb{B}_4^{\pm} \mathcal{S}_3[\bm\psi]  = \bm{P}[\bm \psi] \mp \frac{1}{2} \bm \psi,\\
\label{jump4}
& \mathbb{B}_3^{\pm} \mathcal{S}_4[\bm\psi]  = \bm{Q}[\bm \psi] \pm \frac{1}{2}  \bm \psi .
\end{align}
\end{lemma}
\begin{proof}
\jp{The first two identities are the standard relations for the traces of the single-layer and double-layer potentials. The last two follow from the first relations, combined with the jump relations of the potentials and Lemma \ref{lemma:repPQ}. We also refer the reader to \cite[Ch. X, \S 2]{K79} for a detailed analysis.}
\end{proof}

\begin{lemma}
\label{lem-calderon}
For the thermoelastic scattering by closed-surfaces, the Calder\'on identities
\be  
\label{calc}  
\bm V_2\bm V_1=-\frac{\mathbb{I}_3}{4}+(\bm K')^2, \quad \bm V_1\bm V_2=-\frac{\mathbb{I}_3}{4}+\bm K^2,
\en
and
\be
\label{calc2}
\bm V_4\bm V_3=-\frac{\mathbb{I}_3}{4}+\bm P^2, \quad 
\bm V_3\bm V_4=-\frac{\mathbb{I}_3}{4}+\bm Q^2,
\en
hold.
\end{lemma}
\begin{proof}
Let $\bm U$ be a solution to the thermoelastic equation in $\mathbb{R}^2 \backslash \Gamma_c$ that satisfies the Kupradze radiation condition. Denote the jump of $\mathbb{B}_i \bm U$ across the boundary $\Gamma_c$ by $$[\mathbb{B}_i \bm U]=\mathbb{B}_i^- \bm U -\mathbb{B}_i^+ \bm U , \quad i=1,2,3,4.$$ t follows from the solution representation of layer potentials (see \cite{K79}) that \begin{equation} \label{rep} \bm U(\bm x) = \mathcal{S}_1\big[ [\mathbb{B}_2 \bm U] \big] - \mathcal{S}_2\big[ [\mathbb{B}_1 \bm U] \big], \quad \forall, \bm x \in \mathbb{R}^2 \backslash \Gamma_c. \end{equation} By directly evaluating the right-hand side of \eqref{rep}, we obtain an alternative representation: \begin{equation} \label{rep2} \bm U(\bm x) = \mathcal{S}_3\big[ [\mathbb{B}_4 \bm U] \big] - \mathcal{S}_4\big[ [\mathbb{B}_3 \bm U] \big], \quad \forall, \bm x \in \mathbb{R}^2 \backslash \Gamma_c. \end{equation} Using the jump relations stated in Lemma~\ref{lem-jump}, we define the following operators:
\ben
\bm C_1=\frac{\mathbb{I}_3}{2}+
\begin{pmatrix}
-\bm K & \bm V_1\\
-\bm V_2 & \bm K'
\end{pmatrix},\quad \bm C_2=\frac{\mathbb{I}_3}{2}+
\begin{pmatrix}
-\bm Q & \bm V_3\\
-\bm V_4 & \bm P
\end{pmatrix}.
\enn
These operators are projectors, i.e., $\bm C_i^2 = \bm C_i$, for $i = 1,2$. The desired Calderón identities then follow.

\end{proof}

\begin{lemma}
\label{Kspectrum}
It holds that $\bm K^2 - \bm I_{\lambda,\mu}: H^{1/2}(\Gamma)^3\rightarrow H^{1/2}(\Gamma)^3$, $(\bm K')^2 - \bm I_{\lambda,\mu}: H^{-1/2}(\Gamma)^3\rightarrow H^{-1/2}(\Gamma)^3$, $\bm P^2 - \bm I_{\lambda,\mu}: H^{-1/2}(\Gamma)^2\times H^{1/2}(\Gamma)\rightarrow H^{-1/2}(\Gamma)^2\times H^{1/2}(\Gamma)$ and $\bm Q^2 - \bm I_{\lambda,\mu}: H^{1/2}(\Gamma)^2\times H^{-1/2}(\Gamma)\rightarrow H^{1/2}(\Gamma)^2\times H^{-1/2}(\Gamma)$ are compact where 
\ben
\bm I_{\lambda,\mu}=\begin{pmatrix}
 C_{\lambda ,\mu }^2\mathbb{I}_2 & 0\\
 0 & 0
 \end{pmatrix},
\enn
with $C_{\lambda,\mu}$ being a constant given by
\ben
C_{\lambda ,\mu }= \frac{\mu }{2(\lambda  + 2\mu )} < \frac{1}{2}.
\enn
\end{lemma}
\begin{proof}
Note that the thermoelastic scattering problem takes an analogous Biot system as the poroelastic scattering problem~\cite{S09,SSU09}. Then the compactness of $(\bm K)^2 - \bm I_{\lambda,\mu}$ and $(\bm K')^2 - \bm I_{\lambda,\mu}$ can be shown by following the proof of \cite[Theorem 3.1]{ZXY21}. To show the compactness of $(\bm P)^2 - \bm I_{\lambda,\mu}$, we note from the matrix blocks of $\bm P$ that
\ben
(\bm P)^2 - \bm I_{\lambda,\mu}= \begin{pmatrix}
(\bm{K}'_{11})^2-\bm{V}_{2,12}\bm{V}_{1,21} -C_{\lambda ,\mu }^2\mathbb{I}_2 & \bm{K}'_{11}\bm{V}_{2,12}-\bm{V}_{2,12}\bm{K}_{22}\\ -\bm{V}_{1,21}\bm{K}'_{11}+ \bm{K}_{22}\bm{V}_{1,21} & -\bm{V}_{1,21}\bm{V}_{2,12}+\bm{K}_{22}^2
\end{pmatrix},
\enn
\jp{the result is then a direct consequence of the compactness of the first component of $(\bm K')^2 - \bm I_{\lambda,\mu}$, and Lemma \ref{lemma:compactness1}. The proof for $(\bm Q)^2 - \bm I_{\lambda,\mu}$ is essentially the same. } 
%Analogous steps of the proof can be found in the proof of Theorem~\ref{V34}.
\end{proof}

