\subsection{Regularization of Singular Integrals}
\label{sec:3.4}
Now we are ready to study the regularization techniques for the treatment of strongly- and hyper-singular integrals in numerical evaluation. To avoid repetitive and redundant deductions, here we only present the result for the operator $\bm V_4^w$. The regularized formulations for $\bm V_i^w$, $i=2,3$ can be derived in an analogous manner and we present the details in the appendix.

Denoting 
\ben
\bm V_i^w[\bm\psi]=\begin{pmatrix}
\bm V_{i,11}^w & \bm V_{i,12}^w\\
\bm V_{i,21}^w & V_{i,22}^w
\end{pmatrix}\begin{pmatrix}
\bm\phi \\ \psi
\end{pmatrix}, \quad i=2,3,4,
\enn
it follows that
\begin{align*}
\bm V_{4,11}^w[\bm\phi](x)=& \int_\Gamma \big[\bm T(\pa_{\bm x},\bm\nu_{\bm x})(\bm T(\pa_{\bm y},\bm\nu_{\bm y})\mathbb{E}_{11}(\bm x,\bm y))^{\top}-i\omega\eta \bm T(\pa_{\bm x},\bm\nu_{\bm x})\bm E_{21}(\bm x,\bm y)\bm\nu_{\bm y}^{\top}   \\
&\,-\gamma {\bm\nu}_{\bm x}(\bm T(\pa_{\bm y},\bm\nu_{\bm y})\bm E_{12}(\bm x,\bm y))^{\top}+i\omega\eta\gamma\bm\nu_{\bm x} \bm \nu_{\bm y}^{\top}E_{22}(\bm x,\bm y)\big] w(\bm y) \bm \phi(\bm y)ds_{\bm y},\quad  \bm x\in\Gamma,\\
\bm V_{4,12}^w[\psi](x)=& \int_\Gamma \left[-\bm T(\pa_{\bm x},\bm\nu_{\bm x}) \bm E_{21}(\bm x,\bm y) +\gamma \bm\nu_{\bm x} E_{22}(\bm x,\bm y)\right]\frac{\psi(\bm y)}{w(\bm y)}ds_{\bm y} ,\quad \bm x\in\Gamma,\\
\bm V_{4,21}^w[\bm\phi](x)=& \int_\Gamma \left[-(\bm T(\pa_{\bm y},\bm\nu_{\bm y})\bm E_{12}(\bm x,\bm y))^{\top}+i\omega\eta \bm \nu_{\bm y}^{\top}E_{22}(\bm x,\bm y)\right] w(\bm y)\bm \phi(\bm y) ds_{\bm y} ,\quad x\in\Gamma,\\
\bm V_{4,22}^w[\psi](x)=& \int_\Gamma E_{22}(\bm x,\bm y) \frac{\psi(\bm y)}{w(\bm y)}ds_{\bm y} ,\quad \bm x\in\Gamma.  
\end{align*}
The regularized formulations for $\bm V_{4,11}^w, \bm V_{4,12}^w$ and $\bm V_{4,21}^w$ are concluded in the following theorem. Several new notations will be used. Denote $\mathbb{J}_{\bm \nu_{\bm x} ,\bm \nu_{\bm y}}:=\bm\nu_{\bm y} \bm \nu_{\bm x}^{\top}-\bm\nu_{\bm x} \bm \nu_{\bm y}^{\top}$. The constants $C_i, \,i=1,2,3$ are defined by
\begin{align*}
C_1&=\frac{i\omega\eta\gamma(k_p^{2}+k_1^{2})-k_1^{2}(k_1^{2}-q)(\lambda+2\mu)}{k_1^{2}-k_2^{2}}, \\
C_2&=\frac{i\omega\eta\gamma(k_p^{2}+k_2^{2})-k_2^{2}(k_2^{2}-q)(\lambda+2\mu)}{k_1^{2}-k_2^{2}}, \\
C_3&=\frac{2\mu}{k_1^{2}-k_2^{2}}(\frac{i\omega\eta\gamma}{\lambda+2\mu}-k_2^{2}+q). 
\end{align*}
The weighted tangential operator $D_s^w$ is given by
\ben
D_s^w[v]= w^2D_s[v] + \frac{v}{2}D_s[w^2],
\enn
with $D_s$ denoting the tangential derivative. To simplify the proof of the regularized formulations, the G\"unter derivative $\bm M(\pa, \bm \nu)$ \cite{BSY20,HW08} is introduced in the form of
\ben 
\bm M(\pa,\bm \nu) \bm u= \pa_{\bm \nu} \bm u-\bm \nu (\nabla \cdot \bm u) + \bm \nu \times \mbox{curl}  \bm u.
\enn
Moreover, the G\"unter derivative and the tangential derivative satisfy the following relation:
\ben
\bm M(\pa, \bm \nu) \bm u = \mathbb{A} D_s [\bm u] , \quad \mathbb{A} =\begin{pmatrix}  0 & -1 \\ 1 & 0 \end{pmatrix}.
\enn

\begin{theorem}
\label{regV3}
The integral operators $\bm V_{4,11}^w, \bm V_{4,12}^w$ and $\bm V_{4,21}^w$ can be re-expressed as
\begin{align}
\label{RegV311}
& \bm V_{4,11}^w = \bm V_{4,11}^{w,1} + D_s\bm V_{4,11}^{w,2}D_s^w + \bm V_{4,11}^{w,3}D_s^w+ D_s\bm V_{4,11}^{w,4} ,\\
\label{RegV312}
& \bm V_{4,12}^w = \bm V_{4,12}^{w,1} + D_s\bm V_{4,12}^{w,2}, \\
\label{RegV313}
& \bm V_{4,21}^w= \bm V_{4,21}^{w,1}+ \bm V_{4,21}^{w,2}D_s^w,
\end{align}
where $\bm V_{4,11}^{w,1}[\bm\phi]=\bm V_{4,11}^{1}[w\bm\phi]$, $\bm V_{4,11}^{w,2}[\bm\phi]=\bm V_{4,11}^{2}[w^{-1}\bm\phi]$, $\bm V_{4,11}^{w,3}[\bm\phi]=\bm V_{4,11}^{3}[w^{-1}\bm\phi]$, $\bm V_{4,11}^{w,4}[\bm\phi]=\bm V_{4,11}^{4}[w\bm\phi]$, $\bm V_{4,12}^{w,1}[\psi]=\bm V_{4,12}^{1}[w^{-1}\psi]$, $\bm V_{4,12}^{w,2}[\psi]=\bm V_{4,12}^{2}[w^{-1}\psi]$, $\bm V_{4,21}^{w,1}[\bm\phi]=\bm V_{4,21}^{1}[w\bm\phi]$ and $\bm V_{4,21}^{w,2}[\bm\phi]=\bm V_{4,21}^{2}[w^{-1}\bm\phi]$, and the integral operators
\begin{align*}
\bm V_{4,11}^{1}[\bm\phi]= & -\rho \omega^2 \int_\Gamma \gamma_{k_s}(\bm x,\bm y)(\bm\nu_{\bm x} \bm \nu_{\bm y}^{\top}-\bm\nu_{\bm x}^{\top}\bm \nu_{\bm y} \mathbb{I}_2-\mathbb{J}_{\bm \nu_{\bm x} ,\bm \nu_{\bm y}})\bm\phi(\bm y)d s_{\bm y}\\
& -\int_{\Gamma}[C_1 \gamma_{k_1}(\bm x,\bm y)-C_2 \gamma_{k_2}(\bm x,\bm y)]\bm\nu_{\bm x} \bm \nu_{\bm y}^{\top} \bm\phi(\bm y)d s_{\bm y},\\
\bm V_{4,11}^{2}[\bm\phi] = & \int_\Gamma \left[4\mu\gamma_{k_s}(\bm x,\bm y) \mathbb{I}_2+ 4\mu^2 \mathbb{A} \mathbb{E}_{11}(\bm x,\bm y) \mathbb{A} \right]\bm\phi(\bm y)d s_{\bm y},\\
\bm V_{4,11}^{3}[\bm\phi] = &  \int_\Gamma \bm\nu_{\bm x} \nabla_{\bm x}^{\top} [-2\mu \gamma_{k_s}(\bm x,\bm y)+(2\mu-C_3)\gamma_{k_1}(\bm x,\bm y)+C_3\gamma_{k_2}(\bm x,\bm y)] \mathbb{A} \bm\phi(\bm y)d s_{\bm y},\\
\bm V_{4,11}^{4}[\bm\phi] = &  \int_\Gamma \mathbb{A}\nabla_{\bm y} [-2\mu \gamma_{k_s}(\bm x,\bm y)+(2\mu-C_3)\gamma_{k_1}(\bm x,\bm y)+C_3\gamma_{k_2}(\bm x,\bm y)] \bm\nu_{\bm y}^\top \bm\phi(\bm y)d s_{\bm y},\\
\bm V_{4,12}^{1}[\psi]= & -\frac{\gamma k_p^2}{k_1^2 - k_2^2}\int_\Gamma \bm\nu_{\bm x}\left[\gamma_{k_1}(\bm x,\bm y)- \gamma_{k_2}(\bm x,\bm y)\right] \psi(\bm y)ds_{\bm y},\\
\bm V_{4,12}^{2}[\psi]= & \frac{2\mu\gamma}{(\lambda  + 2\mu )(k_1^2 - k_2^2)} \int_\Gamma \mathbb{A}\nabla_{\bm x}\left[\gamma_{k_1}(\bm x,\bm y) - \gamma _{k_2}(\bm x,\bm y)\right]\psi(\bm y)ds_{\bm y},\\
\bm V_{4,21}^{1}[\bm\phi]= & -\frac{i\omega\eta k_p^2}{k_1^2 - k_2^2}\int_\Gamma \left[\gamma_{k_1}(\bm x,\bm y)- \gamma_{k_2}(\bm x,\bm y)\right]\bm\nu_{\bm y}^\top \bm\phi(\bm y)ds_{\bm y},\\
\bm V_{4,21}^{2}[\bm\phi]= & -\frac{2i\omega\eta\mu}{(\lambda  + 2\mu )(k_1^2 - k_2^2)}\int_\Gamma \nabla_{\bm x}^\top\left[\gamma_{k_1}(\bm x,\bm y) - \gamma _{k_2}(\bm x,\bm y)\right] \mathbb{A}\bm\phi(\bm y)ds_{\bm y},
\end{align*}
are all at most weakly-singular.
\end{theorem}
\begin{proof}
Since the kernel of the operator $\bm V_{4,11}^w$ is similar as the operator $N_1$ in \cite{ZXY21}, following the proof of \cite[Lemma 3.3]{ZXY21} and carefully treating the tangential derivative $D_s(w\bm\phi)$ yield the regularized formulation (\ref{RegV311}). Note that
\ben
\bm T(\partial ,\bm\nu )\nabla  = (\lambda  + 2\mu )\bm \nu \Delta  + 2\mu \bm M(\partial ,\bm\nu )\nabla ,
\enn
since
\ben
{\partial _{\bm\nu} }\nabla  - \bm M(\partial ,\bm\nu )\nabla  = \bm \nu \Delta .
\enn
Then we have
\begin{align*}
\bm V_{4,12}^w[\psi](x)=& -\frac{\gamma k_p^2}{k_1^2 - k_2^2}\int_\Gamma \bm\nu_{\bm x}\left[\gamma_{k_1}(\bm x,\bm y)- \gamma_{k_2}(\bm x,\bm y)\right] \frac{\psi(\bm y)}{w(\bm y)}ds_{\bm y}\\ 
& +\frac{2\mu\gamma}{(\lambda  + 2\mu )(k_1^2 - k_2^2)}D_{s_{\bm x}}\int_\Gamma \mathbb{A}\nabla_{\bm x}\left[\gamma_{k_1}(\bm x,\bm y) - \gamma _{k_2}(\bm x,\bm y)\right]\frac{\psi(\bm y)}{w(\bm y)}ds_{\bm y},
\end{align*}
and
\begin{align*}
\bm V_{4,21}^w[\bm\phi](x)=& -\frac{i\omega\eta k_p^2}{k_1^2 - k_2^2}\int_\Gamma \left[\gamma_{k_1}(\bm x,\bm y)- \gamma_{k_2}(\bm x,\bm y)\right]\bm\nu_{\bm y}^\top \bm\phi(\bm y)w(\bm y)ds_{\bm y}\\
& -\frac{2i\omega\eta\mu}{(\lambda  + 2\mu )(k_1^2 - k_2^2)}\int_\Gamma \nabla_{\bm x}^\top\left[\gamma_{k_1}(\bm x,\bm y) - \gamma _{k_2}(\bm x,\bm y)\right] \mathbb{A}\frac{D_s^w(\bm\phi)(\bm y)}{w(\bm y)}ds_{\bm y},
\end{align*}
which completes the proof.
\end{proof}



\section{Numerical experiments}
\label{sec:4}

\subsection{Numerical implementations}
\label{sec:4.1}

We utilize the Nystr\"om-type method~\cite{BL12,BXY21} to numerically discretize the integral operators \jp{$\bm{V}_i^{w} , i = 1,2,3,4 $} on the basis of the Chebyshev quadrature points $\theta_n=\frac{\pi (2n+1)}{2N},\,\, n=0,1,...,N-1$, and truncated Chebyshev expansions of the smooth densities. Without loss of generality, we assume a smooth parameterization $\jp{\bm x} (t)=(x_1 (t),x_2(t)),\,\,t\in [-1,1]$ of $\Gamma$ satisfying $|\jp{\bm x'}(t)|=|d\jp{\bm x}(t)/dt|>0$, and choose
the weight $w$ so that $w(\jp{\bm x}(t))=\sqrt{1-t^2}$. Hence, the operator $\jp{\bm{V}_1^w}$ will be given by \ben
\jp{\bm{V}_1^w}[\bm \phi](t)=\int_{-1}^1
\jp{\mathbb{E}^\top(\bm x(t),\bm x(\tau))}\frac{\bm \phi(\bm x(\tau))}{\sqrt{1-\tau^2}}|\bm x'(\tau)|d\tau. \enn
Introducing the change of variables $t=\cos\theta$ and
$\tau=\cos\theta'$, we
obtain the periodic weighted operator
\be
\jp{\bm{V}_1^w}[\bm \phi](\theta)=\int_0^\pi
\mathbb{E}^\top(\bm x(\cos\theta),\bm x(\cos\theta'))\widetilde{\bm \phi}(\theta')|\bm x'(\cos\theta')|d\theta',
\quad \widetilde{\bm \phi}(\theta')=\bm \phi(\bm x(\cos\theta')).  \en Using the series expansions of the Hankel functions  \cite{CK13}, we can
obtain the decomposition
\be \label{anal} \jp{\mathbb{E}}(\bm x(t),\bm x(\tau))=\mathbb{E}^{1}(t,\tau)\log|t-\tau|+\mathbb{E}^{2}(t,\tau),  \en
where $\mathbb{E}^1(t,\tau)$ and $\mathbb{E}^2(t,\tau)$ are analytic. The detailed expressions of $\mathbb{E}^1$ and $\mathbb{E}^2$ are presented in the appendix.

It should be noted that, since the wave numbers 
$k_1,k_2$
  are complex, the terms 
$\mathbb{E}^{1}$ and $\mathbb{E}^{2}$
  increase exponentially with frequency 
$\omega$. An alternative regularization technique involves selecting only a few terms from the power series of 
$\mathbb{E}^1(t,\tau)$, which results in new functions 
$\mathbb{E}^1(t,\tau), \mathbb{E}^2(t,\tau)$ increasing polynomially with frequency. However, this approach means the overall scheme will not converge spectrally, but instead with a fixed order, determined by the number of terms selected in the regularization. For this work, we will limit ourselves to low- and medium-frequency regimes and therefore we use the traditional regularization scheme.

Using the Chebyshev points
$\left\{\theta_n=\frac{\pi(2n+1)}{2N}\right\}, n=0,1,\cdots,N-1$, gives
rise to a spectrally convergent cosine representation for smooth,
$2\pi$-periodic and even function $ \widetilde{\bm \phi}$ as \be
\label{periodicexp}
\jp{
\widetilde{\bm \phi}(\theta)=\sum_{n=0}^{N-1}\begin{pmatrix}
a^1_n\\ a^2_n
\end{pmatrix} e_n(\theta), \quad \begin{pmatrix}
a^1_n\\ a^2_n
\end{pmatrix}=\frac{2-\delta_{0n}}{N}\sum_{j=0}^{N-1}\widetilde{\bm \phi}(\theta_j)\cos(n\theta_j),}
\en
where $e_n(\theta) = \cos(n\theta)$. \jp{From \cite{BH07,YS88}, we have that}
\be
\label{symmpro}
-\frac{1}{2\pi}\int_0^\pi \log|\cos\theta-\cos\theta'|e_n(\theta')d\theta' =\lambda_ne_n(\theta), \quad \lambda_n=\begin{cases}
\frac{\log2}{2}, & n=0, \\
\frac{1}{2n}, & n\ge 1.
\end{cases}
\en
Applying equation (\ref{symmpro}) to each term of expansion (\ref{periodicexp}) we can obtain the well-known spectral quadrature rule for the logarithmic kernel
\be
\label{sqr}
\int_0^\pi \log|\cos\theta-\cos\theta'|\widetilde{\bm \phi}(\theta')d\theta' \jp{\approx} \frac{\pi}{N}\sum_{j=0}^{N-1}\widetilde{\bm \phi}(\theta_j)R_j^{(N)}(\theta),
\en
where
\be
\label{RjN}
R_j^{(N)}(\theta)=-2\sum_{m=0}^{N-1}(2-\delta_{0m})
\lambda_m\cos(m\theta_j)\cos(m\theta).  \en Together with the
trapezoidal integration for smooth periodic functions we  obtain a
spectrally quadrature approximation of the operator $\bm{V}_1^{w}$ as \be
\label{sqaS}
\bm{V}_1^{w}[\bm \phi](\theta)\approx  \frac{\pi}{N}\sum_{j=0}^{N-1} |\bm x'(\cos\theta_j)| \left[\mathbb{E}^1 (\cos\theta,\cos\theta_j)R_j^{(N)}(\theta) + \mathbb{E}^2 (\cos\theta,\cos\theta_j)\right]\widetilde{\bm \phi}(\theta_j).
\en
Then we can evaluate $\bm{V}_1^w[\bm \phi]$ in the sets of quadrature points $\{\theta_n, n=0,\cdots,N-1\}$ by means of a matrix-vector multiplication involving the \jp{block}-matrix ${\bf V}_1^w$ whose elements are defined by
\ben
[{\bf V}_1^w]_{ij}=\frac{\pi}{N}|\bm x'(\cos\theta_j)| \left[\mathbb{E}^1 (\cos\theta_i,\cos\theta_j)R_j^{(N)}(\theta_i) + \mathbb{E}^2 (\cos\theta_i,\cos\theta_j)\right],
\enn
in which the quantities $R_j^{(N)}(\theta_i)$ can be evaluated through
\ben
R_j^{(N)}(\theta_i)=R^{(N)}(|i-j|)+R^{(N)}(i+j+1),
\enn
where
\ben
R^{(N)}(l)=-\sum_{m=0}^{N-1} (2-\delta_{0m})\lambda_m\cos\left(\frac{lm\pi}{N}\right), \quad l=0,\cdots,2N-1.
\enn

In order to discretize the operators $\bm{V}_i^w,i=2,3,4$, we use the regualarized technique presented in Section~\ref{sec:3.3}. From the regualarized formulations given in Theorem~\ref{regV3} and in the appendix, the numerical evaluations of the operators $\bm{V}_i^w, i=2,3,4$ reduce to calculate the operators with the following forms
\be \bm{S}_1, \quad D_s \bm{S}_2 D_s^w, \quad \bm{S}_3 D_s^w, \quad D_s \bm{S}_4, \en
where $\bm{S}_i,\,i=1,2,3,4$ are integral operators with kernel of logarithmic type (which can be treated like $\bm{V}_1^w$), and
\begin{align} D_s[\alpha](\theta)=-\frac{1}{|\bm x'(\cos\theta)|}\frac{1}{\sin\theta} \frac{d\alpha(\theta)}{d\theta},
\end{align}
\begin{align}
  D_s^w[\alpha](\theta)=-\frac{\sin\theta}{|\bm x'(\cos\theta)|} \frac{d\alpha(\theta)}{d\theta} - \frac{\alpha(\theta)\cos\theta}{|\bm x'(\cos\theta)|}. \end{align}
Note that $\alpha(\theta)$ is an even function on $[0,\pi]$ which can be extended to be an even $2\pi$-periodic function on $[-\pi,\pi]$ and then whose derivatives respect to $\theta$ can be evaluated by the FFT.





\subsection{Numerical examples}
\label{sec:4.2}

Now we present several numerical examples to demonstrate the accuracy and efficiency of the proposed regularized BIE methods for solving the thermo-elastic scattering by open-arcs. We fix the parameters,  $\rho=1, \mu=1, \lambda=2,
\kappa=1, \eta=0.2$ and $\gamma=0.1$.  The boundary data for the different boundary condition will be given by 
\ben  \bm G_i=- \mathbb{B}_i(\pa,\nu) \bm U^{inc}, \,\, i=1,2,3,4,\enn
where
$\bm U^{inc}=(\bm u^{inc },0)$, with $\bm u^{inc}=\bm d_{inc}^{\bot }\mbox{exp}(i k_s \bm x \cdot \bm d_{inc})$ a plane incident shear wave with direction $\bm d_{inc}=(\cos \theta_{inc},\sin \theta_{inc})$, $\bm d_{inc}^{\bot}=(-\sin \theta_{inc}, \cos \theta_{inc})$ and $\theta_{inc}$ denoting the incident angle.

In what follows we will denote by $\mathrm{Solver}_i(\bm{V}_i^w)$ whenever we are using the  unregularized solvers to approximate the i-th BIE in \eqref{weighted} (i.e., solving the i-th boundary value problem), for $i=1,2,3,4$. Similarly we denote by  $\mathrm{Solver}_i(\bm{V}_{j_i}^w\bm{V}_{j_i-1}^w)$ when we use the regularized solvers, specified on the third column of Table~\ref{RsolrepHIE}, with $j_1=j_2=2,j_3=j_4=4$. All the formulations were implemented in Matlab using the expressions of Section \ref{sec:4.1}, while the resulting linear system were approximated using GMRES. 

