\section*{Appendix}
In this appendix, we first present the regularized formulations for $\bm V_i^w, i=2,3$. Using the notations in Section~\ref{sec:3.3}, it can be derived that the integral operators $\bm V_{2,11}^w$, $\bm V_{2,12}^w$, $\bm V_{2,21}^w$, $\bm V_{2,22}^w$ can be re-expressed as

\begin{align*}
    \bm V_{2,11}^w=&\bm V_{4,11}^w,\\
    \bm V_{2,12}^w=&\bm V_{2,12}^{w,1} + D_s \bm V_{2,12}^{w,2} D_s^w+ D_s \bm V_{2,12}^{w,3}, \\
    \bm V_{2,21}^w=&\bm V_{2,21}^{w,1} + D_s \bm V_{2,21}^{w,2} D_s^w +\bm V_{2,21}^{w,3} D_s^w, \\
   \bm V_{2,22}^w=&\bm V_{2,22}^{w,1} + D_s \bm V_{2,22}^{w,2} D_s^w,
\end{align*}
where $\bm V_{4,11}^w$ is defined in (\ref{RegV311}), and $\bm V_{2,12}^{w,1}[\psi]= \bm V_{2,12}^{1}[w \psi]$,
$\bm V_{2,12}^{w,2}[\psi]= \bm V_{2,12}^{2}[w^{-1}\psi]$,
$\bm V_{2,12}^{w,3}[\psi] =\bm V_{2,12}^{3}[w\psi]$,
$\bm  V_{2,21}^{w,1}[\bm \phi] =\bm  V_{2,21}^{1}[w \bm \phi]$,
$\bm  V_{2,21}^{w,2}[\bm \phi] =\bm  V_{2,21}^{2}[w^{-1}\bm \phi]$,
$\bm V_{2,21}^{w,3}[\bm \phi] =\bm V_{2,21}^{3}[w^{-1}\bm \phi]$,
$\bm V_{2,22}^{w,1} [\psi]= \bm V_{2,22}^{1} [w \psi]$,
$\bm V_{2,22}^{w,2} [\psi] =\bm V_{2,22}^{2} [w^{-1}\psi]$.
The integral operators 
\begin{align*}
    \bm V_{2,12}^{1}[\psi]=& \frac{\gamma k_p^{2} \bm\nu_{\bm x}}{k_1^{2}-k_2^{2}} \int_{\Gamma}  \pa_{ \bm\nu_{\bm y}}[\gamma_{k_1}(\bm x,\bm y)-\gamma_{k_2}(\bm x,\bm y)]\psi(\bm y)d s_{\bm y}, \\ 
    \bm V_{2,12}^{2}[\psi]=& \frac{2\mu \gamma}{(k_1^{2}-k_2^{2})(\lambda+2\mu)} \int_{\Gamma} \nabla_{\bm y} (\gamma_{k_1}(\bm x,\bm y)-\gamma_{k_2}(\bm x,\bm y))\psi(\bm y) d s_{\bm y} ,\\
    \bm V_{2,12}^{3}[\psi]=&-\frac{2\mu \gamma}{(k_1^{2}-k_2^{2})(\lambda+2\mu)}\int_{\Gamma} [k_1^{2}\gamma_{k_1}(\bm x,\bm y)-k_2^{2}\gamma_{k_2}(\bm x,\bm y)]\mathbb{A} \bm \nu_{\bm y} \psi(\bm y)d s_{\bm y},\\
   \bm  V_{2,21}^{1}[\bm \phi]=&\frac{i\omega\eta k_p^{2}}{k_1^{2}-k_2^{2}}\int_{\Gamma} \pa_{\nu_{\bm x}}[\gamma_{k_1}(\bm x,\bm y)-\gamma_{k_2}(\bm x,\bm y)]\bm \nu_{\bm y}^{\top}\bm \phi(\bm y)d s_{\bm y}, \\
   \bm  V_{2,21}^{2}[\bm \phi]=&\frac{2i\mu \omega\eta}{(k_1^{2}-k_2^{2})(\lambda+2\mu)}  \int_{\Gamma} \nabla_{\bm x}^{\top}[\gamma_{k_1}(\bm x,\bm y)-\gamma_{k_2}(\bm x,\bm y)]\bm \phi(\bm y) d s_{\bm y},\\
    \bm V_{2,21}^{3}[\bm \phi]=&-\frac{2i\mu \omega\eta}{(k_1^{2}-k_2^{2})(\lambda+2\mu)} \int_{\Gamma} [k_1^{2}\gamma_{k_1}(\bm x,\bm y)-k_2^{2}\gamma_{k_2}(\bm x,\bm y)]\bm \nu_{\bm x}^{\top}\mathbb{A} \bm \phi (\bm y) d s_{\bm y}, \\
    \bm V_{2,22}^{1} [\psi] =&-\frac{1}{k_1^{2}-k_2^{2}}\int_{\Gamma}[k_1^{2}(k_p^{2}-k_1^{2})\gamma_{k_1}(\bm x,\bm y)-k_2^{2}(k_p^{2}-k_2^{2})\gamma_{k_2}(\bm x,\bm y)]\bm\nu_{\bm x}^{\top}\bm\nu_{\bm y} \psi(\bm y) d s_{\bm y}, \\
    \bm V_{2,22}^{2} [\psi]=&-\frac{1}{k_1^{2}-k_2^{2}}\int_{\Gamma}[(k_p^{2}-k_1^{2})\gamma_{k_1}(\bm x,\bm y)-(k_p^{2}-k_2^{2})\gamma_{k_2}(\bm x,\bm y)] \psi(\bm y) d s_{\bm y},
\end{align*}  
are at most weakly-singular.
Similarly, the operator $\bm V_{3,12}^w,\bm V_{3,21}^w,\bm V_{3,22}^w$ can be re-expressed as
\begin{align*}
    \bm V_{3,12}^w=&\bm V_{3,12}^{w,1} +\bm V_{3,12} ^{w,2} D_s^w,\\
    \bm V_{3,21}^w=&\bm V_{3,21}^{w,1} + D_s \bm V_{3,21}^{w,2}, \\
   \bm  V_{3,22}^w=&\bm V_{2,22}^w,
\end{align*}
where  $\bm V_{3,12}^{w,1} [\psi]= \bm V_{3,12}^{1} [w\psi]$,
$\bm V_{3,12}^{w,2} [\psi] =\bm V_{3,12}^{2} [w^{-1}\psi]$,
$\bm V_{3,21}^{w,1} [\bm \phi] =\bm V_{3,21}^{1} [w^{-1}\bm \phi]$,
$\bm V_{3,21}^{w,2} [\bm \phi]= \bm V_{3,21}^{2} [w^{-1}\bm \phi]$,
and the integral operators
\begin{align*}
    \bm V_{3,12}^{1} [\psi] =&\frac{\gamma}{(k_1^{2}-k_2^{2})(\lambda+2\mu)} \int_{\Gamma} (-k_1^{2}\gamma_{k_1}(\bm x,\bm y)+k_2^{2}\gamma_{k_2}(\bm x,\bm y))\psi(y)\bm\nu_{\bm y}  d s_{\bm y}, \\
    \bm V_{3,12}^{2} [\psi] =&-\frac{\gamma}{(k_1^{2}-k_2^{2})(\lambda+2\mu)}\int_{\Gamma} \mathbb{A} \nabla_{\bm y} (\gamma_{k_1}(\bm x,\bm y)-\gamma_{k_2}(\bm x,\bm y))\psi(\bm y) d s_{\bm y}, \\
    \bm V_{3,21}^{1} [\bm \phi] =&\frac{i\omega \eta}{(k_1^{2}-k_2^{2})(\lambda+2\mu)} \int_{\Gamma} (-k_1^{2}\gamma_{k_1}(\bm x,\bm y)+k_2^{2}\gamma_{k_2}(\bm x,\bm y))\bm\nu_{\bm x}^{\top}  \bm \phi(\bm y)d s_{\bm y}, \\
    \bm V_{3,21}^{2} [\bm \phi] =&-\frac{i\omega\eta}{(k_1^{2}-k_2^{2})(\lambda+2\mu)}  \int_{\Gamma} \nabla_{\bm x}^{\top}(\gamma_{k_1}(\bm x,\bm y)-\gamma_{k_2}(\bm x,\bm y))\mathbb{A}  \bm \phi(\bm y)d s_{\bm y},
\end{align*}
are all at most weakly-singular.

Finally, we present the expressions of $\mathbb{E}^1(t,\tau)$ and $\mathbb{E}^2(t,\tau)$ in (\ref{anal}). 
 Using the series expansions of Bessel functions~\cite{CK13} , when $t\neq \tau$ we obtain
\begin{align*}
 \mathbb{E}_{11}^1(t,\tau)=&-\frac{1}{2\pi\mu}J_0 (k_s r)\mathbb{I}_2+\frac{1}{2\pi\rho \omega^2 r}[k_s J_1 (k_s r)-\frac{k_p^2-k_2^2}{k_1^2-k_2^2}k_1 J_1(k_1 r)+\frac{k_p^2-k_1^2}{k_1^2-k_2^2}k_2 J_1(k_2 r)]\\
 &-\frac{(\bm x(t)-\bm x(\tau))(\bm x(t)-\bm x(\tau))^{\top}}{2\pi\rho\omega^2 r^2}[k_s^2 J_2(k_s r)-\frac{k_p^2-k_2^2}{k_1^2-k_2^2}k_1^2 J_2 (k_1 r)+\frac{k_p^2-k_1^2}{k_1^2-k_2^2}k_2^2 J_2 (k_2 r)],  \\
 \bm E_{12}^1(t,\tau)=&\frac{i\omega \eta}{(k_1^2-k_2^2)(\lambda+2\mu)}\frac{1}{2\pi r}[k_1 J_1(k_1 r) -k_2 J_1(k_2 r)](\bm x(t)-\bm x(\tau)), \\
  \bm E_{21}^1(t,\tau)=&-\frac{ \gamma}{(k_1^2-k_2^2)(\lambda+2\mu)}\frac{1}{2\pi r}[k_1 J_1(k_1 r) -k_2 J_1(k_2 r)](\bm x(t)-\bm x(\tau)), \\
  E_{22}^1 (t,\tau)=&\frac{1}{2\pi}[\frac{1}{k_1^2-k_2^2}(k_p^2-k_1^2)J_0 (k_1 r)-(k_p^2-k_2^2) J_0 (k_2 r)],
 \end{align*}
with $r=|x(t)-x(\tau)|$, $J_n$ denoting Bessel functions of order $n$ and
\ben \mathbb{E}^2 (t,\tau)=\mathbb{E} (\bm x(t),\bm x(\tau))-\mathbb{E}^1 (t,\tau) \log|t-\tau|. \enn
When $t=\tau$, we have
\begin{align*}
\mathbb{E}_{11}^1 (t,t)=&-\frac{1}{2\pi\mu}\mathbb{I}_2+\frac{k_s^2-k_p^2}{4\pi\rho\omega^2}\mathbb{I}_2, \\
 \mathbb{E}_{11}^2 (t,t)=&\frac{i}{4\mu} [1+\frac{2i}{\pi}(\log \frac{k_s |\bm x'(t)|}{2}+C_e)]\mathbb{I}_2-\frac{i}{4\rho\omega^2}\frac{k_s^2-k_p^2}{2}[1+\frac{2i}{\pi}(\log|\bm x'(t)|+C_e)-\frac{i}{\pi}]\mathbb{I}_2 \\
 +&\frac{k_s^2-k_p^2}{4\pi\rho\omega^2}\frac{\bm x'(t)^{\top}\bm x'(t)}{|\bm x'(t)|^2}+\frac{1}{4\pi\rho\omega^2}(k_s^2\, \log\frac{k_s}{2}-\frac{k_p^2-k_2^2}{k_1^2-k_2^2}k_1^2\, \log\frac{k_1}{2}+\frac{k_p^2-k_1^2}{k_1^2-k_2^2}k_2^2 \,\log\frac{k_2}{2})\mathbb{I}_2,\\
 \bm E_{12}^1 (t,t)=&\bm E_{12}^2(t,t)=0, \\
 \bm E_{21}^1(t,t)=&\bm E_{21}^2(t,t)=0, \\
 E_{22}^1(t,t)=&-\frac{1}{2\pi}, \\
 E_{22}^2(t,t)=&\frac{i}{4}-\frac{C_e}{2\pi}+\frac{1}{2\pi}(\frac{k_p^2-k_1^2}{k_1^2-k_2^2}\log \frac{k_1 \vert x'(t) \vert}{2}-\frac{k_p^2-k_2^2}{k_1^2-k_2^2}\log \frac{k_2 \vert x'(t) \vert}{2}),
 \end{align*}
where $C_e$ is the Euler constant. 

